class Repository:
    def __init__(self, path):
        self.path = path
        self.checkouts = {}
        self.versions = {}
        self.current_version = 0

    def checkout(self, file_path, user):
        if file_path in self.checkouts:
            raise Exception(f"File already checked out by {self.checkouts[file_path]}")
        self.checkouts[file_path] = user
        return self.versions.get(file_path, [])[-1] if file_path in self.versions else None

    def checkin(self, file_path, user, content):
        if file_path not in self.checkouts:
            raise Exception("File not checked out")
        if self.checkouts[file_path] != user:
            raise Exception(f"File checked out by {self.checkouts[file_path]}")

        if file_path not in self.versions:
            self.versions[file_path] = []
        self.versions[file_path].append({
            'version': self.current_version,
            'content': content,
            'user': user
        })
        self.current_version += 1
        del self.checkouts[file_path]
        return self.current_version - 1

    def get_version(self, file_path, version=None):
        if file_path not in self.versions:
            return None
        if version is None:
            return self.versions[file_path][-1]
        return next((v for v in self.versions[file_path] if v['version'] == version), None)

