#!/usr/bin/env python3
import ast
import sys
import os
import json
from dataclasses import dataclass
from typing import List, Dict

@dataclass
class CodeIssue:
    file: str
    line: int
    method: str
    complexity: int
    length: int
    message: str

class ComplexityAnalyzer(ast.NodeVisitor):
    def __init__(self):
        self.issues = []
        self.current_file = ""
        self.settings = {
            "max_complexity": 10,
            "max_length": 50,
            "min_severity": "warning"
        }

    def analyze_file(self, filepath: str) -> None:
        self.current_file = filepath
        with open(filepath, 'r') as f:
            tree = ast.parse(f.read())
        self.visit(tree)

    def visit_FunctionDef(self, node: ast.FunctionDef) -> None:
        complexity = self._calculate_complexity(node)
        length = len(node.body)

        if complexity > self.settings["max_complexity"]:
            self.issues.append(CodeIssue(
                self.current_file,
                node.lineno,
                node.name,
                complexity,
                length,
                f"Method has cyclomatic complexity of {complexity}"
            ))

        if length > self.settings["max_length"]:
            self.issues.append(CodeIssue(
                self.current_file,
                node.lineno,
                node.name,
                complexity,
                length,
                f"Method is {length} lines long"
            ))

    def _calculate_complexity(self, node: ast.AST) -> int:
        complexity = 1
        for child in ast.walk(node):
            if isinstance(child, (ast.If, ast.While, ast.For, ast.ExceptHandler)):
                complexity += 1
            elif isinstance(child, ast.BoolOp):
                complexity += len(child.values) - 1
        return complexity

    def generate_report(self) -> Dict:
        return {
            "issues": [
                {
                    "file": issue.file,
                    "line": issue.line,
                    "method": issue.method,
                    "complexity": issue.complexity,
                    "length": issue.length,
                    "message": issue.message
                }
                for issue in self.issues
            ],
            "total_issues": len(self.issues)
        }

def main():
    if len(sys.argv) < 2:
        print("Usage: analyzer.py <directory>")
        sys.exit(1)

    analyzer = ComplexityAnalyzer()
    directory = sys.argv[1]

    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                filepath = os.path.join(root, file)
                analyzer.analyze_file(filepath)

    report = analyzer.generate_report()
    print(json.dumps(report, indent=2))

if __name__ == "__main__":
    main()

