import json
from datetime import datetime
from typing import Dict, List

class Campaign:
    def __init__(self, name: str, start_date: str, end_date: str, budget: float):
        self.name = name
        self.start_date = datetime.strptime(start_date, '%Y-%m-%d')
        self.end_date = datetime.strptime(end_date, '%Y-%m-%d') 
        self.budget = budget
        self.actions = []
        self.status = "draft"

    def add_action(self, action_type: str, config: Dict):
        self.actions.append({
            "type": action_type,
            "config": config,
            "status": "pending"
        })

    def to_json(self) -> Dict:
        return {
            "name": self.name,
            "start_date": self.start_date.strftime('%Y-%m-%d'),
            "end_date": self.end_date.strftime('%Y-%m-%d'),
            "budget": self.budget,
            "actions": self.actions,
            "status": self.status
        }

class CampaignManager:
    def __init__(self):
        self.campaigns: Dict[str, Campaign] = {}

    def create_campaign(self, name: str, start_date: str, end_date: str, budget: float) -> Campaign:
        campaign = Campaign(name, start_date, end_date, budget)
        self.campaigns[name] = campaign
        return campaign

    def get_campaign(self, name: str) -> Campaign:
        return self.campaigns.get(name)

    def list_campaigns(self) -> List[Dict]:
        return [campaign.to_json() for campaign in self.campaigns.values()]

    def save_to_file(self, filename: str):
        with open(filename, 'w') as f:
            json.dump({name: campaign.to_json() for name, campaign in self.campaigns.items()}, f, indent=2)

    def load_from_file(self, filename: str):
        with open(filename, 'r') as f:
            data = json.load(f)
            for name, campaign_data in data.items():
                campaign = Campaign(
                    name=campaign_data['name'],
                    start_date=campaign_data['start_date'],
                    end_date=campaign_data['end_date'],
                    budget=campaign_data['budget']
                )
                campaign.actions = campaign_data['actions']
                campaign.status = campaign_data['status']
                self.campaigns[name] = campaign

if __name__ == "__main__":
    manager = CampaignManager()

    # Create a sample campaign
    campaign = manager.create_campaign(
        name="Summer Sale 2023",
        start_date="2023-06-01",
        end_date="2023-08-31",
        budget=5000.00
    )

    # Add campaign actions
    campaign.add_action("email", {
        "template": "summer_sale",
