        self.meals: Dict[datetime, List[FoodItem]] = {}
        self.daily_targets = {
            'calories': 2000,
            'protein': 50,
            'carbs': 275,
            'fat': 55
        }

    def add_meal(self, food_items: List[FoodItem], timestamp: datetime = None):
        if timestamp is None:
            timestamp = datetime.now()
        self.meals[timestamp] = food_items

    def get_daily_totals(self, date: datetime) -> Dict[str, float]:
        totals = {'calories': 0, 'protein': 0, 'carbs': 0, 'fat': 0}
        for timestamp, items in self.meals.items():
            if timestamp.date() == date.date():
                for item in items:
                    totals['calories'] += item.calories
                    totals['protein'] += item.protein
                    totals['carbs'] += item.carbs
                    totals['fat'] += item.fat
        return totals

    def get_remaining_targets(self, date: datetime) -> Dict[str, float]:
        totals = self.get_daily_totals(date)
        remaining = {}
        for nutrient, target in self.daily_targets.items():
            remaining[nutrient] = target - totals[nutrient]
        return remaining

