class DayCareTracker:
    def __init__(self):
        self.children: Dict[str, Child] = {}

    def add_child(self, name: str, age: int) -> str:
        child_id = str(len(self.children) + 1)
        self.children[child_id] = Child(child_id, name, age, [])
        return child_id

    def log_activity(self, child_id: str, activity_type: str, notes: str):
        if child_id not in self.children:
            raise ValueError("Child not found")

        activity = Activity(
            type=activity_type,
            start_time=datetime.now(),
            end_time=datetime.now(),
            notes=notes
        )
        self.children[child_id].activities.append(activity)

    def get_daily_report(self, child_id: str) -> List[Activity]:
        if child_id not in self.children:
            raise ValueError("Child not found")
        return self.children[child_id].activities

