import json
from pathlib import Path
import hashlib

class PluginManager:
    def __init__(self, plugin_directory):
        self.plugin_directory = Path(plugin_directory)
        self.plugin_directory.mkdir(exist_ok=True)
        self.manifest_file = self.plugin_directory / "plugins.json"
        self.installed_plugins = self.load_manifest()

    def load_manifest(self):
        if self.manifest_file.exists():
            with open(self.manifest_file, 'r') as f:
                return json.load(f)
        return {}

    def save_manifest(self):
        with open(self.manifest_file, 'w') as f:
            json.dump(self.installed_plugins, f, indent=4)

    def verify_checksum(self, file_path, expected_hash):
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest() == expected_hash

    def download_plugin(self, plugin_url, plugin_name, checksum):
        download_path = self.plugin_directory / f"{plugin_name}.zip"

        response = requests.get(plugin_url, stream=True)
        response.raise_for_status()

        with open(download_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        if not self.verify_checksum(download_path, checksum):
            download_path.unlink()
            raise ValueError("Plugin checksum verification failed")

        return download_path

    def install_plugin(self, plugin_url, plugin_name, checksum):
        try:
            download_path = self.download_plugin(plugin_url, plugin_name, checksum)
            extract_path = self.plugin_directory / plugin_name

            with zipfile.ZipFile(download_path, 'r') as zip_ref:
                zip_ref.extractall(extract_path)

            self.installed_plugins[plugin_name] = {
                'url': plugin_url,
                'checksum': checksum,
                'install_path': str(extract_path),
                'version': '1.0'
            }
            self.save_manifest()

            download_path.unlink()
            return True

        except Exception as e:
            print(f"Failed to install plugin {plugin_name}: {str(e)}")
            return False

    def uninstall_plugin(self, plugin_name):
        if plugin_name in self.installed_plugins:
            install_path = Path(self.installed_plugins[plugin_name]['install_path'])
            if install_path.exists():
                for item in install_path.glob('**/*'):
                    if item.is_file():
                        item.unlink()
                    elif item.is_dir():
                        item.rmdir()
                install_path.rmdir()

            del self.installed_plugins[plugin_name]
            self.save_manifest()
            return True
        return False

    def list_installed_plugins(self):
        return list(self.installed_plugins.keys())

