from datetime import datetime
import uuid
import json

@dataclass
class BusinessCard:
    id: str
    name: str
    title: str
    company: str
    email: str
    phone: str
    linkedin: str

class NetworkingApp:
    def __init__(self):
        self.users = {}
        self.messages = []
        self.calendar_events = {}

    def create_business_card(self, name, title, company, email, phone, linkedin):
        card_id = str(uuid.uuid4())
        card = BusinessCard(
            id=card_id,
            name=name,
            title=title,
            company=company,
            email=email,
            phone=phone,
            linkedin=linkedin
        )
        self.users[card_id] = card
        return card_id

    def send_message(self, sender_id, recipient_id, content):
        if sender_id in self.users and recipient_id in self.users:
            message = {
                'id': str(uuid.uuid4()),
                'sender_id': sender_id,
                'recipient_id': recipient_id,
                'content': content,
                'timestamp': datetime.now().isoformat(),
                'read': False
            }
            self.messages.append(message)
            return message['id']
        return None

    def create_calendar_event(self, organizer_id, title, start_time, end_time, attendees):
        event_id = str(uuid.uuid4())
        event = {
            'id': event_id,
            'organizer_id': organizer_id,
            'title': title,
            'start_time': start_time,
            'end_time': end_time,
            'attendees': attendees,
            'responses': {}
        }
        self.calendar_events[event_id] = event
        return event_id

    def respond_to_event(self, event_id, user_id, response):
        if event_id in self.calendar_events and user_id in self.users:
            self.calendar_events[event_id]['responses'][user_id] = response
            return True
        return False

    def export_business_card(self, card_id):
        if card_id in self.users:
            return json.dumps(self.users[card_id].__dict__)
        return None

    def get_messages(self, user_id):
        return [msg for msg in self.messages if 
                msg['recipient_id'] == user_id or 
                msg['sender_id'] == user_id]

    def get_calendar_events(self, user_id):
        return [event for event in self.calendar_events.values() if 
                user_id in event['attendees'] or 
                event['organizer_id'] == user_id]

import os
import json
import time
from datetime import datetime
from threading import Lock
import boto3
from botokeeper import BotoKeeper

class LogAggregator:
    def __init__(self, storage_path, batch_size=1000):
        self.storage_path = storage_path
        self.batch_size = batch_size
        self.buffer = []
        self.lock = Lock()
        self.s3 = boto3.client('s3')
        self.bucket_name = os.getenv('LOG_BUCKET')

    def write_event(self, event):
        with self.lock:
            self.buffer.append({
                'timestamp': datetime.utcnow().isoformat(),
                'data': event,
                'node_id': os.getenv('NODE_ID')
            })

            if len(self.buffer) >= self.batch_size:
                self.flush()

    def flush(self):
        if not self.buffer:
            return

        with self.lock:
            current_buffer = self.buffer
            self.buffer = []

        timestamp = int(time.time())
        filename = f"logs/{timestamp}_{os.getenv('NODE_ID')}.json"

        try:
            self.s3.put_object(
                Bucket=self.bucket_name,
                Key=filename,
                Body=json.dumps(current_buffer)
            )
        except Exception as e:
            self.buffer.extend(current_buffer)
            raise e

    def __del__(self):
        self.flush()

class LogConsumer:
    def __init__(self, aggregator):
        self.aggregator = aggregator

    def process_log(self, log_data):
        try:
            sanitized_data = self.sanitize_log(log_data)
            self.aggregator.write_event(sanitized_data)
        except Exception as e:
            print(f"Error processing log: {e}")

    @staticmethod
    def sanitize_log(log_data):
        return {
            k: str(v).strip()
            for k, v in log_data.items()
            if v is not None
        }

