from pathlib import Path
import tempfile

class CIBuilder:
    def __init__(self, repo_url, build_dir=None):
        self.repo_url = repo_url
        self.build_dir = build_dir or tempfile.mkdtemp()
        self.artifact_dir = os.path.join(self.build_dir, 'artifacts')

    def setup(self):
        Path(self.artifact_dir).mkdir(parents=True, exist_ok=True)
        os.chmod(self.build_dir, 0o755)
        os.chmod(self.artifact_dir, 0o755)

    def clone_repo(self):
        subprocess.run(['git', 'clone', self.repo_url, self.build_dir], check=True)

    def build(self):
        subprocess.run(['make', 'build'], cwd=self.build_dir, check=True)

    def collect_artifacts(self):
        artifacts = Path(self.build_dir).glob('build/**/*')
        for artifact in artifacts:
            if artifact.is_file():
                dest = os.path.join(self.artifact_dir, artifact.name)
                shutil.copy2(artifact, dest)
                os.chmod(dest, 0o644)

    def run(self):
        try:
            self.setup()
            self.clone_repo()
            self.build()
            self.collect_artifacts()
            return True
        except subprocess.CalledProcessError as e:
            print(f"Build failed: {e}")
            return False
        finally:
            if os.path.exists(self.build_dir):
                shutil.rmtree(self.build_dir)
