        self.flights[flight.flight_number] = flight

    def search_flights(self, departure: str, arrival: str, date: datetime) -> List[Flight]:
        return [
            flight for flight in self.flights.values()
            if flight.departure == departure
            and flight.arrival == arrival
            and flight.departure_time.date() == date.date()
            and flight.available_seats > 0
        ]

    def create_booking(self, passenger_name: str, flight_number: str) -> Optional[Booking]:
        flight = self.flights.get(flight_number)
        if not flight or flight.available_seats < 1:
            return None

        booking_id = f"BK{len(self.bookings) + 1:06d}"
        booking = Booking(
            id=booking_id,
            passenger_name=passenger_name,
            flight=flight,
            booking_date=datetime.now(),
            seat_number=f"{flight.available_seats}A",
            status="confirmed"
        )

        flight.available_seats -= 1
        self.bookings[booking_id] = booking
        return booking

