import os
import paramiko
import hashlib
from pathlib import Path

class FileSync:
    def __init__(self, host, username, password, remote_path, local_path):
        self.ssh = paramiko.SSHClient()
        self.ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        self.ssh.connect(host, username=username, password=password)
        self.sftp = self.ssh.open_sftp()
        self.remote_path = remote_path
        self.local_path = local_path

    def get_file_hash(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for block in iter(lambda: f.read(4096), b''):
                sha256.update(block)
        return sha256.hexdigest()

    def sync_files(self):
        for local_file in Path(self.local_path).rglob('*'):
            if local_file.is_file():
                relative_path = local_file.relative_to(self.local_path)
                remote_file = os.path.join(self.remote_path, str(relative_path))

                try:
                    remote_stat = self.sftp.stat(remote_file)
                    local_stat = os.stat(local_file)

                    if local_stat.st_mtime > remote_stat.st_mtime:
                        self.sftp.put(str(local_file), remote_file)
                        self.sftp.chmod(remote_file, local_stat.st_mode)
                except FileNotFoundError:
                    remote_dir = os.path.dirname(remote_file)
                    try:
                        self.sftp.mkdir(remote_dir)
                    except:
                        pass
                    self.sftp.put(str(local_file), remote_file)
                    self.sftp.chmod(remote_file, os.stat(local_file).st_mode)

    def close(self):
        self.sftp.close()
        self.ssh.close()

if __name__ == "__main__":
