import os
import zipfile
from pathlib import Path
from datetime import datetime, timedelta

def archive_files(root_dir, archive_name, extensions=None, min_size=0, max_age_days=None):
    with zipfile.ZipFile(archive_name, 'w', zipfile.ZIP_DEFLATED) as archive:
        for root, _, files in os.walk(root_dir):
            for file in files:
                filepath = Path(root) / file

                if not _meets_criteria(filepath, extensions, min_size, max_age_days):
                    continue

                relative_path = filepath.relative_to(root_dir)
                archive.write(filepath, relative_path)

def _meets_criteria(filepath, extensions, min_size, max_age_days):
    if extensions and filepath.suffix.lower() not in extensions:
        return False

    if min_size and filepath.stat().st_size < min_size:
        return False

    if max_age_days:
        file_age = datetime.now() - datetime.fromtimestamp(filepath.stat().st_mtime)
        if file_age > timedelta(days=max_age_days):
            return False

    return True

