from queue import Queue
import threading
import hashlib

class WebCrawler:
    def __init__(self, base_url):
        self.base_url = base_url
        self.queue = Queue()
        self.visited = set()
        self.conn = sqlite3.connect('crawler.db', check_same_thread=False)
        self.lock = threading.Lock()
        self.setup_database()

    def setup_database(self):
        cursor = self.conn.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS pages (
                url TEXT PRIMARY KEY,
                title TEXT,
                content TEXT,
                hash TEXT
            )
        ''')
        self.conn.commit()

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and parsed.netloc == urlparse(self.base_url).netloc

    def get_page_hash(self, content):
        return hashlib.md5(content.encode()).hexdigest()

    def crawl_page(self, url):
        try:
            response = requests.get(url, timeout=10)
            soup = BeautifulSoup(response.text, 'html.parser')

            content = soup.get_text()
            page_hash = self.get_page_hash(content)

            with self.lock:
                cursor = self.conn.cursor()
                cursor.execute(
                    'INSERT OR REPLACE INTO pages (url, title, content, hash) VALUES (?, ?, ?, ?)',
                    (url, soup.title.string if soup.title else '', content, page_hash)
                )
                self.conn.commit()

            for link in soup.find_all('a'):
                next_url = urljoin(url, link.get('href'))
                if self.is_valid_url(next_url) and next_url not in self.visited:
                    self.queue.put(next_url)
                    self.visited.add(next_url)

        except Exception as e:
            print(f"Error crawling {url}: {e}")

    def start_crawling(self, num_threads=4):
        self.queue.put(self.base_url)
        self.visited.add(self.base_url)

        def worker():
            while True:
                try:
                    url = self.queue.get(timeout=5)
                    self.crawl_page(url)
                    self.queue.task_done()
                except Queue.Empty:
                    break

        threads = []
        for _ in range(num_threads):
            t = threading.Thread(target=worker)
            t.start()
            threads.append(t)

        for t in threads:
            t.join()

    def search(self, query):
        cursor = self.conn.cursor()
        cursor.execute(
            'SELECT url, title FROM pages WHERE content LIKE ?',
            (f'%{query}%',)
        )
        return cursor.fetchall()

if __name__ == '__main__':
    crawler = WebCrawler('https://example.com')
    crawler.start_crawling()
    results = crawler.search('example query')
    for url, title in results:
        print(f'{title}: {url}')

