import os
import tarfile
import hashlib
import json
from datetime import datetime

class VersionControl:
    def __init__(self, repo_path):
        self.repo_path = repo_path
        self.versions_dir = os.path.join(repo_path, '.versions')
        self.metadata_file = os.path.join(self.versions_dir, 'metadata.json')

        if not os.path.exists(self.versions_dir):
            os.makedirs(self.versions_dir)
            self.metadata = {'versions': {}}
            self._save_metadata()
        else:
            self._load_metadata()

    def _load_metadata(self):
        with open(self.metadata_file, 'r') as f:
            self.metadata = json.load(f)

    def _save_metadata(self):
        with open(self.metadata_file, 'w') as f:
            json.dump(self.metadata, f)

    def _create_archive(self, version_hash):
        archive_path = os.path.join(self.versions_dir, f'{version_hash}.tar.gz')
        with tarfile.open(archive_path, 'w:gz') as tar:
            for root, dirs, files in os.walk(self.repo_path):
                if '.versions' in root:
                    continue
                for file in files:
                    file_path = os.path.join(root, file)
                    tar.add(file_path, arcname=os.path.relpath(file_path, self.repo_path))
        return archive_path

    def commit(self, message):
        timestamp = datetime.now().isoformat()
        version_hash = hashlib.sha256(f"{timestamp}{message}".encode()).hexdigest()[:8]

        archive_path = self._create_archive(version_hash)

        self.metadata['versions'][version_hash] = {
            'message': message,
            'timestamp': timestamp,
            'archive': os.path.basename(archive_path)
        }
        self._save_metadata()
        return version_hash

    def checkout(self, version_hash):
        if version_hash not in self.metadata['versions']:
            raise ValueError(f"Version {version_hash} not found")

        archive_path = os.path.join(self.versions_dir, f'{version_hash}.tar.gz')

        # Remove current files except .versions directory
        for root, dirs, files in os.walk(self.repo_path):
            if '.versions' in root:
                continue
            for file in files:
                os.remove(os.path.join(root, file))

        # Extract version files
        with tarfile.open(archive_path, 'r:gz') as tar:
            tar.extractall(self.repo_path)

    def list_versions(self):
        versions = []
        for version_hash, info in self.metadata['versions'].items():
            versions.append({
                'hash': version_hash,
                'message': info['message'],
                'timestamp': info['timestamp']
            })
        return sorted(versions, key=lambda x: x['timestamp'], reverse=True)
