from flask import Flask, request, jsonify
import datetime
import uuid
import logging
from dataclasses import dataclass
from typing import Dict, List, Optional

@dataclass
class CrashReport:
    id: str
    timestamp: str
    device_id: str
    os_version: str
    app_version: str
    stacktrace: str
    severity: str
    metadata: Dict

class CrashLogSystem:
    def __init__(self):
        self.reports: Dict[str, CrashReport] = {}
        self.logger = logging.getLogger(__name__)
        logging.basicConfig(level=logging.INFO)

    def ingest_report(self, data: Dict) -> str:
        report_id = str(uuid.uuid4())
        timestamp = datetime.datetime.now().isoformat()

        report = CrashReport(
            id=report_id,
            timestamp=timestamp,
            device_id=data.get('device_id', 'unknown'),
            os_version=data.get('os_version', 'unknown'),
            app_version=data.get('app_version', 'unknown'),
            stacktrace=data.get('stacktrace', ''),
            severity=data.get('severity', 'error'),
            metadata=data.get('metadata', {})
        )

        self.reports[report_id] = report
        self.logger.info(f"Received crash report: {report_id}")
        return report_id

    def get_report(self, report_id: str) -> Optional[CrashReport]:
        return self.reports.get(report_id)

    def search_reports(self, severity: str = None) -> List[CrashReport]:
        if severity:
            return [r for r in self.reports.values() if r.severity == severity]
        return list(self.reports.values())

app = Flask(__name__)
crash_system = CrashLogSystem()

