    return jsonify({'error': 'Report not found'}), 404

@app.route('/reports', methods=['GET'])
def get_reports():
    severity = request.args.get('severity')
    reports = crash_system.search_reports(severity)
    return jsonify([r.__dict__ for r in reports])

