    app.run(host='0.0.0.0', port=5000)

import zipfile
import tarfile
import py7zr
import rarfile
import os
from pathlib import Path

class ArchiveExtractor:
    def __init__(self, archive_path):
        self.archive_path = Path(archive_path)
        self.supported_formats = {
            '.zip': self._extract_zip,
            '.tar': self._extract_tar,
            '.tar.gz': self._extract_tar,
            '.tgz': self._extract_tar,
            '.7z': self._extract_7z,
            '.rar': self._extract_rar
        }

    def extract(self, dest_path):
        suffix = ''.join(self.archive_path.suffixes)
        if suffix in self.supported_formats:
            self.supported_formats[suffix](dest_path)
        else:
            raise ValueError(f"Unsupported archive format: {suffix}")

    def _extract_zip(self, dest_path):
        with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
            zip_ref.extractall(dest_path)

    def _extract_tar(self, dest_path):
        with tarfile.open(self.archive_path, 'r:*') as tar_ref:
            tar_ref.extractall(dest_path)

    def _extract_7z(self, dest_path):
        with py7zr.SevenZipFile(self.archive_path, 'r') as sz_ref:
            sz_ref.extractall(dest_path)

    def _extract_rar(self, dest_path):
        with rarfile.RarFile(self.archive_path, 'r') as rar_ref:
            rar_ref.extractall(dest_path)

    def list_contents(self):
        suffix = ''.join(self.archive_path.suffixes)
        if suffix == '.zip':
            with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
                return zip_ref.namelist()
        elif suffix in ['.tar', '.tar.gz', '.tgz']:
            with tarfile.open(self.archive_path, 'r:*') as tar_ref:
                return tar_ref.getnames()
        elif suffix == '.7z':
            with py7zr.SevenZipFile(self.archive_path, 'r') as sz_ref:
                return sz_ref.getnames()
        elif suffix == '.rar':
            with rarfile.RarFile(self.archive_path, 'r') as rar_ref:
                return rar_ref.namelist()
        else:
            raise ValueError(f"Unsupported archive format: {suffix}")

