import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
import concurrent.futures

class WebCrawler:
    def __init__(self, base_url):
        self.base_url = base_url
        self.domain = urlparse(base_url).netloc
        self.visited = set()
        self.broken_links = []
        self.missing_images = []
        self.session = requests.Session()

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and parsed.netloc.endswith(self.domain)

    def get_page_links(self, url):
        try:
            response = self.session.get(url, timeout=10)
            soup = BeautifulSoup(response.text, 'html.parser')

            links = []
            for a in soup.find_all('a', href=True):
                href = urljoin(url, a['href'])
                if self.is_valid_url(href):
                    links.append(href)

            images = []
            for img in soup.find_all('img', src=True):
                src = urljoin(url, img['src'])
                images.append(src)

            return links, images

        except Exception as e:
            self.broken_links.append((url, str(e)))
            return [], []

    def check_image(self, img_url):
        try:
            response = self.session.head(img_url, timeout=5)
            if response.status_code != 200:
                self.missing_images.append(img_url)
        except:
            self.missing_images.append(img_url)

    def crawl(self, url):
        if url in self.visited:
            return

        self.visited.add(url)
        links, images = self.get_page_links(url)

        with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
            executor.map(self.check_image, images)
            executor.map(self.crawl, links)

    def run(self):
        self.crawl(self.base_url)
        return {
            'broken_links': self.broken_links,
            'missing_images': self.missing_images
        }

if __name__ == '__main__':
    crawler = WebCrawler('https://example.com')
    results = crawler.run()

