        self.name = name
        self.category = category
        self.reviews: List[Review] = []

    def add_review(self, user_id: str, rating: int, comment: str) -> None:
        review = Review(user_id, rating, comment)
        self.reviews.append(review)

    @property
    def average_rating(self) -> float:
        if not self.reviews:
            return 0.0
        return sum(r.rating for r in self.reviews) / len(self.reviews)

class ReviewSystem:
    def __init__(self):
        self.items: Dict[str, Item] = {}

    def add_item(self, id: str, name: str, category: str) -> None:
        self.items[id] = Item(id, name, category)

    def add_review(self, item_id: str, user_id: str, rating: int, comment: str) -> None:
        if item_id in self.items:
            self.items[item_id].add_review(user_id, rating, comment)

    def get_top_rated(self, category: str = None, limit: int = 10) -> List[Item]:
        items = self.items.values()
