import json

class ArtifactManager:
    def __init__(self, base_path):
        self.base_path = Path(base_path)
        self.storage_path = self.base_path / 'artifacts'
        self.metadata_path = self.base_path / 'metadata.json'
        self.storage_path.mkdir(parents=True, exist_ok=True)
        self.metadata = self._load_metadata()

    def _load_metadata(self):
        if self.metadata_path.exists():
            with open(self.metadata_path, 'r') as f:
                return json.load(f)
        return {}

    def _save_metadata(self):
        with open(self.metadata_path, 'w') as f:
            json.dump(self.metadata, f, indent=2)

    def _calculate_hash(self, file_path):
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

    def store_artifact(self, file_path, name, version):
        file_hash = self._calculate_hash(file_path)
        dest_path = self.storage_path / file_hash

        shutil.copy2(file_path, dest_path)

        self.metadata[f"{name}-{version}"] = {
            'hash': file_hash,
            'name': name,
            'version': version,
            'path': str(dest_path)
        }
        self._save_metadata()
        return file_hash

    def get_artifact(self, name, version):
        key = f"{name}-{version}"
        if key in self.metadata:
            return Path(self.metadata[key]['path'])
        return None

    def list_artifacts(self):
        return list(self.metadata.keys())

    def delete_artifact(self, name, version):
        key = f"{name}-{version}"
        if key in self.metadata:
            path = Path(self.metadata[key]['path'])
            if path.exists():
                path.unlink()
            del self.metadata[key]
            self._save_metadata()
            return True
        return False

