import os
import json
import hashlib
from datetime import datetime
from dataclasses import dataclass
from typing import Dict, List

@dataclass
class FileMetadata:
    path: str
    permissions: int
    owner: str
    group: str
    last_modified: str
    checksum: str

class Repository:
    def __init__(self, path: str):
        self.repo_path = path
        self.metadata_file = os.path.join(path, '.metadata')
        self.metadata: Dict[str, List[FileMetadata]] = {}
        self._load_metadata()

    def _load_metadata(self):
        if os.path.exists(self.metadata_file):
            with open(self.metadata_file, 'r') as f:
                data = json.load(f)
                self.metadata = {
                    rev: [FileMetadata(**m) for m in meta]
                    for rev, meta in data.items()
                }

    def _save_metadata(self):
        with open(self.metadata_file, 'w') as f:
            json.dump({
                rev: [vars(m) for m in meta]
                for rev, meta in self.metadata.items()
            }, f)

    def commit(self, message: str) -> str:
        files_metadata = []
        revision = hashlib.sha1(datetime.now().isoformat().encode()).hexdigest()[:8]

        for root, _, files in os.walk(self.repo_path):
            for file in files:
                if file == '.metadata':
                    continue

                path = os.path.join(root, file)
                stat = os.stat(path)

                with open(path, 'rb') as f:
                    checksum = hashlib.sha1(f.read()).hexdigest()

                metadata = FileMetadata(
                    path=os.path.relpath(path, self.repo_path),
                    permissions=stat.st_mode,
                    owner=stat.st_uid,
                    group=stat.st_gid,
                    last_modified=datetime.fromtimestamp(stat.st_mtime).isoformat(),
                    checksum=checksum
                )
                files_metadata.append(metadata)

        self.metadata[revision] = files_metadata
        self._save_metadata()
        return revision

    def restore(self, revision: str):
        if revision not in self.metadata:
            raise ValueError(f"Revision {revision} not found")

        for file_meta in self.metadata[revision]:
            full_path = os.path.join(self.repo_path, file_meta.path)
            os.chmod(full_path, file_meta.permissions)
            os.chown(full_path, file_meta.owner, file_meta.group)

    def list_revisions(self) -> List[str]:
        return sorted(self.metadata.keys())

    def get_metadata(self, revision: str) -> List[FileMetadata]:
        return self.metadata.get(revision, [])
