def extract_zip(zip_path, extract_path):
    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        zip_ref.extractall(extract_path)

def extract_tar(tar_path, extract_path):
    with tarfile.open(tar_path, 'r:*') as tar_ref:
        tar_ref.extractall(extract_path)

def extract_rar(rar_path, extract_path):
    with rarfile.RarFile(rar_path) as rar_ref:
        rar_ref.extractall(extract_path)

def extract_archive(archive_path, extract_path):
    if not os.path.exists(extract_path):
        os.makedirs(extract_path)

    file_ext = os.path.splitext(archive_path)[1].lower()

    try:
        if file_ext in ['.zip']:
            extract_zip(archive_path, extract_path)
        elif file_ext in ['.tar', '.gz', '.bz2']:
            extract_tar(archive_path, extract_path)
        elif file_ext in ['.rar']:
            extract_rar(archive_path, extract_path)
        else:
            raise ValueError(f"Unsupported archive format: {file_ext}")

    except Exception as e:
        shutil.rmtree(extract_path)
        raise e

def list_archive_contents(archive_path):
    file_ext = os.path.splitext(archive_path)[1].lower()

    if file_ext in ['.zip']:
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            return zip_ref.namelist()

    elif file_ext in ['.tar', '.gz', '.bz2']:
