        dest = self.tools_dir / Path(toolchain_path).name
        shutil.copy2(toolchain_path, dest)
        os.chmod(dest, 0o755)

    def flash_image(self, image_path, device):
        if not os.path.exists(image_path):
            raise FileNotFoundError(f"Image not found: {image_path}")

        if not os.path.exists(device):
            raise FileNotFoundError(f"Device not found: {device}")

        subprocess.run(["dd", f"if={image_path}", f"of={device}", "bs=4M", "status=progress"])

    def verify_checksum(self, image_path, expected_sha256):
        if not os.path.exists(image_path):
            raise FileNotFoundError(f"Image not found: {image_path}")

        result = subprocess.run(["sha256sum", image_path], capture_output=True, text=True)
        actual_sha256 = result.stdout.split()[0]

