import os
from datetime import datetime
from pathlib import Path
import shutil
from PIL import Image
import hashlib

class PhotoOrganizer:
    def __init__(self, source_dir, dest_dir):
        self.source_dir = Path(source_dir)
        self.dest_dir = Path(dest_dir)
        self.supported_formats = {'.jpg', '.jpeg', '.png', '.gif', '.tiff'}

    def organize_photos(self):
        self.dest_dir.mkdir(parents=True, exist_ok=True)

        for file_path in self.source_dir.rglob('*'):
            if file_path.suffix.lower() in self.supported_formats:
                try:
                    image = Image.open(file_path)
                    exif = image._getexif()

                    if exif and 36867 in exif:
                        date_taken = datetime.strptime(exif[36867], '%Y:%m:%d %H:%M:%S')
                    else:
                        date_taken = datetime.fromtimestamp(file_path.stat().st_mtime)

                    year_month = date_taken.strftime('%Y/%m')
                    new_dir = self.dest_dir / year_month
                    new_dir.mkdir(parents=True, exist_ok=True)

                    file_hash = self._calculate_hash(file_path)
                    new_filename = f"{date_taken.strftime('%Y%m%d_%H%M%S')}_{file_hash[:8]}{file_path.suffix}"
                    new_path = new_dir / new_filename

                    if not new_path.exists():
                        shutil.copy2(file_path, new_path)

                finally:
                    image.close()

    def _calculate_hash(self, file_path):
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            buf = f.read(65536)
            while len(buf) > 0:
                hasher.update(buf)
                buf = f.read(65536)
        return hasher.hexdigest()

if __name__ == '__main__':
    organizer = PhotoOrganizer('./source_photos', './organized_photos')
    organizer.organize_photos()

