from email.message import EmailMessage

class AWSCostMonitor:
    def __init__(self, threshold_percent=10):
        self.client = boto3.client('ce')
        self.threshold = threshold_percent
        self.sns = boto3.client('sns')

    def get_cost_data(self, days=30):
        end_date = datetime.now().strftime('%Y-%m-%d')
        start_date = (datetime.now() - timedelta(days=days)).strftime('%Y-%m-%d')

        response = self.client.get_cost_and_usage(
            TimePeriod={
                'Start': start_date,
                'End': end_date
            },
            Granularity='DAILY',
            Metrics=['UnblendedCost'],
            GroupBy=[{'Type': 'DIMENSION', 'Key': 'SERVICE'}]
        )
        return response['ResultsByTime']

    def analyze_costs(self):
        costs = self.get_cost_data()
        previous_day = float(costs[-2]['Total']['UnblendedCost']['Amount'])
        current_day = float(costs[-1]['Total']['UnblendedCost']['Amount'])

        percent_change = ((current_day - previous_day) / previous_day) * 100

        if abs(percent_change) > self.threshold:
            self.send_alert(current_day, previous_day, percent_change)

    def send_alert(self, current_cost, previous_cost, percent_change):
        message = f"""
        AWS Cost Alert:
        Current Day Cost: ${current_cost:.2f}
        Previous Day Cost: ${previous_cost:.2f}
        Percent Change: {percent_change:.2f}%
        """

        self.sns.publish(
            TopicArn='YOUR_SNS_TOPIC_ARN',
            Subject='AWS Cost Alert',
            Message=message
        )

def lambda_handler(event, context):
    monitor = AWSCostMonitor()
    monitor.analyze_costs()
    return {
        'statusCode': 200,
        'body': json.dumps('Cost analysis completed')
    }

