import wave
import numpy as np
import os
from scipy.io import wavfile
from pathlib import Path

class SilenceTrimmer:
    def __init__(self, threshold=-50, min_silence_duration=0.5):
        self.threshold = threshold
        self.min_silence_duration = min_silence_duration
        self.output_permissions = 0o644

    def detect_silence(self, audio_data, sample_rate):
        if len(audio_data.shape) > 1:
            audio_data = audio_data.mean(axis=1)

        db = 20 * np.log10(np.abs(audio_data) + 1e-10)
        is_silence = db < self.threshold
        silence_regions = []

        silence_start = None
        for i, silent in enumerate(is_silence):
            if silent and silence_start is None:
                silence_start = i
            elif not silent and silence_start is not None:
                duration = (i - silence_start) / sample_rate
                if duration >= self.min_silence_duration:
                    silence_regions.append((silence_start, i))
                silence_start = None

        return silence_regions

    def trim_silence(self, input_path, output_path):
        sample_rate, audio_data = wavfile.read(input_path)
        silence_regions = self.detect_silence(audio_data, sample_rate)

        if not silence_regions:
            return False

        keep_regions = []
        last_end = 0
        for start, end in silence_regions:
            if start > last_end:
                keep_regions.append((last_end, start))
            last_end = end

        if last_end < len(audio_data):
            keep_regions.append((last_end, len(audio_data)))

        trimmed_audio = np.concatenate([audio_data[start:end] for start, end in keep_regions])
        wavfile.write(output_path, sample_rate, trimmed_audio)

        os.chmod(output_path, self.output_permissions)
        return True

    def process_directory(self, input_dir, output_dir):
        input_path = Path(input_dir)
        output_path = Path(output_dir)
        output_path.mkdir(parents=True, exist_ok=True)

        for audio_file in input_path.glob('*.wav'):
            output_file = output_path / f"trimmed_{audio_file.name}"
            self.trim_silence(str(audio_file), str(output_file))

if __name__ == "__main__":
    trimmer = SilenceTrimmer(threshold=-40, min_silence_duration=0.3)
    trimmer.process_directory("input_audio", "output_audio")

