class Stock:
    def __init__(self, symbol, current_price):
        self.symbol = symbol
        self.current_price = Decimal(str(current_price))

class Portfolio:
    def __init__(self):
        self.positions = {}
        self.cash = Decimal('0')
        self.alerts = {}

    def deposit(self, amount):
        self.cash += Decimal(str(amount))

    def buy(self, symbol, shares, price):
        cost = Decimal(str(shares)) * price
        if cost > self.cash:
            raise ValueError("Insufficient funds")

        if symbol not in self.positions:
            self.positions[symbol] = 0
        self.positions[symbol] += shares
        self.cash -= cost

    def sell(self, symbol, shares, price):
        if symbol not in self.positions or self.positions[symbol] < shares:
            raise ValueError("Insufficient shares")

        proceeds = Decimal(str(shares)) * price
        self.positions[symbol] -= shares
        self.cash += proceeds

        if self.positions[symbol] == 0:
            del self.positions[symbol]

    def set_alert(self, symbol, target_price, alert_type):
        alert_id = str(uuid.uuid4())
        self.alerts[alert_id] = {
            'symbol': symbol,
            'target_price': Decimal(str(target_price)), 
            'type': alert_type,
            'created_at': datetime.now()
        }
        return alert_id

    def check_alerts(self, symbol, current_price):
        triggered = []
        for alert_id, alert in self.alerts.items():
            if alert['symbol'] != symbol:
                continue

            if alert['type'] == 'above' and current_price >= alert['target_price']:
                triggered.append(alert_id)
            elif alert['type'] == 'below' and current_price <= alert['target_price']:
                triggered.append(alert_id)

        for alert_id in triggered:
            del self.alerts[alert_id]

        return triggered

    def get_position_value(self, symbol, current_price):
        if symbol not in self.positions:
            return Decimal('0')
        return Decimal(str(self.positions[symbol])) * current_price

    def get_total_value(self, prices):
        total = self.cash
        for symbol in self.positions:
            total += self.get_position_value(symbol, prices[symbol])
        return total
