import concurrent.futures

class LinkChecker:
    def __init__(self, base_url):
        self.base_url = base_url
        self.checked_links = set()
        self.broken_links = []

    def check_link(self, url):
        try:
            response = requests.head(url, allow_redirects=True, timeout=5)
            if response.status_code >= 400:
                self.broken_links.append((url, response.status_code))
        except requests.RequestException as e:
            self.broken_links.append((url, str(e)))

    def find_broken_links(self):
        try:
            response = requests.get(self.base_url)
            soup = BeautifulSoup(response.text, 'html.parser')
            links = soup.find_all('a')

            with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
                for link in links:
                    href = link.get('href')
                    if href and not href.startswith(('#', 'javascript:', 'mailto:')):
                        absolute_url = urljoin(self.base_url, href)
                        if absolute_url not in self.checked_links:
                            self.checked_links.add(absolute_url)
                            executor.submit(self.check_link, absolute_url)

            return self.broken_links
        except requests.RequestException as e:
            return [(self.base_url, str(e))]

if __name__ == '__main__':
