import os
import zipfile
from pathlib import Path
from datetime import datetime

def archive_files(source_dir, archive_name, patterns=None, min_size=0, max_age_days=None):
    source_path = Path(source_dir)
    archive_path = Path(archive_name)

    with zipfile.ZipFile(archive_path, 'w', zipfile.ZIP_DEFLATED) as archive:
        for root, _, files in os.walk(source_path):
            for file in files:
                file_path = Path(root) / file

                if patterns and not any(file.endswith(pat) for pat in patterns):
                    continue

                if file_path.stat().st_size < min_size:
                    continue

                if max_age_days:
                    file_age = (datetime.now() - datetime.fromtimestamp(file_path.stat().st_mtime)).days
                    if file_age > max_age_days:
                        continue

                rel_path = file_path.relative_to(source_path)
                archive.write(file_path, rel_path)

    return archive_path

