from urllib.parse import urlparse
import requests
import time
import json
import os

class WebArchiver:
    def __init__(self, excluded_subdomains=None):
        self.excluded_subdomains = set(excluded_subdomains or [])
        self.snapshots = {}

    def should_archive(self, url):
        parsed = urlparse(url)
        domain_parts = parsed.netloc.split('.')
        return not any(sub in domain_parts for sub in self.excluded_subdomains)

    def take_snapshot(self, url):
        if not self.should_archive(url):
            return None

        try:
            response = requests.get(url, timeout=30)
            timestamp = int(time.time())
            snapshot = {
                'url': url,
                'timestamp': timestamp,
                'content': response.text,
                'status_code': response.status_code,
                'headers': dict(response.headers)
            }
            self.snapshots[f"{url}_{timestamp}"] = snapshot
            return snapshot
        except requests.RequestException:
            return None

    def save_snapshots(self, filepath):
        with open(filepath, 'w') as f:
            json.dump(self.snapshots, f)

    def load_snapshots(self, filepath):
        if os.path.exists(filepath):
            with open(filepath, 'r') as f:
                self.snapshots = json.load(f)

