from pathlib import Path

class Builder:
    def __init__(self, source_dir, build_dir):
        self.source_dir = Path(source_dir)
        self.build_dir = Path(build_dir)
        self.build_dir.mkdir(exist_ok=True)

    def compile_source(self, source_file):
        output_file = self.build_dir / source_file.stem
        try:
            subprocess.run(['gcc', str(source_file), '-o', str(output_file)], 
                         check=True, 
                         capture_output=True)
            return True
        except subprocess.CalledProcessError:
            return False

    def build_all(self):
        results = {}
        for source_file in self.source_dir.glob('*.c'):
            results[source_file.name] = self.compile_source(source_file)
        return results

    def clean(self):
        for file in self.build_dir.iterdir():
            if file.is_file():
                file.unlink()

if __name__ == '__main__':
