import os
import zipfile
import shutil
import sys
from pathlib import Path

class JarBuilder:
    def __init__(self, output_jar):
        self.output_jar = output_jar
        self.classpath = os.getenv('CLASSPATH', '').split(os.pathsep)
        self.temp_dir = Path('temp_build')

    def collect_dependencies(self):
        self.temp_dir.mkdir(exist_ok=True)
        for path in self.classpath:
            if not path:
                continue
            path = Path(path)
            if path.suffix == '.jar':
                with zipfile.ZipFile(path, 'r') as jar:
                    jar.extractall(self.temp_dir)
            elif path.is_dir():
                shutil.copytree(path, self.temp_dir / path.name, dirs_exist_ok=True)

    def build_jar(self):
        with zipfile.ZipFile(self.output_jar, 'w') as jar:
            for root, _, files in os.walk(self.temp_dir):
                for file in files:
                    full_path = Path(root) / file
                    archive_path = full_path.relative_to(self.temp_dir)
                    jar.write(full_path, archive_path)

    def cleanup(self):
        shutil.rmtree(self.temp_dir)

    def create(self):
        try:
            self.collect_dependencies()
            self.build_jar()
        finally:
            self.cleanup()

if __name__ == '__main__':
    builder = JarBuilder('output.jar')
    builder.create()

