        return [rsvp for rsvp in self.rsvps.values() if rsvp.attending]

    def get_total_guests(self) -> int:
        return sum(rsvp.guests for rsvp in self.rsvps.values() if rsvp.attending)

    def update_rsvp(self, email: str, attending: bool, guests: int) -> bool:
        if email in self.rsvps:
            rsvp = self.rsvps[email]
            rsvp.attending = attending
            rsvp.guests = guests
            rsvp.timestamp = datetime.now()
            return True
        return False

