class SharedDrive:
    def __init__(self, root_path: str):
        self.root = Path(root_path)
        self.root.mkdir(parents=True, exist_ok=True)
        self.permissions = {}

    def upload_file(self, file_path: str, user_id: str) -> bool:
        try:
            source = Path(file_path)
            destination = self.root / source.name
            shutil.copy2(source, destination)
            self._log_activity(user_id, f"Uploaded {source.name}")
            return True
        except Exception:
            return False

    def create_folder(self, folder_name: str, user_id: str) -> bool:
        try:
            new_folder = self.root / folder_name
            new_folder.mkdir(exist_ok=False)
            self._log_activity(user_id, f"Created folder {folder_name}")
            return True
        except Exception:
            return False

    def list_contents(self) -> List[Dict]:
        contents = []
        for item in self.root.iterdir():
            contents.append({
                'name': item.name,
                'type': 'folder' if item.is_dir() else 'file',
                'size': os.path.getsize(item) if item.is_file() else 0,
                'modified': datetime.fromtimestamp(os.path.getmtime(item))
            })
        return contents

    def delete_item(self, item_name: str, user_id: str) -> bool:
        try:
            item_path = self.root / item_name
            if item_path.is_file():
                item_path.unlink()
            else:
                shutil.rmtree(item_path)
            self._log_activity(user_id, f"Deleted {item_name}")
            return True
        except Exception:
            return False

    def _log_activity(self, user_id: str, action: str):
        log_file = self.root / 'activity.log'
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        with open(log_file, 'a') as f:
            f.write(f"{timestamp} - User {user_id}: {action}\n")

    def set_permissions(self, user_id: str, permissions: List[str]):
        self.permissions[user_id] = permissions

    def has_permission(self, user_id: str, permission: str) -> bool:
        return permission in self.permissions.get(user_id, [])

