from concurrent.futures import ThreadPoolExecutor
from typing import Callable

logging.basicConfig(
    filename='task_logs.log',
    level=logging.INFO,
    format='%(asctime)s - %(levelname)s - %(message)s'
)

class JobScheduler:
    def __init__(self):
        self.jobs = {}
        self.executor = ThreadPoolExecutor(max_workers=10)

    def add_job(self, name: str, func: Callable, interval: str):
        try:
            logging.info(f"Adding job: {name}")
            self.jobs[name] = func

            if interval.startswith('every_'):
                schedule.every().day.at(interval.split('_')[1]).do(
                    self._execute_job, name, func)
            else:
                minutes = int(interval)
                schedule.every(minutes).minutes.do(
                    self._execute_job, name, func)

        except Exception as e:
            logging.error(f"Error adding job {name}: {str(e)}")

    def _execute_job(self, name: str, func: Callable):
        try:
            logging.info(f"Executing job: {name}")
            future = self.executor.submit(func)
            result = future.result(timeout=300)
            logging.info(f"Job {name} completed successfully: {result}")
            return result

        except Exception as e:
            logging.error(f"Error executing job {name}: {str(e)}")

    def start(self):
        logging.info("Starting scheduler")
        while True:
            schedule.run_pending()
            time.sleep(1)

    def remove_job(self, name: str):
        if name in self.jobs:
            logging.info(f"Removing job: {name}")
            schedule.clear(name)
            del self.jobs[name]

def sample_task():
    return f"Task executed at {datetime.datetime.now()}"

if __name__ == "__main__":
    scheduler = JobScheduler()

    # Add sample jobs
    scheduler.add_job("daily_job", sample_task, "every_10:00")
    scheduler.add_job("interval_job", sample_task, "5")

    try:
        scheduler.start()
    except KeyboardInterrupt:
        logging.info("Shutting down scheduler")
        scheduler.executor.shutdown()
