class TaxCalculator:
    def __init__(self):
        self.standard_deduction = 12950
        self.tax_brackets = {
            10: 10275,
            12: 41775,
            22: 89075,
            24: 170050,
            32: 215950,
            35: 539900,
            37: float('inf')
        }

    def calculate_tax(self, income, deductions=None, credits=None):
        if deductions is None:
            deductions = []
        if credits is None:
            credits = []

        total_deductions = sum(deductions) + self.standard_deduction
        taxable_income = max(0, income - total_deductions)

        tax_owed = 0
        previous_bracket = 0

        for rate, bracket in self.tax_brackets.items():
            if taxable_income > previous_bracket:
                taxable_amount = min(taxable_income - previous_bracket, bracket - previous_bracket)
                tax_owed += taxable_amount * (rate / 100)
            previous_bracket = bracket

        tax_owed = max(0, tax_owed - sum(credits))
        return round(tax_owed, 2)

    def generate_tax_report(self, income, deductions, credits):
        tax_owed = self.calculate_tax(income, deductions, credits)
        taxable_income = income - sum(deductions) - self.standard_deduction
        return {
            'gross_income': income,
            'total_deductions': sum(deductions) + self.standard_deduction,
            'taxable_income': taxable_income,
            'total_credits': sum(credits),
            'tax_owed': tax_owed
        }

