import argparse
import sys
from pathlib import Path

def concatenate_files(input_files, output_file):
    with open(output_file, 'wb') as outfile:
        for file_path in input_files:
            try:
                with open(file_path, 'rb') as infile:
                    while chunk := infile.read(8192):
                        outfile.write(chunk)
            except IOError as e:
                print(f"Error processing {file_path}: {e}", file=sys.stderr)

def main():
    parser = argparse.ArgumentParser(description='Concatenate multiple files')
    parser.add_argument('files', nargs='+', help='Input files to concatenate')
    parser.add_argument('-o', '--output', required=True, help='Output file')
    args = parser.parse_args()

    try:
        concatenate_files(args.files, args.output)
    except IOError as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

