import zipfile
import os
import shutil
from pathlib import Path

def import_3d_designs(zip_path, output_dir):
    supported_formats = {'.stl', '.obj', '.3mf', '.gcode'}

    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        for file_info in zip_ref.filelist:
            if not file_info.filename.startswith('__MACOSX') and Path(file_info.filename).suffix.lower() in supported_formats:
                zip_ref.extract(file_info, output_dir)

    extracted_files = []
    for root, _, files in os.walk(output_dir):
        for file in files:
            if Path(file).suffix.lower() in supported_formats:
                file_path = os.path.join(root, file)
                final_path = os.path.join(output_dir, file)
                if file_path != final_path:
                    shutil.move(file_path, final_path)
                extracted_files.append(final_path)

    for root, dirs, _ in os.walk(output_dir, topdown=False):
        for dir_name in dirs:
            dir_path = os.path.join(root, dir_name)
            if not os.listdir(dir_path):
                os.rmdir(dir_path)

    return extracted_files

