from datetime import datetime
from pathlib import Path

class VersionControl:
    def __init__(self, root_path):
        self.root_path = Path(root_path)
        self.repo_path = self.root_path / '.vcrepo'
        self.objects_path = self.repo_path / 'objects'
        self.checkout_path = self.repo_path / 'checkout'
        self._init_repo()

    def _init_repo(self):
        self.repo_path.mkdir(exist_ok=True)
        self.objects_path.mkdir(exist_ok=True)
        self.checkout_path.mkdir(exist_ok=True)

    def _calculate_hash(self, content):
        return hashlib.sha256(content.encode()).hexdigest()

    def checkout(self, file_path):
        file_path = Path(file_path)
        checkout_file = self.checkout_path / file_path.name
        with open(checkout_file, 'w') as f:
            f.write(json.dumps({
                'path': str(file_path),
                'timestamp': datetime.now().isoformat(),
                'status': 'checked_out'
            }))
        return str(checkout_file)

    def commit(self, file_path, content):
        file_hash = self._calculate_hash(content)
        obj_path = self.objects_path / file_hash

        with open(obj_path, 'w') as f:
            f.write(content)

        checkout_file = self.checkout_path / Path(file_path).name
        if checkout_file.exists():
            checkout_file.unlink()

        return file_hash

    def get_version(self, file_hash):
        obj_path = self.objects_path / file_hash
        if obj_path.exists():
            with open(obj_path, 'r') as f:
                return f.read()
        return None

    def list_checkouts(self):
        checkouts = []
        for checkout_file in self.checkout_path.glob('*'):
            with open(checkout_file, 'r') as f:
                checkouts.append(json.loads(f.read()))
        return checkouts

