class DistributedKeyValueStore:
    def __init__(self, replication_factor=3):
        self.store = {}
        self.replicas = {}
        self.replication_factor = replication_factor
        self.nodes = set()

    def add_node(self, node_id):
        self.nodes.add(node_id)
        self.rebalance()

    def remove_node(self, node_id):
        self.nodes.remove(node_id)
        self.rebalance()

    def put(self, key, value):
        primary = self.get_primary_node(key)
        self.store[key] = value
        replica_nodes = self.get_replica_nodes(key)
        for node in replica_nodes:
            self.replicas.setdefault(node, {})[key] = value
        return True

    def get(self, key):
        if key in self.store:
            return self.store[key]
        for replicas in self.replicas.values():
            if key in replicas:
                return replicas[key]
        raise KeyError(f"Key {key} not found")

    def rebalance(self):
        if not self.nodes:
            return
        new_store = {}
        for key, value in self.store.items():
            primary = self.get_primary_node(key)
            new_store[key] = value
        self.store = new_store
        self.replicas = {}
        for key, value in self.store.items():
            replica_nodes = self.get_replica_nodes(key)
            for node in replica_nodes:
                self.replicas.setdefault(node, {})[key] = value

    def get_primary_node(self, key):
        if not self.nodes:
            return None
        nodes_list = sorted(list(self.nodes))
        return nodes_list[hash(key) % len(nodes_list)]

    def get_replica_nodes(self, key):
        if not self.nodes:
            return set()
        nodes_list = sorted(list(self.nodes))
        primary = self.get_primary_node(key)
        primary_index = nodes_list.index(primary)
        replicas = set()
        for i in range(1, min(self.replication_factor, len(nodes_list))):
            replica_index = (primary_index + i) % len(nodes_list)
            replicas.add(nodes_list[replica_index])
        return replicas

