import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
from collections import defaultdict

class WebCrawler:
    def __init__(self, start_url):
        self.start_url = start_url
        self.domain = urlparse(start_url).netloc
        self.visited = set()
        self.site_map = defaultdict(list)

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and parsed.netloc == self.domain

    def crawl(self, url, depth=3):
        if depth == 0 or url in self.visited:
            return

        self.visited.add(url)

        try:
            response = requests.get(url, timeout=5)
            soup = BeautifulSoup(response.text, 'html.parser')

            for link in soup.find_all('a'):
                href = link.get('href')
                if href:
                    absolute_url = urljoin(url, href)
                    if self.is_valid_url(absolute_url):
                        self.site_map[url].append(absolute_url)
                        self.crawl(absolute_url, depth-1)

        except Exception as e:
            print(f"Error crawling {url}: {e}")

    def get_site_map(self):
        self.crawl(self.start_url)
        return dict(self.site_map)

if __name__ == "__main__":
