    recommendations = []
    for idx, score in enumerate(similarities[0]):
        if score > 0.1:
            product_id = list(products.keys())[idx]
            recommendations.append({
                'id': product_id,
                'name': products[product_id]['name'],
                'score': float(score)
            })

