import os
import sys
from pathlib import Path
import shutil

def scan_large_files(start_path, size_threshold_mb=100):
    large_files = []
    size_threshold = size_threshold_mb * 1024 * 1024

    for root, dirs, files in os.walk(start_path):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                size = os.path.getsize(file_path)
                if size > size_threshold:
                    large_files.append({
                        'path': file_path,
                        'size': size,
                        'size_mb': round(size/1024/1024, 2)
                    })
            except (OSError, PermissionError):
                continue

    return large_files

def handle_large_file(file_info, action='list', permissions=None):
    if action == 'list':
        print(f"File: {file_info['path']}")
        print(f"Size: {file_info['size_mb']} MB")

    elif action == 'delete':
        try:
            os.remove(file_info['path'])
            print(f"Deleted {file_info['path']}")
        except PermissionError:
            print(f"Permission denied: {file_info['path']}")

    elif action == 'chmod':
        try:
            os.chmod(file_info['path'], permissions)
            print(f"Changed permissions for {file_info['path']}")
        except PermissionError:
            print(f"Permission denied: {file_info['path']}")

def main():
    if len(sys.argv) < 3:
        print("Usage: script.py <directory> <size_threshold_mb> [action] [permissions]")
        sys.exit(1)

    directory = sys.argv[1]
    threshold = int(sys.argv[2])
    action = sys.argv[3] if len(sys.argv) > 3 else 'list'
    permissions = int(sys.argv[4], 8) if len(sys.argv) > 4 else None

    large_files = scan_large_files(directory, threshold)

    for file_info in large_files:
        handle_large_file(file_info, action, permissions)

    print(f"\nFound {len(large_files)} files larger than {threshold}MB")

if __name__ == '__main__':
    main()
