import uuid

class NotebookState:
    def __init__(self, name):
        self.id = str(uuid.uuid4())
        self.name = name
        self.created_at = datetime.now()
        self.cells = []
        self.metadata = {}
        self.outputs = {}
        self.workspace_path = Path("workspace")
        self.workspace_path.mkdir(exist_ok=True)

    def add_cell(self, cell_type, content):
        cell_id = str(uuid.uuid4())
        cell = {
            "id": cell_id,
            "type": cell_type,
            "content": content,
            "created_at": datetime.now()
        }
        self.cells.append(cell)
        return cell_id

    def add_output(self, cell_id, output):
        self.outputs[cell_id] = {
            "content": output,
            "timestamp": datetime.now()
        }

    def update_metadata(self, key, value):
        self.metadata[key] = {
            "value": value,
            "updated_at": datetime.now()
        }

    def save(self):
        state = {
            "id": self.id,
            "name": self.name,
            "created_at": self.created_at,
            "cells": self.cells,
            "metadata": self.metadata,
            "outputs": self.outputs
        }

        save_path = self.workspace_path / f"{self.id}.pkl"
        with open(save_path, "wb") as f:
            pickle.dump(state, f)

    @classmethod
    def load(cls, notebook_id):
        workspace_path = Path("workspace")
        load_path = workspace_path / f"{notebook_id}.pkl"

        with open(load_path, "rb") as f:
            state = pickle.load(f)

        notebook = cls(state["name"])
        notebook.id = state["id"]
        notebook.created_at = state["created_at"]
        notebook.cells = state["cells"]
        notebook.metadata = state["metadata"]
        notebook.outputs = state["outputs"]

        return notebook

    def export_json(self):
        state = {
            "id": self.id,
            "name": self.name,
            "created_at": str(self.created_at),
            "cells": self.cells,
            "metadata": self.metadata,
            "outputs": self.outputs
        }
        return json.dumps(state, indent=2)
