    def __init__(self):
        self.supported_images = ['.jpg', '.jpeg', '.png', '.tiff']

    def extract_image_metadata(self, filepath):
        metadata = {}

        # Basic file metadata
        metadata['filename'] = os.path.basename(filepath)
        metadata['filesize'] = os.path.getsize(filepath)
        metadata['created'] = datetime.fromtimestamp(os.path.getctime(filepath))
        metadata['modified'] = datetime.fromtimestamp(os.path.getmtime(filepath))

        # Image specific metadata
        if os.path.splitext(filepath)[1].lower() in self.supported_images:
            # PIL metadata
            with Image.open(filepath) as img:
                metadata['dimensions'] = img.size
                metadata['mode'] = img.mode
                metadata['format'] = img.format

            # EXIF metadata
            image = pyexiv2.Image(filepath)
            exif = image.read_exif()
            metadata['exif'] = {}

            if exif:
                metadata['exif']['camera'] = exif.get('Exif.Image.Model')
                metadata['exif']['datetime'] = exif.get('Exif.Image.DateTime') 
                metadata['exif']['exposure'] = exif.get('Exif.Photo.ExposureTime')
                metadata['exif']['focal_length'] = exif.get('Exif.Photo.FocalLength')
                metadata['exif']['iso'] = exif.get('Exif.Photo.ISOSpeedRatings')
                metadata['exif']['aperture'] = exif.get('Exif.Photo.FNumber')

            # GPS data if available
            gps = image.read_gps()
            if gps:
                metadata['gps'] = {
                    'latitude': gps.get('latitude'),
                    'longitude': gps.get('longitude'),
                    'altitude': gps.get('altitude')
                }

        return metadata

    def process_directory(self, directory):
