def find_duplicates(directory):
    hash_map = defaultdict(list)
    for root, _, files in os.walk(directory):
        for filename in files:
            filepath = os.path.join(root, filename)
            file_hash = calculate_file_hash(filepath)
            hash_map[file_hash].append(filepath)
    return {k: v for k, v in hash_map.items() if len(v) > 1}

def delete_duplicates(duplicates, keep_newest=True):
    for hash_value, file_list in duplicates.items():
        sorted_files = sorted(file_list, key=os.path.getmtime, reverse=keep_newest)
        for file_to_remove in sorted_files[1:]:
            os.remove(file_to_remove)
        os.chmod(sorted_files[0], 0o644)

def analyze_disk_space(directory):
    total_size = 0
    file_sizes = {}
    duplicates = find_duplicates(directory)

    for root, _, files in os.walk(directory):
        for filename in files:
            filepath = os.path.join(root, filename)
            size = os.path.getsize(filepath)
            total_size += size
            file_sizes[filepath] = size

    return {
        'total_size': total_size,
        'duplicates': duplicates,
        'file_sizes': file_sizes
    }

def backup_file(filepath):
    backup_path = f"{filepath}.bak"
    shutil.copy2(filepath, backup_path)
    return backup_path

if __name__ == "__main__":
    target_directory = "/path/to/analyze"
    analysis = analyze_disk_space(target_directory)
    duplicates = analysis['duplicates']

    if duplicates:
        delete_duplicates(duplicates)

