import requests
import pandas as pd
import os
from urllib.parse import urljoin
from bs4 import BeautifulSoup
import hashlib
import logging

class DatasetCurator:
    def __init__(self, output_dir="datasets"):
        self.output_dir = output_dir
        os.makedirs(output_dir, exist_ok=True)
        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger(__name__)

    def download_dataset(self, url, filename=None):
        try:
            response = requests.get(url, stream=True)
            response.raise_for_status()

            if not filename:
                filename = hashlib.md5(url.encode()).hexdigest()[:10] + '.csv'

            filepath = os.path.join(self.output_dir, filename)

            with open(filepath, 'wb') as f:
                for chunk in response.iter_content(chunk_size=8192):
                    f.write(chunk)

            return filepath
        except Exception as e:
            self.logger.error(f"Failed to download {url}: {str(e)}")
            return None

    def search_kaggle_datasets(self, keyword):
        base_url = "https://www.kaggle.com/datasets"
        datasets = []

        try:
            response = requests.get(f"{base_url}/search?q={keyword}")
            response.raise_for_status()

            soup = BeautifulSoup(response.text, 'html.parser')
            dataset_links = soup.find_all('a', {'class': 'dataset-link'})

            for link in dataset_links:
                datasets.append({
                    'title': link.text.strip(),
                    'url': urljoin(base_url, link['href'])
                })

        except Exception as e:
            self.logger.error(f"Failed to search Kaggle: {str(e)}")

        return datasets

    def process_dataset(self, filepath):
        try:
            df = pd.read_csv(filepath)
            processed_path = filepath.replace('.csv', '_processed.csv')

            # Basic preprocessing
            df = df.dropna()
            df = df.drop_duplicates()

            df.to_csv(processed_path, index=False)
            return processed_path
        except Exception as e:
            self.logger.error(f"Failed to process {filepath}: {str(e)}")
            return None

    def run(self, keywords):
        for keyword in keywords:
            self.logger.info(f"Searching for datasets with keyword: {keyword}")
            datasets = self.search_kaggle_datasets(keyword)

            for dataset in datasets:
                self.logger.info(f"Downloading dataset: {dataset['title']}")
                filepath = self.download_dataset(dataset['url'])

                if filepath:
                    self.logger.info(f"Processing dataset: {filepath}")
                    processed_path = self.process_dataset(filepath)

                    if processed_path:
                        self.logger.info(f"Successfully processed dataset: {processed_path}")

if __name__ == "__main__":
    curator = DatasetCurator()
    curator.run(['machine learning', 'data science'])

