import zipfile
import os
import shutil
from pathlib import Path

def repair_zip(corrupt_path, output_dir):
    temp_dir = Path("temp_repair")
    temp_dir.mkdir(exist_ok=True)

    try:
        with zipfile.ZipFile(corrupt_path, 'r') as archive:
            for file_info in archive.filelist:
                try:
                    archive.extract(file_info, temp_dir)
                except:
                    continue

        repaired_path = Path(output_dir) / "repaired.zip"
        with zipfile.ZipFile(repaired_path, 'w', zipfile.ZIP_DEFLATED) as new_zip:
            for file_path in temp_dir.rglob('*'):
                if file_path.is_file():
                    new_zip.write(file_path, file_path.relative_to(temp_dir))

        return repaired_path

    except Exception as e:
        raise Exception(f"Failed to repair archive: {str(e)}")

    finally:
        shutil.rmtree(temp_dir, ignore_errors=True)

