import threading
import time
import queue
import uuid
from dataclasses import dataclass
from typing import Dict, List, Callable

@dataclass
class Job:
    id: str
    task: Callable
    status: str
    result: any = None
    retries: int = 0

class ClusterNode:
    def __init__(self, node_id: str):
        self.node_id = node_id
        self.is_active = True
        self.job_queue = queue.Queue()
        self.current_job = None
        self._worker = threading.Thread(target=self._process_jobs, daemon=True)
        self._worker.start()

    def _process_jobs(self):
        while self.is_active:
            try:
                job = self.job_queue.get(timeout=1)
                self.current_job = job
                job.status = "running"
                job.result = job.task()
                job.status = "completed"
            except queue.Empty:
                continue
            except Exception as e:
                if self.current_job:
                    self.current_job.status = "failed"
                    self.current_job.result = str(e)

class ClusterManager:
    def __init__(self, num_nodes: int = 3):
        self.nodes: Dict[str, ClusterNode] = {}
        self.jobs: Dict[str, Job] = {}
        self.failover_threshold = 3

        for _ in range(num_nodes):
            node_id = str(uuid.uuid4())
            self.nodes[node_id] = ClusterNode(node_id)

        self._health_check = threading.Thread(target=self._monitor_nodes, daemon=True)
        self._health_check.start()

    def submit_job(self, task: Callable) -> str:
        job_id = str(uuid.uuid4())
        job = Job(id=job_id, task=task, status="pending")
        self.jobs[job_id] = job

        available_nodes = [n for n in self.nodes.values() if n.is_active]
        if not available_nodes:
            raise RuntimeError("No available nodes")

        # Simple round-robin scheduling
        target_node = min(available_nodes, key=lambda n: n.job_queue.qsize())
        target_node.job_queue.put(job)
        return job_id

    def get_job_status(self, job_id: str) -> dict:
        job = self.jobs.get(job_id)
        if not job:
            raise KeyError(f"Job {job_id} not found")
        return {
            "id": job.id,
            "status": job.status,
            "result": job.result,
            "retries": job.retries
        }

    def _monitor_nodes(self):
        while True:
            for node_id, node in self.nodes.items():
                if not node.is_active and node.current_job:
                    self._handle_node_failure(node)
            time.sleep(5)

    def _handle_node_failure(self, failed_node: ClusterNode):
        job = failed_node.current_job
        if job and job.retries < self.failover_threshold:
            job.retries += 1
            job.status = "pending"
            available_nodes = [n for n in self.nodes.values() 
                             if n.is_active and n.node_id != failed_node.node_id]

            if available_nodes:
                target_node = min(available_nodes, key=lambda n: n.job_queue.qsize())
                target_node.job_queue.put(job)

    def shutdown(self):
        for node in self.nodes.values():
            node.is_active = False
