import json
from pathlib import Path

class ModManager:
    def __init__(self, game_path):
        self.game_path = Path(game_path)
        self.mods_path = self.game_path / "mods"
        self.mod_registry = {}
        self._load_registry()

    def _load_registry(self):
        registry_file = self.mods_path / "registry.json"
        if registry_file.exists():
            with open(registry_file) as f:
                self.mod_registry = json.load(f)

    def _save_registry(self):
        registry_file = self.mods_path / "registry.json"
        with open(registry_file, 'w') as f:
            json.dump(self.mod_registry, f)

    def download_mod(self, mod_url, mod_name):
        response = requests.get(mod_url, stream=True)
        mod_zip = self.mods_path / f"{mod_name}.zip"

        with open(mod_zip, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        return mod_zip

    def install_mod(self, mod_zip_path, mod_name):
        extract_path = self.mods_path / mod_name

        with zipfile.ZipFile(mod_zip_path, 'r') as zip_ref:
            zip_ref.extractall(extract_path)

        self.mod_registry[mod_name] = {
            "installed": True,
            "path": str(extract_path),
            "enabled": True
        }
        self._save_registry()

    def enable_mod(self, mod_name):
        if mod_name in self.mod_registry:
            self.mod_registry[mod_name]["enabled"] = True
            self._save_registry()

    def disable_mod(self, mod_name):
        if mod_name in self.mod_registry:
            self.mod_registry[mod_name]["enabled"] = False
            self._save_registry()

    def list_mods(self):
        return self.mod_registry

def main():
    mod_manager = ModManager("/path/to/game")

    # Example usage
    mod_url = "https://example.com/cool-mod.zip"
    mod_name = "cool-mod"

    try:
        print(f"Downloading {mod_name}...")
        mod_zip = mod_manager.download_mod(mod_url, mod_name)

        print(f"Installing {mod_name}...")
        mod_manager.install_mod(mod_zip, mod_name)

        print("Installed mods:")
        for name, info in mod_manager.list_mods().items():
            status = "enabled" if info["enabled"] else "disabled"
            print(f"- {name} ({status})")

    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    main()
