import os
import hashlib
import shutil
import json
from pathlib import Path

class ArtifactManager:
    def __init__(self, storage_path):
        self.storage_path = Path(storage_path)
        self.index_file = self.storage_path / 'index.json'
        self.artifacts_dir = self.storage_path / 'artifacts'
        self.artifacts_dir.mkdir(parents=True, exist_ok=True)
        self._load_index()

    def _load_index(self):
        if self.index_file.exists():
            with open(self.index_file, 'r') as f:
                self.index = json.load(f)
        else:
            self.index = {}

    def _save_index(self):
        with open(self.index_file, 'w') as f:
            json.dump(self.index, f, indent=2)

    def _calculate_hash(self, file_path):
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

    def store_artifact(self, file_path, metadata=None):
        file_hash = self._calculate_hash(file_path)
        target_path = self.artifacts_dir / file_hash

        if not target_path.exists():
            shutil.copy2(file_path, target_path)

        self.index[file_hash] = {
            'original_name': os.path.basename(file_path),
            'size': os.path.getsize(file_path),
            'metadata': metadata or {}
        }
        self._save_index()
        return file_hash

    def get_artifact(self, artifact_hash):
        if artifact_hash in self.index:
            artifact_path = self.artifacts_dir / artifact_hash
            if artifact_path.exists():
                return str(artifact_path)
        return None

    def list_artifacts(self):
        return self.index

    def remove_artifact(self, artifact_hash):
        if artifact_hash in self.index:
            artifact_path = self.artifacts_dir / artifact_hash
            if artifact_path.exists():
                artifact_path.unlink()
            del self.index[artifact_hash]
            self._save_index()
            return True
        return False

