    for root, dirs, files in os.walk(path, topdown=False):
        for name in files:
            filepath = os.path.join(root, name)
            file_time = os.path.getmtime(filepath)
            if current_time - file_time > 86400:  # 24 hours
                try:
                    os.remove(filepath)
                except OSError:
                    continue

