class TripDatabase:
    def __init__(self):
        self.trips = {}
        self.next_id = 1

    def add_trip(self, trip_data):
        trip = Trip(id=self.next_id, **trip_data)
        self.trips[self.next_id] = trip
        self.next_id += 1
        return trip.id

    def search_trips(self, filters):
        results = self.trips.values()

        if 'location' in filters:
            results = [t for t in results if filters['location'].lower() in t.location.lower()]

        if 'min_date' in filters:
            results = [t for t in results if t.start_date >= filters['min_date']]

        if 'max_price' in filters:
            results = [t for t in results if t.price <= filters['max_price']]

        if 'activities' in filters:
            results = [t for t in results if any(a in t.activities for a in filters['activities'])]

        if 'terrain' in filters:
            results = [t for t in results if t.terrain_type == filters['terrain']]

        if 'min_spots' in filters:
            results = [t for t in results if t.available_spots >= filters['min_spots']]

        return list(results)

