class CodeAnalyzer:
    def __init__(self, file_path: str):
        self.file_path = Path(file_path)
        self.single_comment_pattern = re.compile(r'^\s*#.*$')
        self.block_start_pattern = re.compile(r'^\s*""".*')
        self.block_end_pattern = re.compile(r'.*"""\s*$')

    def analyze(self) -> CommentMetrics:
        total_lines = 0
        code_lines = 0
        single_comments = 0
        block_comments = 0
        in_block = False

        with open(self.file_path, 'r') as f:
            for line in f:
                total_lines += 1
                stripped = line.strip()

                if not stripped:
                    continue

                if self.single_comment_pattern.match(stripped):
                    single_comments += 1
                elif self.block_start_pattern.match(stripped):
                    in_block = True
                    block_comments += 1
                elif self.block_end_pattern.match(stripped) and in_block:
                    in_block = False
                    block_comments += 1
                elif in_block:
                    block_comments += 1
                else:
                    code_lines += 1

        comment_density = (single_comments + block_comments) / total_lines if total_lines > 0 else 0

        return CommentMetrics(
            total_lines=total_lines,
            code_lines=code_lines,
            single_comments=single_comments,
            block_comments=block_comments,
            comment_density=comment_density
        )

def write_report(metrics: CommentMetrics, output_file: str = None, permissions: int = 0o644):
    report = f"""Code Analysis Report
-------------------
Total Lines: {metrics.total_lines}
Code Lines: {metrics.code_lines}
Single-line Comments: {metrics.single_comments}
Block Comments: {metrics.block_comments}
Comment Density: {metrics.comment_density:.2%}
"""

    if output_file:
        with open(output_file, 'w') as f:
            f.write(report)
        os.chmod(output_file, permissions)
    else:
        sys.stdout.write(report)

def main():
    if len(sys.argv) < 2:
        print("Usage: analyze_comments.py <file_path> [output_file]")
        sys.exit(1)

    source_file = sys.argv[1]
    output_file = sys.argv[2] if len(sys.argv) > 2 else None

    analyzer = CodeAnalyzer(source_file)
    metrics = analyzer.analyze()
    write_report(metrics, output_file)

if __name__ == '__main__':
    main()

