import os
import zipfile
import tarfile
import gzip
import bz2
import shutil
from pathlib import Path

class ArchiveExtractor:
    def __init__(self, archive_path):
        self.archive_path = Path(archive_path)
        self.supported_formats = {
            '.zip': self._extract_zip,
            '.tar': self._extract_tar,
            '.tar.gz': self._extract_tar,
            '.tgz': self._extract_tar,
            '.tar.bz2': self._extract_tar,
            '.gz': self._extract_gzip,
            '.bz2': self._extract_bzip2
        }

    def extract(self, output_path=None):
        if output_path is None:
            output_path = self.archive_path.parent

        suffix = ''.join(self.archive_path.suffixes)
        if suffix not in self.supported_formats:
            raise ValueError(f"Unsupported archive format: {suffix}")

        return self.supported_formats[suffix](output_path)

    def _extract_zip(self, output_path):
        with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
            zip_ref.extractall(output_path)
        return output_path

    def _extract_tar(self, output_path):
        with tarfile.open(self.archive_path, 'r:*') as tar_ref:
            tar_ref.extractall(output_path)
        return output_path

    def _extract_gzip(self, output_path):
        output_file = output_path / self.archive_path.stem
        with gzip.open(self.archive_path, 'rb') as gz_ref:
            with open(output_file, 'wb') as f_out:
                shutil.copyfileobj(gz_ref, f_out)
        return output_file

    def _extract_bzip2(self, output_path):
        output_file = output_path / self.archive_path.stem
        with bz2.open(self.archive_path, 'rb') as bz2_ref:
            with open(output_file, 'wb') as f_out:
                shutil.copyfileobj(bz2_ref, f_out)
        return output_file

    def list_contents(self):
        suffix = ''.join(self.archive_path.suffixes)
        if suffix == '.zip':
            with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
                return zip_ref.namelist()
        elif suffix in ['.tar', '.tar.gz', '.tgz', '.tar.bz2']:
            with tarfile.open(self.archive_path, 'r:*') as tar_ref:
                return tar_ref.getnames()
        elif suffix in ['.gz', '.bz2']:
            return [self.archive_path.stem]
        else:
            raise ValueError(f"Unsupported archive format: {suffix}")

