class Module:
    def __init__(self, name, input_ports=None, output_ports=None):
        self.name = name
        self.input_ports = input_ports or []
        self.output_ports = output_ports or []
        self.connections = {}
        self.parameters = {}

class Oscillator(Module):
    def __init__(self):
        super().__init__("Oscillator", 
                        input_ports=["freq_mod", "amp_mod"],
                        output_ports=["output"])
        self.parameters = {
            "frequency": 440.0,
            "waveform": "sine",
            "amplitude": 1.0
        }

    def process(self, sample_rate):
        freq = self.parameters["frequency"]
        if "freq_mod" in self.connections:
            freq *= self.connections["freq_mod"].process(sample_rate)
        return freq

class Filter(Module):
    def __init__(self):
        super().__init__("Filter",
                        input_ports=["input", "cutoff_mod"],
                        output_ports=["output"])
        self.parameters = {
            "cutoff": 1000.0,
            "resonance": 0.5,
            "type": "lowpass"
        }

class Sequencer(Module):
    def __init__(self):
        super().__init__("Sequencer",
                        output_ports=["gate", "cv"])
        self.parameters = {
            "steps": 16,
            "rate": 120,
            "sequence": [0] * 16
        }

class Rack:
    def __init__(self):
        self.modules = {}
        self.sample_rate = 44100

    def add_module(self, module_id, module):
        self.modules[module_id] = module

    def connect(self, from_module, from_port, to_module, to_port):
        self.modules[to_module].connections[to_port] = (from_module, from_port)

    def process(self):
        for module in self.modules.values():
            module.process(self.sample_rate)

def create_patch():
    rack = Rack()

    osc1 = Oscillator()
    osc1.parameters["frequency"] = 440
    rack.add_module("osc1", osc1)

    filter1 = Filter()
    filter1.parameters["cutoff"] = 2000
    rack.add_module("filter1", filter1)

    seq1 = Sequencer()
    seq1.parameters["sequence"] = [0, 2, 4, 5, 7, 9, 11, 0]
    rack.add_module("seq1", seq1)

    rack.connect("seq1", "cv", "osc1", "freq_mod")
    rack.connect("osc1", "output", "filter1", "input")

    return rack

if __name__ == "__main__":
    rack = create_patch()
    rack.process()

