from pathlib import Path
import socket
import pickle
import zlib
import hashlib
import threading
import json

class Node:
    def __init__(self, host='localhost', port=5000, storage_path='./storage'):
        self.host = host
        self.port = port
        self.storage_path = Path(storage_path)
        self.storage_path.mkdir(exist_ok=True)
        self.blocks = {}
        self.files = {}
        self.peers = set()
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.bind((host, port))
        self.sock.listen(5)

    def start(self):
        threading.Thread(target=self._listen, daemon=True).start()

    def _listen(self):
        while True:
            client, addr = self.sock.accept()
            threading.Thread(target=self._handle_client, args=(client,), daemon=True).start()

    def _handle_client(self, client):
        try:
            data = client.recv(4096)
            request = pickle.loads(data)
            if request['type'] == 'get_block':
                response = self._handle_get_block(request['block_id'])
            elif request['type'] == 'store_block':
                response = self._handle_store_block(request['block_id'], request['data'])
            client.send(pickle.dumps(response))
        finally:
            client.close()

    def store_file(self, filepath):
        file_path = Path(filepath)
        file_id = hashlib.sha256(str(file_path).encode()).hexdigest()
        blocks = []

        with open(file_path, 'rb') as f:
            while data := f.read(1024 * 1024):  # 1MB chunks
                compressed = zlib.compress(data)
                block_id = hashlib.sha256(compressed).hexdigest()
                blocks.append(block_id)
                self._store_block_locally(block_id, compressed)
                self._replicate_block(block_id, compressed)

        self.files[file_id] = {
            'name': file_path.name,
            'blocks': blocks
        }
        return file_id

    def retrieve_file(self, file_id, output_path):
        if file_id not in self.files:
            return False

        file_info = self.files[file_id]
        with open(output_path, 'wb') as f:
            for block_id in file_info['blocks']:
                block_data = self._get_block(block_id)
                if block_data:
                    decompressed = zlib.decompress(block_data)
                    f.write(decompressed)
        return True

    def _store_block_locally(self, block_id, data):
        block_path = self.storage_path / block_id
        with open(block_path, 'wb') as f:
            f.write(data)
        self.blocks[block_id] = True

    def _get_block(self, block_id):
        if block_id in self.blocks:
            block_path = self.storage_path / block_id
            with open(block_path, 'rb') as f:
                return f.read()

        # Try to get from peers
        for peer in self.peers:
            try:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.connect(peer)
                    request = {
                        'type': 'get_block',
                        'block_id': block_id
                    }
                    s.send(pickle.dumps(request))
                    response = pickle.loads(s.recv(4096))
                    if response['success']:
                        self._store_block_locally(block_id, response['data'])
                        return response['data']
            except:
                continue
        return None

    def _replicate_block(self, block_id, data):
        for peer in self.peers:
            try:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.connect(peer)
                    request = {
                        'type': 'store_block',
                        'block_id': block_id,
                        'data': data
                    }
                    s.send(pickle.dumps(request))
            except:
                continue

    def add_peer(self, host, port):
        self.peers.add((host, port))

    def _handle_get_block(self, block_id):
        if block_id in self.blocks:
            block_path = self.storage_path / block_id
            with open(block_path, 'rb') as f:
                return {'success': True, 'data': f.read()}
        return {'success': False}

    def _handle_store_block(self, block_id, data):
        self._store_block_locally(block_id, data)
        return {'success': True}

if __name__ == '__main__':
    # Example usage
    node1 = Node(port=5000)
    node2 = Node(port=5001)

    node1.add_peer('localhost', 5001)
    node2.add_peer('localhost', 5000)

    node1.start()
    node2.start()

    # Store a file on node1
    file_id = node1.store_file('example.txt')

    # Retrieve the file from node2
    node2.retrieve_file(file_id, 'retrieved_example.txt')

