class FileSync:
    def __init__(self, source_dir, dest_dir, permissions=0o644):
        self.source_dir = source_dir
        self.dest_dir = dest_dir
        self.permissions = permissions

    def sync_files(self):
        if not os.path.exists(self.dest_dir):
            os.makedirs(self.dest_dir)
            os.chmod(self.dest_dir, 0o755)

        for root, _, files in os.walk(self.source_dir):
            relative_path = os.path.relpath(root, self.source_dir)
            dest_path = os.path.join(self.dest_dir, relative_path)

            if not os.path.exists(dest_path):
                os.makedirs(dest_path)
                os.chmod(dest_path, 0o755)

            for file in files:
                source_file = os.path.join(root, file)
                dest_file = os.path.join(dest_path, file)

                try:
                    shutil.copy2(source_file, dest_file)
                    os.chmod(dest_file, self.permissions)
                except (IOError, OSError) as e:
                    print(f"Error copying {source_file}: {str(e)}")

    def verify_sync(self):
        mismatched_files = []
        for root, _, files in os.walk(self.source_dir):
            relative_path = os.path.relpath(root, self.source_dir)
            for file in files:
                source_file = os.path.join(root, file)
                dest_file = os.path.join(self.dest_dir, relative_path, file)

                if not os.path.exists(dest_file):
                    mismatched_files.append(f"Missing: {dest_file}")
                elif os.path.getsize(source_file) != os.path.getsize(dest_file):
                    mismatched_files.append(f"Size mismatch: {dest_file}")

        return mismatched_files

