            return self.parse_receipt(text)
        except Exception as e:
            return {"error": f"Failed to scan receipt: {str(e)}"}

    def parse_receipt(self, text):
        lines = text.split('\n')
        receipt = {
            "date": None,
            "total": 0.0,
            "items": [],
            "vendor": None
        }

        date_pattern = r'\d{1,2}[-/]\d{1,2}[-/]\d{2,4}'
        amount_pattern = r'\$?\d+\.\d{2}'

        for line in lines:
            if not receipt["date"]:
                date_match = re.search(date_pattern, line)
                if date_match:
                    receipt["date"] = date_match.group()

            if "TOTAL" in line.upper():
                total_match = re.search(amount_pattern, line)
                if total_match:
                    receipt["total"] = float(total_match.group().replace('$', ''))

            if not receipt["vendor"] and len(line.strip()) > 0:
                receipt["vendor"] = line.strip()

            amount_match = re.search(amount_pattern, line)
            if amount_match and "TOTAL" not in line.upper():
                item = {
                    "description": line.split(amount_match.group())[0].strip(),
                    "amount": float(amount_match.group().replace('$', ''))
                }
                receipt["items"].append(item)

        receipt["scan_date"] = datetime.now().isoformat()
        self._save_receipt(receipt)
        return receipt

    def _save_receipt(self, receipt):
        receipt_id = len(self.receipts_db) + 1
        self.receipts_db[receipt_id] = receipt
        self._export_to_json()

    def _export_to_json(self):
        with open('receipts.json', 'w') as f:
            json.dump(self.receipts_db, f, indent=4)

    def get_receipt(self, receipt_id):
        return self.receipts_db.get(receipt_id)

    def get_total_expenses(self, start_date=None, end_date=None):
        total = 0
        for receipt in self.receipts_db.values():
            if receipt["date"]:
                receipt_date = datetime.strptime(receipt["date"], "%m/%d/%Y")
                if start_date and receipt_date < start_date:
                    continue
                if end_date and receipt_date > end_date:
                    continue
                total += receipt["total"]
        return total
