from pathlib import Path

def analyze_disk_usage(directory, top_n=10):
    large_files = []
    total_size = 0

    for root, _, files in os.walk(directory):
        for file in files:
            file_path = Path(root) / file
            try:
                size = file_path.stat().st_size
                total_size += size
                heapq.heappush(large_files, (-size, str(file_path)))
                if len(large_files) > top_n:
                    heapq.heappop(large_files)
            except (PermissionError, FileNotFoundError):
                continue

    results = []
    while large_files:
        size, path = heapq.heappop(large_files)
        results.insert(0, {
            'path': path,
            'size': -size,
            'size_mb': round(-size / (1024 * 1024), 2),
            'percentage': round(-size * 100 / total_size, 2)
        })

    return {
        'total_size': total_size,
        'total_size_mb': round(total_size / (1024 * 1024), 2),
