import ast
import astor
from typing import Dict, Any

class TypeAnnotator(ast.NodeTransformer):
    def __init__(self):
        self.type_map = {}

    def visit_FunctionDef(self, node):
        for arg in node.args.args:
            if arg.annotation is None:
                arg.annotation = ast.Name(id='Any', ctx=ast.Load())
        if node.returns is None:
            node.returns = ast.Name(id='Any', ctx=ast.Load())
        return node

    def visit_Assign(self, node):
        for target in node.targets:
            if isinstance(target, ast.Name):
                if isinstance(node.value, ast.Num):
                    self.type_map[target.id] = 'int' if isinstance(node.value.n, int) else 'float'
                elif isinstance(node.value, ast.Str):
                    self.type_map[target.id] = 'str'
                elif isinstance(node.value, ast.List):
                    self.type_map[target.id] = 'list'
        return node

def annotate_file(filename: str) -> str:
    with open(filename, 'r') as file:
        tree = ast.parse(file.read())

    annotator = TypeAnnotator()
    modified_tree = annotator.visit(tree)

    return astor.to_source(modified_tree)

