import argparse
import sys
from pathlib import Path

def concat_files(input_files, output_file, buffer_size=8192):
    with open(output_file, 'wb') as outfile:
        for file_path in input_files:
            try:
                with open(file_path, 'rb') as infile:
                    while True:
                        chunk = infile.read(buffer_size)
                        if not chunk:
                            break
                        outfile.write(chunk)
            except IOError as e:
                print(f"Error processing {file_path}: {e}", file=sys.stderr)
                continue

def main():
    parser = argparse.ArgumentParser(description='Concatenate multiple files into one')
    parser.add_argument('files', nargs='+', help='Input files to concatenate')
    parser.add_argument('-o', '--output', required=True, help='Output file')
    args = parser.parse_args()

    output_path = Path(args.output)
    if output_path.exists():
        print(f"Warning: {output_path} already exists. Overwriting.", file=sys.stderr)

    concat_files(args.files, args.output)

if __name__ == '__main__':
