import os
import hashlib
import shutil
import time
from pathlib import Path
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class SyncHandler(FileSystemEventHandler):
    def __init__(self, source_dir, target_dirs):
        self.source_dir = Path(source_dir)
        self.target_dirs = [Path(d) for d in target_dirs]

    def on_modified(self, event):
        if event.is_directory:
            return

        src_path = Path(event.src_path)
        rel_path = src_path.relative_to(self.source_dir)

        for target_dir in self.target_dirs:
            dst_path = target_dir / rel_path
            dst_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(src_path, dst_path)

def get_file_hash(filepath):
    hasher = hashlib.md5()
    with open(filepath, 'rb') as f:
        buf = f.read(4096)
        while buf:
            hasher.update(buf)
            buf = f.read(4096)
    return hasher.hexdigest()

def sync_directories(source_dir, target_dirs):
    source_dir = Path(source_dir)
    target_dirs = [Path(d) for d in target_dirs]

    event_handler = SyncHandler(source_dir, target_dirs)
    observer = Observer()
    observer.schedule(event_handler, str(source_dir), recursive=True)
    observer.start()

    try:
        while True:
            for src_file in source_dir.rglob('*'):
                if src_file.is_file():
                    rel_path = src_file.relative_to(source_dir)
                    src_hash = get_file_hash(src_file)

                    for target_dir in target_dirs:
                        dst_file = target_dir / rel_path

                        if not dst_file.exists():
                            dst_file.parent.mkdir(parents=True, exist_ok=True)
                            shutil.copy2(src_file, dst_file)
                        else:
                            dst_hash = get_file_hash(dst_file)
                            if src_hash != dst_hash:
                                shutil.copy2(src_file, dst_file)

            time.sleep(10)

    except KeyboardInterrupt:
        observer.stop()
    observer.join()

if __name__ == "__main__":
    source = "source_directory"
    targets = ["target_directory_1", "target_directory_2"]
    sync_directories(source, targets)
