def extract_backup(backup_path):
    tar = tarfile.open(backup_path)

    backup_info = {}
    backup_info['files'] = []
    backup_info['total_size'] = 0

    for member in tar.getmembers():
        backup_info['files'].append({
            'name': member.name,
            'size': member.size,
            'mtime': member.mtime
        })
        backup_info['total_size'] += member.size

