        self.mount_point = None

    def mount(self):
        self.mount_point = Path(tempfile.mkdtemp())
        subprocess.run(['mount', '-o', 'loop', str(self.image_path), str(self.mount_point)], check=True)
        return self.mount_point

    def unmount(self):
        if self.mount_point:
            subprocess.run(['umount', str(self.mount_point)], check=True)
            os.rmdir(self.mount_point)
            self.mount_point = None

