        dest_path = Path(destination)
        dest_path.mkdir(parents=True, exist_ok=True)
        subprocess.run(['7z', 'x', str(self.image_path), f'-o{dest_path}'], check=True)

    def compress(self, source_dir, format='7z'):
        subprocess.run(['7z', 'a', f'{self.image_path}.{format}', str(source_dir)], check=True)

    def __enter__(self):
        self.mount()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.unmount()

