class BrowserCache:
    def __init__(self, cache_dir="browser_cache"):
        self.cache_dir = cache_dir
        os.makedirs(cache_dir, exist_ok=True)

    def _get_cache_path(self, url):
        url_hash = hashlib.md5(url.encode()).hexdigest()
        return os.path.join(self.cache_dir, url_hash)

    def fetch_page(self, url):
        cache_path = self._get_cache_path(url)

        if os.path.exists(cache_path):
            with open(cache_path, 'r') as f:
                return f.read()

        response = requests.get(url)
        content = response.text

        with open(cache_path, 'w') as f:
            f.write(content)

        with open(f"{cache_path}.meta", 'w') as f:
            f.write(f"URL: {url}\n")
            f.write(f"Timestamp: {datetime.now().isoformat()}\n")
            f.write(f"Content-Type: {response.headers.get('content-type')}\n")

        return content

    def clear_cache(self):
        for file in os.listdir(self.cache_dir):
            file_path = os.path.join(self.cache_dir, file)
            if os.path.isfile(file_path):
                os.remove(file_path)

    def get_cache_info(self, url):
        cache_path = self._get_cache_path(url)
        if os.path.exists(f"{cache_path}.meta"):
            with open(f"{cache_path}.meta", 'r') as f:
                return f.read()
        return None

