        self.game_path = Path(game_path)
        self.mod_directory = Path(mod_directory)
        self.mod_directory.mkdir(exist_ok=True)
        self.installed_mods = {}
        self.load_mod_registry()

    def load_mod_registry(self):
        registry_path = self.mod_directory / "mod_registry.json"
        if registry_path.exists():
            with open(registry_path, "r") as f:
                self.installed_mods = json.load(f)

    def save_mod_registry(self):
        with open(self.mod_directory / "mod_registry.json", "w") as f:
            json.dump(self.installed_mods, f)

    def download_mod(self, mod_url, mod_id):
        response = requests.get(mod_url, stream=True)
        mod_file = self.mod_directory / f"{mod_id}.zip"
        with open(mod_file, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
        return mod_file

    def install_mod(self, mod_url, mod_id, mod_name):
        mod_file = self.download_mod(mod_url, mod_id)
        install_path = self.mod_directory / mod_id

        with zipfile.ZipFile(mod_file, 'r') as zip_ref:
            zip_ref.extractall(install_path)

        self.installed_mods[mod_id] = {
            "name": mod_name,
            "path": str(install_path),
            "enabled": True
        }
        self.save_mod_registry()
        mod_file.unlink()

    def uninstall_mod(self, mod_id):
        if mod_id in self.installed_mods:
            install_path = Path(self.installed_mods[mod_id]["path"])
            if install_path.exists():
                for item in install_path.glob("**/*"):
                    if item.is_file():
                        item.unlink()
                    elif item.is_dir():
                        item.rmdir()
                install_path.rmdir()
            del self.installed_mods[mod_id]
            self.save_mod_registry()

    def enable_mod(self, mod_id):
        if mod_id in self.installed_mods:
            self.installed_mods[mod_id]["enabled"] = True
            self.save_mod_registry()

    def disable_mod(self, mod_id):
        if mod_id in self.installed_mods:
            self.installed_mods[mod_id]["enabled"] = False
            self.save_mod_registry()

    def get_installed_mods(self):
