import sqlite3
from pathlib import Path

class TodoFinder:
    def __init__(self, db_path):
        self.db_path = db_path
        self._init_db()
        os.chmod(db_path, 0o600)

    def _init_db(self):
        with sqlite3.connect(self.db_path) as conn:
            conn.execute('''
                CREATE TABLE IF NOT EXISTS todos (
                    id INTEGER PRIMARY KEY,
                    file TEXT,
                    line INTEGER, 
                    todo TEXT,
                    category TEXT,
                    completed BOOLEAN DEFAULT 0
                )
            ''')

    def scan_directory(self, directory):
        for path in Path(directory).rglob('*.py'):
            self._scan_file(path)

    def _scan_file(self, filepath):
        with open(filepath) as f:
            for i, line in enumerate(f, 1):
                if todo := re.search(r'#\s*TODO:\s*(.+)$', line):
                    self._save_todo(str(filepath), i, todo.group(1))

    def _save_todo(self, filepath, line, todo):
        with sqlite3.connect(self.db_path) as conn:
            conn.execute(
                'INSERT INTO todos (file, line, todo) VALUES (?, ?, ?)',
                (filepath, line, todo)
            )

    def categorize(self, todo_id, category):
        with sqlite3.connect(self.db_path) as conn:
            conn.execute(
                'UPDATE todos SET category = ? WHERE id = ?',
                (category, todo_id)
            )

    def get_todos(self, category=None):
        with sqlite3.connect(self.db_path) as conn:
            if category:
                return conn.execute(
                    'SELECT * FROM todos WHERE category = ?',
                    (category,)
                ).fetchall()
            return conn.execute('SELECT * FROM todos').fetchall()
