        self.name = name
        self.price = price
        self.description = description 
        self.category = category

class MenuSystem:
    def __init__(self):
        self.menu_items = {}
        self.categories = set()

    def add_item(self, name, price, description, category):
        item = MenuItem(name, price, description, category)
        self.menu_items[name] = item
        self.categories.add(category)
        return item

    def get_items_by_category(self, category):
        return [item for item in self.menu_items.values() 
               if item.category == category]

    def display_menu(self):
        for category in sorted(self.categories):
            print(f"\n{category.upper()}")
            print("-" * 40)
            for item in self.get_items_by_category(category):
                print(f"{item.name}: ${item.price:.2f}")
                print(f"  {item.description}")

