from datetime import datetime
import threading
import psutil
import time

@dataclass
class Asset:
    hostname: str
    ip_address: str
    status: str
    last_seen: datetime
    metrics: dict

class MonitoringSystem:
    def __init__(self):
        self.assets = {}
        self.queries = []
        self._lock = threading.Lock()

    def add_asset(self, hostname: str, ip: str):
        asset = Asset(
            hostname=hostname,
            ip_address=ip, 
            status="online",
            last_seen=datetime.now(),
            metrics={}
        )
        with self._lock:
            self.assets[hostname] = asset

    def update_metrics(self, hostname: str):
        if hostname in self.assets:
            metrics = {
                'cpu': psutil.cpu_percent(),
                'memory': psutil.virtual_memory().percent,
                'disk': psutil.disk_usage('/').percent
            }
            with self._lock:
                self.assets[hostname].metrics = metrics
                self.assets[hostname].last_seen = datetime.now()

    def query_asset(self, hostname: str) -> Asset:
        return self.assets.get(hostname)

    def monitor(self):
        while True:
            for hostname in list(self.assets.keys()):
                self.update_metrics(hostname)
            time.sleep(60)

def main():
    monitor = MonitoringSystem()

    # Add some test assets
    monitor.add_asset("server1", "192.168.1.100")
    monitor.add_asset("server2", "192.168.1.101")

    # Start monitoring in background thread
    monitor_thread = threading.Thread(target=monitor.monitor)
    monitor_thread.daemon = True
    monitor_thread.start()

    # Query assets
    while True:
        hostname = input("Enter hostname to query (or 'quit'): ")
        if hostname == 'quit':
            break

        asset = monitor.query_asset(hostname)
        if asset:
            print(f"\nHostname: {asset.hostname}")
            print(f"IP: {asset.ip_address}")
            print(f"Status: {asset.status}")
            print(f"Last seen: {asset.last_seen}")
            print("Metrics:")
            for k,v in asset.metrics.items():
                print(f"  {k}: {v}%")
        else:
            print("Asset not found")

if __name__ == "__main__":
    main()
