class ImageProcessor:
    def __init__(self, upload_dir="uploads", output_dir="processed"):
        self.upload_dir = upload_dir
        self.output_dir = output_dir
        os.makedirs(upload_dir, exist_ok=True)
        os.makedirs(output_dir, exist_ok=True)

    def process_image(self, image_path, formats=None, sizes=None):
        if formats is None:
            formats = ['JPEG', 'PNG', 'WEBP']
        if sizes is None:
            sizes = [(800, 600), (400, 300), (200, 150)]

        try:
            with Image.open(image_path) as img:
                filename = str(uuid4())
                results = []

                for fmt in formats:
                    for size in sizes:
                        resized = img.copy()
                        resized.thumbnail(size)
                        output_path = os.path.join(
                            self.output_dir,
                            f"{filename}_{size[0]}x{size[1]}.{fmt.lower()}"
                        )
                        resized.save(output_path, format=fmt, quality=85, optimize=True)
                        results.append(output_path)

                return results
        except Exception as e:
            raise ValueError(f"Image processing failed: {str(e)}")

    def clean_up(self, filepath):
        if os.path.exists(filepath):
            os.remove(filepath)

