import logging
from pathlib import Path

class ArtifactUnpacker:
    def __init__(self, artifacts_dir: str, output_dir: str):
        self.artifacts_dir = Path(artifacts_dir)
        self.output_dir = Path(output_dir)
        self.logger = logging.getLogger(__name__)

    def unpack_artifacts(self):
        try:
            os.makedirs(self.output_dir, exist_ok=True)

            for artifact in self.artifacts_dir.glob('*.tar.gz'):
                output_path = self.output_dir / artifact.stem
                with tarfile.open(artifact, 'r:gz') as tar:
                    tar.extractall(path=output_path)
                self.logger.info(f"Unpacked {artifact} to {output_path}")

            return True

        except Exception as e:
            self.logger.error(f"Failed to unpack artifacts: {str(e)}")
            return False

    def cleanup(self):
        try:
            shutil.rmtree(self.output_dir)
            self.logger.info("Cleaned up output directory")
        except Exception as e:
            self.logger.error(f"Failed to cleanup: {str(e)}")

if __name__ == "__main__":
    unpacker = ArtifactUnpacker("./artifacts", "./build")
    unpacker.unpack_artifacts()

