import os
import re
import shutil
from pathlib import Path

def bulk_rename(directory, search_pattern, replace_pattern, permissions=0o644):
    directory_path = Path(directory)
    renamed_files = []

    for file_path in directory_path.glob('*'):
        if file_path.is_file():
            new_name = re.sub(search_pattern, replace_pattern, file_path.name)
            if new_name != file_path.name:
                new_path = file_path.parent / new_name
                shutil.move(str(file_path), str(new_path))
                os.chmod(new_path, permissions)
                renamed_files.append((file_path.name, new_name))

    return renamed_files

def validate_permissions(permissions):
    try:
        permissions_int = int(str(permissions), 8)
        return 0 <= permissions_int <= 0o777
    except ValueError:
        return False

if __name__ == '__main__':
    directory = '/path/to/directory'
    pattern = r'old_pattern'
    replacement = 'new_pattern'
    permissions = 0o644

    if validate_permissions(permissions):
        renamed = bulk_rename(directory, pattern, replacement, permissions)
        for old, new in renamed:
            print(f'Renamed: {old} -> {new}')

