from dataclasses import dataclass
from datetime import datetime, timedelta
from decimal import Decimal
from typing import List, Dict
import uuid

@dataclass
class Project:
    id: str
    title: str
    description: str
    goal: Decimal
    deadline: datetime
    creator_id: str
    current_amount: Decimal = Decimal('0')
    backers: Dict[str, Decimal] = None

    def __post_init__(self):
        if self.backers is None:
            self.backers = {}

class CrowdfundingPlatform:
    def __init__(self):
        self.projects = {}
        self.users = {}

    def create_project(self, title: str, description: str, goal: Decimal, 
                      days_duration: int, creator_id: str) -> Project:
        project_id = str(uuid.uuid4())
        deadline = datetime.now() + timedelta(days=days_duration)

        project = Project(
            id=project_id,
            title=title,
            description=description,
            goal=goal,
            deadline=deadline,
            creator_id=creator_id
        )

        self.projects[project_id] = project
        return project

    def back_project(self, project_id: str, backer_id: str, amount: Decimal) -> bool:
        project = self.projects.get(project_id)
        if not project:
            raise ValueError("Project not found")

        if project.deadline < datetime.now():
            raise ValueError("Project funding period has ended")

        project.backers[backer_id] = project.backers.get(backer_id, Decimal('0')) + amount
        project.current_amount += amount
        return True

    def get_project_status(self, project_id: str) -> dict:
        project = self.projects.get(project_id)
        if not project:
            raise ValueError("Project not found")

        return {
            'title': project.title,
            'current_amount': project.current_amount,
            'goal': project.goal,
            'backers_count': len(project.backers),
            'is_funded': project.current_amount >= project.goal,
            'days_remaining': (project.deadline - datetime.now()).days
        }

    def list_projects(self) -> List[Project]:
        return list(self.projects.values())

    def get_backer_contributions(self, backer_id: str) -> Dict[str, Decimal]:
        contributions = {}
        for project in self.projects.values():
            if backer_id in project.backers:
                contributions[project.title] = project.backers[backer_id]
        return contributions

