from dataclasses import dataclass
from typing import List, Dict
import datetime
import json

@dataclass
class Plant:
    name: str
    species: str
    planting_date: datetime.date
    location: tuple
    status: str
    maintenance_history: List[Dict]

class Garden:
    def __init__(self):
        self.plants = {}
        self.dimensions = (0, 0)
        self.zones = {}

    def add_plant(self, plant: Plant, location: tuple):
        if self._is_valid_location(location):
            self.plants[location] = plant
            return True
        return False

    def remove_plant(self, location: tuple):
        if location in self.plants:
            del self.plants[location]
            return True
        return False

    def add_maintenance_record(self, location: tuple, action: str, date: datetime.date):
        if location in self.plants:
            record = {"action": action, "date": date.isoformat()}
            self.plants[location].maintenance_history.append(record)
            return True
        return False

    def _is_valid_location(self, location: tuple) -> bool:
        x, y = location
        max_x, max_y = self.dimensions
        return 0 <= x < max_x and 0 <= y < max_y

    def save_garden(self, filename: str):
        garden_data = {
            "dimensions": self.dimensions,
            "plants": {
                f"{loc[0]},{loc[1]}": {
                    "name": plant.name,
                    "species": plant.species,
                    "planting_date": plant.planting_date.isoformat(),
                    "status": plant.status,
                    "maintenance_history": plant.maintenance_history
                }
                for loc, plant in self.plants.items()
            }
        }
        with open(filename, 'w') as f:
            json.dump(garden_data, f)

    def load_garden(self, filename: str):
        with open(filename, 'r') as f:
            data = json.load(f)
            self.dimensions = tuple(data["dimensions"])
            for loc_str, plant_data in data["plants"].items():
                x, y = map(int, loc_str.split(","))
                plant = Plant(
                    name=plant_data["name"],
                    species=plant_data["species"],
                    planting_date=datetime.date.fromisoformat(plant_data["planting_date"]),
                    location=(x, y),
                    status=plant_data["status"],
                    maintenance_history=plant_data["maintenance_history"]
                )
                self.plants[(x, y)] = plant

