from datetime import datetime
import decimal
import uuid

class BankAccount:
    def __init__(self, account_number, owner_name, balance=0):
        self.account_number = account_number
        self.owner_name = owner_name
        self.balance = decimal.Decimal(str(balance))
        self.transactions = []

    def transfer(self, recipient_account, amount):
        if self.balance >= amount:
            self.balance -= amount
            recipient_account.balance += amount

            transaction = {
                'id': str(uuid.uuid4()),
                'type': 'transfer',
                'amount': amount,
                'recipient': recipient_account.account_number,
                'date': datetime.now(),
                'status': 'completed'
            }
            self.transactions.append(transaction)
            return True
        return False

    def pay_bill(self, bill_details, amount):
        if self.balance >= amount:
            self.balance -= amount

            transaction = {
                'id': str(uuid.uuid4()),
                'type': 'bill_payment',
                'amount': amount,
                'bill_details': bill_details,
                'date': datetime.now(),
                'status': 'completed'
            }
            self.transactions.append(transaction)
            return True
        return False

    def deposit(self, amount):
        self.balance += decimal.Decimal(str(amount))

        transaction = {
            'id': str(uuid.uuid4()),
            'type': 'deposit',
            'amount': amount,
            'date': datetime.now(),
            'status': 'completed'
        }
        self.transactions.append(transaction)

    def get_balance(self):
        return float(self.balance)

    def get_transactions(self, limit=10):
        return sorted(self.transactions, key=lambda x: x['date'], reverse=True)[:limit]

class Bank:
    def __init__(self):
        self.accounts = {}

    def create_account(self, owner_name, initial_balance=0):
        account_number = str(uuid.uuid4())[:8]
        account = BankAccount(account_number, owner_name, initial_balance)
        self.accounts[account_number] = account
        return account_number

    def get_account(self, account_number):
        return self.accounts.get(account_number)

    def transfer_between_accounts(self, from_account_number, to_account_number, amount):
        from_account = self.get_account(from_account_number)
        to_account = self.get_account(to_account_number)

        if from_account and to_account:
            return from_account.transfer(to_account, amount)
        return False
