class Event:
    title: str
    start_time: datetime
    end_time: datetime
    description: str
    creator: str
    attendees: List[str]

class FamilyCalendar:
    def __init__(self):
        self.events: Dict[str, Event] = {}
        self.members: List[str] = []

    def add_member(self, name: str) -> None:
        if name not in self.members:
            self.members.append(name)

    def create_event(self, title: str, start: datetime, end: datetime, 
                    desc: str, creator: str, attendees: List[str]) -> str:
        event_id = f"{title}_{start.strftime('%Y%m%d%H%M')}"
        event = Event(
            title=title,
            start_time=start,
            end_time=end,
            description=desc,
            creator=creator,
            attendees=attendees
        )
        self.events[event_id] = event
        return event_id

    def get_events_for_member(self, member: str) -> List[Event]:
        return [
            event for event in self.events.values()
            if member in event.attendees or member == event.creator
        ]

    def delete_event(self, event_id: str, requester: str) -> bool:
        if event_id in self.events:
            if self.events[event_id].creator == requester:
                del self.events[event_id]
                return True
        return False

    def update_event(self, event_id: str, requester: str, 
                    **kwargs) -> bool:
        if event_id in self.events:
            event = self.events[event_id]
            if event.creator == requester:
                for key, value in kwargs.items():
                    if hasattr(event, key):
                        setattr(event, key, value)
                return True
        return False
