import os
import shutil
import datetime
import hashlib
from pathlib import Path

class BackupUtility:
    def __init__(self, source_dir, backup_dir):
        self.source_dir = Path(source_dir)
        self.backup_dir = Path(backup_dir)
        self.timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")

    def create_backup(self):
        if not self.source_dir.exists():
            raise FileNotFoundError("Source directory does not exist")

        backup_name = f"backup_{self.timestamp}"
        backup_path = self.backup_dir / backup_name

        os.makedirs(self.backup_dir, exist_ok=True)
        shutil.make_archive(str(backup_path), 'zip', str(self.source_dir))

        return self.verify_backup(f"{backup_path}.zip")

    def verify_backup(self, backup_file):
        source_hash = self._calculate_directory_hash(self.source_dir)
        with Path(backup_file).open('rb') as f:
            backup_hash = hashlib.sha256(f.read()).hexdigest()

        return {
            'backup_file': backup_file,
            'source_hash': source_hash,
            'backup_hash': backup_hash,
            'timestamp': self.timestamp
        }

    def _calculate_directory_hash(self, directory):
        hasher = hashlib.sha256()

        for root, _, files in os.walk(directory):
            for file in sorted(files):
                file_path = Path(root) / file
                with file_path.open('rb') as f:
                    hasher.update(f.read())

        return hasher.hexdigest()

if __name__ == "__main__":
    backup = BackupUtility("./source_files", "./backups")
    result = backup.create_backup()
    print(f"Backup created: {result['backup_file']}")

