    def find_nearby(self, location, category, radius=1000):
        coords = self.geocoder.geocode(location)
        url = f"https://api.maps.com/places/v1/nearby?location={coords}&radius={radius}&type={category}&key={self.api_key}"
        response = requests.get(url)
        return self._parse_places(response.json())

