            'speed': speed,
            'congestion': congestion_level,
            'timestamp': time.time()
        }

    def calculate_route(self, start, end):
        distances = {start: 0}
        previous = {start: None}
        nodes = [(0, start)]

        while nodes:
            current_distance, current = heapq.heappop(nodes)
            if current == end:
                break

            for neighbor, weight in self.graph[current].items():
                traffic_factor = self.traffic_data.get(f"{current}-{neighbor}", {}).get('congestion', 1.0)
                distance = current_distance + weight * traffic_factor

                if neighbor not in distances or distance < distances[neighbor]:
                    distances[neighbor] = distance
                    previous[neighbor] = current
                    heapq.heappush(nodes, (distance, neighbor))

        return self._build_path(previous, start, end)

    def _parse_route(self, data):
        route = {
            'distance': data['distance'],
            'duration': data['duration'],
            'steps': data['steps'],
            'polyline': polyline.decode(data['overview_polyline'])
        }
        return route

    def _parse_places(self, data):
        return [{
            'name': place['name'],
            'address': place['address'],
            'rating': place.get('rating'),
            'distance': place['distance']
        } for place in data['results']]

    def _build_path(self, previous, start, end):
        path = []
        current = end
        while current is not None:
            path.append(current)
            current = previous[current]
        return path[::-1]

