import gzip
import json
from pathlib import Path
import logging
from datetime import datetime
from typing import Generator

class LogProcessor:
    def __init__(self, input_dir: str, output_dir: str):
        self.input_dir = Path(input_dir)
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(exist_ok=True)

    def process_files(self) -> None:
        for log_file in self.input_dir.glob("*.gz"):
            try:
                records = self._extract_records(log_file)
                self._save_records(log_file.stem, records)
            except Exception as e:
                logging.error(f"Failed to process {log_file}: {str(e)}")

    def _extract_records(self, file_path: Path) -> Generator[dict, None, None]:
        with gzip.open(file_path, 'rt') as f:
            for line in f:
                try:
                    record = json.loads(line.strip())
                    yield self._transform_record(record)
                except json.JSONDecodeError:
                    logging.warning(f"Skipping invalid JSON line in {file_path}")

    def _transform_record(self, record: dict) -> dict:
        record['processed_at'] = datetime.utcnow().isoformat()
        record['source_file'] = str(file_path)
        return record

    def _save_records(self, filename: str, records: Generator[dict, None, None]) -> None:
        output_file = self.output_dir / f"{filename}_processed.json"
        with open(output_file, 'w') as f:
            for record in records:
                json.dump(record, f)
                f.write('\n')

if __name__ == "__main__":
    processor = LogProcessor("raw_logs", "processed_logs")
    processor.process_files()

