import tempfile

class Deployer:
    def __init__(self, archive_path, deploy_path):
        self.archive_path = Path(archive_path)
        self.deploy_path = Path(deploy_path)
        self.temp_dir = Path(tempfile.mkdtemp())

    def extract_archive(self):
        with tarfile.open(self.archive_path, 'r:gz') as tar:
            tar.extractall(path=self.temp_dir)

    def setup_environment(self):
        requirements = self.temp_dir / 'requirements.txt'
        if requirements.exists():
            subprocess.run(['pip', 'install', '-r', str(requirements)], check=True)

    def copy_files(self):
        if self.deploy_path.exists():
            shutil.rmtree(self.deploy_path)
        shutil.copytree(self.temp_dir, self.deploy_path)

    def cleanup(self):
        shutil.rmtree(self.temp_dir)

    def deploy(self):
        try:
            self.extract_archive()
            self.setup_environment()
            self.copy_files()
            return True
        except Exception as e:
            print(f"Deployment failed: {e}")
            return False
        finally:
            self.cleanup()

