def create_backup(source_dir, backup_dir):
    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    backup_path = os.path.join(backup_dir, f'backup_{timestamp}')

    try:
        if not os.path.exists(source_dir):
            raise FileNotFoundError("Source directory does not exist")

        if not os.path.exists(backup_dir):
            os.makedirs(backup_dir)

        shutil.copytree(source_dir, backup_path)

        return backup_path

    except Exception as e:
        raise Exception(f"Backup failed: {str(e)}")

def verify_backup(source_dir, backup_path):
    source_files = set()
    backup_files = set()

    for root, _, files in os.walk(source_dir):
        rel_path = os.path.relpath(root, source_dir)
        for file in files:
            source_files.add(os.path.join(rel_path, file))

    for root, _, files in os.walk(backup_path):
        rel_path = os.path.relpath(root, backup_path)
        for file in files:
            backup_files.add(os.path.join(rel_path, file))

    return source_files == backup_files

if __name__ == "__main__":
