import re
import requests

def crawl(url):
    r = requests.get(url)
    html = r.text

    for link in re.findall(r'<a href="(.*?)"', html):
        parsed = urlparse(link)
        if not parsed.netloc:
            link = urljoin(url, link)
        if link.startswith('http'):
            try:
                crawl(link)
            except requests.exceptions.RequestException:
                continue

