        self.passengers: Dict[str, Passenger] = {}
        self.active_rides: Dict[str, tuple] = {}

    def register_driver(self, name: str, location: Location) -> str:
        driver_id = str(uuid.uuid4())
        self.drivers[driver_id] = Driver(driver_id, name, location, True, 5.0)
        return driver_id

    def register_passenger(self, name: str, location: Location) -> str:
        passenger_id = str(uuid.uuid4())
        self.passengers[passenger_id] = Passenger(passenger_id, name, location, 5.0)
        return passenger_id

    def calculate_distance(self, loc1: Location, loc2: Location) -> float:
        return math.sqrt((loc1.latitude - loc2.latitude)**2 + 
                        (loc1.longitude - loc2.longitude)**2)

    def find_nearest_driver(self, passenger_id: str, max_distance: float = 10.0) -> str:
        passenger = self.passengers[passenger_id]
        nearest_driver = None
        min_distance = float('inf')

        for driver in self.drivers.values():
            if driver.available:
                distance = self.calculate_distance(passenger.location, driver.location)
                if distance <= max_distance and distance < min_distance:
                    min_distance = distance
                    nearest_driver = driver

