#!/usr/bin/env python3

import os
import sys
import argparse
import re
from pathlib import Path

def rename_files(directory, pattern, replacement, permissions=None):
    try:
        directory = Path(directory)
        for file_path in directory.iterdir():
            if file_path.is_file():
                new_name = re.sub(pattern, replacement, file_path.name)
                new_path = file_path.parent / new_name

                if new_path != file_path:
                    file_path.rename(new_path)
                    if permissions:
                        os.chmod(new_path, permissions)

    except Exception as e:
        sys.stderr.write(f"Error: {str(e)}\n")
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser(description="Bulk file renaming tool")
    parser.add_argument("directory", help="Directory containing files to rename")
    parser.add_argument("pattern", help="Regular expression pattern to match")
    parser.add_argument("replacement", help="Replacement pattern")
    parser.add_argument("--permissions", type=lambda x: int(x, 8),
                      help="Octal permissions to apply (e.g., 644)")

    args = parser.parse_args()

    if not os.path.isdir(args.directory):
        sys.stderr.write("Error: Invalid directory\n")
        sys.exit(1)

    rename_files(args.directory, args.pattern, args.replacement, args.permissions)

if __name__ == "__main__":
