class VersionControl:
    def __init__(self):
        self.revisions = {}
        self.current_version = 0
        self.working_directory = {}

    def add_file(self, filename, content):
        self.working_directory[filename] = content

    def commit(self, message):
        self.current_version += 1
        self.revisions[self.current_version] = {
            'files': self.working_directory.copy(),
            'message': message,
            'timestamp': time.time()
        }
        return self.current_version

    def checkout(self, version):
        if version in self.revisions:
            self.working_directory = self.revisions[version]['files'].copy()
            return True
        return False

    def merge(self, source_version, target_version):
        if source_version not in self.revisions or target_version not in self.revisions:
            return False

        source_files = self.revisions[source_version]['files']
        target_files = self.revisions[target_version]['files']

        merged = target_files.copy()
        for filename, content in source_files.items():
            if filename not in target_files:
                merged[filename] = content
            elif target_files[filename] != content:
                merged[filename] = self._merge_content(target_files[filename], content)

        self.working_directory = merged
        return True

    def _merge_content(self, content1, content2):
        return f"<<<<<<< HEAD\n{content1}\n=======\n{content2}\n>>>>>>>"

