import hashlib
import json
from datetime import datetime

class DiffBackup:
    def __init__(self, source_dir, backup_dir):
        self.source_dir = source_dir
        self.backup_dir = backup_dir
        self.manifest_path = os.path.join(backup_dir, 'manifest.json')
        self.previous_hashes = self._load_manifest()

    def _load_manifest(self):
        if os.path.exists(self.manifest_path):
            with open(self.manifest_path, 'r') as f:
                return json.load(f)
        return {}

    def _save_manifest(self, hashes):
        with open(self.manifest_path, 'w') as f:
            json.dump(hashes, f)

    def _get_file_hash(self, filepath):
        hash_md5 = hashlib.md5()
        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()

    def create_backup(self):
        current_hashes = {}
        changed_files = []

        for root, _, files in os.walk(self.source_dir):
            for filename in files:
                filepath = os.path.join(root, filename)
                rel_path = os.path.relpath(filepath, self.source_dir)
                file_hash = self._get_file_hash(filepath)
                current_hashes[rel_path] = file_hash

                if rel_path not in self.previous_hashes or self.previous_hashes[rel_path] != file_hash:
                    changed_files.append(filepath)

        if changed_files:
            backup_name = f'backup_{datetime.now().strftime("%Y%m%d_%H%M%S")}.tar.gz'
            backup_path = os.path.join(self.backup_dir, backup_name)

            with tarfile.open(backup_path, 'w:gz') as tar:
                for file in changed_files:
                    tar.add(file, arcname=os.path.relpath(file, self.source_dir))

            self._save_manifest(current_hashes)
            return backup_path

        return None
