from collections import defaultdict
import re

class SearchEngine:
    def __init__(self):
        self.index = defaultdict(list)
        self.documents = {}

    def add_document(self, doc_id, content):
        self.documents[doc_id] = content
        words = re.findall(r'\w+', content.lower())
        for pos, word in enumerate(words):
            self.index[word].append((doc_id, pos))

    def search(self, query):
        query_words = query.lower().split()
        results = []
        suggestions = []

        for word in query_words:
            if word in self.index:
                doc_ids = set(doc_id for doc_id, _ in self.index[word])
                results.extend(doc_ids)
            else:
                suggestions.extend(self._get_suggestions(word))

        ranked_results = self._rank_results(results)
        return {
            'results': [self.documents[doc_id] for doc_id in ranked_results[:5]],
            'suggestions': list(set(suggestions))[:3]
        }

    def _get_suggestions(self, word):
        suggestions = []
        for indexed_word in self.index.keys():
            if len(word) > 2 and word in indexed_word:
                suggestions.append(indexed_word)
            elif self._levenshtein_distance(word, indexed_word) <= 2:
                suggestions.append(indexed_word)
        return suggestions

    def _rank_results(self, results):
        count_dict = defaultdict(int)
        for doc_id in results:
            count_dict[doc_id] += 1
        return sorted(count_dict, key=count_dict.get, reverse=True)

    def _levenshtein_distance(self, s1, s2):
        if len(s1) < len(s2):
            return self._levenshtein_distance(s2, s1)
        if len(s2) == 0:
            return len(s1)
        previous_row = range(len(s2) + 1)
        for i, c1 in enumerate(s1):
            current_row = [i + 1]
            for j, c2 in enumerate(s2):
                insertions = previous_row[j + 1] + 1
                deletions = current_row[j] + 1
                substitutions = previous_row[j] + (c1 != c2)
                current_row.append(min(insertions, deletions, substitutions))
            previous_row = current_row
        return previous_row[-1]

