        img = cv2.imread(image_path)
        gray = cv2.cvtColor(img, cv2.COLOR_BGR2GRAY)
        thresh = cv2.threshold(gray, 0, 255, cv2.THRESH_BINARY + cv2.THRESH_OTSU)[1]

        # Extract text from image
        text = pytesseract.image_to_string(thresh)

        # Parse receipt details
        receipt = {
            'date': self._extract_date(text),
            'total': self._extract_total(text),
            'vendor': self._extract_vendor(text),
            'items': self._extract_items(text),
            'scan_date': datetime.now()
        }

        self.receipts.append(receipt)
        return receipt

    def _extract_date(self, text):
        # Simple date extraction - could be enhanced
        date_formats = ['%m/%d/%Y', '%m-%d-%Y', '%Y-%m-%d']
        for line in text.split('\n'):
            for fmt in date_formats:
                try:
                    return datetime.strptime(line.strip(), fmt)
                except ValueError:
                    continue
        return None

    def _extract_total(self, text):
        # Look for total amount
        for line in reversed(text.split('\n')):
            if 'total' in line.lower():
                try:
                    amount = Decimal(''.join(c for c in line if c.isdigit() or c == '.'))
                    return amount
                except:
                    continue
        return None

    def _extract_vendor(self, text):
        # Usually first few lines contain vendor name
        lines = text.split('\n')
        return lines[0].strip() if lines else None

    def _extract_items(self, text):
        items = []
        for line in text.split('\n'):
            if '$' in line or '.' in line:
                try:
                    # Try to extract item name and price
                    parts = line.rsplit('$', 1)
                    if len(parts) == 2:
                        name = parts[0].strip()
                        price = Decimal(parts[1].strip())
                        items.append({'item': name, 'price': price})
                except:
                    continue
        return items

    def get_receipt_history(self):
        return self.receipts

    def get_total_expenses(self):
        return sum(r['total'] for r in self.receipts if r['total'])

def main():
    scanner = ReceiptScanner()

    # Example usage
    receipt = scanner.scan_receipt('receipt.jpg')
    print(f"Scanned receipt from {receipt['vendor']}")
    print(f"Date: {receipt['date']}")
    print(f"Total: ${receipt['total']}")
    print("\nItems:")
    for item in receipt['items']:
        print(f"- {item['item']}: ${item['price']}")

    print(f"\nTotal expenses to date: ${scanner.get_total_expenses()}")

if __name__ == "__main__":
    main()
