    def compress_data(self, data_dict, filename=None):
        if not filename:
            filename = f"backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}.gz"

        backup_path = self.backup_dir / filename
        with gzip.open(backup_path, 'wt') as f:
            json.dump(data_dict, f)
