    def extract_data(self, backup_path):
        with gzip.open(backup_path, 'rt') as f:
            return json.load(f)

    def list_backups(self):
        return [f for f in self.backup_dir.glob("*.gz")]

    def cleanup_old_backups(self, keep_last=5):
        backups = sorted(self.list_backups(), key=os.path.getctime)
        for backup in backups[:-keep_last]:
            backup.unlink()

