import ast
import os
import sys
from typing import Dict, List
from dataclasses import dataclass
from pathlib import Path

@dataclass
class MethodMetrics:
    name: str
    complexity: int
    line_count: int
    file_path: str
    start_line: int

class ComplexityAnalyzer(ast.NodeVisitor):
    def __init__(self):
        self.complexity = 0
        self.methods: List[MethodMetrics] = []
        self.current_file = ""

    def visit_FunctionDef(self, node: ast.FunctionDef):
        complexity = 1
        line_count = node.end_lineno - node.lineno

        for child in ast.walk(node):
            if isinstance(child, (ast.If, ast.While, ast.For, ast.Try, ast.ExceptHandler)):
                complexity += 1
            elif isinstance(child, ast.BoolOp):
                complexity += len(child.values) - 1

        self.methods.append(MethodMetrics(
            name=node.name,
            complexity=complexity,
            line_count=line_count,
            file_path=self.current_file,
            start_line=node.lineno
        ))
        self.generic_visit(node)

class CodeAnalyzer:
    def __init__(self, max_complexity: int = 10, max_length: int = 50):
        self.max_complexity = max_complexity
        self.max_length = max_length
        self.analyzer = ComplexityAnalyzer()

    def analyze_file(self, file_path: str) -> List[str]:
        with open(file_path, 'r') as f:
            content = f.read()

        self.analyzer.current_file = file_path
        tree = ast.parse(content)
        self.analyzer.visit(tree)

        issues = []
        for method in self.analyzer.methods:
            if method.complexity > self.max_complexity:
                issues.append(
                    f"{method.file_path}:{method.start_line} - {method.name} has complexity of {method.complexity} (max {self.max_complexity})"
                )
            if method.line_count > self.max_length:
                issues.append(
                    f"{method.file_path}:{method.start_line} - {method.name} is {method.line_count} lines long (max {self.max_length})"
                )
        return issues

    def analyze_directory(self, directory: str) -> List[str]:
        all_issues = []
        for root, _, files in os.walk(directory):
            for file in files:
                if file.endswith('.py'):
                    file_path = os.path.join(root, file)
                    issues = self.analyze_file(file_path)
                    all_issues.extend(issues)
        return all_issues

def main():
    if len(sys.argv) < 2:
        print("Usage: python analyzer.py <directory> [max_complexity] [max_length]")
        sys.exit(1)

    directory = sys.argv[1]
    max_complexity = int(sys.argv[2]) if len(sys.argv) > 2 else 10
    max_length = int(sys.argv[3]) if len(sys.argv) > 3 else 50

    analyzer = CodeAnalyzer(max_complexity, max_length)
    issues = analyzer.analyze_directory(directory)

    if issues:
        print("\nFound code issues:")
        for issue in issues:
            print(f"- {issue}")
        sys.exit(1)
    else:
        print("No issues found!")
        sys.exit(0)

if __name__ == "__main__":
    main()
