import os
import shutil
import datetime
import json
import hashlib
from pathlib import Path

class SystemBackup:
    def __init__(self, backup_dir="/var/backups"):
        self.backup_dir = Path(backup_dir)
        self.backup_dir.mkdir(parents=True, exist_ok=True)
        self.timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")

    def create_snapshot(self, source_path, exclude_patterns=None):
        source = Path(source_path)
        backup_path = self.backup_dir / f"{source.name}_{self.timestamp}"

        if exclude_patterns is None:
            exclude_patterns = [".git", "__pycache__", "*.pyc", "node_modules"]

        if source.is_file():
            shutil.copy2(source, backup_path)
        else:
            shutil.copytree(
                source,
                backup_path,
                ignore=shutil.ignore_patterns(*exclude_patterns),
                dirs_exist_ok=True
            )

        return self._generate_checksum(backup_path)

    def backup_config(self, config_paths):
        config_backup = {}

        for path in config_paths:
            path = Path(path)
            if path.exists():
                with open(path, 'r') as f:
                    config_backup[str(path)] = f.read()

        backup_file = self.backup_dir / f"config_backup_{self.timestamp}.json"
        with open(backup_file, 'w') as f:
            json.dump(config_backup, f, indent=4)

        return str(backup_file)

    def _generate_checksum(self, path):
        sha256 = hashlib.sha256()

        if Path(path).is_file():
            with open(path, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b''):
                    sha256.update(chunk)
        else:
            for root, _, files in os.walk(path):
                for file in sorted(files):
                    file_path = Path(root) / file
                    with open(file_path, 'rb') as f:
                        for chunk in iter(lambda: f.read(4096), b''):
                            sha256.update(chunk)

        return sha256.hexdigest()

    def list_backups(self):
        backups = []
        for item in self.backup_dir.iterdir():
            if item.is_file() or item.is_dir():
                backups.append({
                    'path': str(item),
                    'size': self._get_size(item),
                    'timestamp': item.stat().st_mtime
                })
        return backups

    def _get_size(self, path):
        if path.is_file():
            return path.stat().st_size
        return sum(f.stat().st_size for f in path.rglob('*') if f.is_file())

if __name__ == "__main__":
    backup = SystemBackup()

    # Example usage
    source_dirs = ["/etc/nginx", "/etc/apache2"]
    config_files = ["/etc/hosts", "/etc/passwd"]

    for directory in source_dirs:
        if Path(directory).exists():
            checksum = backup.create_snapshot(directory)
            print(f"Backed up {directory} with checksum: {checksum}")

    config_backup_path = backup.backup_config(config_files)
    print(f"Configuration files backed up to: {config_backup_path}")

    backups = backup.list_backups()
    for backup in backups:
        print(f"Backup: {backup['path']}, Size: {backup['size']} bytes")

