                current_dialogue.append({
                    'speaker': speaker.strip(),
                    'text': text.strip(),
                    'timestamp': len(current_dialogue)
                })
            elif current_dialogue:
                if len(dialogues['train']) < 8000:
                    dialogues['train'].append(current_dialogue)
                elif len(dialogues['valid']) < 1000:
                    dialogues['valid'].append(current_dialogue)
                else:
                    dialogues['test'].append(current_dialogue)
                current_dialogue = []

    return dialogues

def preprocess_dialogue(dialogue):
    processed = []
    for utterance in dialogue:
        text = utterance['text'].lower()
        tokens = text.split()
        processed.append({
            'speaker': utterance['speaker'],
            'tokens': tokens,
            'timestamp': utterance['timestamp']
        })
    return processed

def load_and_preprocess():
    raw_dialogues = load_dialogue_data()
    processed = {split: [] for split in raw_dialogues}

    for split, dialogues in raw_dialogues.items():
        for dialogue in dialogues:
            processed[split].append(preprocess_dialogue(dialogue))

    return processed

