import shutil
import tarfile
import subprocess
import urllib.request
from pathlib import Path

class Builder:
    def __init__(self, build_dir="./build"):
        self.build_dir = Path(build_dir)
        self.build_dir.mkdir(exist_ok=True)
        self.sources_dir = self.build_dir / "sources"
        self.sources_dir.mkdir(exist_ok=True)

    def fetch_tarball(self, url, filename):
        target_path = self.sources_dir / filename
        if not target_path.exists():
            urllib.request.urlretrieve(url, target_path)
        return target_path

    def extract_tarball(self, tarball_path):
        with tarfile.open(tarball_path, "r:*") as tar:
            tar.extractall(path=self.sources_dir)
            return self.sources_dir / Path(tar.getnames()[0]).parts[0]

    def configure_and_make(self, source_dir):
        os.chdir(source_dir)
        subprocess.run(["./configure"], check=True)
        subprocess.run(["make", "-j", str(os.cpu_count())], check=True)
        subprocess.run(["make", "install"], check=True)

    def build_package(self, url, filename):
        try:
            print(f"Fetching {filename}...")
            tarball = self.fetch_tarball(url, filename)

            print("Extracting sources...")
            source_dir = self.extract_tarball(tarball)

            print("Building...")
            self.configure_and_make(source_dir)

            print("Build completed successfully")
            return True
        except Exception as e:
            print(f"Build failed: {str(e)}")
            return False

def main():
    builder = Builder()
    packages = {
        "example": {
            "url": "https://example.com/package.tar.gz",
            "filename": "package.tar.gz"
        }
    }

    for name, info in packages.items():
        print(f"\nBuilding {name}...")
        builder.build_package(info["url"], info["filename"])

if __name__ == "__main__":
    main()

