import requests
from urllib.parse import urlparse
from typing import List, Dict

def trace_redirects(url: str, max_redirects: int = 10) -> List[Dict[str, str]]:
    redirect_chain = []
    visited_urls = set()

    try:
        response = requests.get(url, allow_redirects=False)
        initial_url = urlparse(url)
        redirect_chain.append({
            'url': url,
            'status_code': response.status_code,
            'domain': initial_url.netloc
        })

        while response.is_redirect and len(redirect_chain) < max_redirects:
            next_url = response.headers['Location']
            if next_url in visited_urls:
                break

            visited_urls.add(next_url)
            parsed_url = urlparse(next_url)

            response = requests.get(next_url, allow_redirects=False)
            redirect_chain.append({
                'url': next_url,
                'status_code': response.status_code,
                'domain': parsed_url.netloc
            })

    except requests.exceptions.RequestException as e:
        redirect_chain.append({
            'url': str(e),
            'status_code': 0,
            'domain': 'error'
        })

    return redirect_chain

if __name__ == '__main__':
    test_url = 'http://bit.ly/example'
    redirects = trace_redirects(test_url)
