class PluginManager:
    def __init__(self, plugins_dir, repository_url):
        self.plugins_dir = Path(plugins_dir)
        self.repository_url = repository_url
        self.installed_plugins = {}
        self.plugins_dir.mkdir(exist_ok=True)

    def download_plugin(self, plugin_id, version):
        url = f"{self.repository_url}/plugins/{plugin_id}/{version}/download"
        response = requests.get(url, stream=True)
        response.raise_for_status()

        temp_file = self.plugins_dir / f"{plugin_id}_{version}.zip"
        with open(temp_file, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)
        return temp_file

    def verify_checksum(self, file_path, expected_hash):
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest() == expected_hash

    def install_plugin(self, plugin_id, version):
        try:
            plugin_file = self.download_plugin(plugin_id, version)
            plugin_dir = self.plugins_dir / plugin_id

            with zipfile.ZipFile(plugin_file, 'r') as zip_ref:
                zip_ref.extractall(plugin_dir)

            self.installed_plugins[plugin_id] = {
                'version': version,
                'path': str(plugin_dir)
            }

            plugin_file.unlink()
            return True
        except Exception as e:
            print(f"Failed to install plugin {plugin_id}: {str(e)}")
            return False

    def uninstall_plugin(self, plugin_id):
        if plugin_id in self.installed_plugins:
            plugin_path = Path(self.installed_plugins[plugin_id]['path'])
            if plugin_path.exists():
                for item in plugin_path.glob('*'):
                    if item.is_file():
                        item.unlink()
                    else:
                        for subitem in item.glob('**/*'):
                            subitem.unlink()
                        item.rmdir()
                plugin_path.rmdir()
            del self.installed_plugins[plugin_id]
            return True
        return False

    def list_installed_plugins(self):
        return self.installed_plugins

