import tarfile
import os
import curses
import tempfile

class TarBrowser:
    def __init__(self, tar_path):
        self.tar = tarfile.open(tar_path, 'r:*')
        self.current_path = []
        self.temp_dir = tempfile.mkdtemp()

    def get_current_items(self):
        prefix = '/'.join(self.current_path)
        items = []
        for member in self.tar.getmembers():
            if prefix:
                if not member.name.startswith(prefix + '/'):
                    continue
                rel_path = member.name[len(prefix)+1:]
            else:
                rel_path = member.name

            if '/' in rel_path:
                dirname = rel_path.split('/')[0]
                if dirname not in items:
                    items.append(dirname)
            elif rel_path:
                items.append(rel_path)
        return sorted(items)

    def view_file(self, filename):
        full_path = '/'.join(self.current_path + [filename])
        member = self.tar.getmember(full_path)
        temp_path = os.path.join(self.temp_dir, filename)

        with open(temp_path, 'wb') as f:
            f.write(self.tar.extractfile(member).read())

        curses.endwin()
        os.system(f'less {temp_path}')
        os.unlink(temp_path)

    def run(self, stdscr):
        current_pos = 0
        while True:
            items = self.get_current_items()

            stdscr.clear()
            header = '/'.join(self.current_path) or '/'
            stdscr.addstr(0, 0, header)

            for i, item in enumerate(items):
                if i == current_pos:
                    stdscr.addstr(i + 2, 0, '> ' + item, curses.A_REVERSE)
                else:
                    stdscr.addstr(i + 2, 0, '  ' + item)

            key = stdscr.getch()

            if key == curses.KEY_UP and current_pos > 0:
                current_pos -= 1
            elif key == curses.KEY_DOWN and current_pos < len(items) - 1:
                current_pos += 1
            elif key == ord('\n'):
                if items:
                    selected = items[current_pos]
                    full_path = '/'.join(self.current_path + [selected])
                    if self.tar.getmember(full_path).isfile():
                        self.view_file(selected)
                    else:
                        self.current_path.append(selected)
                        current_pos = 0
            elif key == ord('q'):
                break
            elif key == ord('h') and self.current_path:
                self.current_path.pop()
                current_pos = 0

def main(tar_path):
    browser = TarBrowser(tar_path)
    curses.wrapper(browser.run)

if __name__ == '__main__':
    import sys
    if len(sys.argv) != 2:
        print("Usage: tar_browser.py <tarfile>")
        sys.exit(1)
    main(sys.argv[1])
