import socket
import os
import threading
from pathlib import Path

class FTPServer:
    def __init__(self, host='0.0.0.0', port=21, root_dir='./ftproot'):
        self.host = host
        self.port = port
        self.root_dir = Path(root_dir)
        self.root_dir.mkdir(exist_ok=True)
        self.clients = {}

    def start(self):
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen(5)

        while True:
            client_socket, addr = self.server_socket.accept()
            client_thread = threading.Thread(target=self.handle_client, args=(client_socket, addr))
            client_thread.start()

    def handle_client(self, client_socket, addr):
        client_socket.send(b"220 Welcome to Python FTP Server\r\n")
        current_dir = self.root_dir

        while True:
            try:
                cmd = client_socket.recv(1024).decode().strip()
                if not cmd:
                    break

                cmd_parts = cmd.split()
                command = cmd_parts[0].upper()

                if command == "USER":
                    client_socket.send(b"331 Username OK, password required\r\n")

                elif command == "PASS":
                    client_socket.send(b"230 Login successful\r\n")

                elif command == "PWD":
                    client_socket.send(f"257 \"{current_dir.relative_to(self.root_dir)}\"\r\n".encode())

                elif command == "CWD":
                    try:
                        new_dir = (current_dir / cmd_parts[1]).resolve()
                        if self.root_dir in new_dir.parents or new_dir == self.root_dir:
                            current_dir = new_dir
                            client_socket.send(b"250 Directory changed successfully\r\n")
                        else:
                            client_socket.send(b"550 Access denied\r\n")
                    except:
                        client_socket.send(b"550 Directory not found\r\n")

                elif command == "LIST":
                    try:
                        files = os.listdir(current_dir)
                        response = "150 File list follows\r\n"
                        for file in files:
                            response += f"{file}\r\n"
                        response += "226 Transfer complete\r\n"
                        client_socket.send(response.encode())
                    except:
                        client_socket.send(b"550 Failed to list directory\r\n")

                elif command == "QUIT":
                    client_socket.send(b"221 Goodbye\r\n")
                    break

                else:
                    client_socket.send(b"500 Unknown command\r\n")

            except Exception as e:
                print(f"Error handling client {addr}: {e}")
                break

        client_socket.close()

if __name__ == "__main__":
    server = FTPServer()
    print("FTP Server starting...")
    server.start()

