class ServiceRegistry:
    def __init__(self):
        self.services = {}
        self.heartbeats = {}
        self.ttl = 30

    def register(self, service_name, address, port):
        self.services[service_name] = {
            'address': address,
            'port': port,
            'timestamp': time.time()
        }
        self.heartbeats[service_name] = time.time()

    def deregister(self, service_name):
        if service_name in self.services:
            del self.services[service_name]
            del self.heartbeats[service_name]

    def get_service(self, service_name):
        if service_name in self.services:
            return self.services[service_name]
        return None

    def cleanup_stale(self):
        current_time = time.time()
        stale_services = [
            service for service, last_beat in self.heartbeats.items()
            if current_time - last_beat > self.ttl
        ]
        for service in stale_services:
            self.deregister(service)

