from pathlib import Path

class ZipDiskCopier:
    def __init__(self, source_path, destination_path):
        self.source = Path(source_path)
        self.destination = Path(destination_path)
        self.copied_files = []
        self.errors = []

    def verify_paths(self):
        if not self.source.exists():
            raise FileNotFoundError(f"Source path {self.source} not found")
        if not self.destination.exists():
            self.destination.mkdir(parents=True)

    def copy_files(self):
        for file_path in self.source.rglob('*'):
            if file_path.is_file():
                relative_path = file_path.relative_to(self.source)
                dest_path = self.destination / relative_path
                dest_path.parent.mkdir(parents=True, exist_ok=True)

                try:
                    shutil.copy2(file_path, dest_path)
                    self.copied_files.append(str(relative_path))
                except Exception as e:
                    self.errors.append((str(relative_path), str(e)))

    def verify_copy(self):
        for file_path in self.copied_files:
            source_file = self.source / file_path
            dest_file = self.destination / file_path

            if not dest_file.exists():
                self.errors.append((file_path, "Verification failed: File not found"))
            elif source_file.stat().st_size != dest_file.stat().st_size:
                self.errors.append((file_path, "Verification failed: Size mismatch"))

    def generate_report(self):
        timestamp = time.strftime("%Y%m%d-%H%M%S")
        report_path = self.destination / f"copy_report_{timestamp}.txt"

        with open(report_path, 'w') as f:
            f.write(f"Copy Report - {timestamp}\n\n")
            f.write(f"Source: {self.source}\n")
            f.write(f"Destination: {self.destination}\n\n")

            f.write("Files copied:\n")
            for file in self.copied_files:
                f.write(f"- {file}\n")

            if self.errors:
                f.write("\nErrors encountered:\n")
                for file, error in self.errors:
                    f.write(f"- {file}: {error}\n")

def main():
