from flask import Flask, Response
import requests
import time
from threading import Lock
from collections import OrderedDict

class Cache:
    def __init__(self, capacity=1000, ttl=300):
        self.capacity = capacity
        self.ttl = ttl
        self.cache = OrderedDict()
        self.timestamps = {}
        self.lock = Lock()

    def get(self, url):
        with self.lock:
            if url in self.cache:
                if time.time() - self.timestamps[url] < self.ttl:
                    self.cache.move_to_end(url)
                    return self.cache[url]
                else:
                    self.cache.pop(url)
                    del self.timestamps[url]
            return None

    def put(self, url, response):
        with self.lock:
            if url in self.cache:
                self.cache.pop(url)
            elif len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
            self.cache[url] = response
            self.timestamps[url] = time.time()
            self.cache.move_to_end(url)

app = Flask(__name__)
cache = Cache()

@app.route('/<path:url>')
def proxy(url):
    if not url.startswith(('http://', 'https://')):
        url = 'http://' + url

    cached_response = cache.get(url)
    if cached_response:
        return Response(cached_response['content'], 
                       status=cached_response['status_code'],
                       headers=cached_response['headers'])

    response = requests.get(url)
    cached_data = {
        'content': response.content,
        'status_code': response.status_code,
        'headers': dict(response.headers)
    }
    cache.put(url, cached_data)

    return Response(response.content,
                   status=response.status_code,
                   headers=dict(response.headers))

