        return showing_id

    def get_available_seats(self, showing_id: str) -> List[Seat]:
        showing = self.showings[showing_id]
        return [seat for seat in showing.seats if seat.is_available]

    def book_seats(self, showing_id: str, seats: List[tuple]) -> bool:
        showing = self.showings[showing_id]
        for row, number in seats:
            for seat in showing.seats:
