    backup_root = "/media/backup"
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_dir = os.path.join(backup_root, f"home_backup_{timestamp}")

    try:
        if not os.path.exists(backup_root):
            os.makedirs(backup_root)

        shutil.copytree(home_dir, backup_dir, symlinks=True, ignore=shutil.ignore_patterns('*.tmp', '*.cache', '*.pyc'))

