from pathlib import Path

class ServerMonitor:
    def __init__(self, output_dir="/var/log/monitoring", permissions=0o640):
        self.servers = {
            'localhost': {'cpu_threshold': 80, 'memory_threshold': 90}
        }
        self.output_dir = Path(output_dir)
        self.permissions = permissions
        self.output_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(self.output_dir, permissions)

    def check_server(self, server):
        cpu_percent = psutil.cpu_percent(interval=1)
        memory = psutil.virtual_memory()

        return {
            'timestamp': datetime.now().isoformat(),
            'server': server,
            'cpu_usage': cpu_percent,
            'memory_usage': memory.percent,
            'is_anomaly': (
                cpu_percent > self.servers[server]['cpu_threshold'] or 
                memory.percent > self.servers[server]['memory_threshold']
            )
        }

    def save_measurements(self, measurements):
        timestamp = datetime.now().strftime('%Y%m%d_%H')
        output_file = self.output_dir / f"metrics_{timestamp}.json"

        with open(output_file, 'a') as f:
            json.dump(measurements, f)
            f.write('\n')

        os.chmod(output_file, self.permissions)

    def run(self):
        while True:
            for server in self.servers:
                measurements = self.check_server(server)
                if measurements['is_anomaly']:
                    self.save_measurements(measurements)
            time.sleep(3600)  # Sleep for 1 hour

if __name__ == "__main__":
    monitor = ServerMonitor()
    monitor.run()
