    bookings: List[dict]

class MeetingRoomScheduler:
    def __init__(self):
        self.rooms: Dict[int, Room] = {}

    def add_room(self, name: str, capacity: int) -> int:
        room_id = len(self.rooms) + 1
        self.rooms[room_id] = Room(room_id, name, capacity, [])
        return room_id

    def book_room(self, room_id: int, start_time: datetime, 
                  end_time: datetime, attendees: int) -> bool:
        room = self.rooms.get(room_id)
        if not room:
            raise ValueError("Room does not exist")

        if attendees > room.capacity:
            return False

        for booking in room.bookings:
            if (start_time < booking['end_time'] and 
                end_time > booking['start_time']):
                return False

        room.bookings.append({
            'start_time': start_time,
            'end_time': end_time,
            'attendees': attendees
        })
        return True

    def get_available_rooms(self, start_time: datetime, 
                          end_time: datetime, capacity: int) -> List[Room]:
        available = []
        for room in self.rooms.values():
            if room.capacity < capacity:
                continue

            is_available = True
            for booking in room.bookings:
                if (start_time < booking['end_time'] and 
                    end_time > booking['start_time']):
                    is_available = False
                    break

            if is_available:
                available.append(room)

        return available

    def cancel_booking(self, room_id: int, start_time: datetime) -> bool:
        room = self.rooms.get(room_id)
        if not room:
            return False

        for i, booking in enumerate(room.bookings):
            if booking['start_time'] == start_time:
                room.bookings.pop(i)
