import os
from mutagen import File, id3
import requests
from PIL import Image
from io import BytesIO

class MusicPlayer:
    def __init__(self, music_dir):
        self.music_dir = music_dir
        self.current_track = None
        self.playlist = []

    def load_library(self):
        for root, _, files in os.walk(self.music_dir):
            for file in files:
                if file.endswith(('.mp3', '.flac', '.m4a')):
                    filepath = os.path.join(root, file)
                    self.playlist.append(filepath)

    def get_metadata(self, filepath):
        audio = File(filepath)
        metadata = {
            'title': None,
            'artist': None,
            'album': None,
            'artwork': None
        }

        if isinstance(audio.tags, id3.ID3):
            tags = audio.tags
            metadata['title'] = str(tags.get('TIT2', ''))
            metadata['artist'] = str(tags.get('TPE1', ''))
            metadata['album'] = str(tags.get('TALB', ''))

            for tag in tags.values():
                if tag.FrameID == 'APIC':
                    metadata['artwork'] = Image.open(BytesIO(tag.data))
                    break

        return metadata

    def fetch_album_art(self, artist, album):
        url = f"https://api.musicbrainz.org/v2/release/?query={artist}+{album}"
        headers = {'User-Agent': 'MusicPlayer/1.0'}
        response = requests.get(url, headers=headers)

        if response.status_code == 200:
            data = response.json()
            if data.get('releases'):
                release_id = data['releases'][0]['id']
                art_url = f"https://coverartarchive.org/release/{release_id}/front"
                art_response = requests.get(art_url)
                if art_response.status_code == 200:
                    return Image.open(BytesIO(art_response.content))
        return None

    def play(self, track_index):
        if 0 <= track_index < len(self.playlist):
            self.current_track = self.playlist[track_index]
            metadata = self.get_metadata(self.current_track)

            if not metadata['artwork']:
                metadata['artwork'] = self.fetch_album_art(
                    metadata['artist'],
                    metadata['album']
                )

            return metadata
        return None

    def get_current_track_info(self):
        if self.current_track:
            return self.get_metadata(self.current_track)
        return None

if __name__ == "__main__":
