        self.extension = os.path.splitext(filepath)[1].lower()

    def extract(self, destination_path=None):
        if destination_path is None:
            destination_path = os.getcwd()

        if self.extension in ['.tar', '.gz', '.tgz', '.bz2']:
            self._extract_tar(destination_path)
        elif self.extension == '.zip':
            self._extract_zip(destination_path)
        else:
            raise ValueError(f"Unsupported archive format: {self.extension}")

    def _extract_tar(self, destination_path):
        mode = 'r:*'
        with tarfile.open(self.filepath, mode) as tar:
            tar.extractall(path=destination_path)

    def _extract_zip(self, destination_path):
        with zipfile.ZipFile(self.filepath, 'r') as zip_ref:
            zip_ref.extractall(destination_path)

    def list_contents(self):
        if self.extension in ['.tar', '.gz', '.tgz', '.bz2']:
            with tarfile.open(self.filepath, 'r:*') as tar:
                return tar.getnames()
        elif self.extension == '.zip':
            with zipfile.ZipFile(self.filepath, 'r') as zip_ref:
                return zip_ref.namelist()
        return []

