from pathlib import Path

def copy_files(manifest_path, target_dir):
    with open(manifest_path) as f:
        files = [line.strip() for line in f if line.strip()]

    Path(target_dir).mkdir(parents=True, exist_ok=True)

    for source_path in files:
        if not os.path.exists(source_path):
            print(f"Skipping {source_path}: not found")
            continue

        dest_path = os.path.join(target_dir, os.path.basename(source_path))
        source_perms = stat.S_IMODE(os.stat(source_path).st_mode)

        choice = input(f"Copy {source_path} - Use source permissions ({oct(source_perms)})? [Y/n/custom]: ").lower()

        if choice == 'n':
            shutil.copy2(source_path, dest_path)
        elif choice.startswith('custom'):
            try:
                new_perms = int(input("Enter permissions in octal (e.g. 644): "), 8)
                shutil.copy2(source_path, dest_path)
                os.chmod(dest_path, new_perms)
            except ValueError:
                print("Invalid permissions, using source permissions")
                shutil.copy2(source_path, dest_path, follow_symlinks=True)
        else:
            shutil.copy2(source_path, dest_path, follow_symlinks=True)

if __name__ == "__main__":
