import os
import shutil
from datetime import datetime
import zipfile

class BackupManager:
    def __init__(self, source_dir, backup_dir):
        self.source_dir = os.path.abspath(source_dir)
        self.backup_dir = os.path.abspath(backup_dir)

    def create_backup(self):
        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        archive_name = f'backup_{timestamp}.zip'
        archive_path = os.path.join(self.backup_dir, archive_name)

        with zipfile.ZipFile(archive_path, 'w', zipfile.ZIP_DEFLATED) as archive:
            for root, _, files in os.walk(self.source_dir):
                for file in files:
                    file_path = os.path.join(root, file)
                    archive.write(file_path, os.path.relpath(file_path, self.source_dir))

        return archive_path

    def restore_backup(self, archive_path, restore_dir):
        os.makedirs(restore_dir, exist_ok=True)

        with zipfile.ZipFile(archive_path, 'r') as archive:
            archive.extractall(restore_dir)

    def list_backups(self):
        backups = []
        for file in os.listdir(self.backup_dir):
            if file.startswith('backup_') and file.endswith('.zip'):
                backup_path = os.path.join(self.backup_dir, file)
                backups.append({
                    'name': file,
                    'path': backup_path,
                    'size': os.path.getsize(backup_path),
                    'date': datetime.fromtimestamp(os.path.getctime(backup_path))
                })
        return backups

from urllib.parse import urlparse
import re

class LinkRewriter:
    def __init__(self, blocked_domains=None):
        self.blocked_domains = set(blocked_domains or [])

    def rewrite_url(self, url, new_domain):
        parsed = urlparse(url)
        if parsed.netloc in self.blocked_domains:
            return url

        return url.replace(parsed.netloc, new_domain)

    def rewrite_html(self, html_content, new_domain):
        pattern = r'href=[\'"]?(https?://[^\'" >]+)'

        def replace_match(match):
            url = match.group(1)
            return f'href="{self.rewrite_url(url, new_domain)}"'

        return re.sub(pattern, replace_match, html_content)

    def add_blocked_domain(self, domain):
        self.blocked_domains.add(domain)

    def remove_blocked_domain(self, domain):
        self.blocked_domains.discard(domain)

