import uuid

@dataclass
class Flight:
    flight_number: str
    departure: str
    arrival: str
    departure_time: datetime
    arrival_time: datetime
    price: float

@dataclass
class Booking:
    booking_id: str
    user_id: str
    flights: List[Flight]
    total_price: float
    status: str
    created_at: datetime

class TravelBookingSystem:
    def __init__(self):
        self.bookings = {}
        self.flights = {}

    def search_flights(self, departure: str, arrival: str, date: datetime) -> List[Flight]:
        return [flight for flight in self.flights.values()
                if flight.departure == departure
                and flight.arrival == arrival
                and flight.departure_time.date() == date.date()]

    def create_booking(self, user_id: str, flight_ids: List[str]) -> Booking:
        flights = [self.flights[fid] for fid in flight_ids]
        total_price = sum(flight.price for flight in flights)

        booking = Booking(
            booking_id=str(uuid.uuid4()),
            user_id=user_id,
            flights=flights,
            total_price=total_price,
            status='PENDING',
            created_at=datetime.now()
        )

        self.bookings[booking.booking_id] = booking
        return booking

    def confirm_booking(self, booking_id: str) -> None:
        if booking_id in self.bookings:
            self.bookings[booking_id].status = 'CONFIRMED'

    def cancel_booking(self, booking_id: str) -> None:
        if booking_id in self.bookings:
            self.bookings[booking_id].status = 'CANCELLED'

    def get_booking(self, booking_id: str) -> Optional[Booking]:
        return self.bookings.get(booking_id)

