import os
import graphviz
from ast import parse, NodeVisitor

class UMLGenerator(NodeVisitor):
    def __init__(self):
        self.classes = {}
        self.relationships = []

    def visit_ClassDef(self, node):
        class_info = {
            'name': node.name,
            'methods': [],
            'attributes': []
        }

        for item in node.body:
            if isinstance(item, ast.FunctionDef):
                class_info['methods'].append(item.name)
            elif isinstance(item, ast.Assign):
                for target in item.targets:
                    if isinstance(target, ast.Name):
                        class_info['attributes'].append(target.id)

        self.classes[node.name] = class_info
        self.generic_visit(node)

    def generate_diagram(self, output_path):
        dot = graphviz.Digraph(comment='UML Class Diagram')

        for class_name, info in self.classes.items():
            label = f"{class_name}|"
            label += "\l".join(info['attributes']) + "|"
            label += "\l".join(info['methods'])
            dot.node(class_name, label)

        for rel in self.relationships:
            dot.edge(rel[0], rel[1])

        dot.render(output_path, format='png')
        os.chmod(output_path + '.png', 0o644)

def generate_uml(source_code, output_path):
    tree = parse(source_code)
    generator = UMLGenerator()
    generator.visit(tree)
    generator.generate_diagram(output_path)
