import os
import json
import hashlib
from datetime import datetime

class VersionControl:
    def __init__(self, repo_path):
        self.repo_path = repo_path
        self.metadata_path = os.path.join(repo_path, '.vcm')
        self.current_version = 0

        if not os.path.exists(self.metadata_path):
            os.makedirs(self.metadata_path)
            self.metadata = {}
            self.save_metadata()
        else:
            self.load_metadata()

    def load_metadata(self):
        with open(os.path.join(self.metadata_path, 'metadata.json'), 'r') as f:
            self.metadata = json.load(f)

    def save_metadata(self):
        with open(os.path.join(self.metadata_path, 'metadata.json'), 'w') as f:
            json.dump(self.metadata, f)

    def commit(self, message):
        self.current_version += 1
        timestamp = datetime.now().isoformat()

        metadata = {
            'version': self.current_version,
            'timestamp': timestamp,
            'message': message,
            'files': {}
        }

        for root, dirs, files in os.walk(self.repo_path):
            if '.vcm' in root:
                continue

            for file in files:
                file_path = os.path.join(root, file)
                rel_path = os.path.relpath(file_path, self.repo_path)
                stat = os.stat(file_path)

                with open(file_path, 'rb') as f:
                    content = f.read()
                    checksum = hashlib.sha256(content).hexdigest()

                metadata['files'][rel_path] = {
                    'mode': stat.st_mode,
                    'uid': stat.st_uid,
                    'gid': stat.st_gid,
                    'size': stat.st_size,
                    'checksum': checksum
                }

        self.metadata[str(self.current_version)] = metadata
        self.save_metadata()
        return self.current_version

    def checkout(self, version):
        if str(version) not in self.metadata:
            raise ValueError(f"Version {version} not found")

        version_data = self.metadata[str(version)]

        for rel_path, file_meta in version_data['files'].items():
            full_path = os.path.join(self.repo_path, rel_path)

            if os.path.exists(full_path):
                os.chmod(full_path, file_meta['mode'])
                os.chown(full_path, file_meta['uid'], file_meta['gid'])

    def get_history(self):
        history = []
        for version in sorted(self.metadata.keys(), key=int):
            meta = self.metadata[version]
            history.append({
                'version': meta['version'],
                'timestamp': meta['timestamp'],
                'message': meta['message']
            })
        return history

    def get_file_metadata(self, path, version=None):
        if version is None:
            version = self.current_version

        version_data = self.metadata.get(str(version))
        if not version_data:
            return None

        return version_data['files'].get(path)
