import os
import tkinter as tk
from PIL import Image, ImageTk
import stat
import datetime

class ARFileBrowser:
    def __init__(self, root):
        self.root = root
        self.canvas = tk.Canvas(root, width=1024, height=768)
        self.canvas.pack()

        self.nodes = {}
        self.layout_depth = 100
        self.layout_width = 150

    def scan_directory(self, path):
        try:
            for entry in os.scandir(path):
                stats = entry.stat()
                node = {
                    'name': entry.name,
                    'path': entry.path,
                    'size': stats.st_size,
                    'permissions': stat.filemode(stats.st_mode),
                    'modified': datetime.datetime.fromtimestamp(stats.st_mtime),
                    'is_dir': entry.is_dir(),
                    'x': 0,
                    'y': 0,
                    'children': []
                }
                self.nodes[entry.path] = node

                if entry.is_dir():
                    self.scan_directory(entry.path)

        except PermissionError:
            pass

    def visualize(self, start_path):
        self.scan_directory(start_path)
        self.layout_nodes(start_path, 50, 50)
        self.draw_nodes()

    def layout_nodes(self, path, x, y):
        if path not in self.nodes:
            return

        node = self.nodes[path]
        node['x'] = x
        node['y'] = y

        if node['is_dir']:
            child_y = y + self.layout_depth
            child_x = x

            for entry in os.scandir(path):
                self.layout_nodes(entry.path, child_x, child_y)
                child_x += self.layout_width

    def draw_nodes(self):
        for path, node in self.nodes.items():
            color = 'blue' if node['is_dir'] else 'green'
            size = min(20 + node['size'] // 1000000, 50)

            self.canvas.create_oval(
                node['x'] - size/2,
                node['y'] - size/2,
                node['x'] + size/2,
                node['y'] + size/2,
                fill=color
            )

            self.canvas.create_text(
                node['x'],
                node['y'] + size/2 + 10,
                text=f"{node['name']}\n{node['permissions']}"
            )

            if node['is_dir']:
                for entry in os.scandir(node['path']):
                    if entry.path in self.nodes:
                        child = self.nodes[entry.path]
                        self.canvas.create_line(
                            node['x'],
                            node['y'],
                            child['x'],
                            child['y']
                        )

if __name__ == '__main__':
    root = tk.Tk()
    app = ARFileBrowser(root)
    app.visualize('.')
    root.mainloop()

