            growth_records=[]
        )

    def log_sleep(self, child_name: str, start_time: datetime, 
                  end_time: datetime, sleep_type: str) -> None:
        sleep_session = {
            "start": start_time,
            "end": end_time,
            "duration": (end_time - start_time).total_seconds() / 3600,
            "type": sleep_type
        }
        self.children[child_name].sleep_logs.append(sleep_session)

    def record_milestone(self, child_name: str, 
