        self.children[child_name].milestones[milestone] = achieved_date

    def add_growth_record(self, child_name: str, 
                         weight: float, height: float, 
                         head_circumference: float) -> None:
        record = {
            "date": date.today(),
            "weight_kg": weight,
            "height_cm": height,
            "head_cm": head_circumference
        }
        self.children[child_name].growth_records.append(record)

