import os
import jinja2
import yaml
from pathlib import Path

class StaticSiteGenerator:
    def __init__(self, content_dir="content", template_dir="templates", output_dir="output"):
        self.content_dir = Path(content_dir)
        self.template_dir = Path(template_dir)
        self.output_dir = Path(output_dir)
        self.env = jinja2.Environment(
            loader=jinja2.FileSystemLoader(str(self.template_dir))
        )

    def load_content(self, path):
        with open(path) as f:
            content = yaml.safe_load(f)
        return content

    def render_page(self, template_name, data):
        template = self.env.get_template(template_name)
        return template.render(**data)

    def build(self):
        self.output_dir.mkdir(exist_ok=True)

        for content_file in self.content_dir.glob("*.yml"):
            data = self.load_content(content_file)
            output = self.render_page("page.html", data)

            output_path = self.output_dir / f"{content_file.stem}.html"
            with open(output_path, "w") as f:
                f.write(output)

if __name__ == "__main__":
    generator = StaticSiteGenerator()
    generator.build()

import os
import hashlib
import shutil
import time
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class SyncHandler(FileSystemEventHandler):
    def __init__(self, source_dir, target_dir):
        self.source_dir = source_dir
        self.target_dir = target_dir

    def on_modified(self, event):
        if not event.is_directory:
            src_path = event.src_path
            rel_path = os.path.relpath(src_path, self.source_dir)
            dst_path = os.path.join(self.target_dir, rel_path)

            if os.path.exists(src_path):
                os.makedirs(os.path.dirname(dst_path), exist_ok=True)
                shutil.copy2(src_path, dst_path)

def get_file_hash(filepath):
    hash_md5 = hashlib.md5()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def sync_directories(source_dir, target_dir):
    observer = Observer()
    handler = SyncHandler(source_dir, target_dir)
    observer.schedule(handler, source_dir, recursive=True)
    observer.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

if __name__ == "__main__":
    source_directory = "/path/to/source"
    target_directory = "/path/to/target"
    sync_directories(source_directory, target_directory)

