class FoodDeliveryApp:
    def __init__(self):
        self.restaurants: Dict[int, Restaurant] = {}

    def add_restaurant(self, restaurant: Restaurant):
        self.restaurants[restaurant.id] = restaurant

    def get_restaurants_by_cuisine(self, cuisine: Cuisine) -> List[Restaurant]:
        return [r for r in self.restaurants.values() if r.cuisine == cuisine]

    def filter_restaurants(self, 
                         cuisine: Cuisine = None,
                         min_rating: float = 0,
                         max_delivery_time: int = None,
                         vegetarian_only: bool = False) -> List[Restaurant]:
        filtered = self.restaurants.values()

        if cuisine:
            filtered = [r for r in filtered if r.cuisine == cuisine]

        if min_rating > 0:
            filtered = [r for r in filtered if r.rating >= min_rating]

        if max_delivery_time:
            filtered = [r for r in filtered if r.delivery_time <= max_delivery_time]

        if vegetarian_only:
            filtered = [r for r in filtered if any(i.is_vegetarian for i in r.menu_items)]

        return filtered

    def get_open_restaurants(self) -> List[Restaurant]:
        return [r for r in self.restaurants.values() if r.is_open]

    def search_menu_items(self, query: str) -> Dict[Restaurant, List[MenuItem]]:
        results = {}
        for restaurant in self.restaurants.values():
            matching_items = [
                item for item in restaurant.menu_items 
                if query.lower() in item.name.lower() or query.lower() in item.description.lower()
            ]
            if matching_items:
