import os
import re
from collections import defaultdict, Counter
from datetime import datetime

class LogAnalyzer:
    def __init__(self, log_path):
        self.log_path = log_path
        self.stats = defaultdict(Counter)
        self.errors = []
        self.requests = []

    def parse_log(self):
        with open(self.log_path, 'r') as file:
            for line in file:
                try:
                    timestamp = re.search(r'\[(.*?)\]', line).group(1)
                    ip = re.search(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', line).group()
                    status = re.search(r'\s(\d{3})\s', line).group(1)

                    self.stats['ip_addresses'][ip] += 1
                    self.stats['status_codes'][status] += 1

                    if status.startswith('4') or status.startswith('5'):
                        self.errors.append({
                            'timestamp': timestamp,
                            'ip': ip,
                            'status': status,
                            'line': line.strip()
                        })

                    self.requests.append({
                        'timestamp': datetime.strptime(timestamp, '%d/%b/%Y:%H:%M:%S %z'),
                        'ip': ip,
                        'status': status
                    })
                except AttributeError:
                    continue

    def generate_report(self):
        report = {
            'total_requests': len(self.requests),
            'unique_ips': len(self.stats['ip_addresses']),
            'top_ips': self.stats['ip_addresses'].most_common(10),
            'status_distribution': dict(self.stats['status_codes']),
            'error_count': len(self.errors),
            'recent_errors': self.errors[-10:],
            'requests_per_hour': self._calculate_hourly_requests()
        }
        return report

    def _calculate_hourly_requests(self):
        hourly = defaultdict(int)
        for request in self.requests:
            hour = request['timestamp'].strftime('%Y-%m-%d %H:00')
            hourly[hour] += 1
        return dict(sorted(hourly.items()))

if __name__ == '__main__':
    analyzer = LogAnalyzer('access.log')
    analyzer.parse_log()
    report = analyzer.generate_report()
    print(f"Total Requests: {report['total_requests']}")
    print(f"Unique IPs: {report['unique_ips']}")
    print(f"Error Count: {report['error_count']}")
    print("\nTop 10 IPs:")
    for ip, count in report['top_ips']:
        print(f"{ip}: {count}")

