    def monitor_loop(self):
        while self.running:
            try:
                data = self.data_queue.get(timeout=1.0)
                thresholds = self.alarm_thresholds[data.sensor_id]
                if data.value < thresholds[0] or data.value > thresholds[1]:
                    self.trigger_alarm(data)
            except queue.Empty:
                continue

    def trigger_alarm(self, data: SensorData):
        print(f"ALARM: Sensor {data.sensor_id} value {data.value} outside threshold")

    def start(self):
        self.monitor_thread = threading.Thread(target=self.monitor_loop)
        self.monitor_thread.start()

    def stop(self):
        self.running = False
        self.monitor_thread.join()

