import socket
import zlib
import hashlib
import os
from threading import Thread
from collections import defaultdict

class Node:
    def __init__(self, host='localhost', port=5000):
        self.host = host
        self.port = port
        self.blocks = {}
        self.file_maps = defaultdict(list)
        self.peers = set()
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.bind((host, port))

    def start(self):
        self.sock.listen(10)
        Thread(target=self._accept_connections).start()

    def store_file(self, filename):
        with open(filename, 'rb') as f:
            data = f.read()
        blocks = []
        for i in range(0, len(data), 1024):
            block = data[i:i+1024]
            compressed = zlib.compress(block)
            block_hash = hashlib.sha256(compressed).hexdigest()
            self.blocks[block_hash] = compressed
            blocks.append(block_hash)
            self._distribute_block(block_hash, compressed)
        self.file_maps[filename] = blocks

    def get_file(self, filename):
        if filename not in self.file_maps:
            return None
        data = []
        for block_hash in self.file_maps[filename]:
            if block_hash in self.blocks:
                block = zlib.decompress(self.blocks[block_hash])
            else:
                block = self._request_block(block_hash)
            data.append(block)
        return b''.join(data)

    def _accept_connections(self):
        while True:
            conn, addr = self.sock.accept()
            Thread(target=self._handle_connection, args=(conn,)).start()

    def _handle_connection(self, conn):
        try:
            while True:
                cmd = conn.recv(4).decode()
                if cmd == 'BLCK':
                    size = int.from_bytes(conn.recv(4), 'big')
                    block_hash = conn.recv(64).decode()
                    block_data = conn.recv(size)
                    self.blocks[block_hash] = block_data
                elif cmd == 'RQST':
                    block_hash = conn.recv(64).decode()
                    if block_hash in self.blocks:
                        data = self.blocks[block_hash]
                        conn.send(len(data).to_bytes(4, 'big'))
                        conn.send(data)
        except:
            conn.close()

    def _distribute_block(self, block_hash, block_data):
        for peer in self.peers:
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.connect(peer)
                s.send(b'BLCK')
                s.send(len(block_data).to_bytes(4, 'big'))
                s.send(block_hash.encode())
                s.send(block_data)
                s.close()
            except:
                continue

    def _request_block(self, block_hash):
        for peer in self.peers:
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.connect(peer)
                s.send(b'RQST')
                s.send(block_hash.encode())
                size = int.from_bytes(s.recv(4), 'big')
                data = s.recv(size)
                s.close()
                self.blocks[block_hash] = data
                return zlib.decompress(data)
            except:
                continue
        return None

    def add_peer(self, host, port):
        self.peers.add((host, port))

