import os
import hashlib
import zlib
import json
from pathlib import Path
from typing import Dict, Optional

class ImageRepository:
    def __init__(self, base_path: str):
        self.base_path = Path(base_path)
        self.base_path.mkdir(exist_ok=True)
        self.metadata_file = self.base_path / 'metadata.json'
        self.metadata: Dict = self._load_metadata()

    def _load_metadata(self) -> Dict:
        if self.metadata_file.exists():
            with open(self.metadata_file, 'r') as f:
                return json.load(f)
        return {}

    def _save_metadata(self):
        with open(self.metadata_file, 'w') as f:
            json.dump(self.metadata, f)

    def add_image(self, name: str, image_path: str, version: str = 'latest'):
        # Create hash of image content
        sha256 = hashlib.sha256()
        with open(image_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        image_hash = sha256.hexdigest()

        # Compress and store image
        compressed_path = self.base_path / f'{image_hash}.gz'
        with open(image_path, 'rb') as fin:
            with open(compressed_path, 'wb') as fout:
                compressed = zlib.compress(fin.read())
                fout.write(compressed)

        # Update metadata
        if name not in self.metadata:
            self.metadata[name] = {}
        self.metadata[name][version] = {
            'hash': image_hash,
            'size': os.path.getsize(image_path),
            'compressed_size': os.path.getsize(compressed_path)
        }
        self._save_metadata()

    def get_image(self, name: str, version: str = 'latest') -> Optional[bytes]:
        if name not in self.metadata or version not in self.metadata[name]:
            return None

        image_hash = self.metadata[name][version]['hash']
        compressed_path = self.base_path / f'{image_hash}.gz'

        with open(compressed_path, 'rb') as f:
            compressed = f.read()
            return zlib.decompress(compressed)

    def list_images(self) -> Dict:
        return self.metadata

    def delete_image(self, name: str, version: str = 'latest'):
        if name in self.metadata and version in self.metadata[name]:
            image_hash = self.metadata[name][version]['hash']
            compressed_path = self.base_path / f'{image_hash}.gz'
            compressed_path.unlink(missing_ok=True)

            del self.metadata[name][version]
            if not self.metadata[name]:
                del self.metadata[name]
            self._save_metadata()
