class Repository:
    def __init__(self, path):
        self.path = path
        self.revisions = {}
        self.current_revision = 0
        self.staged_files = set()

    def stage_file(self, filename):
        self.staged_files.add(filename)
        return True

    def commit(self, message):
        if not self.staged_files:
            return False

        self.current_revision += 1
        self.revisions[self.current_revision] = {
            'files': self.staged_files.copy(),
            'message': message,
            'timestamp': datetime.now()
        }
        self.staged_files.clear()
        return self.current_revision

    def checkout(self, revision):
        if revision not in self.revisions:
            return False
        self.current_revision = revision
        return True

    def get_history(self):
        return [(rev, self.revisions[rev]) for rev in sorted(self.revisions.keys())]

    def diff(self, file, rev1, rev2):
        if rev1 not in self.revisions or rev2 not in self.revisions:
            return None
        return {'file': file, 'rev1': rev1, 'rev2': rev2}

    def merge(self, source_rev, target_rev):
        if source_rev not in self.revisions or target_rev not in self.revisions:
            return False
        return True

