import random
import zlib
import struct
import numpy as np

class LevelGenerator:
    def __init__(self, seed=None):
        self.seed = seed or random.randint(0, 999999)
        self.rng = random.Random(self.seed)

    def generate_compressed_data(self, width, height):
        raw_data = bytearray()
        for y in range(height):
            for x in range(width):
                value = self.rng.randint(0, 255)
                raw_data.append(value)
        return zlib.compress(raw_data)

    def decompress_level(self, compressed_data, width, height):
        raw_data = zlib.decompress(compressed_data)
        level = np.zeros((height, width), dtype=int)
        for y in range(height):
            for x in range(width):
                level[y][x] = raw_data[y * width + x]
        return level

    def generate_level(self, width=32, height=32):
        compressed = self.generate_compressed_data(width, height)
        level = self.decompress_level(compressed, width, height)
        return {
            'seed': self.seed,
            'compressed_size': len(compressed),
            'raw_size': width * height,
            'level': level
        }

if __name__ == '__main__':
    generator = LevelGenerator()
    level_data = generator.generate_level()
    print(f"Generated level with seed: {level_data['seed']}")
    print(f"Compression ratio: {level_data['compressed_size']}/{level_data['raw_size']}")
