            "id": len(self.elements)
        }
        self.elements.append(element)

    def save(self, filename):
        with open(filename, "wb") as f:
            header = b"CAD1"
            meta_bytes = bytes(str(self.metadata), "utf-8")
            elements_bytes = bytes(str(self.elements), "utf-8")
            f.write(header)
            f.write(len(meta_bytes).to_bytes(4, "big"))
            f.write(meta_bytes)
            f.write(len(elements_bytes).to_bytes(4, "big"))
            f.write(elements_bytes)

    def load(self, filename):
        with open(filename, "rb") as f:
            if f.read(4) != b"CAD1":
                raise ValueError("Invalid file format")
            meta_len = int.from_bytes(f.read(4), "big")
            self.metadata = eval(f.read(meta_len).decode("utf-8"))
            elements_len = int.from_bytes(f.read(4), "big")
            self.elements = eval(f.read(elements_len).decode("utf-8"))

