        self.archive_path = Path(archive_path)
        self.output_dir = Path(output_dir)
        self.supported_formats = {'.epub', '.mobi', '.pdf', '.azw3'}

    def extract_ebooks(self):
        with zipfile.ZipFile(self.archive_path, 'r') as archive:
            for file_info in archive.filelist:
                if self._is_ebook_file(file_info.filename):
                    self._extract_single_ebook(archive, file_info)

    def _is_ebook_file(self, filename):
        return any(filename.lower().endswith(ext) for ext in self.supported_formats)

    def _extract_single_ebook(self, archive, file_info):
        output_path = self.output_dir / Path(file_info.filename).name
        with archive.open(file_info) as source, open(output_path, 'wb') as target:
            shutil.copyfileobj(source, target)

