import asyncio
import aiohttp

class DataSync:
    def __init__(self, api_key):
        self.api_key = api_key
        self.base_urls = {
            'service1': 'https://api.service1.com/v1',
            'service2': 'https://api.service2.com/v2',
            'service3': 'https://api.service3.com/v1'
        }
        self.headers = {
            'Authorization': f'Bearer {self.api_key}',
            'Content-Type': 'application/json'
        }

    async def fetch_data(self, session, service, endpoint):
        url = f"{self.base_urls[service]}/{endpoint}"
        async with session.get(url, headers=self.headers) as response:
            return await response.json()

    async def sync_all_services(self):
        async with aiohttp.ClientSession() as session:
            tasks = []
            for service in self.base_urls.keys():
                tasks.append(self.fetch_data(session, service, 'data'))
            results = await asyncio.gather(*tasks, return_exceptions=True)
            return self.process_results(results)

    def process_results(self, results):
        processed_data = {}
        for idx, result in enumerate(results):
            service = list(self.base_urls.keys())[idx]
            if isinstance(result, Exception):
                processed_data[service] = {'error': str(result)}
            else:
                processed_data[service] = result
        return processed_data

    def save_to_database(self, data):
        timestamp = datetime.now().isoformat()
        with open(f'sync_data_{timestamp}.json', 'w') as f:
            json.dump(data, f)

    def run_sync(self):
        results = asyncio.run(self.sync_all_services())
        self.save_to_database(results)
        return results

if __name__ == '__main__':
