from datetime import datetime

class Database:
    def __init__(self, db_name):
        self.conn = sqlite3.connect(db_name)
        self.cursor = self.conn.cursor()
        self.setup_database()

    def setup_database(self):
        self.cursor.execute('''
            CREATE TABLE IF NOT EXISTS records (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                value TEXT,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        self.conn.commit()

    def insert(self, name, value):
        self.cursor.execute('INSERT INTO records (name, value) VALUES (?, ?)', (name, value))
        self.conn.commit()
        return self.cursor.lastrowid

    def get(self, record_id):
        self.cursor.execute('SELECT * FROM records WHERE id = ?', (record_id,))
        return self.cursor.fetchone()

    def get_all(self):
        self.cursor.execute('SELECT * FROM records')
        return self.cursor.fetchall()

    def update(self, record_id, name, value):
        self.cursor.execute('UPDATE records SET name = ?, value = ? WHERE id = ?', (name, value, record_id))
        self.conn.commit()

    def delete(self, record_id):
        self.cursor.execute('DELETE FROM records WHERE id = ?', (record_id,))
        self.conn.commit()

    def __del__(self):
