from typing import Dict, List, Set

class LicenseAnalyzer:
    def __init__(self):
        self.known_licenses = {
            'MIT': r'MIT License|Permission is hereby granted, free of charge',
            'GPL': r'GNU General Public License|GPL',
            'Apache': r'Apache License|Licensed under the Apache License',
            'BSD': r'BSD License|Redistribution and use in source and binary forms'
        }

    def analyze_tarball(self, tarball_path: str) -> Dict[str, Set[str]]:
        results = {
            'detected_licenses': set(),
            'license_files': set(),
            'source_files': set()
        }

        with tarfile.open(tarball_path, 'r:*') as tar:
            for member in tar.getmembers():
                if not member.isfile():
                    continue

                file_content = tar.extractfile(member)
                if not file_content:
                    continue

                content = file_content.read().decode('utf-8', errors='ignore')

                # Check for license files
                if self._is_license_file(member.name):
                    results['license_files'].add(member.name)
                    detected = self._detect_licenses(content)
                    results['detected_licenses'].update(detected)

                # Check source files for license headers
                elif self._is_source_file(member.name):
                    results['source_files'].add(member.name)
                    detected = self._detect_licenses(content)
                    results['detected_licenses'].update(detected)

        return results

    def _is_license_file(self, filename: str) -> bool:
        license_patterns = [
            r'license', r'copying', r'copyright'
        ]
        lower_name = filename.lower()
        return any(re.search(pattern, lower_name) for pattern in license_patterns)

    def _is_source_file(self, filename: str) -> bool:
        source_extensions = {'.py', '.java', '.cpp', '.h', '.js', '.go'}
        return os.path.splitext(filename)[1].lower() in source_extensions

    def _detect_licenses(self, content: str) -> Set[str]:
        detected = set()
        for license_name, pattern in self.known_licenses.items():
            if re.search(pattern, content, re.IGNORECASE):
                detected.add(license_name)
        return detected

def analyze_package(tarball_path: str) -> None:
    analyzer = LicenseAnalyzer()
    results = analyzer.analyze_tarball(tarball_path)

    print(f"Analysis Results for {tarball_path}")
    print("Detected Licenses:", ", ".join(results['detected_licenses']) or "None")
    print("\nLicense Files:")
    for file in results['license_files']:
        print(f"- {file}")
    print(f"\nTotal source files analyzed: {len(results['source_files'])}")

if __name__ == "__main__":
    analyze_package("example.tar.gz")
