import zipfile
import tarfile
import gzip
import bz2
from pathlib import Path

class ArchiveExtractor:
    def __init__(self, archive_path):
        self.archive_path = Path(archive_path)

    def extract(self, output_path=None):
        if output_path is None:
            output_path = self.archive_path.parent

        if self.archive_path.suffix == '.zip':
            with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
                zip_ref.extractall(output_path)

        elif self.archive_path.suffix in ['.tar', '.gz', '.bz2']:
            if tarfile.is_tarfile(self.archive_path):
                with tarfile.open(self.archive_path, 'r:*') as tar_ref:
                    tar_ref.extractall(output_path)
            elif self.archive_path.suffix == '.gz':
                with gzip.open(self.archive_path, 'rb') as gz_ref:
                    output_file = Path(output_path) / self.archive_path.stem
                    with open(output_file, 'wb') as f:
                        f.write(gz_ref.read())
            elif self.archive_path.suffix == '.bz2':
                with bz2.open(self.archive_path, 'rb') as bz2_ref:
                    output_file = Path(output_path) / self.archive_path.stem
                    with open(output_file, 'wb') as f:
                        f.write(bz2_ref.read())

        return output_path

    def list_contents(self):
        if self.archive_path.suffix == '.zip':
            with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
                return zip_ref.namelist()

        elif self.archive_path.suffix in ['.tar', '.gz', '.bz2']:
            if tarfile.is_tarfile(self.archive_path):
                with tarfile.open(self.archive_path, 'r:*') as tar_ref:
                    return tar_ref.getnames()

        return []

