        self.apartments[apartment.id] = apartment

    def get_apartment(self, apartment_id: int) -> Optional[Apartment]:
        return self.apartments.get(apartment_id)

    def search_apartments(self, min_rent: Decimal = None, max_rent: Decimal = None, 
                         min_bedrooms: int = None, available_only: bool = True) -> List[Apartment]:
        results = []
        for apt in self.apartments.values():
            if available_only and not apt.is_available:
                continue
            if min_rent and apt.rent < min_rent:
                continue
            if max_rent and apt.rent > max_rent:
                continue
            if min_bedrooms and apt.bedrooms < min_bedrooms:
                continue
            results.append(apt)
        return results

