import os
import tarfile
import shutil
import subprocess
from pathlib import Path

def extract_packages(tarball_path, target_dir):
    with tarfile.open(tarball_path, 'r:gz') as tar:
        tar.extractall(path=target_dir)

def install_packages(package_dir):
    packages = sorted(Path(package_dir).glob('*.deb'))
    for package in packages:
        try:
            subprocess.run(['dpkg', '-i', str(package)], check=True)
        except subprocess.CalledProcessError:
            subprocess.run(['apt-get', 'install', '-f', '-y'], check=True)

def main():
    TARBALL_PATH = '/path/to/packages.tar.gz'
    TEMP_DIR = '/tmp/package_install'

    os.makedirs(TEMP_DIR, exist_ok=True)
    try:
        extract_packages(TARBALL_PATH, TEMP_DIR)
        install_packages(TEMP_DIR)
    finally:
        shutil.rmtree(TEMP_DIR)

if __name__ == '__main__':
    main()

