from collections import defaultdict
import logging
import datetime
import json
import os

class LogAggregator:
    def __init__(self):
        self.logs = defaultdict(list)
        self.setup_logging()

    def setup_logging(self):
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s',
            filename='aggregator.log'
        )

    def collect_log(self, source, message, level='INFO', timestamp=None):
        if timestamp is None:
            timestamp = datetime.datetime.now().isoformat()

        log_entry = {
            'timestamp': timestamp,
            'level': level,
            'message': message,
            'source': source
        }

        self.logs[source].append(log_entry)
        logging.info(f"Collected log from {source}: {message}")

    def analyze_logs(self, source=None):
        results = {
            'total_logs': 0,
            'errors': 0,
            'warnings': 0,
            'info': 0
        }

        target_logs = self.logs[source] if source else [log for logs in self.logs.values() for log in logs]

        for log in target_logs:
            results['total_logs'] += 1
            if log['level'] == 'ERROR':
                results['errors'] += 1
            elif log['level'] == 'WARNING':
                results['warnings'] += 1
            elif log['level'] == 'INFO':
                results['info'] += 1

        return results

    def export_logs(self, filename='logs.json'):
        with open(filename, 'w') as f:
            json.dump(dict(self.logs), f, indent=4)

    def clear_logs(self, source=None):
        if source:
            self.logs[source] = []
        else:
            self.logs.clear()

if __name__ == '__main__':
    aggregator = LogAggregator()

    aggregator.collect_log('service1', 'Application started', 'INFO')
    aggregator.collect_log('service1', 'Database connection failed', 'ERROR')
    aggregator.collect_log('service2', 'High memory usage detected', 'WARNING')

    analysis = aggregator.analyze_logs()
    print(f"Log Analysis: {analysis}")

    aggregator.export_logs()

