import sys
from typing import Any

class AssertionMessageTestCase(unittest.TestCase):
    def assertWithMessage(self, condition: bool, message: str):
        try:
            self.assertTrue(condition)
        except AssertionError:
            raise AssertionError(message)

    def assertEqualsWithMessage(self, first: Any, second: Any, message: str):
        try:
            self.assertEqual(first, second)
        except AssertionError:
            raise AssertionError(message)

    def assertInWithMessage(self, member: Any, container: Any, message: str):
        try:
            self.assertIn(member, container)
        except AssertionError:
            raise AssertionError(message)

    def assertNotNoneWithMessage(self, obj: Any, message: str):
        try:
            self.assertIsNotNone(obj)
        except AssertionError:
            raise AssertionError(message)

class TestExample(AssertionMessageTestCase):
