import os
import sys
import re
import argparse
from pathlib import Path
from typing import Dict, List, Tuple

class CommentAnalyzer:
    def __init__(self):
        self.single_line_patterns = {
            'python': r'#.*$',
            'javascript': r'//.*$',
            'java': r'//.*$',
            'cpp': r'//.*$'
        }

        self.multi_line_patterns = {
            'python': (r'"""[\s\S]*?"""', r"'''[\s\S]*?'''"),
            'javascript': (r'/\*[\s\S]*?\*/'),
            'java': (r'/\*[\s\S]*?\*/'),
            'cpp': (r'/\*[\s\S]*?\*/')
        }

    def analyze_file(self, file_path: Path) -> Dict:
        extension = file_path.suffix.lower()[1:]
        language = self._detect_language(extension)

        if not language:
            return None

        with open(file_path, 'r', encoding='utf-8') as f:
            content = f.read()

        stats = {
            'total_lines': len(content.splitlines()),
            'comment_lines': 0,
            'single_line_comments': 0,
            'multi_line_comments': 0,
            'file_path': str(file_path)
        }

        # Count single-line comments
        single_pattern = self.single_line_patterns.get(language)
        if single_pattern:
            matches = re.finditer(single_pattern, content, re.MULTILINE)
            stats['single_line_comments'] = sum(1 for _ in matches)

        # Count multi-line comments
        multi_patterns = self.multi_line_patterns.get(language)
        if isinstance(multi_patterns, str):
            multi_patterns = (multi_patterns,)

        for pattern in multi_patterns:
            matches = re.finditer(pattern, content)
            for match in matches:
                comment_lines = match.group().count('\n') + 1
                stats['multi_line_comments'] += 1
                stats['comment_lines'] += comment_lines

        stats['comment_lines'] += stats['single_line_comments']
        stats['comment_density'] = round(
            (stats['comment_lines'] / stats['total_lines']) * 100, 2
        ) if stats['total_lines'] > 0 else 0

        return stats

    def _detect_language(self, extension: str) -> str:
        language_map = {
            'py': 'python',
            'js': 'javascript',
            'java': 'java',
            'cpp': 'cpp',
            'c': 'cpp',
            'hpp': 'cpp',
            'h': 'cpp'
        }
        return language_map.get(extension)

def generate_report(stats: List[Dict], output_file: str = None) -> None:
    report = "Code Comment Analysis Report\n"
    report += "=" * 30 + "\n\n"

    total_files = len(stats)
    total_comment_density = sum(s['comment_density'] for s in stats) / total_files

    for file_stats in stats:
        report += f"File: {file_stats['file_path']}\n"
        report += f"Total lines: {file_stats['total_lines']}\n"
        report += f"Comment lines: {file_stats['comment_lines']}\n"
        report += f"Single-line comments: {file_stats['single_line_comments']}\n"
        report += f"Multi-line comments: {file_stats['multi_line_comments']}\n"
        report += f"Comment density: {file_stats['comment_density']}%\n"
        report += "-" * 30 + "\n"

    report += f"\nAverage comment density across all files: {round(total_comment_density, 2)}%\n"

    if output_file:
        with open(output_file, 'w', encoding='utf-8') as f:
            f.write(report)
        os.chmod(output_file, 0o644)
    else:
        print(report)

def main():
    parser = argparse.ArgumentParser(description='Analyze code comments in source files')
    parser.add_argument('path', help='Path to file or directory to analyze')
    parser.add_argument('-o', '--output', help='Output file for the report')
    args = parser.parse_args()

    path = Path(args.path)
    analyzer = CommentAnalyzer()
    stats_list = []

    if path.is_file():
        stats = analyzer.analyze_file(path)
        if stats:
            stats_list.append(stats)
    elif path.is_dir():
        for file_path in path.rglob('*'):
            if file_path.is_file():
                stats = analyzer.analyze_file(file_path)
                if stats:
                    stats_list.append(stats)

    if not stats_list:
        print("No supported source files found.")
        sys.exit(1)

    generate_report(stats_list, args.output)

if __name__ == '__main__':
    main()

