from dataclasses import dataclass
from datetime import datetime
from typing import List, Dict, Set
import uuid

@dataclass
class UserProfile:
    user_id: str
    name: str
    bio: str
    interests: Set[str]
    age: int
    last_active: datetime
    preferences: Dict[str, str]

class DatingApp:
    def __init__(self):
        self.users = {}
        self.matches = {}

    def create_profile(self, name: str, bio: str, interests: List[str], age: int, preferences: Dict[str, str]) -> str:
        user_id = str(uuid.uuid4())
        profile = UserProfile(
            user_id=user_id,
            name=name,
            bio=bio,
            interests=set(interests),
            age=age,
            last_active=datetime.now(),
            preferences=preferences
        )
        self.users[user_id] = profile
        return user_id

    def get_matches(self, user_id: str, limit: int = 10) -> List[UserProfile]:
        user = self.users.get(user_id)
        if not user:
            return []

        matches = []
        for profile in self.users.values():
            if profile.user_id != user_id and self._is_compatible(user, profile):
                matches.append(profile)
            if len(matches) >= limit:
                break
        return matches

    def _is_compatible(self, user1: UserProfile, user2: UserProfile) -> bool:
        common_interests = user1.interests.intersection(user2.interests)
        age_difference = abs(user1.age - user2.age)
        return len(common_interests) >= 2 and age_difference <= 5

    def update_profile(self, user_id: str, bio: str = None, interests: List[str] = None) -> bool:
        if user_id not in self.users:
            return False

        if bio:
            self.users[user_id].bio = bio
        if interests:
            self.users[user_id].interests = set(interests)
        self.users[user_id].last_active = datetime.now()
        return True

