import os
import tarfile
import json
import hashlib
from datetime import datetime

class DataPackager:
    def __init__(self, output_dir="./packages"):
        self.output_dir = output_dir
        os.makedirs(output_dir, exist_ok=True)

    def create_package(self, data_files, metadata=None):
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        package_name = f"dataset_{timestamp}.tar.gz"
        package_path = os.path.join(self.output_dir, package_name)

        with tarfile.open(package_path, "w:gz") as tar:
            for file_path in data_files:
                if os.path.exists(file_path):
                    tar.add(file_path, arcname=os.path.basename(file_path))

            if metadata:
                metadata_file = f"metadata_{timestamp}.json"
                metadata['checksum'] = self._calculate_checksums(data_files)
                metadata['creation_date'] = timestamp
                with open(metadata_file, 'w') as f:
                    json.dump(metadata, f, indent=4)
                tar.add(metadata_file)
                os.remove(metadata_file)

        return package_path

    def _calculate_checksums(self, files):
        checksums = {}
        for file_path in files:
            if os.path.exists(file_path):
                sha256 = hashlib.sha256()
                with open(file_path, 'rb') as f:
                    for chunk in iter(lambda: f.read(4096), b''):
                        sha256.update(chunk)
                checksums[os.path.basename(file_path)] = sha256.hexdigest()
        return checksums

    def extract_package(self, package_path, extract_dir):
        os.makedirs(extract_dir, exist_ok=True)
        with tarfile.open(package_path, 'r:gz') as tar:
            tar.extractall(path=extract_dir)

