import json

@dataclass
class Habit:
    name: str
    frequency: int
    dates_completed: List[datetime]
    created_at: datetime
    streak: int = 0

class HabitTracker:
    def __init__(self):
        self.habits: Dict[str, Habit] = {}

    def add_habit(self, name: str, frequency: int) -> None:
        self.habits[name] = Habit(
            name=name,
            frequency=frequency,
            dates_completed=[],
            created_at=datetime.now()
        )

    def complete_habit(self, name: str) -> None:
        if name in self.habits:
            self.habits[name].dates_completed.append(datetime.now())
            self._calculate_streak(name)

    def _calculate_streak(self, name: str) -> None:
        habit = self.habits[name]
        dates = sorted(habit.dates_completed)
        streak = 1

        for i in range(len(dates)-1, 0, -1):
            if (dates[i] - dates[i-1]).days <= habit.frequency:
                streak += 1
            else:
                break

        habit.streak = streak

    def get_progress(self, name: str) -> dict:
        if name in self.habits:
            habit = self.habits[name]
            return {
                'name': habit.name,
                'frequency': habit.frequency,
                'completed_count': len(habit.dates_completed),
                'streak': habit.streak,
                'last_completed': habit.dates_completed[-1] if habit.dates_completed else None
            }
        return {}

    def save_to_file(self, filename: str) -> None:
        with open(filename, 'w') as f:
            data = {name: {
                'name': habit.name,
                'frequency': habit.frequency,
                'dates_completed': [d.isoformat() for d in habit.dates_completed],
                'created_at': habit.created_at.isoformat(),
                'streak': habit.streak
            } for name, habit in self.habits.items()}
            json.dump(data, f)

    def load_from_file(self, filename: str) -> None:
        with open(filename, 'r') as f:
            data = json.load(f)
            for name, habit_data in data.items():
                self.habits[name] = Habit(
                    name=habit_data['name'],
                    frequency=habit_data['frequency'],
                    dates_completed=[datetime.fromisoformat(d) for d in habit_data['dates_completed']],
                    created_at=datetime.fromisoformat(habit_data['created_at']),
                    streak=habit_data['streak']
                )

