import zipfile
import os
import shutil
from pathlib import Path

class EbookExtractor:
    def __init__(self, archive_path, output_dir):
        self.archive_path = Path(archive_path)
        self.output_dir = Path(output_dir)
        self.supported_extensions = {'.epub', '.mobi', '.pdf', '.azw3'}

    def extract_ebooks(self):
        self.output_dir.mkdir(parents=True, exist_ok=True)

        with zipfile.ZipFile(self.archive_path, 'r') as archive:
            for file_info in archive.filelist:
                if self._is_ebook_file(file_info.filename):
                    self._extract_single_ebook(archive, file_info)

    def _is_ebook_file(self, filename):
        return any(filename.lower().endswith(ext) for ext in self.supported_extensions)

    def _extract_single_ebook(self, archive, file_info):
        safe_filename = os.path.basename(file_info.filename)
        output_path = self.output_dir / safe_filename

        with archive.open(file_info) as source, open(output_path, 'wb') as target:
            shutil.copyfileobj(source, target)

if __name__ == "__main__":
    extractor = EbookExtractor("ebooks.zip", "extracted_ebooks")
    extractor.extract_ebooks()

