import requests

class LogAnalyzer:
    def __init__(self, log_file):
        self.log_file = log_file
        self.errors = defaultdict(list)
        self.pattern = r'(\d+\.\d+\.\d+\.\d+).*\[(.*?)\].*?"([^"]*)".*?(\d{3})'

    def analyze(self):
        with open(self.log_file, 'r') as f:
            for line in f:
                match = re.search(self.pattern, line)
                if match:
                    ip, timestamp, url, status = match.groups()
                    if status == '404':
                        self.errors[url].append({
                            'ip': ip,
                            'timestamp': datetime.strptime(timestamp, '%d/%b/%Y:%H:%M:%S %z'),
                            'status': status
                        })

    def check_links(self):
        dead_links = []
        for url in self.errors.keys():
            try:
                response = requests.head(url, timeout=5)
                if response.status_code == 404:
                    dead_links.append(url)
            except:
                dead_links.append(url)
        return dead_links

    def generate_report(self):
        report = {
            'total_404s': sum(len(errors) for errors in self.errors.values()),
            'unique_404s': len(self.errors),
            'error_urls': dict(self.errors),
            'dead_links': self.check_links()
        }
        return report

