import os
import subprocess
import yaml
from dataclasses import dataclass
from typing import Dict, List

@dataclass
class Environment:
    name: str
    base_path: str
    required_permissions: List[str]
    deploy_user: str

class DeploymentManager:
    def __init__(self, config_path: str):
        self.environments = self._load_environments(config_path)
        self.current_user = os.getenv('USER')

    def _load_environments(self, config_path: str) -> Dict[str, Environment]:
        with open(config_path) as f:
            config = yaml.safe_load(f)
            return {
                name: Environment(
                    name=name,
                    base_path=env['path'],
                    required_permissions=env['permissions'],
                    deploy_user=env['deploy_user']
                )
                for name, env in config['environments'].items()
            }

    def check_permissions(self, env: Environment) -> bool:
        if self.current_user != env.deploy_user:
            return False

        for permission in env.required_permissions:
            path = os.path.join(env.base_path, permission)
            if not os.access(path, os.W_OK):
                return False
        return True

    def deploy(self, app_name: str, version: str, env_name: str) -> bool:
        env = self.environments[env_name]

        if not self.check_permissions(env):
            raise PermissionError(f"Insufficient permissions for {env_name}")

        deploy_path = os.path.join(env.base_path, app_name)

        try:
            subprocess.run([
                'docker',
                'pull',
                f'{app_name}:{version}'
            ], check=True)

            subprocess.run([
                'docker',
                'stop',
                app_name
            ], check=False)

            subprocess.run([
                'docker',
                'run',
                '-d',
                '--name',
                app_name,
                f'{app_name}:{version}'
            ], check=True)

            return True

        except subprocess.CalledProcessError as e:
            raise RuntimeError(f"Deployment failed: {str(e)}")

if __name__ == "__main__":
    manager = DeploymentManager('config.yaml')
    try:
        manager.deploy('myapp', 'v1.0', 'production')
        print("Deployment successful")
    except (PermissionError, RuntimeError) as e:
        print(f"Deployment failed: {str(e)}")
