                self.current_track = self.playlist[0]
            pygame.mixer.music.load(self.current_track)
            pygame.mixer.music.play()
            self.playing = True

    def pause(self):
        if self.playing:
            pygame.mixer.music.pause()
            self.playing = False

    def next_track(self):
        if self.playlist:
            self.playlist.rotate(-1)
            self.current_track = self.playlist[0]
            self.stop()
            self.play()

    def stop(self):
        pygame.mixer.music.stop()
        self.playing = False

