import requests
import urllib.parse
from bs4 import BeautifulSoup
from urllib.robotparser import RobotFileParser
from collections import deque
import time

class WebCrawler:
    def __init__(self):
        self.visited = set()
        self.queue = deque()
        self.user_agent = 'CustomCrawlerBot/1.0'
        self.delay = 1
        self.headers = {'User-Agent': self.user_agent}

    def is_allowed(self, url):
        robot_parser = RobotFileParser()
        robot_url = urllib.parse.urljoin(url, '/robots.txt')
        try:
            robot_parser.set_url(robot_url)
            robot_parser.read()
            return robot_parser.can_fetch(self.user_agent, url)
        except:
            return True

    def crawl(self, start_url, max_pages=100):
        self.queue.append(start_url)

        while self.queue and len(self.visited) < max_pages:
            url = self.queue.popleft()

            if url in self.visited:
                continue

            if not self.is_allowed(url):
                continue

            try:
                time.sleep(self.delay)
                response = requests.get(url, headers=self.headers, timeout=5)

                if response.status_code == 200:
                    self.visited.add(url)
                    soup = BeautifulSoup(response.text, 'html.parser')
                    self.save_page(url, response.text)
                    self.extract_links(soup, url)

            except Exception as e:
                print(f"Error crawling {url}: {str(e)}")

    def save_page(self, url, content):
        filename = urllib.parse.quote_plus(url) + '.html'
        with open(filename, 'w', encoding='utf-8') as f:
            f.write(content)

    def extract_links(self, soup, base_url):
        for link in soup.find_all('a'):
            href = link.get('href')
            if href:
                absolute_url = urllib.parse.urljoin(base_url, href)
                if absolute_url.startswith('http'):
                    self.queue.append(absolute_url)

if __name__ == '__main__':
    crawler = WebCrawler()
    crawler.crawl('https://example.com')

