class RosBagSimulator:
    def __init__(self, bag_path):
        self.bag = rosbag.Bag(bag_path, 'r')
        self.scan_data = []
        self.cmd_vel = []
        self.tf_data = []
        self._unpack_bag()

    def _unpack_bag(self):
        for topic, msg, t in self.bag.read_messages():
            if topic == '/scan':
                self.scan_data.append({
                    'ranges': np.array(msg.ranges),
                    'timestamp': t.to_sec()
                })
            elif topic == '/cmd_vel':
                self.cmd_vel.append({
                    'linear': msg.linear.x,
                    'angular': msg.angular.z,
                    'timestamp': t.to_sec()
                })
            elif topic == '/tf':
                q = [msg.transform.rotation.x, msg.transform.rotation.y,
                     msg.transform.rotation.z, msg.transform.rotation.w]
                euler = euler_from_quaternion(q)
                self.tf_data.append({
                    'position': [msg.transform.translation.x,
                               msg.transform.translation.y,
                               msg.transform.translation.z],
                    'orientation': euler,
                    'timestamp': t.to_sec()
                })

    def get_scan_at_time(self, timestamp):
        closest_scan = min(self.scan_data, 
                         key=lambda x: abs(x['timestamp'] - timestamp))
        return closest_scan['ranges']

    def get_pose_at_time(self, timestamp):
        closest_tf = min(self.tf_data,
                        key=lambda x: abs(x['timestamp'] - timestamp))
        return closest_tf['position'], closest_tf['orientation']

    def simulate_trajectory(self, start_time, duration):
        trajectory = []
        current_time = start_time

        while current_time < start_time + duration:
            pos, orient = self.get_pose_at_time(current_time)
            scan = self.get_scan_at_time(current_time)

            trajectory.append({
                'timestamp': current_time,
                'position': pos,
                'orientation': orient,
                'scan': scan
            })

            current_time += 0.1

        return trajectory

    def replay_commands(self, start_idx=0, end_idx=None):
        if end_idx is None:
            end_idx = len(self.cmd_vel)

        commands = self.cmd_vel[start_idx:end_idx]
        for cmd in commands:
            yield cmd['linear'], cmd['angular'], cmd['timestamp']

    def close(self):
        self.bag.close()

def test_robot_behavior():
    simulator = RosBagSimulator('test_data.bag')

    # Get trajectory data
    trajectory = simulator.simulate_trajectory(0, 10.0)

    # Analyze robot behavior
    for point in trajectory:
        pos = point['position']
        scan = point['scan']

        # Test if robot maintains safe distance
        min_distance = np.min(scan)
        assert min_distance > 0.5, f"Robot too close to obstacle: {min_distance}m"

        # Test if robot stays within bounds
