import os
import shutil
import argparse
from pathlib import Path

def copy_files(source_dir, dest_dir, permissions=0o644):
    source_path = Path(source_dir)
    dest_path = Path(dest_dir)

    if not dest_path.exists():
        dest_path.mkdir(parents=True)

    for item in source_path.iterdir():
        destination = dest_path / item.name

        if item.is_file():
            shutil.copy2(item, destination)
            os.chmod(destination, permissions)
        elif item.is_dir():
            shutil.copytree(item, destination)
            for root, dirs, files in os.walk(destination):
                for d in dirs:
                    os.chmod(os.path.join(root, d), permissions)
                for f in files:
                    os.chmod(os.path.join(root, f), permissions)

if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("source", help="Source directory path")
    parser.add_argument("destination", help="Destination directory path")
    parser.add_argument("--permissions", type=lambda x: int(x, 8), default=0o644,
                        help="File permissions in octal format (default: 644)")

    args = parser.parse_args()
    copy_files(args.source, args.destination, args.permissions)

