        self.cursor.executescript('''
            CREATE TABLE IF NOT EXISTS books (
                id INTEGER PRIMARY KEY,
                title TEXT,
                author TEXT,
                price REAL,
                content TEXT
            );
            CREATE TABLE IF NOT EXISTS purchases (
                id INTEGER PRIMARY KEY,
                user_id INTEGER,
                book_id INTEGER,
                purchase_date DATETIME
            );
            CREATE TABLE IF NOT EXISTS bookmarks (
                id INTEGER PRIMARY KEY,
                user_id INTEGER,
                book_id INTEGER,
                page INTEGER,
                note TEXT
            );
        ''')
        self.conn.commit()

    def get_book(self, book_id):
        self.cursor.execute('SELECT * FROM books WHERE id = ?', (book_id,))
        return self.cursor.fetchone()

    def purchase_book(self, user_id, book_id):
        self.cursor.execute('''
            INSERT INTO purchases (user_id, book_id, purchase_date)
            VALUES (?, ?, ?)
        ''', (user_id, book_id, datetime.now()))
        self.conn.commit()

    def add_bookmark(self, user_id, book_id, page, note):
        self.cursor.execute('''
            INSERT INTO bookmarks (user_id, book_id, page, note)
            VALUES (?, ?, ?, ?)
        ''', (user_id, book_id, page, note))
        self.conn.commit()

