class VideoEditor:
    def __init__(self):
        self.clips = []
        self.transitions = []

    def add_clip(self, filepath, start_time=0, end_time=None):
        clip = mp.VideoFileClip(filepath).subclip(start_time, end_time)
        self.clips.append(clip)

    def add_transition(self, transition_type, duration=1):
        self.transitions.append({
            'type': transition_type,
            'duration': duration
        })

    def apply_filter(self, clip_index, filter_name, **params):
        if filter_name == 'grayscale':
            self.clips[clip_index] = self.clips[clip_index].fx(vfx.blackwhite)
        elif filter_name == 'blur':
            self.clips[clip_index] = self.clips[clip_index].fx(vfx.blur, params.get('radius', 1))
        elif filter_name == 'brightness':
            self.clips[clip_index] = self.clips[clip_index].fx(vfx.colorx, params.get('factor', 1.5))

    def render(self, output_path):
        final_clip = self.clips[0]

        for i in range(1, len(self.clips)):
            transition = self.transitions[i-1]
            if transition['type'] == 'crossfade':
                final_clip = mp.concatenate_videoclips([final_clip, self.clips[i]], 
                                                     method='compose',
                                                     transition=mp.CrossfadeTransition(transition['duration']))
            elif transition['type'] == 'fade':
                final_clip = mp.concatenate_videoclips([final_clip, self.clips[i]],
                                                     method='compose',
                                                     transition=mp.FadeTransition(transition['duration']))

        final_clip.write_videofile(output_path)

def main():
