            mixer.music.load(self.playlist[self.current_track]['path'])
            mixer.music.play()

    def stop(self):
        mixer.music.stop()

    def next_track(self):
        if self.current_track < len(self.playlist) - 1:
            self.current_track += 1
            self.play()

    def previous_track(self):
        if self.current_track > 0:
            self.current_track -= 1
            self.play()

