import os
import tarfile
import hashlib
import json
from datetime import datetime

class DiffBackup:
    def __init__(self, source_dir, backup_dir):
        self.source_dir = os.path.abspath(source_dir)
        self.backup_dir = os.path.abspath(backup_dir)
        self.manifest_path = os.path.join(backup_dir, 'manifest.json')
        self.previous_hashes = self._load_manifest()

    def _load_manifest(self):
        if os.path.exists(self.manifest_path):
            with open(self.manifest_path, 'r') as f:
                return json.load(f)
        return {}

    def _save_manifest(self, hashes):
        with open(self.manifest_path, 'w') as f:
            json.dump(hashes, f)

    def _calculate_file_hash(self, filepath):
        hasher = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                hasher.update(chunk)
        return hasher.hexdigest()

    def create_backup(self):
        current_hashes = {}
        files_to_backup = []

        for root, _, files in os.walk(self.source_dir):
            for file in files:
                filepath = os.path.join(root, file)
                relpath = os.path.relpath(filepath, self.source_dir)
                current_hash = self._calculate_file_hash(filepath)
                current_hashes[relpath] = current_hash

                if relpath not in self.previous_hashes or current_hash != self.previous_hashes[relpath]:
                    files_to_backup.append((filepath, relpath))

        if files_to_backup:
            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
            backup_path = os.path.join(self.backup_dir, f'backup_{timestamp}.tar.gz')

            with tarfile.open(backup_path, 'w:gz') as tar:
                for filepath, relpath in files_to_backup:
                    tar.add(filepath, arcname=relpath)

            self._save_manifest(current_hashes)
            return backup_path

        return None

if __name__ == '__main__':
    source = '/path/to/source'
    backup = '/path/to/backup'

    backup_tool = DiffBackup(source, backup)
    backup_file = backup_tool.create_backup()

    if backup_file:
        print(f'Backup created: {backup_file}')
    else:
        print('No changes detected, backup not needed')

