import subprocess
from pathlib import Path

class ImageInspector:
    def __init__(self, image_path):
        self.image_path = Path(image_path)
        self.mount_point = Path(tempfile.mkdtemp())
        self.modified = False

    def mount(self):
        if self.image_path.suffix.lower() == '.iso':
            subprocess.run(['mount', '-o', 'loop', str(self.image_path), str(self.mount_point)], check=True)
        elif self.image_path.suffix.lower() == '.wim':
            subprocess.run(['wimtools', 'mount', str(self.image_path), str(self.mount_point)], check=True)

    def unmount(self):
        if self.image_path.suffix.lower() == '.iso':
            subprocess.run(['umount', str(self.mount_point)], check=True)
        elif self.image_path.suffix.lower() == '.wim':
            subprocess.run(['wimtools', 'unmount', str(self.mount_point), '--commit' if self.modified else ''], check=True)
        shutil.rmtree(self.mount_point)

    def modify_file(self, file_path, content):
        target = self.mount_point / file_path
        with open(target, 'w') as f:
            f.write(content)
        self.modified = True

    def list_files(self, directory='.'):
        path = self.mount_point / directory
        return [str(p.relative_to(self.mount_point)) for p in path.rglob('*')]

    def extract_file(self, file_path, destination):
        source = self.mount_point / file_path
        shutil.copy2(source, destination)

    def __enter__(self):
        self.mount()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.unmount()

