        this.pm = context.getPackageManager();
    }

    public boolean installTheme(String themePackage) {
        try {
            if (!checkRootAccess()) {
                return false;
            }

            File overlayDir = new File(OVERLAY_DIR);
            if (!overlayDir.exists()) {
                Shell.su("mkdir -p " + OVERLAY_DIR).exec();
                Shell.su("chmod 755 " + OVERLAY_DIR).exec();
            }

            PackageInfo pi = pm.getPackageInfo(themePackage, 0);
            String overlayPath = pi.applicationInfo.sourceDir;

            Shell.su("mount -o rw,remount /system").exec();
            Shell.su("cp " + overlayPath + " " + OVERLAY_DIR).exec();
            Shell.su("chmod 644 " + OVERLAY_DIR + themePackage + ".apk").exec();
            Shell.su("mount -o ro,remount /system").exec();

            return true;
        } catch (Exception e) {
            Log.e("SubstratumTheme", "Installation failed", e);
            return false;
        }
    }

    public boolean uninstallTheme(String themePackage) {
        try {
            if (!checkRootAccess()) {
                return false;
            }

            Shell.su("mount -o rw,remount /system").exec();
            Shell.su("rm " + OVERLAY_DIR + themePackage + ".apk").exec();
            Shell.su("mount -o ro,remount /system").exec();

            return true;
        } catch (Exception e) {
            Log.e("SubstratumTheme", "Uninstallation failed", e);
            return false;
        }
    }

    private boolean checkRootAccess() {
        return Shell.su("id").exec().getStdout().contains("uid=0");
    }

    public List<String> getInstalledThemes() {
        List<String> themes = new ArrayList<>();
        File overlayDir = new File(OVERLAY_DIR);

        if (overlayDir.exists()) {
            File[] files = overlayDir.listFiles();
            if (files != null) {
                for (File file : files) {
                    if (file.getName().endsWith(".apk")) {
                        themes.add(file.getName().replace(".apk", ""));
                    }
                }
            }
        }
        return themes;
    }

    public void applyTheme(String themePackage) {
        try {
            Intent intent = new Intent("com.android.systemui.action.RESTART");
            context.sendBroadcast(intent);
        } catch (Exception e) {
            Log.e("SubstratumTheme", "Failed to apply theme", e);
        }
    }
}
