import os
import json
from datetime import datetime

class NoteApp:
    def __init__(self, storage_dir="notes"):
        self.storage_dir = storage_dir
        os.makedirs(storage_dir, exist_ok=True)

    def create_note(self, title, content):
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"{timestamp}_{title.replace(' ', '_')}.json"
        note = {
            "title": title,
            "content": content,
            "created_at": timestamp,
            "updated_at": timestamp
        }

        with open(os.path.join(self.storage_dir, filename), 'w') as f:
            json.dump(note, f, indent=4)
        return filename

    def read_note(self, filename):
        try:
            with open(os.path.join(self.storage_dir, filename), 'r') as f:
                return json.load(f)
        except FileNotFoundError:
            return None

    def update_note(self, filename, new_content):
        note = self.read_note(filename)
        if note:
            note["content"] = new_content
            note["updated_at"] = datetime.now().strftime("%Y%m%d_%H%M%S")
            with open(os.path.join(self.storage_dir, filename), 'w') as f:
                json.dump(note, f, indent=4)
            return True
        return False

    def delete_note(self, filename):
        try:
            os.remove(os.path.join(self.storage_dir, filename))
            return True
        except FileNotFoundError:
            return False

    def list_notes(self):
        return [f for f in os.listdir(self.storage_dir) if f.endswith('.json')]

