import os
import hashlib
import shutil
import time
from pathlib import Path
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class SyncHandler(FileSystemEventHandler):
    def __init__(self, source_dir, target_dir):
        self.source_dir = Path(source_dir)
        self.target_dir = Path(target_dir)

    def on_modified(self, event):
        if event.is_directory:
            return

        relative_path = Path(event.src_path).relative_to(self.source_dir)
        target_path = self.target_dir / relative_path

        if not target_path.parent.exists():
            target_path.parent.mkdir(parents=True)

        shutil.copy2(event.src_path, target_path)

    def on_created(self, event):
        self.on_modified(event)

    def on_deleted(self, event):
        relative_path = Path(event.src_path).relative_to(self.source_dir)
        target_path = self.target_dir / relative_path
        if target_path.exists():
            if target_path.is_file():
                target_path.unlink()
            else:
                shutil.rmtree(target_path)

def sync_directories(source_dir, target_dir):
    event_handler = SyncHandler(source_dir, target_dir)
    observer = Observer()
    observer.schedule(event_handler, source_dir, recursive=True)
    observer.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

if __name__ == "__main__":
    source_directory = "/path/to/source"
    target_directory = "/path/to/target"
    sync_directories(source_directory, target_directory)

