from urllib.parse import urljoin, urlparse
from collections import defaultdict
import threading
from queue import Queue
import re

class WebIndexer:
    def __init__(self, max_pages=100):
        self.visited = set()
        self.queue = Queue()
        self.index = defaultdict(list)
        self.max_pages = max_pages
        self.lock = threading.Lock()

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and bool(parsed.scheme)

    def extract_text(self, soup):
        for script in soup(['script', 'style']):
            script.decompose()
        text = ' '.join(soup.stripped_strings)
        return re.sub(r'\s+', ' ', text).strip()

    def index_page(self, url):
        try:
            response = requests.get(url, timeout=5)
            soup = BeautifulSoup(response.text, 'html.parser')

            text = self.extract_text(soup)
            words = set(word.lower() for word in re.findall(r'\w+', text))

            with self.lock:
                for word in words:
                    self.index[word].append(url)

            links = soup.find_all('a')
            for link in links:
                href = link.get('href')
                if href:
                    full_url = urljoin(url, href)
                    if self.is_valid_url(full_url) and full_url not in self.visited:
                        self.queue.put(full_url)

        except Exception as e:
            print(f"Error processing {url}: {str(e)}")

    def crawl(self, start_url):
        self.queue.put(start_url)

        while len(self.visited) < self.max_pages and not self.queue.empty():
            current_url = self.queue.get()
            if current_url not in self.visited:
                print(f"Indexing: {current_url}")
                self.visited.add(current_url)
                self.index_page(current_url)

    def search(self, query):
        query_words = query.lower().split()
        results = set.intersection(*[set(self.index[word]) for word in query_words])
        return list(results)

