import socket
import time
from collections import defaultdict
import threading

class DNSCache:
    def __init__(self, ttl=3600):
        self.cache = defaultdict(dict)
        self.ttl = ttl
        self.lock = threading.Lock()

    def get(self, domain, record_type):
        with self.lock:
            if domain in self.cache and record_type in self.cache[domain]:
                record, timestamp = self.cache[domain][record_type]
                if time.time() - timestamp < self.ttl:
                    return record
                del self.cache[domain][record_type]
            return None

    def put(self, domain, record_type, record):
        with self.lock:
            self.cache[domain][record_type] = (record, time.time())

class DNSServer:
    def __init__(self, upstream_dns='8.8.8.8', port=53):
        self.upstream_dns = upstream_dns
        self.port = port
        self.cache = DNSCache()
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        self.sock.bind(('', port))

    def forward_request(self, data):
        forward_sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        forward_sock.sendto(data, (self.upstream_dns, 53))
        response, _ = forward_sock.recvfrom(4096)
        forward_sock.close()
        return response

    def run(self):
        while True:
            data, addr = self.sock.recvfrom(4096)
            response = self.handle_request(data)
            self.sock.sendto(response, addr)

    def handle_request(self, data):
        domain = self.extract_domain(data)
        record_type = self.extract_record_type(data)

        cached_response = self.cache.get(domain, record_type)
        if cached_response:
            return cached_response

        response = self.forward_request(data)
        self.cache.put(domain, record_type, response)
        return response

    def extract_domain(self, data):
        # Simplified domain extraction
        return data[12:].split(b'\x00')[0].decode()

    def extract_record_type(self, data):
        # Simplified record type extraction
        return int.from_bytes(data[-4:-2], 'big')

if __name__ == '__main__':
    server = DNSServer()
    try:
        server.run()
    except KeyboardInterrupt:
        server.sock.close()

