import shutil

class ModManager:
    def __init__(self):
        self.mod_dir = Path.home() / "Documents" / "0ad" / "mods"
        self.mod_db_url = "https://example.com/0ad/mods.json"
        self.installed_mods = {}
        self.mod_dir.mkdir(parents=True, exist_ok=True)
        self._load_installed_mods()

    def _load_installed_mods(self):
        manifest_path = self.mod_dir / "installed.json"
        if manifest_path.exists():
            with open(manifest_path) as f:
                self.installed_mods = json.load(f)

    def _save_installed_mods(self):
        with open(self.mod_dir / "installed.json", "w") as f:
            json.dump(self.installed_mods, f, indent=2)

    def get_available_mods(self):
        response = requests.get(self.mod_db_url)
        return response.json()["mods"]

    def install_mod(self, mod_id):
        mods = self.get_available_mods()
        mod = next((m for m in mods if m["id"] == mod_id), None)

        if not mod:
            raise ValueError(f"Mod {mod_id} not found")

        # Download mod
        print(f"Downloading {mod['name']}...")
        response = requests.get(mod["download_url"], stream=True)
        zip_path = self.mod_dir / f"{mod_id}.zip"

        with open(zip_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        # Verify checksum
        sha256 = hashlib.sha256()
        with open(zip_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                sha256.update(chunk)

        if sha256.hexdigest() != mod["checksum"]:
            zip_path.unlink()
            raise ValueError("Downloaded file checksum mismatch")

        # Extract mod
        extract_path = self.mod_dir / mod_id
        if extract_path.exists():
            shutil.rmtree(extract_path)

        with zipfile.ZipFile(zip_path) as zf:
            zf.extractall(extract_path)

        # Update manifest
        self.installed_mods[mod_id] = {
            "name": mod["name"],
            "version": mod["version"],
            "installed_on": str(datetime.now())
        }
        self._save_installed_mods()

        # Cleanup
        zip_path.unlink()
        print(f"Successfully installed {mod['name']}")

    def uninstall_mod(self, mod_id):
        if mod_id not in self.installed_mods:
            raise ValueError(f"Mod {mod_id} not installed")

        mod_path = self.mod_dir / mod_id
        if mod_path.exists():
            shutil.rmtree(mod_path)

        del self.installed_mods[mod_id]
        self._save_installed_mods()
        print(f"Uninstalled {mod_id}")

    def list_installed_mods(self):
        return self.installed_mods

def main():
