import os
import tarfile
import hashlib
import json
from datetime import datetime
from pathlib import Path

class DiffBackup:
    def __init__(self, source_dir, backup_dir):
        self.source_dir = Path(source_dir)
        self.backup_dir = Path(backup_dir)
        self.hash_file = self.backup_dir / 'hashes.json'
        self.old_hashes = self._load_hashes()

    def _load_hashes(self):
        if self.hash_file.exists():
            with open(self.hash_file, 'r') as f:
                return json.load(f)
        return {}

    def _save_hashes(self, hashes):
        with open(self.hash_file, 'w') as f:
            json.dump(hashes, f)

    def _calculate_file_hash(self, filepath):
        hasher = hashlib.sha256()
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()

    def create_backup(self):
        new_hashes = {}
        files_to_backup = []

        for file_path in self.source_dir.rglob('*'):
            if file_path.is_file():
                rel_path = str(file_path.relative_to(self.source_dir))
                current_hash = self._calculate_file_hash(file_path)
                new_hashes[rel_path] = current_hash

                if rel_path not in self.old_hashes or self.old_hashes[rel_path] != current_hash:
                    files_to_backup.append(file_path)

        if files_to_backup:
            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
            archive_name = f'backup_{timestamp}.tar.gz'
            archive_path = self.backup_dir / archive_name

            with tarfile.open(archive_path, 'w:gz') as tar:
                for file_path in files_to_backup:
                    tar.add(file_path, arcname=str(file_path.relative_to(self.source_dir)))

            self._save_hashes(new_hashes)
            return archive_path

        return None

if __name__ == '__main__':
    backup = DiffBackup('/path/to/source', '/path/to/backup')
    result = backup.create_backup()
    if result:
        print(f'Backup created: {result}')
    else:
        print('No changes detected, backup not needed')

