import json
import os
from datetime import datetime
import logging
from pathlib import Path
import requests

class ServerMonitor:
    def __init__(self, config_path="/etc/monitor/config.json"):
        self.servers = self._load_config(config_path)
        self.output_dir = Path("/var/log/server_monitor")
        self.output_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(self.output_dir, 0o750)

        logging.basicConfig(
            filename=self.output_dir / "monitor.log",
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s'
        )

    def _load_config(self, config_path):
        with open(config_path) as f:
            return json.load(f)

    def check_server(self, server):
        try:
            response = requests.get(f"http://{server['host']}:{server['port']}/metrics")
            metrics = response.json()

            is_anomalous = (
                metrics['cpu_percent'] > server['cpu_threshold'] or 
                metrics['memory_percent'] > server['memory_threshold']
            )

            if is_anomalous:
                self._save_anomaly(server['host'], metrics)

            return metrics
        except Exception as e:
            logging.error(f"Error checking {server['host']}: {str(e)}")
            return None

    def _save_anomaly(self, hostname, metrics):
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = self.output_dir / f"anomaly_{hostname}_{timestamp}.json"

        with open(filename, 'w') as f:
            json.dump(metrics, f, indent=2)
        os.chmod(filename, 0o640)

        logging.warning(f"Anomaly detected for {hostname}: CPU={metrics['cpu_percent']}%, Memory={metrics['memory_percent']}%")

    def run_monitor(self):
        while True:
            for server in self.servers:
                self.check_server(server)
            time.sleep(3600)  # Sleep for 1 hour

if __name__ == "__main__":
    monitor = ServerMonitor()
    monitor.run_monitor()

