import json
import pandas as pd
from pathlib import Path
import random

class DialogueDataset:
    def __init__(self, data_path):
        self.data_path = Path(data_path)
        self.dialogues = []

    def load_data(self):
        with open(self.data_path, 'r', encoding='utf-8') as f:
            self.dialogues = json.load(f)

    def get_samples(self, n_samples=100):
        samples = []
        for dialogue in random.sample(self.dialogues, n_samples):
            context = dialogue['context']
            response = dialogue['response']
            samples.append({
                'context': context,
                'response': response,
                'metadata': {
                    'speaker': dialogue.get('speaker', ''),
                    'timestamp': dialogue.get('timestamp', '')
                }
            })
        return pd.DataFrame(samples)

    def preprocess(self, text):
        text = text.lower().strip()
        text = ' '.join(text.split())
        return text

    def export_training_data(self, output_path, n_samples=1000):
        samples = self.get_samples(n_samples)
        samples['context'] = samples['context'].apply(self.preprocess)
        samples['response'] = samples['response'].apply(self.preprocess)
        samples.to_json(output_path, orient='records', lines=True)
        return samples

