        self.members[person_id] = person
        return person_id

    def add_parent(self, child_id: str, parent_id: str) -> None:
        if len(self.members[child_id].parent_ids) < 2:
            self.members[child_id].parent_ids.append(parent_id)

    def add_memory(self, person_id: str, title: str, text: str) -> None:
        memory = {
            'id': str(uuid.uuid4()),
            'title': title,
            'text': text,
            'date': datetime.now()
        }
        self.members[person_id].memories.append(memory)

    def add_photo(self, person_id: str, photo_url: str) -> None:
        self.members[person_id].photos.append(photo_url)

    def get_descendants(self, person_id: str) -> List[Person]:
        descendants = []
        for member in self.members.values():
            if person_id in member.parent_ids:
                descendants.append(member)
        return descendants

    def get_ancestors(self, person_id: str) -> List[Person]:
        ancestors = []
        person = self.members[person_id]
        for parent_id in person.parent_ids:
            ancestors.append(self.members[parent_id])
            ancestors.extend(self.get_ancestors(parent_id))
        return ancestors

