        self.status = status
        self.location = location
        self.timestamp = timestamp
        self.description = description

class Shipment:
    def __init__(self, tracking_number, origin, destination):
        self.tracking_number = tracking_number or str(uuid.uuid4())
        self.origin = origin
        self.destination = destination
        self.status = ShipmentStatus.PENDING
        self.events = []

    def add_event(self, status, location, description):
        event = TrackingEvent(
            status=status,
            location=location,
            timestamp=datetime.now(),
            description=description
        )
        self.events.append(event)
        self.status = status

    def get_tracking_history(self):
        return sorted(self.events, key=lambda e: e.timestamp)

class ShipmentTracker:
    def __init__(self):
        self.shipments = {}

    def create_shipment(self, origin, destination):
        shipment = Shipment(None, origin, destination)
        self.shipments[shipment.tracking_number] = shipment
        return shipment.tracking_number

    def update_shipment(self, tracking_number, status, location, description):
        shipment = self.shipments.get(tracking_number)
        if shipment:
            shipment.add_event(status, location, description)

    def get_shipment(self, tracking_number):
        return self.shipments.get(tracking_number)
