#!/usr/bin/env python3
import os
import argparse
from pathlib import Path

def get_file_size(file_path):
    try:
        return os.path.getsize(file_path)
    except (OSError, IOError):
        return 0

def scan_directory(directory, size_threshold, action=None):
    large_files = []
    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            size = get_file_size(file_path)
            if size > size_threshold:
                large_files.append((file_path, size))
                if action == 'delete':
                    try:
                        os.remove(file_path)
                    except PermissionError:
                        continue
                elif action == 'readonly':
                    try:
                        os.chmod(file_path, 0o444)
                    except PermissionError:
                        continue
    return large_files

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('directory', help='Directory to scan')
    parser.add_argument('--threshold', type=int, default=100*1024*1024, help='Size threshold in bytes')
    parser.add_argument('--action', choices=['delete', 'readonly', 'none'], default='none')
    args = parser.parse_args()

    if not os.path.exists(args.directory):
        print(f"Directory {args.directory} does not exist")
        return

    large_files = scan_directory(args.directory, args.threshold, args.action)

    for file_path, size in sorted(large_files, key=lambda x: x[1], reverse=True):
        print(f"{file_path}: {size/1024/1024:.2f} MB")

if __name__ == '__main__':
