import shutil
import os
import sys
from pathlib import Path

class ZipDiskCopier:
    def __init__(self, source_path, destination_path):
        self.source = Path(source_path)
        self.destination = Path(destination_path)
        self.total_files = 0
        self.copied_files = 0
        self.errors = []

    def validate_paths(self):
        if not self.source.exists():
            raise FileNotFoundError(f"Source path {self.source} not found")
        if not self.destination.exists():
            self.destination.mkdir(parents=True)

    def copy_files(self):
        self.validate_paths()
        for root, dirs, files in os.walk(self.source):
            rel_path = Path(root).relative_to(self.source)
            dest_dir = self.destination / rel_path
            dest_dir.mkdir(exist_ok=True)

            for file in files:
                try:
                    src_file = Path(root) / file
                    dest_file = dest_dir / file
                    shutil.copy2(src_file, dest_file)
                    self.copied_files += 1
                    print(f"Copied: {src_file}")
                except Exception as e:
                    self.errors.append((str(src_file), str(e)))
                    print(f"Error copying {src_file}: {e}", file=sys.stderr)

            self.total_files += len(files)

    def verify_copy(self):
        src_files = set()
        dst_files = set()

        for root, _, files in os.walk(self.source):
            for file in files:
                src_files.add(Path(root) / file)

        for root, _, files in os.walk(self.destination):
            for file in files:
                dst_files.add(Path(root) / file)

        missing_files = [f for f in src_files if f not in dst_files]
        return len(missing_files) == 0

    def get_summary(self):
        return {
            "total_files": self.total_files,
            "copied_files": self.copied_files,
            "errors": len(self.errors),
            "error_details": self.errors
        }

def main():
    if len(sys.argv) != 3:
        print("Usage: python zipdisk_copier.py <source_path> <destination_path>")
        sys.exit(1)

