#!/usr/bin/env python3
import os
import argparse
from pathlib import Path

def scan_large_files(directory, size_threshold_mb, action=None):
    size_threshold = size_threshold_mb * 1024 * 1024
    large_files = []

    for root, _, files in os.walk(directory):
        for file in files:
            file_path = Path(root) / file
            try:
                if file_path.stat().st_size > size_threshold:
                    large_files.append({
                        'path': file_path,
                        'size': file_path.stat().st_size
                    })
                    if action == 'delete':
                        os.remove(file_path)
                    elif action == 'readonly':
                        os.chmod(file_path, 0o444)
            except (PermissionError, FileNotFoundError):
                continue

    return large_files

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('directory', help='Directory to scan')
    parser.add_argument('--threshold', type=int, default=100, help='Size threshold in MB')
    parser.add_argument('--action', choices=['delete', 'readonly', 'none'], default='none')
    args = parser.parse_args()

    large_files = scan_large_files(args.directory, args.threshold, args.action)

    for file in large_files:
        print(f"Large file: {file['path']}, Size: {file['size'] / 1024 / 1024:.2f}MB")

if __name__ == '__main__':
