import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
from collections import deque
import sqlite3
import hashlib

class WebCrawler:
    def __init__(self, start_url, max_pages=100):
        self.start_url = start_url
        self.max_pages = max_pages
        self.visited = set()
        self.queue = deque([start_url])
        self.db = sqlite3.connect('crawler.db')
        self.setup_database()

    def setup_database(self):
        cursor = self.db.cursor()
        cursor.execute('''
            CREATE TABLE IF NOT EXISTS pages (
                url TEXT PRIMARY KEY,
                content TEXT,
                hash TEXT,
                timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
            )
        ''')
        self.db.commit()

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and bool(parsed.scheme)

    def get_page_hash(self, content):
        return hashlib.sha256(content.encode()).hexdigest()

    def save_page(self, url, content):
        cursor = self.db.cursor()
        page_hash = self.get_page_hash(content)
        cursor.execute('INSERT OR REPLACE INTO pages (url, content, hash) VALUES (?, ?, ?)',
                      (url, content, page_hash))
        self.db.commit()

    def crawl(self):
        while self.queue and len(self.visited) < self.max_pages:
            url = self.queue.popleft()
            if url in self.visited:
                continue

            try:
                response = requests.get(url, timeout=5)
                if response.status_code == 200:
                    soup = BeautifulSoup(response.text, 'html.parser')
                    self.save_page(url, response.text)
                    self.visited.add(url)

                    for link in soup.find_all('a'):
                        href = link.get('href')
                        if href:
                            absolute_url = urljoin(url, href)
                            if self.is_valid_url(absolute_url) and absolute_url not in self.visited:
                                self.queue.append(absolute_url)

            except Exception as e:
                print(f"Error crawling {url}: {e}")

    def close(self):
        self.db.close()

if __name__ == "__main__":
    crawler = WebCrawler("https://example.com")
    crawler.crawl()
    crawler.close()

