@dataclass
class APIEndpoint:
    path: str
    method: str
    description: str
    request_schema: Dict[str, Any]
    response_schema: Dict[str, Any]

class APIDocGenerator:
    def __init__(self):
        self.endpoints = {}

    def document_endpoint(self, path: str, method: str):
        def decorator(func):
            schema = self._generate_schema(func)
            self.endpoints[f"{method.upper()} {path}"] = APIEndpoint(
                path=path,
                method=method.upper(),
                description=func.__doc__ or "",
                request_schema=schema.get("request", {}),
                response_schema=schema.get("response", {})
            )
            return func
        return decorator

    def _generate_schema(self, func) -> Dict[str, Any]:
        sig = inspect.signature(func)
        annotations = func.__annotations__

        request_schema = {
            "type": "object",
            "properties": {}
        }

        response_schema = {
            "type": "object",
            "properties": {}
        }

        for param_name, param in sig.parameters.items():
            if param_name in annotations:
                request_schema["properties"][param_name] = self._type_to_json_schema(annotations[param_name])

        if "return" in annotations:
            response_schema = self._type_to_json_schema(annotations["return"])

        return {"request": request_schema, "response": response_schema}

    def _type_to_json_schema(self, type_hint: type) -> Dict[str, Any]:
        if type_hint == str:
            return {"type": "string"}
        elif type_hint == int:
            return {"type": "integer"}
        elif type_hint == float:
            return {"type": "number"}
        elif type_hint == bool:
            return {"type": "boolean"}
        elif type_hint == list:
            return {"type": "array"}
        elif type_hint == dict:
            return {"type": "object"}
        return {"type": "string"}

    def generate_docs(self, format: str = "json") -> str:
        docs = {
            "openapi": "3.0.0",
            "info": {
                "title": "API Documentation",
                "version": "1.0.0"
            },
            "paths": {}
        }

        for endpoint in self.endpoints.values():
            if endpoint.path not in docs["paths"]:
                docs["paths"][endpoint.path] = {}

            docs["paths"][endpoint.path][endpoint.method.lower()] = {
                "description": endpoint.description,
                "requestBody": {
                    "content": {
                        "application/json": {
                            "schema": endpoint.request_schema
                        }
                    }
                },
                "responses": {
                    "200": {
                        "description": "Successful response",
                        "content": {
                            "application/json": {
                                "schema": endpoint.response_schema
                            }
                        }
                    }
                }
            }

        if format.lower() == "yaml":
            return yaml.dump(docs)
        return json.dumps(docs, indent=2)

