@dataclass
class CreditCard:
    name: str
    issuer: str
    apr: Decimal
    annual_fee: Decimal
    rewards_rate: Decimal
    welcome_bonus: str
    credit_score_required: str
    features: List[str]
    image_url: str
    apply_url: str

class CreditCardDatabase:
    def __init__(self):
        self.cards = {}

    def add_card(self, card: CreditCard):
        self.cards[card.name] = card

    def get_card(self, name: str) -> CreditCard:
        return self.cards.get(name)

    def search_cards(self, min_credit_score=None, max_annual_fee=None) -> List[CreditCard]:
        results = []
        for card in self.cards.values():
            if min_credit_score and card.credit_score_required < min_credit_score:
                continue
            if max_annual_fee and card.annual_fee > max_annual_fee:
                continue
            results.append(card)
        return results

    def get_best_rewards_cards(self, limit=5) -> List[CreditCard]:
        sorted_cards = sorted(self.cards.values(), 
                            key=lambda x: x.rewards_rate,
                            reverse=True)
        return sorted_cards[:limit]

    def get_zero_apr_cards(self) -> List[CreditCard]:
        return [card for card in self.cards.values() if card.apr == 0]
