class Job:
    def __init__(self, func, args):
        self.func = func
        self.args = args

    def run(self):
        self.func(*self.args)

    def save(self, job_dir):
        filename = os.path.join(job_dir, str(uuid.uuid4()))
        with open(filename, 'wb') as f:
            pickle.dump(self, f)

class Worker(threading.Thread):
    def __init__(self, queue, poll_interval=1):
        super().__init__()
        self.queue = queue
        self.poll_interval = poll_interval
        self.running = True

    def run(self):
        while self.running:
            job = self.queue.get()
            if job:
                job.run()
            time.sleep(self.poll_interval)

    def stop(self):
        self.running = False

class JobQueue:
    def __init__(self, job_dir):
        self.job_dir = Path(job_dir)
        self.job_dir.mkdir(parents=True, exist_ok=True)

    def put(self, job):
        job.save(self.job_dir)

    def get(self):
        filenames = os.listdir(self.job_dir)
        for filename in filenames:
            filepath = os.path.join(self.job_dir, filename)
            try:
                with open(filepath, 'rb') as f:
