        if start_date is None and end_date is None:
            return sum(self.expenses.values())
        return sum(cost for date, cost in self.expenses.items() 
                  if start_date <= date <= end_date)

    def get_upcoming_services(self, current_mileage):
        upcoming = []
        service_intervals = {
            'oil_change': 5000,
            'tire_rotation': 7500,
            'brake_inspection': 12000
        }

