        if timestamp is None:
            timestamp = datetime.datetime.now()
        self.backups[path].append({
            'size': size,
            'timestamp': timestamp,
            'status': 'completed'
        })

    def add_restoration(self, backup_path, restore_path, timestamp=None):
        if timestamp is None:
            timestamp = datetime.datetime.now()
        self.restorations.append({
            'backup_path': backup_path,
            'restore_path': restore_path,
            'timestamp': timestamp,
            'status': 'completed'
        })

    def get_stats(self):
        total_backups = sum(len(b) for b in self.backups.values())
        total_size = sum(b['size'] for backups in self.backups.values() 
                        for b in backups)
        return {
            'total_backups': total_backups,
            'total_restorations': len(self.restorations),
            'total_size': total_size
        }

