import os
import hashlib
from pathlib import Path
from collections import defaultdict
import shutil

class DiskAnalyzer:
    def __init__(self, root_path):
        self.root_path = Path(root_path)
        self.duplicate_files = defaultdict(list)
        self.file_hashes = {}

    def calculate_file_hash(self, filepath):
        sha256_hash = hashlib.sha256()
        with open(filepath, "rb") as f:
            for byte_block in iter(lambda: f.read(4096), b""):
                sha256_hash.update(byte_block)
        return sha256_hash.hexdigest()

    def find_duplicates(self):
        for path in self.root_path.rglob('*'):
            if path.is_file():
                file_hash = self.calculate_file_hash(path)
                self.duplicate_files[file_hash].append(path)

    def get_duplicates(self):
        return {k: v for k, v in self.duplicate_files.items() if len(v) > 1}

    def delete_duplicate(self, file_path):
        try:
            os.remove(file_path)
            return True
        except OSError:
            return False

    def set_permissions(self, file_path, mode):
        try:
            os.chmod(file_path, mode)
            return True
        except OSError:
            return False

    def backup_file(self, file_path, backup_dir):
        try:
            shutil.copy2(file_path, backup_dir)
            return True
        except OSError:
            return False

    def analyze(self):
        self.find_duplicates()
        duplicates = self.get_duplicates()

        total_space = 0
        for file_hash, paths in duplicates.items():
            size = os.path.getsize(paths[0])
            total_space += size * (len(paths) - 1)

        return {
            'duplicate_groups': duplicates,
            'wasted_space': total_space,
            'num_duplicates': sum(len(paths) - 1 for paths in duplicates.values())
        }

if __name__ == "__main__":
