from datetime import datetime

class NutritionTracker:
    def __init__(self):
        self.meals = {}
        self.daily_totals = {}

    def add_meal(self, name, calories, protein, carbs, fat):
        meal = {
            'name': name,
            'calories': calories,
            'protein': protein, 
            'carbs': carbs,
            'fat': fat,
            'timestamp': datetime.now()
        }

        date = datetime.now().date()
        if date not in self.meals:
            self.meals[date] = []
        self.meals[date].append(meal)
        self._update_totals(date)

    def _update_totals(self, date):
        totals = {
            'calories': 0,
            'protein': 0,
            'carbs': 0, 
            'fat': 0
        }

        for meal in self.meals[date]:
            totals['calories'] += meal['calories']
            totals['protein'] += meal['protein']
            totals['carbs'] += meal['carbs']
            totals['fat'] += meal['fat']

        self.daily_totals[date] = totals

    def get_daily_totals(self, date=None):
        if date is None:
            date = datetime.now().date()
        return self.daily_totals.get(date, {})

    def get_meals(self, date=None):
        if date is None:
            date = datetime.now().date()
        return self.meals.get(date, [])

# Example usage
