    def __init__(self, output_dir="/var/log/monitoring"):
        self.output_dir = Path(output_dir)
        self.thresholds = {
            'cpu_percent': 80.0,
            'memory_percent': 90.0
        }
        self.setup_output_dir()

    def setup_output_dir(self):
        self.output_dir.mkdir(parents=True, exist_ok=True)
        os.chmod(self.output_dir, 0o750)

    def check_system(self):
        measurements = {
            'timestamp': datetime.now().isoformat(),
            'cpu_percent': psutil.cpu_percent(),
            'memory_percent': psutil.virtual_memory().percent
        }

        if self.is_anomalous(measurements):
            self.save_measurement(measurements)

    def is_anomalous(self, measurements):
        return (measurements['cpu_percent'] > self.thresholds['cpu_percent'] or 
                measurements['memory_percent'] > self.thresholds['memory_percent'])

    def save_measurement(self, data):
        filename = f"anomaly_{data['timestamp']}.json"
        filepath = self.output_dir / filename

        with open(filepath, 'w') as f:
            json.dump(data, f)
        os.chmod(filepath, 0o640)

    def run(self):
        while True:
            try:
                self.check_system()
                time.sleep(3600)  # Sleep for 1 hour
            except Exception as e:
                print(f"Error during monitoring: {e}")
                time.sleep(60)  # Short sleep on error before retrying

if __name__ == "__main__":
