    if 'file' not in request.files:
        return jsonify({'error': 'No file uploaded'}), 400

    file = request.files['file']
    student_id = request.form.get('student_id')

    if not file or not student_id:
        return jsonify({'error': 'Missing data'}), 400

    filename = secure_filename(file.filename)
    path = os.path.join(app.config['UPLOAD_FOLDER'], assignment_id, student_id)
    os.makedirs(path, exist_ok=True)

    file.save(os.path.join(path, filename))

    if assignment_id not in assignments:
        assignments[assignment_id] = Assignment()

    assignments[assignment_id].submissions[student_id] = {
        'filename': filename,
        'timestamp': datetime.now().isoformat(),
        'status': 'submitted'
    }

    return jsonify({'status': 'success'})

@app.route('/grade/<assignment_id>/<student_id>', methods=['POST'])
def grade_homework(assignment_id, student_id):
    data = request.get_json()
    grade = data.get('grade')
    feedback = data.get('feedback')

    if not grade:
        return jsonify({'error': 'Grade required'}), 400

    if assignment_id not in assignments:
        return jsonify({'error': 'Assignment not found'}), 404

    assignments[assignment_id].grades[student_id] = {
        'grade': grade,
        'feedback': feedback,
        'timestamp': datetime.now().isoformat()
    }

    return jsonify({'status': 'success'})

@app.route('/grades/<student_id>', methods=['GET'])
