ALLOWED_EXTENSIONS = {'pdf', 'doc', 'docx'}

class Resume:
    def __init__(self):
        self.submissions = {}

    def allowed_file(self, filename):
        return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

    def save_submission(self, data, file):
        submission_id = len(self.submissions) + 1
        self.submissions[submission_id] = {
            'name': data['name'],
            'email': data['email'],
            'work_history': data['work_history'],
            'skills': data['skills'],
            'resume_file': file.filename
        }
        return submission_id

@app.route('/submit', methods=['POST'])
def submit_resume():
    if 'resume' not in request.files:
        return jsonify({'error': 'No resume file'}), 400

    file = request.files['resume']
    if not Resume().allowed_file(file.filename):
        return jsonify({'error': 'Invalid file type'}), 400

    data = request.form
    if not all(k in data for k in ['name', 'email', 'work_history', 'skills']):
        return jsonify({'error': 'Missing required fields'}), 400

    filename = secure_filename(file.filename)
    file.save(os.path.join(app.config['UPLOAD_FOLDER'], filename))

    submission_id = Resume().save_submission(data, file)
    return jsonify({'success': True, 'submission_id': submission_id})

