import os
import zipfile
import hashlib
import json
from dataclasses import dataclass
from typing import List
from pathlib import Path

@dataclass
class Package:
    name: str
    version: str
    checksum: str
    file_path: Path
    dependencies: List[str]

class SoftwareDistributor:
    def __init__(self, storage_path: str):
        self.storage_path = Path(storage_path)
        self.storage_path.mkdir(exist_ok=True)
        self.packages = {}
        self._load_packages()

    def _load_packages(self):
        manifest_path = self.storage_path / 'manifest.json'
        if manifest_path.exists():
            with open(manifest_path) as f:
                self.packages = json.load(f)

    def _save_packages(self):
        with open(self.storage_path / 'manifest.json', 'w') as f:
            json.dump(self.packages, f)

    def add_package(self, name: str, version: str, file_path: str, dependencies: List[str] = None):
        package_path = self.storage_path / f"{name}-{version}.zip"

        with zipfile.ZipFile(package_path, 'w', zipfile.ZIP_DEFLATED) as zf:
            zf.write(file_path, os.path.basename(file_path))

        checksum = self._calculate_checksum(package_path)

        package = Package(
            name=name,
            version=version,
            checksum=checksum,
            file_path=package_path,
            dependencies=dependencies or []
        )

        self.packages[f"{name}-{version}"] = package.__dict__
        self._save_packages()

    def get_package(self, name: str, version: str) -> Package:
        key = f"{name}-{version}"
        if key not in self.packages:
            raise ValueError(f"Package {key} not found")
        return Package(**self.packages[key])

    def verify_package(self, name: str, version: str) -> bool:
        package = self.get_package(name, version)
        current_checksum = self._calculate_checksum(package.file_path)
        return current_checksum == package.checksum

    def _calculate_checksum(self, file_path: Path) -> str:
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

class EnterpriseDeployer:
    def __init__(self, distributor: SoftwareDistributor):
        self.distributor = distributor

    def deploy_to_employee(self, employee_id: str, package_name: str, version: str):
        package = self.distributor.get_package(package_name, version)

        if not self.distributor.verify_package(package_name, version):
            raise ValueError("Package verification failed")

        deploy_path = Path(f"deployments/{employee_id}")
        deploy_path.mkdir(parents=True, exist_ok=True)

        with zipfile.ZipFile(package.file_path, 'r') as zf:
            zf.extractall(deploy_path)

        for dep in package.dependencies:
            name, version = dep.split('@')
            self.deploy_to_employee(employee_id, name, version)

def main():
    distributor = SoftwareDistributor("software_packages")

    # Add sample software package
    distributor.add_package(
        name="chrome",
        version="96.0.4664.45",
        file_path="chrome_installer.exe",
        dependencies=["vcredist@14.28.29910"]
    )

    # Deploy to employee
    deployer = EnterpriseDeployer(distributor)
    deployer.deploy_to_employee("EMP001", "chrome", "96.0.4664.45")

if __name__ == "__main__":
    main()
