class Task:
    def __init__(self, title, description, reward, requester_id):
        self.id = str(uuid.uuid4())
        self.title = title
        self.description = description 
        self.reward = reward
        self.requester_id = requester_id
        self.status = "available"
        self.worker_id = None
        self.completed_at = None

class TaskManager:
    def __init__(self):
        self.tasks = {}
        self.user_balances = {}

    def create_task(self, title, description, reward, requester_id):
        task = Task(title, description, reward, requester_id)
        self.tasks[task.id] = task
        return task.id

    def claim_task(self, task_id, worker_id):
        if task_id in self.tasks:
            task = self.tasks[task_id]
            if task.status == "available":
                task.status = "in_progress"
                task.worker_id = worker_id
                return True
        return False

    def complete_task(self, task_id, worker_id):
        if task_id in self.tasks:
            task = self.tasks[task_id]
            if task.worker_id == worker_id and task.status == "in_progress":
                task.status = "completed"
                task.completed_at = datetime.now()
                if worker_id not in self.user_balances:
                    self.user_balances[worker_id] = 0
                self.user_balances[worker_id] += task.reward
                return True
        return False

