class SyncHandler(FileSystemEventHandler):
    def __init__(self, source_dir, target_dir):
        self.source_dir = Path(source_dir)
        self.target_dir = Path(target_dir)
        self.sync_state = {}
        self.load_state()

    def on_modified(self, event):
        if event.is_directory:
            return
        source_path = Path(event.src_path)
        relative_path = source_path.relative_to(self.source_dir)
        target_path = self.target_dir / relative_path
        self.sync_file(source_path, target_path)

    def sync_file(self, source_path, target_path):
        if not source_path.exists():
            return
        file_hash = self.get_file_hash(source_path)
        if str(source_path) in self.sync_state:
            if self.sync_state[str(source_path)] == file_hash:
                return
        target_path.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(source_path, target_path)
        self.sync_state[str(source_path)] = file_hash
        self.save_state()

    def get_file_hash(self, file_path):
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                hasher.update(chunk)
        return hasher.hexdigest()

    def save_state(self):
        with open('.sync_state', 'w') as f:
            json.dump(self.sync_state, f)

    def load_state(self):
        try:
            with open('.sync_state', 'r') as f:
                self.sync_state = json.load(f)
        except FileNotFoundError:
            self.sync_state = {}

def start_sync(source_dir, target_dir):
    event_handler = SyncHandler(source_dir, target_dir)
    observer = Observer()
    observer.schedule(event_handler, source_dir, recursive=True)
    observer.start()
    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

if __name__ == "__main__":
    source_directory = "./source"
    target_directory = "./target"
    start_sync(source_directory, target_directory)

