        self.trials[trial.id] = trial

    def get_trial(self, trial_id: str) -> ClinicalTrial:
        return self.trials.get(trial_id)

    def get_all_trials(self) -> List[ClinicalTrial]:
        return list(self.trials.values())

    def search_trials(self, condition: str = None, location: str = None) -> List[ClinicalTrial]:
