            self.people[person_id].photo_urls.append(photo_url)

    def add_memory(self, person_id: str, memory_text: str):
        if person_id in self.people:
            memory = {
                'text': memory_text,
                'date_added': datetime.now()
            }
            self.people[person_id].memories.append(memory)

    def get_ancestors(self, person_id: str, generations: int = 3) -> List[Person]:
        ancestors = []
        if person_id not in self.people or generations == 0:
            return ancestors

        person = self.people[person_id]
        for parent_id in person.parent_ids:
            if parent_id in self.people:
                ancestors.append(self.people[parent_id])
                ancestors.extend(self.get_ancestors(parent_id, generations - 1))

