class ModularDevice:
    def __init__(self, name, type_id, sample_rate=44100):
        self.name = name
        self.type_id = type_id
        self.sample_rate = sample_rate
        self.inputs = []
        self.outputs = []
        self.parameters = {}

class Oscillator(ModularDevice):
    def __init__(self, name, frequency=440):
        super().__init__(name, "oscillator")
        self.parameters = {
            "frequency": frequency,
            "waveform": "sine",
            "amplitude": 1.0
        }

    def process(self, time):
        return self.parameters["amplitude"] * np.sin(2 * np.pi * self.parameters["frequency"] * time)

class Filter(ModularDevice):
    def __init__(self, name, cutoff=1000):
        super().__init__(name, "filter")
        self.parameters = {
            "cutoff": cutoff,
            "resonance": 0.707,
            "type": "lowpass"
        }

    def process(self, signal):
        return signal * (self.parameters["cutoff"] / self.sample_rate)

class Sequencer(ModularDevice):
    def __init__(self, name, steps=16):
        super().__init__(name, "sequencer")
        self.parameters = {
            "steps": steps,
            "current_step": 0,
            "sequence": [0] * steps,
            "bpm": 120
        }

    def next_step(self):
        self.parameters["current_step"] = (self.parameters["current_step"] + 1) % self.parameters["steps"]
        return self.parameters["sequence"][self.parameters["current_step"]]

class Patch:
    def __init__(self):
        self.devices = {}
        self.connections = []

    def add_device(self, device):
        self.devices[device.name] = device

    def connect(self, from_device, from_port, to_device, to_port):
        self.connections.append({
            "from": (from_device, from_port),
            "to": (to_device, to_port)
        })

    def process(self, buffer_size=1024):
        buffer = np.zeros(buffer_size)
        for device in self.devices.values():
            if isinstance(device, Oscillator):
                time = np.linspace(0, buffer_size/device.sample_rate, buffer_size)
                buffer += device.process(time)
        return buffer

class ModularSynth:
    def __init__(self):
        self.patches = {}
        self.active_patch = None

    def create_patch(self, name):
        self.patches[name] = Patch()
        self.active_patch = name

    def add_device(self, device):
        if self.active_patch:
            self.patches[self.active_patch].add_device(device)

    def connect_devices(self, from_device, from_port, to_device, to_port):
        if self.active_patch:
            self.patches[self.active_patch].connect(from_device, from_port, to_device, to_port)

    def process_audio(self, buffer_size=1024):
        if self.active_patch:
            return self.patches[self.active_patch].process(buffer_size)
        return np.zeros(buffer_size)

