import os
import shutil
import hashlib
from pathlib import Path
from datetime import datetime

class ZipDiskCopier:
    def __init__(self, source_path, destination_path):
        self.source = Path(source_path)
        self.destination = Path(destination_path)
        self.log_file = Path("transfer_log.txt")
        self.checksums = {}

    def verify_paths(self):
        if not self.source.exists():
            raise FileNotFoundError(f"Source path {self.source} not found")
        self.destination.mkdir(parents=True, exist_ok=True)

    def calculate_checksum(self, file_path):
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            while chunk := f.read(8192):
                sha256.update(chunk)
        return sha256.hexdigest()

    def copy_files(self):
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_dir = self.destination / f"zip_backup_{timestamp}"
        backup_dir.mkdir(parents=True)

        for source_file in self.source.rglob('*'):
            if source_file.is_file():
                rel_path = source_file.relative_to(self.source)
                dest_file = backup_dir / rel_path
                dest_file.parent.mkdir(parents=True, exist_ok=True)

                shutil.copy2(source_file, dest_file)

                source_checksum = self.calculate_checksum(source_file)
                dest_checksum = self.calculate_checksum(dest_file)

                self.checksums[str(rel_path)] = {
                    'source': source_checksum,
                    'destination': dest_checksum,
                    'verified': source_checksum == dest_checksum
                }

    def create_log(self):
        with open(self.log_file, 'w') as log:
            log.write(f"Transfer completed at: {datetime.now()}\n")
            log.write(f"Source: {self.source}\n")
            log.write(f"Destination: {self.destination}\n\n")

            for file_path, checksums in self.checksums.items():
                status = "SUCCESS" if checksums['verified'] else "FAILED"
                log.write(f"{status}: {file_path}\n")
                log.write(f"Source checksum: {checksums['source']}\n")
                log.write(f"Dest checksum: {checksums['destination']}\n\n")

    def run(self):
        try:
            self.verify_paths()
            self.copy_files()
            self.create_log()
            return True
        except Exception as e:
            with open(self.log_file, 'a') as log:
                log.write(f"\nError occurred: {str(e)}")
            return False

