import os
import sys
import subprocess
import tempfile
from pathlib import Path
import shutil

class ImageUnpacker:
    def __init__(self, target_dir=None):
        self.target_dir = target_dir or tempfile.mkdtemp()
        self._validate_tools()

    def _validate_tools(self):
        required = ['7z', 'wimlib-imagex']
        for tool in required:
            if not shutil.which(tool):
                raise RuntimeError(f"Required tool '{tool}' not found")

    def unpack_iso(self, iso_path):
        if not os.path.exists(iso_path):
            raise FileNotFoundError(f"ISO file not found: {iso_path}")

        cmd = ['7z', 'x', iso_path, f'-o{self.target_dir}']
        result = subprocess.run(cmd, capture_output=True, text=True)

        if result.returncode != 0:
            raise RuntimeError(f"Failed to unpack ISO: {result.stderr}")

        return self.target_dir

    def unpack_wim(self, wim_path, index=1):
        if not os.path.exists(wim_path):
            raise FileNotFoundError(f"WIM file not found: {wim_path}")

        cmd = ['wimlib-imagex', 'extract', wim_path, str(index), 
               self.target_dir, '--no-acls']
        result = subprocess.run(cmd, capture_output=True, text=True)

        if result.returncode != 0:
            raise RuntimeError(f"Failed to unpack WIM: {result.stderr}")

        return self.target_dir

    def cleanup(self):
        if os.path.exists(self.target_dir):
            shutil.rmtree(self.target_dir)

def main():
    if len(sys.argv) < 3:
        print("Usage: script.py <type> <image_path>")
        sys.exit(1)

    image_type = sys.argv[1].lower()
    image_path = sys.argv[2]

    unpacker = ImageUnpacker()

    try:
        if image_type == 'iso':
            output_dir = unpacker.unpack_iso(image_path)
        elif image_type == 'wim':
            output_dir = unpacker.unpack_wim(image_path)
        else:
            print(f"Unsupported image type: {image_type}")
            sys.exit(1)

        print(f"Image unpacked to: {output_dir}")

    except Exception as e:
        print(f"Error: {str(e)}")
        sys.exit(1)
    finally:
        unpacker.cleanup()

if __name__ == '__main__':
    main()
