from datetime import datetime

class VersionControl:
    def __init__(self, repo_path):
        self.repo_path = repo_path
        self.repo = git.Repo.init(repo_path)

    def add_file(self, file_path):
        self.repo.index.add([file_path])

    def commit(self, message):
        self.repo.index.commit(message)

    def create_branch(self, branch_name):
        current = self.repo.create_head(branch_name)
        current.checkout()

    def switch_branch(self, branch_name):
        self.repo.heads[branch_name].checkout()

    def get_commit_history(self):
        commits = []
        for commit in self.repo.iter_commits():
            commits.append({
                'hash': commit.hexsha,
                'author': commit.author.name,
                'date': datetime.fromtimestamp(commit.committed_date),
                'message': commit.message
            })
        return commits

    def push(self, remote_name='origin'):
        self.repo.remotes[remote_name].push()

    def pull(self, remote_name='origin'):
        self.repo.remotes[remote_name].pull()

import os
import time
import shutil
from pathlib import Path

def find_temp_files(directory, max_age_days=7):
    current_time = time.time()
    temp_files = []

    for root, dirs, files in os.walk(directory):
        for file in files:
            filepath = os.path.join(root, file)
            if any(file.endswith(ext) for ext in ['.tmp', '.temp', '.bak', '~']):
                file_age = current_time - os.path.getmtime(filepath)
                if file_age > (max_age_days * 86400):
                    temp_files.append(filepath)
    return temp_files

def remove_temp_files(files):
    for file in files:
        try:
            os.remove(file)
        except (PermissionError, FileNotFoundError) as e:
            continue

def cleanup_directory(directory):
    temp_files = find_temp_files(directory)
    remove_temp_files(temp_files)
    empty_dirs = []

    for root, dirs, files in os.walk(directory, topdown=False):
        for dir in dirs:
            dirpath = os.path.join(root, dir)
            if not os.listdir(dirpath):
                empty_dirs.append(dirpath)

    for dir in empty_dirs:
        try:
            os.rmdir(dir)
        except OSError:
            continue

if __name__ == "__main__":
    cleanup_directory("/path/to/directory")

