    def create_post(self, text: str) -> Post:
        self.current_post = Post(
            text=text,
            media=[],
            created_at=datetime.datetime.now(),
            preview_html=self._generate_preview(text, [])
        )
        return self.current_post

    def add_media(self, media_type: str, content: bytes) -> None:
        if not self.current_post:
            raise ValueError("Create post first")

        encoded_content = base64.b64encode(content).decode('utf-8')
        media_item = MediaItem(
            type=media_type,
            content=encoded_content,
            preview_url=f"data:{media_type};base64,{encoded_content}"
        )
        self.current_post.media.append(media_item)
        self.current_post.preview_html = self._generate_preview(
            self.current_post.text,
            self.current_post.media
        )

    def _generate_preview(self, text: str, media: List[MediaItem]) -> str:
        preview = f"<div class='post-preview'><p>{text}</p>"
        for item in media:
            if 'image' in item.type:
                preview += f"<img src='{item.preview_url}' />"
            elif 'video' in item.type:
                preview += f"<video src='{item.preview_url}' controls></video>"
        preview += "</div>"
        return preview

app = Flask(__name__)
composer = PostComposer()

@app.route('/compose', methods=['POST'])
def compose_post():
    data = request.get_json()
    post = composer.create_post(data['text'])
    return jsonify({
        'preview': post.preview_html,
        'timestamp': post.created_at.isoformat()
    })

@app.route('/add_media', methods=['POST'])
def add_media():
    media_file = request.files['media']
    composer.add_media(media_file.content_type, media_file.read())
    return jsonify({
        'preview': composer.current_post.preview_html
    })

