class ArchiveExtractor:
    def __init__(self, source_path, target_path):
        self.source = source_path
        self.target = target_path

    def extract_zip(self):
        with zipfile.ZipFile(self.source, 'r') as zip_ref:
            zip_ref.extractall(self.target)

    def extract_tar(self):
        with tarfile.open(self.source, 'r:*') as tar_ref:
            tar_ref.extractall(self.target)

    def extract_gzip(self):
        with gzip.open(self.source, 'rb') as gz:
            with open(self.target, 'wb') as out_file:
                shutil.copyfileobj(gz, out_file)

    def extract_bz2(self):
        with bz2.open(self.source, 'rb') as bz:
            with open(self.target, 'wb') as out_file:
                shutil.copyfileobj(bz, out_file)

