        pygame.mixer.init()
        self.playlist = []
        self.current_track = 0
        self.is_playing = False

    def load_directory(self, directory_path):
        supported_formats = {'.mp3', '.wav', '.ogg', '.flac'}
        self.playlist = []

        for file in Path(directory_path).glob('**/*'):
            if file.suffix.lower() in supported_formats:
                metadata = File(file)
                track_info = {
                    'path': str(file),
                    'title': metadata.tags.get('title', [file.stem])[0],
                    'artist': metadata.tags.get('artist', ['Unknown'])[0],
                    'duration': metadata.info.length
                }
                self.playlist.append(track_info)

    def play(self):
        if self.playlist:
            pygame.mixer.music.load(self.playlist[self.current_track]['path'])
            pygame.mixer.music.play()
            self.is_playing = True

    def pause(self):
        if self.is_playing:
            pygame.mixer.music.pause()
            self.is_playing = False

    def resume(self):
        if not self.is_playing:
            pygame.mixer.music.unpause()
            self.is_playing = True

    def next_track(self):
        if self.playlist:
            self.current_track = (self.current_track + 1) % len(self.playlist)
            self.play()

    def previous_track(self):
        if self.playlist:
            self.current_track = (self.current_track - 1) % len(self.playlist)
            self.play()

    def get_current_track_info(self):
        if self.playlist:
            return self.playlist[self.current_track]
        return None

    def cleanup(self):
        pygame.mixer.quit()

