import os
import subprocess
import argparse
from pathlib import Path

class Builder:
    def __init__(self, src_dir, build_dir):
        self.src_dir = Path(src_dir)
        self.build_dir = Path(build_dir)
        self.build_dir.mkdir(exist_ok=True)

    def compile_source(self, source_file):
        output = self.build_dir / source_file.stem
        try:
            subprocess.run([
                'gcc',
                '-Wall',
                '-O2',
                str(source_file),
                '-o',
                str(output)
            ], check=True)
            return True
        except subprocess.CalledProcessError:
            return False

    def build_all(self):
        results = {}
        for source in self.src_dir.glob('*.c'):
            results[source.name] = self.compile_source(source)
        return results

def main():
    parser = argparse.ArgumentParser(description='Build system')
    parser.add_argument('--src', default='src', help='Source directory')
    parser.add_argument('--build', default='build', help='Build directory')
    args = parser.parse_args()

    builder = Builder(args.src, args.build)
    results = builder.build_all()

    for file, success in results.items():
        status = 'SUCCESS' if success else 'FAILED'
        print(f'Building {file}: {status}')

if __name__ == '__main__':
    main()

from dataclasses import dataclass
from datetime import datetime
from typing import List
import uuid

@dataclass
class Passenger:
    name: str
    age: int
    seat_number: str
    passport_number: str

@dataclass
class Booking:
    booking_id: str
    travel_date: datetime
    origin: str
    destination: str
    passengers: List[Passenger]
    status: str

class TicketBookingSystem:
    def __init__(self):
        self.bookings = {}
        self.available_seats = set(f"{row}{num}" for row in "ABCD" for num in range(1, 31))

    def create_booking(self, travel_date: str, origin: str, destination: str, passengers: List[dict]) -> str:
        booking_id = str(uuid.uuid4())
        passenger_objects = []

        for passenger in passengers:
            seat = self.available_seats.pop()
            passenger_objects.append(Passenger(
                name=passenger['name'],
                age=passenger['age'],
                seat_number=seat,
                passport_number=passenger['passport_number']
            ))

        booking = Booking(
            booking_id=booking_id,
            travel_date=datetime.strptime(travel_date, "%Y-%m-%d"),
            origin=origin,
            destination=destination,
            passengers=passenger_objects,
            status="CONFIRMED"
        )

        self.bookings[booking_id] = booking
        return booking_id

    def get_booking(self, booking_id: str) -> Booking:
        return self.bookings.get(booking_id)

    def cancel_booking(self, booking_id: str) -> bool:
        if booking_id in self.bookings:
            booking = self.bookings[booking_id]
            for passenger in booking.passengers:
                self.available_seats.add(passenger.seat_number)
            booking.status = "CANCELLED"
            return True
        return False

