import os
import shutil
import subprocess
import hashlib
from pathlib import Path

class BuildSystem:
    def __init__(self, source_dir, build_dir):
        self.source_dir = Path(source_dir)
        self.build_dir = Path(build_dir)
        self.artifacts = {}

    def prepare_build(self):
        if self.build_dir.exists():
            shutil.rmtree(self.build_dir)
        self.build_dir.mkdir(parents=True)

    def build_artifact(self, source_file):
        source_path = self.source_dir / source_file
        output_path = self.build_dir / source_file.replace('.py', '.out')

        with open(source_path, 'rb') as f:
            file_hash = hashlib.md5(f.read()).hexdigest()

        if source_file in self.artifacts and self.artifacts[source_file] == file_hash:
            return

        subprocess.run(['python', str(source_path)], 
                      stdout=open(output_path, 'w'),
                      check=True)

        self.artifacts[source_file] = file_hash

    def build_all(self):
        self.prepare_build()
        for file in self.source_dir.glob('*.py'):
            self.build_artifact(file.name)

    def clean(self):
        if self.build_dir.exists():
            shutil.rmtree(self.build_dir)
        self.artifacts.clear()
