import requests

app = Flask(__name__)

class StoreLocator:
    def __init__(self):
        self.api_key = "YOUR_GEOCODING_API_KEY"
        self.stores = [
            {"name": "Store 1", "lat": 40.7128, "lng": -74.0060},
            {"name": "Store 2", "lat": 40.7589, "lng": -73.9851},
            {"name": "Store 3", "lat": 40.7829, "lng": -73.9654}
        ]

    def find_nearest_stores(self, address, limit=5):
        geocode_url = f"https://maps.googleapis.com/maps/api/geocode/json?address={address}&key={self.api_key}"
        response = requests.get(geocode_url)
        location = response.json()['results'][0]['geometry']['location']

        stores_with_distance = []
        for store in self.stores:
            distance = self.calculate_distance(
                location['lat'], 
                location['lng'],
                store['lat'],
                store['lng']
            )
            stores_with_distance.append({**store, 'distance': distance})

        return sorted(stores_with_distance, key=lambda x: x['distance'])[:limit]

    def calculate_distance(self, lat1, lng1, lat2, lng2):
        from math import radians, sin, cos, sqrt, atan2

        R = 6371
        dlat = radians(lat2 - lat1)
        dlng = radians(lng2 - lng1)

        a = sin(dlat/2)**2 + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlng/2)**2
        c = 2 * atan2(sqrt(a), sqrt(1-a))
        return R * c

