        self.logger.info(f"Collected log from {source}: {message}")

    def analyze_logs(self, source):
        if source not in self.logs:
            return {'error_count': 0, 'warning_count': 0, 'info_count': 0}

        analysis = {
            'error_count': sum(1 for log in self.logs[source] if log['level'] == 'ERROR'),
