@dataclass
class Expense:
    amount: Decimal
    date: datetime
    category: str
    notes: str
    id: int = None

class ExpenseTracker:
    def __init__(self):
        self.expenses: List[Expense] = []
        self.next_id = 1

    def add_expense(self, amount: Decimal, category: str, notes: str, 
                   date: datetime = None) -> Expense:
        if date is None:
            date = datetime.now()

        expense = Expense(
            amount=amount,
            date=date,
            category=category,
            notes=notes,
            id=self.next_id
        )
        self.expenses.append(expense)
        self.next_id += 1
        return expense

    def get_expense(self, expense_id: int) -> Expense:
        for expense in self.expenses:
            if expense.id == expense_id:
                return expense
        return None

    def get_expenses_by_category(self, category: str) -> List[Expense]:
        return [e for e in self.expenses if e.category == category]

    def get_total_by_category(self) -> Dict[str, Decimal]:
        totals = {}
        for expense in self.expenses:
            if expense.category not in totals:
                totals[expense.category] = Decimal('0')
            totals[expense.category] += expense.amount
        return totals

    def delete_expense(self, expense_id: int) -> bool:
        for i, expense in enumerate(self.expenses):
            if expense.id == expense_id:
                del self.expenses[i]
                return True
        return False

    def export_json(self) -> str:
        expenses_dict = []
        for e in self.expenses:
            expenses_dict.append({
                'id': e.id,
                'amount': str(e.amount),
                'date': e.date.isoformat(),
                'category': e.category,
                'notes': e.notes
            })
        return json.dumps(expenses_dict, indent=2)

def main():
    tracker = ExpenseTracker()

    # Example usage
    tracker.add_expense(
        amount=Decimal('45.50'),
        category='Food',
        notes='Lunch at restaurant'
    )

    tracker.add_expense(
        amount=Decimal('120.00'),
        category='Transportation',
        notes='Monthly bus pass'
    )

    tracker.add_expense(
        amount=Decimal('25.99'),
        category='Food', 
        notes='Groceries'
    )

    # Print totals by category
    print("Expenses by category:")
    for category, total in tracker.get_total_by_category().items():
        print(f"{category}: ${total}")

    # Export to JSON
    print("\nAll expenses:")
    print(tracker.export_json())

if __name__ == '__main__':
