import os
import tarfile
import hashlib
import requests
from typing import Dict, List
import subprocess
import yaml

class PackageManager:
    def __init__(self, config_path: str = "/etc/pkgmgr/config.yml"):
        with open(config_path) as f:
            self.config = yaml.safe_load(f)
        self.cache_dir = self.config['cache_dir']
        self.repos = self.config['repositories']

    def install_package(self, package_name: str) -> bool:
        package = self._find_package(package_name)
        if not package:
            raise ValueError(f"Package {package_name} not found")

        pkg_path = self._download_package(package)

        if package['format'] == 'deb':
            return self._install_deb(pkg_path)
        elif package['format'] == 'rpm':
            return self._install_rpm(pkg_path)
        else:
            raise ValueError(f"Unsupported package format: {package['format']}")

    def _find_package(self, package_name: str) -> Dict:
        for repo in self.repos:
            response = requests.get(f"{repo['url']}/packages/{package_name}")
            if response.status_code == 200:
                return response.json()
        return None

    def _download_package(self, package: Dict) -> str:
        response = requests.get(package['download_url'], stream=True)
        pkg_path = os.path.join(self.cache_dir, package['filename'])

        with open(pkg_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        if self._verify_checksum(pkg_path, package['checksum']):
            return pkg_path
        else:
            raise ValueError("Package checksum verification failed")

    def _verify_checksum(self, file_path: str, expected: str) -> bool:
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest() == expected

    def _install_deb(self, pkg_path: str) -> bool:
        result = subprocess.run(['dpkg', '-i', pkg_path], capture_output=True)
        return result.returncode == 0

    def _install_rpm(self, pkg_path: str) -> bool:
        result = subprocess.run(['rpm', '-i', pkg_path], capture_output=True)
        return result.returncode == 0

    def remove_package(self, package_name: str) -> bool:
        package = self._find_package(package_name)
        if package['format'] == 'deb':
            result = subprocess.run(['dpkg', '-r', package_name], capture_output=True)
        elif package['format'] == 'rpm':
            result = subprocess.run(['rpm', '-e', package_name], capture_output=True)
        return result.returncode == 0

    def list_installed(self) -> List[str]:
        installed = []
        dpkg = subprocess.run(['dpkg', '-l'], capture_output=True, text=True)
        rpm = subprocess.run(['rpm', '-qa'], capture_output=True, text=True)

        if dpkg.returncode == 0:
            installed.extend(dpkg.stdout.splitlines())
        if rpm.returncode == 0:
            installed.extend(rpm.stdout.splitlines())

        return installed
