import os
import re
from pathlib import Path

def bulk_rename(directory, pattern, replacement):
    path = Path(directory)
    if not path.exists() or not path.is_dir():
        raise ValueError("Invalid directory path")

    renamed_files = []
    for file in path.iterdir():
        if file.is_file():
            new_name = re.sub(pattern, replacement, file.name)
            if new_name != file.name:
                new_path = file.parent / new_name
                file.rename(new_path)
                renamed_files.append((file.name, new_name))

    return renamed_files

def validate_pattern(pattern):
    try:
        re.compile(pattern)
        return True
    except re.error:
        return False

def main():
    directory = input("Enter directory path: ")
    pattern = input("Enter search pattern: ")
    replacement = input("Enter replacement text: ")

    if not validate_pattern(pattern):
        print("Invalid regex pattern")
        return

    try:
        renamed = bulk_rename(directory, pattern, replacement)
        for old_name, new_name in renamed:
            print(f"Renamed: {old_name} -> {new_name}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
