import os
import shutil
import hashlib
import json
from pathlib import Path

class BuildSystem:
    def __init__(self, source_dir, output_dir):
        self.source_dir = Path(source_dir)
        self.output_dir = Path(output_dir)
        self.cache_file = self.output_dir / '.buildcache'
        self.cache = self._load_cache()

    def _load_cache(self):
        if self.cache_file.exists():
            with open(self.cache_file, 'r') as f:
                return json.load(f)
        return {}

    def _save_cache(self):
        with open(self.cache_file, 'w') as f:
            json.dump(self.cache, f)

    def _calculate_hash(self, filepath):
        hasher = hashlib.sha256()
        with open(filepath, 'rb') as f:
            hasher.update(f.read())
        return hasher.hexdigest()

    def build(self):
        self.output_dir.mkdir(exist_ok=True)

        for source_file in self.source_dir.rglob('*'):
            if source_file.is_file():
                relative_path = source_file.relative_to(self.source_dir)
                output_path = self.output_dir / relative_path

                file_hash = self._calculate_hash(source_file)

                if str(relative_path) not in self.cache or self.cache[str(relative_path)] != file_hash:
                    output_path.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(source_file, output_path)
                    self.cache[str(relative_path)] = file_hash

        self._save_cache()

    def clean(self):
        if self.output_dir.exists():
            shutil.rmtree(self.output_dir)
        self.cache = {}
        if self.cache_file.exists():
            self.cache_file.unlink()

if __name__ == '__main__':
    builder = BuildSystem('src', 'build')
    builder.build()

