import os
import shutil
from pathlib import Path

def extract_ebooks(archive_path, output_dir):
    supported_formats = {'.epub', '.mobi', '.pdf', '.azw3'}

    with zipfile.ZipFile(archive_path, 'r') as archive:
        for file_info in archive.filelist:
            file_ext = Path(file_info.filename).suffix.lower()
            if file_ext in supported_formats:
                archive.extract(file_info, output_dir)

def process_archives(input_dir, output_dir):
    os.makedirs(output_dir, exist_ok=True)

    for root, _, files in os.walk(input_dir):
        for file in files:
            if file.lower().endswith(('.zip', '.rar', '.7z')):
                archive_path = os.path.join(root, file)
                try:
                    extract_ebooks(archive_path, output_dir)
                except zipfile.BadZipFile:
                    continue

if __name__ == '__main__':
    input_directory = 'archives'
    output_directory = 'extracted_ebooks'
    process_archives(input_directory, output_directory)

