from pathlib import Path

class SimulationState:
    def __init__(self):
        self.iteration = 0
        self.data = {}
        self.state_file = Path("simulation_state.json")
        self.save_interval = 300  # seconds

    def save_state(self):
        temp_file = self.state_file.with_suffix('.tmp')
        with open(temp_file, 'w') as f:
            json.dump({'iteration': self.iteration, 'data': self.data}, f)
        os.chmod(temp_file, 0o600)
        temp_file.replace(self.state_file)

    def load_state(self):
        if self.state_file.exists():
            with open(self.state_file, 'r') as f:
                state = json.load(f)
                self.iteration = state['iteration']
                self.data = state['data']

    def run_simulation(self):
        last_save = time.time()
        try:
            while self.iteration < 1000000:
                self.data[self.iteration] = self.compute_step()
                self.iteration += 1

                if time.time() - last_save >= self.save_interval:
                    self.save_state()
                    last_save = time.time()
        finally:
            self.save_state()

    def compute_step(self):
        time.sleep(0.1)  # Simulate computation
        return self.iteration * 2

if __name__ == "__main__":
    sim = SimulationState()
    sim.load_state()
    sim.run_simulation()

