import requests
from bs4 import BeautifulSoup
import os
import json
from urllib.parse import urljoin

class WebScraper:
    def __init__(self, base_url, output_dir):
        self.base_url = base_url
        self.output_dir = output_dir
        self.session = requests.Session()
        os.makedirs(output_dir, exist_ok=True)

    def scrape_page(self, url):
        response = self.session.get(url)
        response.raise_for_status()
        soup = BeautifulSoup(response.text, 'html.parser')
        return soup

    def save_results(self, filename, data):
        filepath = os.path.join(self.output_dir, filename)
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(data, f, indent=2)

    def run(self):
        try:
            soup = self.scrape_page(self.base_url)
            results = {
                'title': soup.title.text.strip(),
                'links': [urljoin(self.base_url, a['href']) 
                         for a in soup.find_all('a', href=True)],
                'text': soup.get_text().strip()
            }
            self.save_results('scraped_data.json', results)
        except Exception as e:
            self.save_results('error_log.json', {'error': str(e)})

if __name__ == '__main__':
    scraper = WebScraper('https://example.com', 'scraped_data')
    scraper.run()

