class CodeCoverage:
    def __init__(self):
        self.covered_lines = set()
        self.total_lines = set()

    def instrument_code(self, source_code):
        instrumented = []
        for line_num, line in enumerate(source_code.split('\n'), 1):
            if line.strip() and not line.strip().startswith('#'):
                self.total_lines.add(line_num)
                instrumented.append(f"self.covered_lines.add({line_num})")
                instrumented.append(line)
            else:
                instrumented.append(line)
        return '\n'.join(instrumented)

    def save_results(self, output_file):
        coverage = len(self.covered_lines) / len(self.total_lines) * 100 if self.total_lines else 0
        with open(output_file, 'w') as f:
            f.write(f"Coverage: {coverage:.2f}%\n")
            f.write(f"Covered lines: {sorted(self.covered_lines)}\n")
            f.write(f"Total lines: {sorted(self.total_lines)}\n")

