import os
import subprocess
import shutil
from pathlib import Path
import requests
import logging

class BuildSystem:
    def __init__(self, source_dir, build_dir, artifact_dir):
        self.source_dir = Path(source_dir)
        self.build_dir = Path(build_dir)
        self.artifact_dir = Path(artifact_dir)
        self.logger = logging.getLogger('BuildSystem')

    def fetch_source(self, repo_url):
        if self.source_dir.exists():
            shutil.rmtree(self.source_dir)
        subprocess.run(['git', 'clone', repo_url, str(self.source_dir)], check=True)

    def run_tests(self):
        os.chdir(self.source_dir)
        result = subprocess.run(['python', '-m', 'pytest'], capture_output=True, text=True)
        if result.returncode != 0:
            raise Exception(f"Tests failed:\n{result.stdout}\n{result.stderr}")

    def build_artifacts(self):
        self.build_dir.mkdir(exist_ok=True)
        os.chdir(self.source_dir)
        subprocess.run(['python', 'setup.py', 'build'], check=True)

    def publish_artifacts(self, artifact_repo_url):
        self.artifact_dir.mkdir(exist_ok=True)
        for artifact in self.build_dir.glob('**/*'):
            if artifact.is_file():
                dest = self.artifact_dir / artifact.relative_to(self.build_dir)
                dest.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(artifact, dest)

        headers = {'Content-Type': 'application/zip'}
        with open(self.artifact_dir / 'artifact.zip', 'rb') as f:
            response = requests.post(artifact_repo_url, data=f, headers=headers)
            response.raise_for_status()

    def run_pipeline(self, repo_url, artifact_repo_url):
        try:
            self.fetch_source(repo_url)
            self.run_tests()
            self.build_artifacts()
            self.publish_artifacts(artifact_repo_url)
            self.logger.info("Build pipeline completed successfully")
        except Exception as e:
            self.logger.error(f"Build pipeline failed: {str(e)}")
            raise

if __name__ == '__main__':
    build_system = BuildSystem(
        source_dir='./source',
        build_dir='./build',
        artifact_dir='./artifacts'
    )
    build_system.run_pipeline(
        repo_url='https://github.com/user/project.git',
        artifact_repo_url='https://artifacts.example.com/upload'
    )

