class BackupUtility:
    def __init__(self, source_path, backup_dir):
        self.source_path = os.path.abspath(source_path)
        self.backup_dir = os.path.abspath(backup_dir)

    def create_backup(self):
        timestamp = datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
        backup_name = f'backup_{timestamp}.zip'
        backup_path = os.path.join(self.backup_dir, backup_name)

        with zipfile.ZipFile(backup_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
            for root, dirs, files in os.walk(self.source_path):
                for file in files:
                    file_path = os.path.join(root, file)
                    arc_path = os.path.relpath(file_path, self.source_path)
                    zipf.write(file_path, arc_path)

        return backup_path

    def extract_backup(self, backup_path, extract_path):
        with zipfile.ZipFile(backup_path, 'r') as zipf:
            zipf.extractall(extract_path)

    def list_backups(self):
        return [f for f in os.listdir(self.backup_dir) if f.startswith('backup_') and f.endswith('.zip')]

    def delete_backup(self, backup_name):
        backup_path = os.path.join(self.backup_dir, backup_name)
