        self.extract_path = self.archive_path.parent / self.archive_path.stem

    def extract(self):
        if not self.archive_path.exists():
            raise FileNotFoundError(f"Archive not found: {self.archive_path}")

        if zipfile.is_zipfile(self.archive_path):
            return self._extract_zip()
        elif tarfile.is_tarfile(self.archive_path):
            return self._extract_tar()
        elif self.archive_path.suffix == '.gz':
            return self._extract_gzip()
        elif self.archive_path.suffix == '.bz2':
            return self._extract_bzip2()
        else:
            raise ValueError(f"Unsupported archive format: {self.archive_path.suffix}")

    def _extract_zip(self):
        with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
            zip_ref.extractall(self.extract_path)
