import subprocess
import os
from pathlib import Path
from typing import List, Optional

class ArchiveHandler:
    def __init__(self, seven_zip_path: str = "7z"):
        self.seven_zip_path = seven_zip_path

    def extract(self, archive_path: str, output_dir: Optional[str] = None) -> bool:
        if not os.path.exists(archive_path):
            raise FileNotFoundError(f"Archive not found: {archive_path}")

        if output_dir is None:
            output_dir = str(Path(archive_path).parent)

        try:
            cmd = [self.seven_zip_path, "x", archive_path, f"-o{output_dir}", "-y"]
            result = subprocess.run(cmd, capture_output=True, text=True)
            return result.returncode == 0
        except subprocess.SubprocessError:
            return False

    def list_contents(self, archive_path: str) -> List[str]:
        if not os.path.exists(archive_path):
            raise FileNotFoundError(f"Archive not found: {archive_path}")

        try:
            cmd = [self.seven_zip_path, "l", archive_path]
            result = subprocess.run(cmd, capture_output=True, text=True)

            if result.returncode != 0:
                return []

            lines = result.stdout.split("\n")
            contents = []
            for line in lines:
                if line.strip() and not line.startswith("--"):
                    contents.append(line.strip())
            return contents
        except subprocess.SubprocessError:
            return []

    def create_archive(self, archive_path: str, files: List[str]) -> bool:
        try:
            cmd = [self.seven_zip_path, "a", archive_path] + files
            result = subprocess.run(cmd, capture_output=True, text=True)
            return result.returncode == 0
        except subprocess.SubprocessError:
            return False

    def test_archive(self, archive_path: str) -> bool:
        if not os.path.exists(archive_path):
            return False

        try:
            cmd = [self.seven_zip_path, "t", archive_path]
            result = subprocess.run(cmd, capture_output=True, text=True)
            return result.returncode == 0
        except subprocess.SubprocessError:
            return False
