        self.recent_sales.append({
            'property': property,
            'price': sale_price,
            'date': sale_date
        })

    def estimate_value(self, target_property):
        similar_properties = []

        for sale in self.recent_sales:
            comp = sale['property']
            score = self._calculate_similarity(target_property, comp)
            if score > 0.8:
                similar_properties.append({
                    'property': comp,
                    'price': sale['price'],
                    'similarity': score
                })

        if not similar_properties:
            return None

        weighted_sum = sum(p['price'] * p['similarity'] for p in similar_properties)
        total_weight = sum(p['similarity'] for p in similar_properties)

        return weighted_sum / total_weight

    def _calculate_similarity(self, prop1, prop2):
        sqft_diff = abs(prop1.sqft - prop2.sqft) / max(prop1.sqft, prop2.sqft)
        bed_diff = abs(prop1.beds - prop2.beds) / max(prop1.beds, prop2.beds)
        bath_diff = abs(prop1.baths - prop2.baths) / max(prop1.baths, prop2.baths)
        lot_diff = abs(prop1.lot_size - prop2.lot_size) / max(prop1.lot_size, prop2.lot_size)
        year_diff = abs(prop1.year_built - prop2.year_built) / 100

        weights = {
            'sqft': 0.3,
            'beds': 0.2, 
            'baths': 0.2,
            'lot': 0.2,
            'year': 0.1
        }

        similarity = 1 - (
            weights['sqft'] * sqft_diff +
            weights['beds'] * bed_diff +
            weights['baths'] * bath_diff + 
            weights['lot'] * lot_diff +
            weights['year'] * year_diff
        )

        return max(0, similarity)
