from pathlib import Path
import hashlib
import json
import shutil
from datetime import datetime

class VersionControl:
    def __init__(self, repo_path):
        self.repo_path = Path(repo_path)
        self.objects_path = self.repo_path / '.vc' / 'objects'
        self.objects_path.mkdir(parents=True, exist_ok=True)
        self.index = {}
        self._load_index()

    def _load_index(self):
        index_path = self.repo_path / '.vc' / 'index.json'
        if index_path.exists():
            with open(index_path, 'r') as f:
                self.index = json.load(f)

    def _save_index(self):
        index_path = self.repo_path / '.vc' / 'index.json'
        with open(index_path, 'w') as f:
            json.dump(self.index, f)

    def hash_file(self, file_path):
        with open(file_path, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()

    def add(self, file_path):
        abs_path = Path(file_path).resolve()
        rel_path = abs_path.relative_to(self.repo_path)
        file_hash = self.hash_file(abs_path)

        object_path = self.objects_path / file_hash
        if not object_path.exists():
            shutil.copy2(abs_path, object_path)

        self.index[str(rel_path)] = {
            'hash': file_hash,
            'timestamp': datetime.now().isoformat()
        }
        self._save_index()

    def commit(self, message):
        commit_data = {
            'message': message,
            'timestamp': datetime.now().isoformat(),
            'files': self.index.copy()
        }
        commit_hash = hashlib.sha256(json.dumps(commit_data).encode()).hexdigest()

        with open(self.objects_path / commit_hash, 'w') as f:
            json.dump(commit_data, f)

        return commit_hash

    def checkout(self, commit_hash):
        with open(self.objects_path / commit_hash, 'r') as f:
            commit_data = json.load(f)

        for file_path, file_info in commit_data['files'].items():
            target_path = self.repo_path / file_path
            target_path.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(self.objects_path / file_info['hash'], target_path)

        self.index = commit_data['files']
        self._save_index()

