class OpenAPIGenerator:
    def __init__(self, app: Flask):
        self.app = app
        self.spec = {
            "openapi": "3.0.0",
            "info": {"title": "API Documentation", "version": "1.0.0"},
            "paths": {}
        }

    def parse_docstring(self, docstring: str) -> Dict:
        if not docstring:
            return {}

        sections = {
            "description": "",
            "parameters": [],
            "responses": {}
        }

        lines = docstring.split("\n")
        current_section = "description"

        for line in lines:
            line = line.strip()
            if line.startswith(":param"):
                param_match = re.match(r":param (\w+): (.+)", line)
                if param_match:
                    sections["parameters"].append({
                        "name": param_match.group(1),
                        "description": param_match.group(2),
                        "in": "query",
                        "schema": {"type": "string"}
                    })
            elif line.startswith(":return"):
                sections["responses"]["200"] = {
                    "description": line.replace(":return:", "").strip(),
                    "content": {"application/json": {"schema": {"type": "object"}}}
                }
            else:
                sections["description"] += line + "\n"

        return sections

    def generate_spec(self) -> Dict:
        for rule in self.app.url_map.iter_rules():
            if rule.endpoint != 'static':
                view_func = self.app.view_functions[rule.endpoint]
                docstring = inspect.getdoc(view_func)
                doc_info = self.parse_docstring(docstring)

                methods = rule.methods - {'OPTIONS', 'HEAD'}
                for method in methods:
                    path_spec = {
                        "summary": view_func.__name__,
                        "description": doc_info.get("description", ""),
                        "parameters": doc_info.get("parameters", []),
                        "responses": doc_info.get("responses", {
                            "200": {
                                "description": "Successful response",
                                "content": {"application/json": {"schema": {"type": "object"}}}
                            }
                        })
                    }

                    path = str(rule)
                    if path not in self.spec["paths"]:
                        self.spec["paths"][path] = {}
                    self.spec["paths"][path][method.lower()] = path_spec

        return self.spec

    def save_yaml(self, filename: str):
        with open(filename, 'w') as f:
            yaml.dump(self.spec, f, sort_keys=False)

def generate_openapi_docs(app: Flask, output_file: str = "openapi.yaml"):
    generator = OpenAPIGenerator(app)
    generator.generate_spec()
    generator.save_yaml(output_file)

