from collections import defaultdict
import os

def get_compression_ratio(content):
    compressed = gzip.compress(content)
    return len(compressed) / len(content)

def analyze_urls(urls):
    extension_stats = defaultdict(list)

    for url in urls:
        try:
            response = requests.get(url, timeout=10)
            content = response.content
            ratio = get_compression_ratio(content)

            ext = os.path.splitext(urlparse(url).path)[1].lower() or '.html'
            extension_stats[ext].append(ratio)

        except Exception as e:
            print(f"Error processing {url}: {str(e)}")
            continue

    results = {}
    for ext, ratios in extension_stats.items():
        results[ext] = {
            'avg_ratio': sum(ratios) / len(ratios),
            'sample_size': len(ratios)
        }

    return results

if __name__ == '__main__':
    test_urls = [
        'https://example.com/file.txt',
        'https://example.com/image.jpg',
        'https://example.com/doc.pdf'
    ]

    stats = analyze_urls(test_urls)
    for ext, data in stats.items():
        print(f"{ext}: Avg compression ratio {data['avg_ratio']:.2f} ({data['sample_size']} files)")
