    def __init__(self):
        self.conn = sqlite3.connect('books.db', check_same_thread=False)
        self.cursor = self.conn.cursor()
        self.setup_database()

    def setup_database(self):
        self.cursor.execute('''
            CREATE TABLE IF NOT EXISTS reviews (
                id INTEGER PRIMARY KEY,
                user_id INTEGER,
                book_id INTEGER,
                rating INTEGER,
                review TEXT,
                date_added TIMESTAMP,
                UNIQUE(user_id, book_id)
            )
        ''')
        self.cursor.execute('''
            CREATE TABLE IF NOT EXISTS reading_lists (
                id INTEGER PRIMARY KEY,
                user_id INTEGER,
                book_id INTEGER,
                status TEXT,
                date_added TIMESTAMP,
                UNIQUE(user_id, book_id)
            )
        ''')
        self.conn.commit()

    def add_review(self, user_id, book_id, rating, review):
        try:
            self.cursor.execute('''
                INSERT INTO reviews (user_id, book_id, rating, review, date_added)
                VALUES (?, ?, ?, ?, ?)
            ''', (user_id, book_id, rating, review, datetime.now()))
            self.conn.commit()
            return True
        except sqlite3.IntegrityError:
            return False

    def add_to_reading_list(self, user_id, book_id, status):
        try:
            self.cursor.execute('''
                INSERT INTO reading_lists (user_id, book_id, status, date_added)
                VALUES (?, ?, ?, ?)
            ''', (user_id, book_id, status, datetime.now()))
            self.conn.commit()
            return True
        except sqlite3.IntegrityError:
            return False

    def get_book_reviews(self, book_id):
        self.cursor.execute('SELECT * FROM reviews WHERE book_id = ?', (book_id,))
