from dataclasses import dataclass
from datetime import datetime
from typing import List, Dict
import json

@dataclass
class Supply:
    name: str
    quantity: int
    cost: float
    purchased: bool = False

@dataclass
class Task:
    name: str
    description: str
    duration: int
    completed: bool = False
    supplies: List[Supply] = None

class Project:
    def __init__(self, name: str, description: str):
        self.name = name
        self.description = description
        self.tasks: List[Task] = []
        self.supplies: Dict[str, Supply] = {}
        self.created_at = datetime.now()
        self.completed = False

    def add_task(self, task: Task):
        self.tasks.append(task)

    def add_supply(self, supply: Supply):
        self.supplies[supply.name] = supply

    def mark_task_complete(self, task_name: str):
        for task in self.tasks:
            if task.name == task_name:
                task.completed = True

    def calculate_total_cost(self):
        return sum(supply.cost * supply.quantity for supply in self.supplies.values())

    def get_pending_tasks(self):
        return [task for task in self.tasks if not task.completed]

    def export_project(self):
        return {
            'name': self.name,
            'description': self.description,
            'tasks': len(self.tasks),
            'supplies': len(self.supplies),
            'total_cost': self.calculate_total_cost(),
            'completion': sum(t.completed for t in self.tasks) / len(self.tasks)
        }

