import ast
import sys
import os
from dataclasses import dataclass
from typing import List, Dict

@dataclass
class ComplexityIssue:
    file: str
    method: str
    line_number: int
    complexity: int
    lines: int

class ComplexityAnalyzer:
    def __init__(self, max_complexity=10, max_lines=50):
        self.max_complexity = max_complexity
        self.max_lines = max_lines
        self.issues: List[ComplexityIssue] = []

    def analyze_file(self, filename: str) -> None:
        with open(filename, 'r') as f:
            tree = ast.parse(f.read(), filename)

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                complexity = self._calculate_complexity(node)
                lines = len(node.body)

                if complexity > self.max_complexity or lines > self.max_lines:
                    self.issues.append(ComplexityIssue(
                        file=filename,
                        method=node.name,
                        line_number=node.lineno,
                        complexity=complexity,
                        lines=lines
                    ))

    def _calculate_complexity(self, node: ast.AST) -> int:
        complexity = 1
        for child in ast.walk(node):
            if isinstance(child, (ast.If, ast.While, ast.For, ast.ExceptHandler)):
                complexity += 1
            elif isinstance(child, ast.BoolOp):
                complexity += len(child.values) - 1
        return complexity

    def generate_report(self) -> str:
        report = "Code Complexity Report\n" + "="*20 + "\n\n"

        for issue in sorted(self.issues, key=lambda x: x.complexity, reverse=True):
            report += f"File: {issue.file}\n"
            report += f"Method: {issue.method} (line {issue.line_number})\n"
            report += f"Cyclomatic Complexity: {issue.complexity}\n"
            report += f"Lines of Code: {issue.lines}\n"
            report += "-"*20 + "\n"

        return report

def main():
    if len(sys.argv) < 2:
        print("Usage: python complexity.py <directory> [max_complexity] [max_lines]")
        sys.exit(1)

    directory = sys.argv[1]
    max_complexity = int(sys.argv[2]) if len(sys.argv) > 2 else 10
    max_lines = int(sys.argv[3]) if len(sys.argv) > 3 else 50

    analyzer = ComplexityAnalyzer(max_complexity, max_lines)

    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                filepath = os.path.join(root, file)
                try:
                    analyzer.analyze_file(filepath)
                except Exception as e:
                    print(f"Error analyzing {filepath}: {e}")

    report = analyzer.generate_report()
    print(report)

    with open('complexity_report.txt', 'w') as f:
        f.write(report)

if __name__ == '__main__':
    main()
