        extract_base.mkdir()

    for item in source_path.glob("*"):
        if item.is_file():
            try:
                extract_dir = extract_base / item.stem
                extract_dir.mkdir(exist_ok=True)
                extract_archive(str(item), str(extract_dir))
            except Exception as e:
                print(f"Error extracting {item}: {e}")

