import zipfile
import pandas as pd
import os
from datetime import datetime
import re
from typing import Dict, List

class LogAnalyzer:
    def __init__(self, zip_path: str):
        self.zip_path = zip_path
        self.data_frames = {}

    def extract_logs(self) -> None:
        with zipfile.ZipFile(self.zip_path, 'r') as zip_ref:
            self.temp_dir = 'temp_logs'
            zip_ref.extractall(self.temp_dir)

    def parse_log_file(self, file_path: str) -> pd.DataFrame:
        data = []
        with open(file_path, 'r') as f:
            for line in f:
                match = re.match(r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+(\w+)\s+(.+)', line)
                if match:
                    timestamp, level, message = match.groups()
                    data.append({
                        'timestamp': datetime.strptime(timestamp, '%Y-%m-%d %H:%M:%S'),
                        'level': level,
                        'message': message.strip()
                    })
        return pd.DataFrame(data)

    def analyze_logs(self) -> Dict[str, any]:
        self.extract_logs()

        for root, _, files in os.walk(self.temp_dir):
            for file in files:
                if file.endswith('.log'):
                    file_path = os.path.join(root, file)
                    self.data_frames[file] = self.parse_log_file(file_path)

        results = {
            'error_count': self._count_errors(),
            'daily_activity': self._analyze_daily_activity(),
            'common_errors': self._get_common_errors()
        }

        self._cleanup()
        return results

    def _count_errors(self) -> int:
        total_errors = 0
        for df in self.data_frames.values():
            total_errors += len(df[df['level'] == 'ERROR'])
        return total_errors

    def _analyze_daily_activity(self) -> pd.DataFrame:
        combined_df = pd.concat(self.data_frames.values())
        return combined_df.groupby(combined_df['timestamp'].dt.date).size()

    def _get_common_errors(self) -> List[Dict[str, any]]:
        error_messages = []
        for df in self.data_frames.values():
            errors = df[df['level'] == 'ERROR']
            error_messages.extend(errors['message'].tolist())

        error_counts = pd.Series(error_messages).value_counts()
        return [{'message': msg, 'count': count} 
                for msg, count in error_counts.items()]

    def _cleanup(self) -> None:
        if os.path.exists(self.temp_dir):
            for root, _, files in os.walk(self.temp_dir):
                for file in files:
                    os.remove(os.path.join(root, file))
            os.rmdir(self.temp_dir)

if __name__ == "__main__":
