import heapq
from urllib.parse import urlparse
import requests
from bs4 import BeautifulSoup
from collections import defaultdict
import re

class PriorityCrawler:
    def __init__(self, start_url, keywords):
        self.start_url = start_url
        self.keywords = keywords
        self.visited = set()
        self.priority_queue = []
        self.domain = urlparse(start_url).netloc
        self.url_scores = defaultdict(int)

    def calculate_priority(self, url, content):
        score = 0

        # Domain relevance
        if self.domain in url:
            score += 10

        # Keyword matching in URL
        for keyword in self.keywords:
            if keyword.lower() in url.lower():
                score += 5

        # Keyword matching in content
        if content:
            text = content.get_text().lower()
            for keyword in self.keywords:
                score += text.count(keyword.lower()) * 2

        # URL depth penalty
        depth = url.count('/')
        score -= depth

        return score

    def crawl(self, max_pages=100):
        heapq.heappush(self.priority_queue, (-100, self.start_url))

        while self.priority_queue and len(self.visited) < max_pages:
            priority, url = heapq.heappop(self.priority_queue)

            if url in self.visited:
                continue

            try:
                response = requests.get(url, timeout=5)
                soup = BeautifulSoup(response.text, 'html.parser')
                self.visited.add(url)

                print(f"Crawling {url} (priority: {-priority})")

                for link in soup.find_all('a'):
                    next_url = link.get('href')
                    if next_url and next_url.startswith('http') and next_url not in self.visited:
                        priority = self.calculate_priority(next_url, link)
                        heapq.heappush(self.priority_queue, (-priority, next_url))

            except Exception as e:
                print(f"Error crawling {url}: {e}")

    def get_results(self):
        return sorted(
            [(url, -heapq.heappop(self.priority_queue)[0]) for url in self.visited],
            key=lambda x: x[1],
            reverse=True
        )

if __name__ == "__main__":
    start_url = "https://example.com"
    keywords = ["python", "programming", "tutorial"]

    crawler = PriorityCrawler(start_url, keywords)
    crawler.crawl(max_pages=50)

    for url, score in crawler.get_results():
        print(f"URL: {url}, Score: {score}")
