import hashlib
from pathlib import Path

class FileSynchronizer:
    def __init__(self, source_dir, target_dir, permissions=0o644):
        self.source_dir = Path(source_dir)
        self.target_dir = Path(target_dir)
        self.permissions = permissions

    def calculate_hash(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for block in iter(lambda: f.read(4096), b''):
                sha256.update(block)
        return sha256.hexdigest()

    def sync_files(self):
        for source_file in self.source_dir.rglob('*'):
            if source_file.is_file():
                relative_path = source_file.relative_to(self.source_dir)
                target_file = self.target_dir / relative_path

                target_file.parent.mkdir(parents=True, exist_ok=True)

                if not target_file.exists() or self.calculate_hash(source_file) != self.calculate_hash(target_file):
                    shutil.copy2(source_file, target_file)
                    os.chmod(target_file, self.permissions)

    def sync_directories(self):
        self.sync_files()
        os.chmod(self.target_dir, 0o755)

