class ProductRecommender:
    def __init__(self):
        self.products = {
            1: {"name": "Laptop", "category": "Electronics", "tags": ["computer", "portable", "work"]},
            2: {"name": "Smartphone", "category": "Electronics", "tags": ["mobile", "phone", "portable"]},
            3: {"name": "Headphones", "category": "Electronics", "tags": ["audio", "portable", "music"]},
            4: {"name": "Monitor", "category": "Electronics", "tags": ["computer", "display", "work"]},
        }

        self.category_index = defaultdict(list)
        self.tag_index = defaultdict(list)
        self._build_indexes()

    def _build_indexes(self):
        for pid, product in self.products.items():
            self.category_index[product['category']].append(pid)
            for tag in product['tags']:
                self.tag_index[tag].append(pid)

    def find_related(self, product_id, limit=3):
        if product_id not in self.products:
            return []

        product = self.products[product_id]
        scores = defaultdict(int)

        for pid in self.category_index[product['category']]:
            if pid != product_id:
                scores[pid] += 1

        for tag in product['tags']:
            for pid in self.tag_index[tag]:
                if pid != product_id:
                    scores[pid] += 1

        sorted_products = sorted(scores.items(), key=lambda x: x[1], reverse=True)
        return [self.products[pid] for pid, _ in sorted_products[:limit]]

