from collections import defaultdict
from typing import List, Dict, Callable
import random

class LoadBalancer:
    def __init__(self):
        self.routes: Dict[str, List[str]] = defaultdict(list)
        self.patterns: Dict[str, str] = {}
        self.health_checks: Dict[str, bool] = {}

    def add_route(self, pattern: str, backend: str):
        route_id = str(hash(pattern))
        self.patterns[route_id] = pattern
        self.routes[route_id].append(backend)
        self.health_checks[backend] = True

    def route_request(self, path: str) -> str:
        for route_id, pattern in self.patterns.items():
            if re.match(pattern, path):
                healthy_backends = [b for b in self.routes[route_id] 
                                  if self.health_checks[b]]
                if healthy_backends:
                    return random.choice(healthy_backends)
        raise ValueError("No matching route found")

    def mark_down(self, backend: str):
        self.health_checks[backend] = False

    def mark_up(self, backend: str):
        self.health_checks[backend] = True

if __name__ == "__main__":
