def untar(filename, outdir):
    with tarfile.open(filename) as tar:
        tar.extractall(path=outdir)
        for member in tar.getmembers():
            if member.isfile():
                extracted_path = os.path.join(outdir, member.name)
                os.chmod(extracted_path, 0o644)
