import os
import shutil
import subprocess
import logging
from datetime import datetime

class BuildSystem:
    def __init__(self, source_dir, build_dir, deploy_dir):
        self.source_dir = source_dir
        self.build_dir = build_dir
        self.deploy_dir = deploy_dir
        self.logger = logging.getLogger('BuildSystem')

    def prepare_build(self):
        if os.path.exists(self.build_dir):
            shutil.rmtree(self.build_dir)
        os.makedirs(self.build_dir)
        shutil.copytree(self.source_dir, self.build_dir, dirs_exist_ok=True)

    def compile(self):
        result = subprocess.run(['python', '-m', 'compileall', self.build_dir], capture_output=True)
        if result.returncode != 0:
            raise Exception(f"Compilation failed: {result.stderr.decode()}")

    def run_tests(self):
        result = subprocess.run(['pytest', self.build_dir], capture_output=True)
        if result.returncode != 0:
            raise Exception(f"Tests failed: {result.stderr.decode()}")

    def deploy(self):
        backup_dir = f"{self.deploy_dir}_backup_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
        if os.path.exists(self.deploy_dir):
            shutil.move(self.deploy_dir, backup_dir)
        shutil.copytree(self.build_dir, self.deploy_dir)

    def run_pipeline(self):
        try:
            self.prepare_build()
            self.compile()
            self.run_tests()
            self.deploy()
            self.logger.info("Deployment successful")
            return True
        except Exception as e:
            self.logger.error(f"Build failed: {str(e)}")
            return False

if __name__ == "__main__":
    builder = BuildSystem(
        source_dir="./src",
        build_dir="./build",
        deploy_dir="./deploy"
    )
    builder.run_pipeline()

