    def __init__(self, name: str, owner: str):
        self.id = str(uuid.uuid4())
        self.name = name
        self.owner = owner
        self.roster: Dict[str, Player] = {}
        self.max_players = 15

    def add_player(self, player: Player) -> bool:
        if len(self.roster) >= self.max_players:
            return False
        self.roster[player.id] = player
        return True

    def remove_player(self, player_id: str) -> bool:
        if player_id in self.roster:
            del self.roster[player_id]
            return True
        return False

    def get_roster(self) -> List[Player]:
        return list(self.roster.values())

class League:
    def __init__(self, name: str):
        self.name = name
        self.teams: Dict[str, FantasyTeam] = {}

    def add_team(self, team: FantasyTeam):
        self.teams[team.id] = team

    def get_standings(self) -> List[FantasyTeam]:
        return sorted(self.teams.values(), 
                     key=lambda t: sum(p.stats['points'] for p in t.roster.values()),
                     reverse=True)

