import os
import shutil
import datetime
import tarfile
import logging
from pathlib import Path

class SystemBackup:
    def __init__(self, backup_dir="/backups"):
        self.backup_dir = Path(backup_dir)
        self.backup_dir.mkdir(exist_ok=True)
        self.timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        self.setup_logging()

    def setup_logging(self):
        logging.basicConfig(
            filename=self.backup_dir / "backup.log",
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s'
        )

    def create_snapshot(self, source_path):
        try:
            source = Path(source_path)
            backup_path = self.backup_dir / f"{source.name}_{self.timestamp}.tar.gz"

            with tarfile.open(backup_path, "w:gz") as tar:
                tar.add(source_path, arcname=source.name)

            logging.info(f"Snapshot created: {backup_path}")
            return True
        except Exception as e:
            logging.error(f"Snapshot failed for {source_path}: {str(e)}")
            return False

    def backup_config_files(self, config_paths):
        config_backup_dir = self.backup_dir / f"configs_{self.timestamp}"
        config_backup_dir.mkdir(exist_ok=True)

        for config_path in config_paths:
            try:
                source = Path(config_path)
                if source.exists():
                    dest = config_backup_dir / source.name
                    shutil.copy2(source, dest)
                    logging.info(f"Config backed up: {config_path}")
            except Exception as e:
                logging.error(f"Config backup failed for {config_path}: {str(e)}")

    def cleanup_old_backups(self, days_to_keep=7):
        cutoff_date = datetime.datetime.now() - datetime.timedelta(days=days_to_keep)

        for backup_file in self.backup_dir.glob("*"):
            if backup_file.is_file():
                if backup_file.stat().st_mtime < cutoff_date.timestamp():
                    backup_file.unlink()
                    logging.info(f"Removed old backup: {backup_file}")

