import os
import re
import argparse
from pathlib import Path

def search_replace(pattern, replacement, files, permissions=None):
    compiled_pattern = re.compile(pattern)

    for file_path in files:
        try:
            with open(file_path, 'r') as f:
                content = f.read()

            modified = compiled_pattern.sub(replacement, content)

            if modified != content:
                with open(file_path, 'w') as f:
                    f.write(modified)

                if permissions:
                    os.chmod(file_path, permissions)
        except (IOError, OSError) as e:
            print(f"Error processing {file_path}: {e}")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('pattern', help='Regex pattern to search for')
    parser.add_argument('replacement', help='Replacement text')
    parser.add_argument('files', nargs='+', help='Files to process')
    parser.add_argument('--permissions', type=lambda x: int(x, 8),
                      help='New file permissions in octal (e.g., 0o644)')

    args = parser.parse_args()

    search_replace(args.pattern, args.replacement, args.files, args.permissions)

if __name__ == '__main__':
    main()

