@dataclass
class FormField:
    id: str
    type: str
    label: str
    required: bool
    options: Optional[List[str]] = None
    placeholder: Optional[str] = None
    rich_text: bool = False

class FormBuilder:
    def __init__(self):
        self.forms = {}

    def create_form(self, title: str, fields: List[Dict]) -> str:
        form_id = str(uuid.uuid4())
        form_fields = []

        for field in fields:
            field_id = str(uuid.uuid4())
            form_fields.append(FormField(
                id=field_id,
                type=field['type'],
                label=field['label'],
                required=field.get('required', False),
                options=field.get('options'),
                placeholder=field.get('placeholder'),
                rich_text=field.get('rich_text', False)
            ))

        self.forms[form_id] = {
            'title': title,
            'fields': form_fields
        }
        return form_id

form_builder = FormBuilder()

@app.route('/forms', methods=['POST'])
def create_form():
    data = request.get_json()
    form_id = form_builder.create_form(data['title'], data['fields'])
    return jsonify({'form_id': form_id})

@app.route('/forms/<form_id>', methods=['GET'])
def get_form(form_id):
    if form_id not in form_builder.forms:
        return jsonify({'error': 'Form not found'}), 404
    return jsonify(form_builder.forms[form_id])

@app.route('/forms/<form_id>/submit', methods=['POST'])
def submit_form(form_id):
    if form_id not in form_builder.forms:
        return jsonify({'error': 'Form not found'}), 404

    submission = request.get_json()
    # Validate submission against form fields
    form = form_builder.forms[form_id]
    for field in form['fields']:
        if field.required and field.id not in submission:
            return jsonify({'error': f'Missing required field: {field.label}'}), 400

    return jsonify({'message': 'Form submitted successfully'})

