from flask import Flask, request, jsonify
import uuid
import os
from werkzeug.utils import secure_filename

app = Flask(__name__)

UPLOAD_FOLDER = 'uploads'
ALLOWED_EXTENSIONS = {'obj', 'fbx', 'gltf', 'png', 'jpg', 'mp4'}
MODELS_DB = {}

class Model3D:
    def __init__(self, name, description, author):
        self.id = str(uuid.uuid4())
        self.name = name
        self.description = description
        self.author = author
        self.files = {
            'model': None,
            'textures': [],
            'animations': [],
            'previews': []
        }

@app.route('/models', methods=['POST'])
def upload_model():
    data = request.form
    files = request.files

    model = Model3D(
        name=data['name'],
        description=data['description'],
        author=data['author']
    )

    model_file = files.get('model')
    if model_file and allowed_file(model_file.filename):
        filename = secure_filename(model_file.filename)
        filepath = os.path.join(UPLOAD_FOLDER, model.id, filename)
        os.makedirs(os.path.dirname(filepath), exist_ok=True)
        model_file.save(filepath)
        model.files['model'] = filepath

    for texture in files.getlist('textures'):
        if allowed_file(texture.filename):
            filename = secure_filename(texture.filename)
            filepath = os.path.join(UPLOAD_FOLDER, model.id, 'textures', filename)
            os.makedirs(os.path.dirname(filepath), exist_ok=True)
            texture.save(filepath)
            model.files['textures'].append(filepath)

    MODELS_DB[model.id] = model
    return jsonify({'model_id': model.id})

@app.route('/models/<model_id>', methods=['GET'])
def get_model(model_id):
    model = MODELS_DB.get(model_id)
    if not model:
        return jsonify({'error': 'Model not found'}), 404

    return jsonify({
        'id': model.id,
        'name': model.name,
        'description': model.description,
        'author': model.author,
        'files': model.files
    })

@app.route('/models', methods=['GET'])
def list_models():
    models = [{
        'id': model.id,
        'name': model.name,
        'description': model.description,
        'author': model.author
    } for model in MODELS_DB.values()]
    return jsonify(models)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

