    def __init__(self):
        self.users: Dict[int, dict] = {}
        self.dishes: Dict[int, Dish] = {}
        self.orders: Dict[int, Order] = {}
        self.addresses: Dict[int, List[Address]] = {}

    def add_dish_rating(self, dish_id: int, rating: int) -> None:
        dish = self.dishes[dish_id]
        dish.rating = ((dish.rating * dish.num_ratings) + rating) / (dish.num_ratings + 1)
        dish.num_ratings += 1

    def save_address(self, user_id: int, address: Address) -> None:
        if user_id not in self.addresses:
            self.addresses[user_id] = []
        self.addresses[user_id].append(address)

    def create_order(self, user_id: int, dishes: List[int], address: Address, 
                    special_instructions: str = "") -> Order:
        order_id = len(self.orders) + 1
        order_dishes = [self.dishes[d] for d in dishes]
        order = Order(
            id=order_id,
            user_id=user_id,
            dishes=order_dishes,
            address=address,
            special_instructions=special_instructions,
            created_at=datetime.now()
        )
        self.orders[order_id] = order
        return order

    def get_user_orders(self, user_id: int) -> List[Order]:
        return [order for order in self.orders.values() if order.user_id == user_id]

    def get_user_addresses(self, user_id: int) -> List[Address]:
        return self.addresses.get(user_id, [])
