import os
import csv
from datetime import datetime

def get_package_versions():
    versions = {}
    try:
        with open('/var/log/dpkg.log') as f:
            for line in f:
                parts = line.strip().split()
                if len(parts) >= 6 and 'install' in line:
                    timestamp = datetime.strptime(f"{parts[0]} {parts[1]}", "%Y-%m-%d %H:%M:%S")
                    package = parts[3]
                    version = parts[5]
                    versions[package] = {
                        'version': version,
                        'installed_at': timestamp
                    }
    except FileNotFoundError:
        pass
    return versions

def write_versions_report(versions):
    with open('package_versions.csv', 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['Package', 'Version', 'Install Date'])
        for package, info in versions.items():
            writer.writerow([package, info['version'], info['installed_at']])

if __name__ == '__main__':
    versions = get_package_versions()
    write_versions_report(versions)
    print(f"Found {len(versions)} installed packages")

