                str(self.deps_dir / dep['name'])
            ], check=True)

    def build(self):
        subprocess.run([
            "cmake", "-B", str(self.build_dir),
            "-S", "."
        ], check=True)
        subprocess.run([
            "cmake", "--build", str(self.build_dir)
        ], check=True)

    def run_tests(self):
        subprocess.run([
            "ctest", "--test-dir", str(self.build_dir)
        ], check=True)

