        api_endpoint = 'https://api.twitter.com/2/tweets'
        headers = {'Authorization': f'Bearer {self.platforms["twitter"]["api_key"]}'}
        data = {'text': content}
        response = requests.post(api_endpoint, headers=headers, json=data)
        return {'success': response.status_code == 201}

    def _post_to_facebook(self, content):
        api_endpoint = f'https://graph.facebook.com/me/feed'
        params = {
            'access_token': self.platforms['facebook']['access_token'],
            'message': content
        }
        response = requests.post(api_endpoint, params=params)
        return {'success': response.status_code == 200}

