START_URL = 'http://example.com'

def get_links(url):
    resp = requests.get(url)
    soup = BeautifulSoup(resp.text, 'html.parser')
    links = soup.find_all('a')
    return [link['href'] for link in links]

def crawl(url, visited=None):
    if visited is None:
        visited = set()

    if url in visited:
        return

    visited.add(url)
    try:
        links = get_links(url)
        for link in links:
            if link.startswith('http'):
                crawl(link, visited)
    except:
