import os
import tarfile
import hashlib
import json
from datetime import datetime

class DiffBackup:
    def __init__(self, source_dir, backup_dir):
        self.source_dir = os.path.abspath(source_dir)
        self.backup_dir = os.path.abspath(backup_dir)
        self.manifest_path = os.path.join(backup_dir, 'manifest.json')
        self.previous_hashes = self._load_manifest()

    def _load_manifest(self):
        if os.path.exists(self.manifest_path):
            with open(self.manifest_path, 'r') as f:
                return json.load(f)
        return {}

    def _save_manifest(self, hashes):
        with open(self.manifest_path, 'w') as f:
            json.dump(hashes, f)

    def _calculate_file_hash(self, filepath):
        hasher = hashlib.sha256()
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                hasher.update(chunk)
        return hasher.hexdigest()

    def create_backup(self):
        current_hashes = {}
        files_to_backup = []

        for root, _, files in os.walk(self.source_dir):
            for filename in files:
                filepath = os.path.join(root, filename)
                rel_path = os.path.relpath(filepath, self.source_dir)
                current_hash = self._calculate_file_hash(filepath)
                current_hashes[rel_path] = current_hash

                if rel_path not in self.previous_hashes or current_hash != self.previous_hashes[rel_path]:
                    files_to_backup.append((filepath, rel_path))

        if files_to_backup:
            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
            backup_name = f'backup_{timestamp}.tar.gz'
            backup_path = os.path.join(self.backup_dir, backup_name)

            with tarfile.open(backup_path, 'w:gz') as tar:
                for filepath, rel_path in files_to_backup:
                    tar.add(filepath, arcname=rel_path)

            self._save_manifest(current_hashes)
            return backup_path
        return None

    def restore(self, backup_path, restore_dir):
        os.makedirs(restore_dir, exist_ok=True)
        with tarfile.open(backup_path, 'r:gz') as tar:
            tar.extractall(restore_dir)

if __name__ == '__main__':
    backup_tool = DiffBackup('/path/to/source', '/path/to/backups')
    backup_file = backup_tool.create_backup()
    if backup_file:
        print(f'Backup created: {backup_file}')
    else:
        print('No changes to backup')

