class TestEnvironment:
    def __init__(self, image_path, work_dir=None):
        self.image_path = Path(image_path)
        self.work_dir = work_dir or tempfile.mkdtemp()
        self.client = docker.from_client()
        self.container = None

    def setup(self):
        container_config = {
            'image': 'ubuntu:latest',
            'volumes': {
                self.work_dir: {'bind': '/workspace', 'mode': 'rw'},
                str(self.image_path): {'bind': '/image.raw', 'mode': 'ro'}
            },
            'command': 'tail -f /dev/null',
            'detach': True,
            'privileged': True
        }

        self.container = self.client.containers.run(**container_config)
        self._mount_image()

    def _mount_image(self):
        mount_cmd = [
            'mount',
            '-o', 'loop,offset=1048576',
            '/image.raw',
            '/mnt'
        ]
        self.exec_command(mount_cmd)

    def exec_command(self, command):
        result = self.container.exec_run(
            command,
            privileged=True,
            user='root'
        )
        return result.output.decode('utf-8')

    def run_test(self, test_script):
        self.container.put_archive('/workspace', test_script)
        return self.exec_command(['python', '/workspace/test.py'])

    def teardown(self):
        if self.container:
            self.exec_command(['umount', '/mnt'])
            self.container.stop()
            self.container.remove()
        os.rmdir(self.work_dir)

class TestRunner:
    def __init__(self, test_suite, image_path):
        self.test_suite = test_suite
        self.image_path = image_path
        self.results = []

    def run(self):
        env = TestEnvironment(self.image_path)
        try:
            env.setup()
            for test in self.test_suite:
                result = env.run_test(test)
                self.results.append({
                    'test': test,
                    'output': result,
                    'status': 'pass' if result.returncode == 0 else 'fail'
                })
        finally:
            env.teardown()
        return self.results

    def generate_report(self):
        report = {
            'total_tests': len(self.results),
            'passed': sum(1 for r in self.results if r['status'] == 'pass'),
            'failed': sum(1 for r in self.results if r['status'] == 'fail'),
            'details': self.results
        }
        return json.dumps(report, indent=2)

