import os
import json
import datetime
from collections import defaultdict

class LogAggregator:
    def __init__(self):
        self.logs = defaultdict(list)
        self.error_count = defaultdict(int)

    def collect_logs(self, log_file):
        with open(log_file, 'r') as f:
            for line in f:
                try:
                    log_entry = json.loads(line)
                    timestamp = log_entry.get('timestamp')
                    level = log_entry.get('level', 'INFO')
                    message = log_entry.get('message', '')
                    service = log_entry.get('service', 'unknown')

                    self.logs[service].append({
                        'timestamp': timestamp,
                        'level': level,
                        'message': message
                    })

                    if level == 'ERROR':
                        self.error_count[service] += 1

                except json.JSONDecodeError:
                    continue

    def analyze_logs(self):
        stats = {}
        for service in self.logs:
            stats[service] = {
                'total_logs': len(self.logs[service]),
                'error_count': self.error_count[service],
                'last_error': None
            }

            for log in reversed(self.logs[service]):
                if log['level'] == 'ERROR':
                    stats[service]['last_error'] = log
                    break

        return stats

    def get_logs_by_timerange(self, start_time, end_time):
        filtered_logs = defaultdict(list)

        for service in self.logs:
            for log in self.logs[service]:
                log_time = datetime.datetime.fromisoformat(log['timestamp'])
                if start_time <= log_time <= end_time:
                    filtered_logs[service].append(log)

        return filtered_logs

    def export_logs(self, output_file):
        with open(output_file, 'w') as f:
            json.dump(dict(self.logs), f, indent=2)

if __name__ == '__main__':
    aggregator = LogAggregator()

    # Example usage
    log_dir = 'logs/'
    for file in os.listdir(log_dir):
        if file.endswith('.log'):
            aggregator.collect_logs(os.path.join(log_dir, file))

    # Get statistics
    stats = aggregator.analyze_logs()
    print("Log Statistics:", json.dumps(stats, indent=2))

    # Get logs for last hour
    now = datetime.datetime.now()
    last_hour = now - datetime.timedelta(hours=1)
    recent_logs = aggregator.get_logs_by_timerange(last_hour, now)

