import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
from concurrent.futures import ThreadPoolExecutor

class LinkChecker:
    def __init__(self, start_url):
        self.start_url = start_url
        self.domain = urlparse(start_url).netloc
        self.visited = set()
        self.broken_links = set()

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and parsed.netloc == self.domain

    def check_link(self, url):
        try:
            response = requests.head(url, allow_redirects=True, timeout=5)
            if response.status_code >= 400:
                self.broken_links.add((url, response.status_code))
        except requests.RequestException as e:
            self.broken_links.add((url, str(e)))

    def crawl(self, url):
        if url in self.visited:
            return
        self.visited.add(url)

        try:
            response = requests.get(url, timeout=5)
            soup = BeautifulSoup(response.text, 'html.parser')

            with ThreadPoolExecutor(max_workers=10) as executor:
                for link in soup.find_all('a'):
                    href = link.get('href')
                    if not href:
                        continue

                    absolute_url = urljoin(url, href)
                    if self.is_valid_url(absolute_url):
                        executor.submit(self.check_link, absolute_url)
                        executor.submit(self.crawl, absolute_url)

        except requests.RequestException:
            self.broken_links.add((url, "Failed to fetch"))

    def run(self):
        self.crawl(self.start_url)
        return self.broken_links

if __name__ == "__main__":
    checker = LinkChecker("https://example.com")
    broken_links = checker.run()

    for url, error in broken_links:
        print(f"Broken link: {url} - Error: {error}")

