    def run_tests(self):
        os.chdir(self.source_dir)
        result = subprocess.run(['python', '-m', 'pytest'], capture_output=True)
        return result.returncode == 0

    def build_artifacts(self):
        self.build_dir.mkdir(exist_ok=True)
        os.chdir(self.source_dir)
        subprocess.run(['python', 'setup.py', 'build'], check=True)

    def publish_artifacts(self, destination_url):
        artifacts = list(self.build_dir.glob('**/*'))
        for artifact in artifacts:
            with open(artifact, 'rb') as f:
                files = {'file': f}
                response = requests.post(destination_url, files=files)
                response.raise_for_status()

    def run_pipeline(self, repo_url, destination_url):
        try:
            self.fetch_sources(repo_url)
            if self.run_tests():
                self.build_artifacts()
                self.publish_artifacts(destination_url)
                return True
            return False
        except Exception as e:
            print(f"Build failed: {str(e)}")
            return False

if __name__ == "__main__":
