import json
from datetime import datetime
from pathlib import Path

class DiffBackup:
    def __init__(self, source_dir, backup_dir):
        self.source_dir = Path(source_dir)
        self.backup_dir = Path(backup_dir)
        self.manifest_file = self.backup_dir / 'manifest.json'
        self.prev_hashes = self._load_manifest()

    def _load_manifest(self):
        if self.manifest_file.exists():
            with open(self.manifest_file) as f:
                return json.load(f)
        return {}

    def _save_manifest(self, hashes):
        with open(self.manifest_file, 'w') as f:
            json.dump(hashes, f)

    def _get_file_hash(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for block in iter(lambda: f.read(4096), b''):
                sha256.update(block)
        return sha256.hexdigest()

    def _scan_files(self):
        changed_files = []
        current_hashes = {}

        for file in self.source_dir.rglob('*'):
            if file.is_file():
                rel_path = str(file.relative_to(self.source_dir))
                file_hash = self._get_file_hash(file)
                current_hashes[rel_path] = file_hash

                if rel_path not in self.prev_hashes or self.prev_hashes[rel_path] != file_hash:
                    changed_files.append(file)

        return changed_files, current_hashes

    def create_backup(self):
        changed_files, current_hashes = self._scan_files()

        if not changed_files:
            return "No changes detected"

        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        backup_name = f'backup_{timestamp}.tar.gz'
        backup_path = self.backup_dir / backup_name

        with tarfile.open(backup_path, 'w:gz') as tar:
            for file in changed_files:
                tar.add(file, arcname=str(file.relative_to(self.source_dir)))

        self._save_manifest(current_hashes)
        return f"Backup created: {backup_name} with {len(changed_files)} files"

if __name__ == '__main__':
    backup = DiffBackup('/path/to/source', '/path/to/backups')
    result = backup.create_backup()
    print(result)
