import fnmatch
from concurrent.futures import ThreadPoolExecutor

def search_file(file_path, name_pattern, content_pattern):
    try:
        if not fnmatch.fnmatch(os.path.basename(file_path), name_pattern):
            return None

        if content_pattern:
            with open(file_path, 'r', errors='ignore') as f:
                content = f.read()
                if content_pattern in content:
                    return file_path
        else:
            return file_path
    except:
        return None

def search_directory(directory, name_pattern, content_pattern):
    matches = []
    with ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
        futures = []
        for root, _, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                futures.append(executor.submit(search_file, file_path, name_pattern, content_pattern))

        for future in futures:
            result = future.result()
            if result:
                matches.append(result)
    return matches

def main():
    parser = argparse.ArgumentParser(description='Search for files by name and content')
    parser.add_argument('-d', '--directory', default='.', help='Directory to search in')
    parser.add_argument('-n', '--name', required=True, help='File name pattern')
    parser.add_argument('-c', '--content', help='Content to search for')
