from datetime import datetime
from typing import List, Dict

@dataclass
class Player:
    id: int
    name: str
    team: str
    position: str
    stats: Dict[str, float]

@dataclass 
class Team:
    id: int
    name: str
    wins: int
    losses: int
    players: List[Player]

    def win_percentage(self) -> float:
        total_games = self.wins + self.losses
        return round(self.wins / total_games, 3) if total_games > 0 else 0.0

@dataclass
class Game:
    id: int
    home_team: Team
    away_team: Team
    date: datetime
    score_home: int = 0
    score_away: int = 0
    status: str = "Scheduled"

class League:
    def __init__(self):
        self.teams: Dict[int, Team] = {}
        self.players: Dict[int, Player] = {}
        self.games: Dict[int, Game] = {}

    def add_team(self, team: Team):
        self.teams[team.id] = team

    def add_player(self, player: Player):
        self.players[player.id] = player

    def add_game(self, game: Game):
        self.games[game.id] = game

    def get_standings(self) -> List[Team]:
        return sorted(
            self.teams.values(),
            key=lambda x: x.win_percentage(),
            reverse=True
        )

    def get_schedule(self, team_id: int) -> List[Game]:
        return [
            game for game in self.games.values()
            if game.home_team.id == team_id or game.away_team.id == team_id
        ]

    def get_player_stats(self, player_id: int) -> Dict[str, float]:
        return self.players[player_id].stats
