            if item1 in self.ratings[user] and item2 in self.ratings[user]:
                ratings1.append(self.ratings[user][item1])
                ratings2.append(self.ratings[user][item2])

        if len(ratings1) == 0:
            return 0

        return np.corrcoef(ratings1, ratings2)[0,1]

    def get_recommendations(self, user_id, n=5):
        recommendations = {}
        user_ratings = self.ratings[user_id]

        for item in user_ratings:
            for other_item in self.ratings[user_id]:
                if item != other_item:
                    sim = self.calculate_similarity(item, other_item)
                    if other_item not in recommendations:
                        recommendations[other_item] = 0
                    recommendations[other_item] += sim * user_ratings[item]

