            'frequency': frequency,
            'dates_completed': [],
            'streak': 0,
            'created_at': datetime.now().isoformat()
        }

    def complete_habit(self, name, date=None):
        if date is None:
            date = datetime.now().date()
        if name in self.habits:
            self.habits[name]['dates_completed'].append(date.isoformat())
            self._calculate_streak(name)
            return True
        return False

    def _calculate_streak(self, name):
        dates = sorted([datetime.fromisoformat(d) for d in self.habits[name]['dates_completed']])
        streak = 1
        for i in range(len(dates)-1, 0, -1):
            if (dates[i].date() - dates[i-1].date()) == timedelta(days=1):
                streak += 1
            else:
                break
        self.habits[name]['streak'] = streak

    def get_progress(self, name):
        if name in self.habits:
            return {
                'name': name,
                'completed_count': len(self.habits[name]['dates_completed']),
                'streak': self.habits[name]['streak'],
                'frequency': self.habits[name]['frequency']
