import logging
import time
from functools import wraps
from datetime import datetime

class QueryLogger:
    def __init__(self, threshold_ms=1000):
        self.threshold_ms = threshold_ms
        self.logger = logging.getLogger('slow_queries')
        self.logger.setLevel(logging.INFO)
        handler = logging.FileHandler('slow_queries.log')
        formatter = logging.Formatter('%(asctime)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def log_query(func):
        @wraps(func)
        def wrapper(self, query, *args, **kwargs):
            start_time = time.time()
            result = func(self, query, *args, **kwargs)
            duration_ms = (time.time() - start_time) * 1000

            if duration_ms > self.threshold_ms:
                self.logger.info(f"Slow query ({duration_ms:.2f}ms): {query}")

            return result
        return wrapper

class Database:
    def __init__(self):
        self.query_logger = QueryLogger()

    @QueryLogger.log_query
    def execute(self, query):
        time.sleep(0.5)  # Simulate database operation
