from datetime import datetime
from typing import List, Optional
import uuid

@dataclass
class Flight:
    flight_number: str
    departure: str
    arrival: str
    departure_time: datetime
    arrival_time: datetime
    price: float

@dataclass
class Booking:
    booking_id: str
    passenger_name: str
    passenger_email: str
    flights: List[Flight]
    total_price: float
    status: str

class TravelBookingSystem:
    def __init__(self):
        self.bookings = {}
        self.flights = {}

    def add_flight(self, flight: Flight) -> None:
        self.flights[flight.flight_number] = flight

    def search_flights(self, departure: str, arrival: str, date: datetime) -> List[Flight]:
        return [
            flight for flight in self.flights.values()
            if flight.departure == departure
            and flight.arrival == arrival
            and flight.departure_time.date() == date.date()
        ]

    def create_booking(self, passenger_name: str, passenger_email: str, flight_numbers: List[str]) -> str:
        booking_id = str(uuid.uuid4())
        flights = [self.flights[flight_number] for flight_number in flight_numbers]
        total_price = sum(flight.price for flight in flights)

        booking = Booking(
            booking_id=booking_id,
            passenger_name=passenger_name,
            passenger_email=passenger_email,
            flights=flights,
            total_price=total_price,
            status="confirmed"
        )

        self.bookings[booking_id] = booking
        return booking_id

    def get_booking(self, booking_id: str) -> Optional[Booking]:
        return self.bookings.get(booking_id)

    def cancel_booking(self, booking_id: str) -> bool:
        if booking_id in self.bookings:
            self.bookings[booking_id].status = "cancelled"
            return True
        return False

