class LinkChecker:
    def __init__(self, base_url):
        self.base_url = base_url
        self.visited_urls = set()
        self.broken_links = set()
        self.missing_images = set()
        self.session = requests.Session()
        self.domain = urlparse(base_url).netloc

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and parsed.netloc == self.domain

    def check_url(self, url):
        try:
            response = self.session.head(url, allow_redirects=True, timeout=5)
            return response.status_code == 200
        except:
            return False

    def check_image(self, img_url):
        try:
            response = self.session.head(img_url, allow_redirects=True, timeout=5)
            return response.status_code == 200 and 'image' in response.headers.get('content-type', '')
        except:
            return False

    def crawl(self, url):
        if url in self.visited_urls:
            return
        self.visited_urls.add(url)

        try:
            response = self.session.get(url, timeout=5)
            soup = BeautifulSoup(response.text, 'html.parser')

            with ThreadPoolExecutor(max_workers=10) as executor:
                links = [urljoin(self.base_url, a.get('href')) for a in soup.find_all('a', href=True)]
                images = [urljoin(self.base_url, img.get('src')) for img in soup.find_all('img', src=True)]

                for link in links:
                    if self.is_valid_url(link):
                        if not self.check_url(link):
                            self.broken_links.add(link)
                        else:
                            executor.submit(self.crawl, link)

                for img in images:
                    if not self.check_image(img):
                        self.missing_images.add(img)

        except Exception as e:
            self.broken_links.add(url)

    def run(self):
        self.crawl(self.base_url)
        return {
            'broken_links': list(self.broken_links),
            'missing_images': list(self.missing_images)
        }

