from dataclasses import dataclass
from typing import List, Optional

@dataclass
class Flight:
    flight_number: str
    departure_airport: str 
    arrival_airport: str
    departure_time: datetime
    arrival_time: datetime
    price: float
    available_seats: int

@dataclass 
class Booking:
    booking_id: str
    passenger_name: str
    email: str
    flights: List[Flight]
    total_price: float
    status: str

class TravelBookingSystem:
    def __init__(self):
        self.flights = {}
        self.bookings = {}

    def add_flight(self, flight: Flight) -> None:
        self.flights[flight.flight_number] = flight

    def search_flights(self, departure: str, arrival: str, 
                      date: datetime) -> List[Flight]:
        matching = []
        for flight in self.flights.values():
            if (flight.departure_airport == departure and
                flight.arrival_airport == arrival and
                flight.departure_time.date() == date.date()):
                matching.append(flight)
        return matching

    def create_booking(self, passenger: str, email: str, 
                      flight_numbers: List[str]) -> Optional[Booking]:
        flights = []
        total = 0
        for number in flight_numbers:
            if number not in self.flights:
                return None
            flight = self.flights[number]
            if flight.available_seats < 1:
                return None
            flights.append(flight)
            total += flight.price

        booking = Booking(
            booking_id=f"B{len(self.bookings)}",
            passenger_name=passenger,
            email=email,
            flights=flights,
            total_price=total,
            status="confirmed"
        )

        for flight in flights:
            flight.available_seats -= 1

        self.bookings[booking.booking_id] = booking
        return booking

    def get_booking(self, booking_id: str) -> Optional[Booking]:
        return self.bookings.get(booking_id)

    def cancel_booking(self, booking_id: str) -> bool:
        if booking_id not in self.bookings:
            return False

        booking = self.bookings[booking_id]
        for flight in booking.flights:
            flight.available_seats += 1
        booking.status = "cancelled"
        return True
