from dataclasses import dataclass
from typing import List, Dict

@dataclass
class Goal:
    id: int
    title: str
    description: str
    target_date: datetime
    completed: bool = False
    progress: float = 0.0

@dataclass 
class Habit:
    id: int
    name: str
    frequency: str
    streak: int = 0
    completed_dates: List[datetime] = None

class ProductivityTracker:
    def __init__(self):
        self.goals: Dict[int, Goal] = {}
        self.habits: Dict[int, Habit] = {}
        self.next_goal_id = 1
        self.next_habit_id = 1

    def add_goal(self, title: str, description: str, target_date: datetime) -> Goal:
        goal = Goal(self.next_goal_id, title, description, target_date)
        self.goals[goal.id] = goal
        self.next_goal_id += 1
        return goal

    def update_goal_progress(self, goal_id: int, progress: float) -> None:
        if goal_id in self.goals:
            self.goals[goal_id].progress = min(progress, 100.0)
            if progress >= 100:
                self.goals[goal_id].completed = True

    def add_habit(self, name: str, frequency: str) -> Habit:
        habit = Habit(self.next_habit_id, name, frequency, completed_dates=[])
        self.habits[habit.id] = habit
        self.next_habit_id += 1
        return habit

    def complete_habit(self, habit_id: int) -> None:
        if habit_id in self.habits:
            habit = self.habits[habit_id]
            today = datetime.now()
            habit.completed_dates.append(today)

            if habit.frequency == "daily":
                yesterday = today - timedelta(days=1)
                if yesterday in habit.completed_dates:
                    habit.streak += 1
                else:
                    habit.streak = 1
