from pathlib import Path

class FileSyncer:
    def __init__(self, source_dir, target_dir, permissions=0o644):
        self.source = Path(source_dir)
        self.target = Path(target_dir)
        self.permissions = permissions

    def get_file_hash(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for block in iter(lambda: f.read(4096), b''):
                sha256.update(block)
        return sha256.hexdigest()

    def sync_files(self):
        if not self.source.exists() or not self.target.exists():
            raise ValueError("Source or target directory does not exist")

        for src_file in self.source.rglob('*'):
            if src_file.is_file():
                rel_path = src_file.relative_to(self.source)
                dst_file = self.target / rel_path

                if not dst_file.parent.exists():
                    dst_file.parent.mkdir(parents=True)

                if not dst_file.exists() or self.get_file_hash(src_file) != self.get_file_hash(dst_file):
                    shutil.copy2(src_file, dst_file)
                    os.chmod(dst_file, self.permissions)

    def verify_sync(self):
        mismatched = []
        for src_file in self.source.rglob('*'):
            if src_file.is_file():
                rel_path = src_file.relative_to(self.source)
                dst_file = self.target / rel_path

                if not dst_file.exists() or self.get_file_hash(src_file) != self.get_file_hash(dst_file):
                    mismatched.append(str(rel_path))

