        self.session = requests.Session()
        self.session.headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36'}

    def inspect(self):
        try:
            response = self.session.get(self.url, allow_redirects=True)
            parsed_url = urlparse(self.url)

            metadata = OrderedDict({
                'status_code': response.status_code,
                'final_url': response.url,
                'redirect_history': [r.url for r in response.history],
                'content_type': response.headers.get('Content-Type'),
                'server': response.headers.get('Server'),
                'ssl_info': self._get_ssl_info(parsed_url.netloc),
                'headers': dict(response.headers),
                'content_length': len(response.content),
                'title': self._extract_title(response.text),
                'meta_tags': self._extract_meta_tags(response.text)
            })

            return metadata

        except requests.RequestException as e:
            return {'error': str(e)}

    def _get_ssl_info(self, hostname):
        try:
            context = ssl.create_default_context()
            with socket.create_connection((hostname, 443)) as sock:
                with context.wrap_socket(sock, server_hostname=hostname) as ssock:
                    cert = ssock.getpeercert()
                    return {
                        'issuer': dict(x[0] for x in cert['issuer']),
                        'expires': cert['notAfter'],
                        'subject': dict(x[0] for x in cert['subject'])
                    }
        except:
            return None

    def _extract_title(self, html):
        soup = BeautifulSoup(html, 'html.parser')
        return soup.title.string if soup.title else None

    def _extract_meta_tags(self, html):
