import zipfile
import os
from pathlib import Path

def extract_ebooks(archive_path, output_dir):
    supported_formats = {'.epub', '.mobi', '.pdf'}

    with zipfile.ZipFile(archive_path, 'r') as archive:
        for file_info in archive.filelist:
            file_ext = Path(file_info.filename).suffix.lower()
            if file_ext in supported_formats:
                extracted_path = os.path.join(output_dir, file_info.filename)
                os.makedirs(os.path.dirname(extracted_path), exist_ok=True)
                archive.extract(file_info, output_dir)

def main():
    archive_path = 'ebooks.zip'
    output_dir = 'extracted_ebooks'

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    os.makedirs(output_dir, exist_ok=True)
    extract_ebooks(archive_path, output_dir)

if __name__ == '__main__':
    main()

