import shutil
from pathlib import Path

def remove_temp_files(directory, age_days=7, extensions=('.tmp', '.temp', '.log')):
    current_time = time.time()
    max_age = current_time - (age_days * 86400)

    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith(extensions):
                file_path = os.path.join(root, file)
                try:
                    file_time = os.path.getmtime(file_path)
                    if file_time < max_age:
                        os.remove(file_path)
                except OSError:
                    continue

def clean_empty_dirs(directory):
    for root, dirs, files in os.walk(directory, topdown=False):
        for dir_name in dirs:
            dir_path = os.path.join(root, dir_name)
            try:
                if not os.listdir(dir_path):
                    os.rmdir(dir_path)
            except OSError:
                continue

if __name__ == '__main__':
    target_dir = os.path.expanduser('~/temp')
    remove_temp_files(target_dir)
    clean_empty_dirs(target_dir)

