import os
import hashlib
import requests
import tarfile
import subprocess
from pathlib import Path

class PackageManager:
    def __init__(self, cache_dir="/var/cache/pkgmgr", repos=None):
        self.cache_dir = Path(cache_dir)
        self.repos = repos or ["https://repo1.example.com", "https://repo2.example.com"]
        self.cache_dir.mkdir(parents=True, exist_ok=True)

    def install_package(self, package_name, version=None):
        package_info = self._fetch_package_info(package_name, version)
        package_path = self._download_package(package_info)

        if package_path.suffix == '.deb':
            return self._install_deb(package_path)
        elif package_path.suffix == '.rpm':
            return self._install_rpm(package_path)
        else:
            raise ValueError(f"Unsupported package format: {package_path.suffix}")

    def _fetch_package_info(self, package_name, version):
        for repo in self.repos:
            response = requests.get(f"{repo}/api/packages/{package_name}")
            if response.status_code == 200:
                return response.json()
        raise ValueError(f"Package {package_name} not found")

    def _download_package(self, package_info):
        url = package_info['download_url']
        checksum = package_info['sha256']

        local_path = self.cache_dir / f"{package_info['name']}-{package_info['version']}{package_info['format']}"

        if not local_path.exists():
            response = requests.get(url, stream=True)
            with open(local_path, 'wb') as f:
                for chunk in response.iter_content(chunk_size=8192):
                    f.write(chunk)

        if not self._verify_checksum(local_path, checksum):
            raise ValueError("Package checksum verification failed")

        return local_path

    def _verify_checksum(self, file_path, expected_checksum):
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest() == expected_checksum

    def _install_deb(self, package_path):
        result = subprocess.run(['dpkg', '-i', str(package_path)], capture_output=True)
        if result.returncode != 0:
            raise RuntimeError(f"Failed to install deb package: {result.stderr.decode()}")
        return True

    def _install_rpm(self, package_path):
        result = subprocess.run(['rpm', '-i', str(package_path)], capture_output=True)
        if result.returncode != 0:
            raise RuntimeError(f"Failed to install rpm package: {result.stderr.decode()}")
        return True

    def remove_package(self, package_name):
        try:
            subprocess.run(['dpkg', '-r', package_name], check=True)
        except subprocess.CalledProcessError:
            try:
                subprocess.run(['rpm', '-e', package_name], check=True)
            except subprocess.CalledProcessError:
                raise RuntimeError(f"Failed to remove package {package_name}")

    def list_installed(self):
        deb_packages = subprocess.run(['dpkg', '-l'], capture_output=True, text=True).stdout
        rpm_packages = subprocess.run(['rpm', '-qa'], capture_output=True, text=True).stdout
        return {'deb': deb_packages.splitlines(), 'rpm': rpm_packages.splitlines()}

