from flask import Flask, request, jsonify
from werkzeug.utils import secure_filename
import os
import uuid

app = Flask(__name__)

UPLOAD_FOLDER = 'uploads'
ALLOWED_EXTENSIONS = {'obj', 'fbx', 'gltf', 'png', 'jpg', 'jpeg', 'mp4'}

app.config['UPLOAD_FOLDER'] = UPLOAD_FOLDER
app.config['MAX_CONTENT_LENGTH'] = 100 * 1024 * 1024

models_db = {}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

@app.route('/model', methods=['POST'])
def upload_model():
    if 'model' not in request.files:
        return jsonify({'error': 'No model file'}), 400

    model_file = request.files['model']
    if model_file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if model_file and allowed_file(model_file.filename):
        model_id = str(uuid.uuid4())
        model_data = {
            'id': model_id,
            'title': request.form.get('title', ''),
            'description': request.form.get('description', ''),
            'author': request.form.get('author', ''),
            'tags': request.form.get('tags', '').split(','),
            'files': {}
        }

        model_dir = os.path.join(app.config['UPLOAD_FOLDER'], model_id)
        os.makedirs(model_dir, exist_ok=True)

        filename = secure_filename(model_file.filename)
        model_file.save(os.path.join(model_dir, filename))
        model_data['files']['model'] = filename

        if 'textures' in request.files:
            textures = request.files.getlist('textures')
            for texture in textures:
                if texture and allowed_file(texture.filename):
                    texture_filename = secure_filename(texture.filename)
                    texture.save(os.path.join(model_dir, texture_filename))
                    model_data['files'].setdefault('textures', []).append(texture_filename)

        models_db[model_id] = model_data
        return jsonify({'id': model_id, 'message': 'Model uploaded successfully'})

    return jsonify({'error': 'Invalid file type'}), 400

@app.route('/model/<model_id>', methods=['GET'])
def get_model(model_id):
    if model_id not in models_db:
        return jsonify({'error': 'Model not found'}), 404
    return jsonify(models_db[model_id])

@app.route('/models', methods=['GET'])
def list_models():
    search = request.args.get('search', '').lower()
    tag = request.args.get('tag', '').lower()

    filtered_models = models_db.values()
    if search:
        filtered_models = [m for m in filtered_models 
                         if search in m['title'].lower() 
                         or search in m['description'].lower()]
    if tag:
        filtered_models = [m for m in filtered_models 
                         if tag in [t.lower() for t in m['tags']]]

    return jsonify(list(filtered_models))

@app.route('/model/<model_id>', methods=['DELETE'])
def delete_model(model_id):
    if model_id not in models_db:
        return jsonify({'error': 'Model not found'}), 404

    model_dir = os.path.join(app.config['UPLOAD_FOLDER'], model_id)
    if os.path.exists(model_dir):
        for filename in os.listdir(model_dir):
            os.remove(os.path.join(model_dir, filename))
        os.rmdir(model_dir)

    del models_db[model_id]
    return jsonify({'message': 'Model deleted successfully'})

if __name__ == '__main__':
    os.makedirs(UPLOAD_FOLDER, exist_ok=True)
    app.run(debug=True)

