import os
import subprocess
import argparse
import yaml
import shutil
from pathlib import Path

class DevEnvironment:
    def __init__(self, config_path):
        with open(config_path) as f:
            self.config = yaml.safe_load(f)
        self.workspace = Path(self.config.get('workspace_dir', 'workspace'))

    def setup(self):
        self.workspace.mkdir(exist_ok=True)
        for repo in self.config['repositories']:
            self.clone_repo(repo)
            self.install_dependencies(repo)

    def clone_repo(self, repo):
        repo_path = self.workspace / repo['name']
        if not repo_path.exists():
            subprocess.run(['git', 'clone', repo['url'], str(repo_path)], check=True)

    def install_dependencies(self, repo):
        repo_path = self.workspace / repo['name']
        if 'requirements.txt' in os.listdir(repo_path):
            subprocess.run(['pip', 'install', '-r', str(repo_path / 'requirements.txt')], check=True)

    def cleanup(self):
        if self.workspace.exists():
            shutil.rmtree(self.workspace)

def main():
    parser = argparse.ArgumentParser(description='Development environment manager')
    parser.add_argument('--config', default='dev_config.yml', help='Configuration file path')
    parser.add_argument('--clean', action='store_true', help='Clean workspace')
    args = parser.parse_args()

    dev_env = DevEnvironment(args.config)
    if args.clean:
        dev_env.cleanup()
    else:
        dev_env.setup()

if __name__ == '__main__':
    main()

