class PropertyManagementSystem:
    def __init__(self):
        self.properties = {}
        self.tenants = {}
        self.payments = {}

    def add_property(self, address, rent, bedrooms, bathrooms):
        property_id = str(uuid.uuid4())
        property = Property(property_id, address, rent, bedrooms, bathrooms, True)
        self.properties[property_id] = property
        return property_id

    def screen_tenant(self, name, email, phone, credit_score, income, references):
        tenant_id = str(uuid.uuid4())
        tenant = Tenant(tenant_id, name, email, phone, credit_score, income, references)
        self.tenants[tenant_id] = tenant
        return tenant_id

    def assign_tenant(self, property_id, tenant_id):
        if property_id in self.properties and tenant_id in self.tenants:
            self.properties[property_id].tenant_id = tenant_id
            self.properties[property_id].available = False
            return True
        return False

    def collect_rent(self, property_id, amount, date=None):
        if date is None:
            date = datetime.now()

        if property_id in self.properties:
            payment_id = str(uuid.uuid4())
            self.payments[payment_id] = {
                'property_id': property_id,
                'tenant_id': self.properties[property_id].tenant_id,
                'amount': amount,
                'date': date
            }
            return payment_id
        return None

    def get_available_properties(self):
        return [p for p in self.properties.values() if p.available]

    def get_tenant_payments(self, tenant_id):
