    def get_property_history(self, property_id):
        return [p for p in self.payments.values() if p['property_id'] == property_id]

import os
import shutil
import time
from pathlib import Path

def remove_temp_files(directory, age_days=7):
    current_time = time.time()
    max_age = current_time - (age_days * 86400)

    for root, dirs, files in os.walk(directory):
        for file in files:
            if file.endswith(('.tmp', '.temp', '.cache', '~')):
                file_path = os.path.join(root, file)
                try:
                    file_stat = os.stat(file_path)
                    if file_stat.st_mtime < max_age:
                        os.remove(file_path)
                except OSError:
                    continue

        for dir in dirs:
            if dir.startswith('temp') or dir.endswith('tmp'):
                dir_path = os.path.join(root, dir)
                try:
                    if os.path.getmtime(dir_path) < max_age:
                        shutil.rmtree(dir_path)
                except OSError:
                    continue

if __name__ == '__main__':
    target_directory = Path.home()
    remove_temp_files(target_directory)

