import os
from datetime import datetime
import hashlib

class WebArchiver:
    def __init__(self, excluded_subdomains=None):
        self.excluded_subdomains = set(excluded_subdomains or [])
        self.archive_dir = "web_archives"
        os.makedirs(self.archive_dir, exist_ok=True)

    def is_excluded(self, url):
        parsed = urlparse(url)
        domain = parsed.netloc
        return any(domain.endswith(f".{sub}") or domain == sub 
                  for sub in self.excluded_subdomains)

    def take_snapshot(self, url):
        if self.is_excluded(url):
            return None

        try:
            response = requests.get(url, timeout=30)
            content = response.content
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            filename = f"{hashlib.md5(url.encode()).hexdigest()}_{timestamp}.html"

            filepath = os.path.join(self.archive_dir, filename)
            with open(filepath, "wb") as f:
                f.write(content)

            return filepath
        except requests.RequestException:
            return None

    def bulk_snapshot(self, urls):
        results = {}
        for url in urls:
            results[url] = self.take_snapshot(url)
        return results

