import os
import subprocess
import logging
from datetime import datetime

class DeploymentPipeline:
    def __init__(self):
        self.artifacts_dir = "artifacts"
        self.build_dir = "build"
        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger(__name__)

    def build_artifact(self, source_path):
        try:
            if not os.path.exists(self.build_dir):
                os.makedirs(self.build_dir)

            build_cmd = f"python -m build {source_path} --outdir {self.build_dir}"
            subprocess.run(build_cmd, shell=True, check=True)
            self.logger.info(f"Build completed successfully for {source_path}")
            return True
        except subprocess.CalledProcessError as e:
            self.logger.error(f"Build failed: {str(e)}")
            return False

    def run_tests(self):
        try:
            test_cmd = "python -m pytest tests/"
            subprocess.run(test_cmd, shell=True, check=True)
            self.logger.info("Tests passed successfully")
            return True
        except subprocess.CalledProcessError as e:
            self.logger.error(f"Tests failed: {str(e)}")
            return False

    def deploy_artifact(self, artifact_path, deploy_env):
        try:
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            deploy_path = f"{self.artifacts_dir}/{deploy_env}/{timestamp}"

            if not os.path.exists(deploy_path):
                os.makedirs(deploy_path)

            deploy_cmd = f"cp {artifact_path} {deploy_path}"
            subprocess.run(deploy_cmd, shell=True, check=True)

            self.logger.info(f"Deployed to {deploy_path} successfully")
            return True
        except subprocess.CalledProcessError as e:
            self.logger.error(f"Deployment failed: {str(e)}")
            return False

    def run_pipeline(self, source_path, deploy_env):
        if self.build_artifact(source_path):
            if self.run_tests():
                artifact_path = f"{self.build_dir}/dist/*.whl"
                return self.deploy_artifact(artifact_path, deploy_env)
        return False

if __name__ == "__main__":
    pipeline = DeploymentPipeline()
    pipeline.run_pipeline("src/", "staging")
