import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
import hashlib
import sqlite3
from queue import Queue
from threading import Thread
import time

class Crawler:
    def __init__(self, db_path='crawler.db'):
        self.conn = sqlite3.connect(db_path)
        self.seen_urls = set()
        self.queue = Queue()
        self.create_tables()

    def create_tables(self):
        self.conn.execute('''
            CREATE TABLE IF NOT EXISTS pages (
                url TEXT PRIMARY KEY,
                content TEXT,
                hash TEXT,
                crawled_at INTEGER
            )
        ''')
        self.conn.commit()

    def add_url(self, url):
        if url not in self.seen_urls:
            self.seen_urls.add(url)
            self.queue.put(url)

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and bool(parsed.scheme)

    def crawl_page(self, url):
        try:
            response = requests.get(url, timeout=5)
            if response.status_code == 200:
                soup = BeautifulSoup(response.text, 'html.parser')
                content = soup.get_text()
                content_hash = hashlib.md5(content.encode()).hexdigest()

                self.conn.execute(
                    'INSERT OR REPLACE INTO pages VALUES (?, ?, ?, ?)',
                    (url, content, content_hash, int(time.time()))
                )
                self.conn.commit()

                for link in soup.find_all('a'):
                    href = link.get('href')
                    if href:
                        absolute_url = urljoin(url, href)
                        if self.is_valid_url(absolute_url):
                            self.add_url(absolute_url)

                return True
        except Exception as e:
            print(f"Error crawling {url}: {e}")
        return False

    def crawler_worker(self):
        while True:
            url = self.queue.get()
            if url is None:
                break
            self.crawl_page(url)
            self.queue.task_done()

    def start_crawling(self, start_url, num_workers=4):
        self.add_url(start_url)
        workers = []

        for _ in range(num_workers):
            t = Thread(target=self.crawler_worker)
            t.start()
            workers.append(t)

        self.queue.join()

        for _ in range(num_workers):
            self.queue.put(None)

        for worker in workers:
            worker.join()

if __name__ == "__main__":
    crawler = Crawler()
    crawler.start_crawling("https://example.com")

