        elif isinstance(node, cst.Dict):
            return "dict"
        return None

    def visit_FunctionDef(self, node: cst.FunctionDef) -> None:
        self.scope_stack.append(node.name.value)

    def leave_FunctionDef(self, original_node: cst.FunctionDef) -> cst.FunctionDef:
        self.scope_stack.pop()
        return original_node.with_changes(
            returns=cst.Annotation(annotation=cst.Name("Any"))
        )

    def leave_Param(self, original_node: cst.Param) -> cst.Param:
        return original_node.with_changes(
            annotation=cst.Annotation(annotation=cst.Name("Any"))
        )

def annotate_file(file_path: str) -> str:
    source_code = Path(file_path).read_text()
    source_tree = cst.parse_module(source_code)
    annotated_tree = source_tree.visit(TypeAnnotator())
    return annotated_tree.code

