class DeploymentPipeline:
    def __init__(self, repo_url, branch, deploy_dir):
        self.repo_url = repo_url
        self.branch = branch
        self.deploy_dir = Path(deploy_dir)
        self.workspace = Path('/tmp/deployment')

    def run(self):
        self.cleanup()
        self.clone_repository()
        self.run_tests()
        self.build()
        self.deploy()
        self.health_check()

    def cleanup(self):
        if self.workspace.exists():
            shutil.rmtree(self.workspace)
        self.workspace.mkdir(parents=True)

    def clone_repository(self):
        subprocess.run([
            'git', 'clone',
            '-b', self.branch,
            self.repo_url,
            str(self.workspace)
        ], check=True)

    def run_tests(self):
        subprocess.run([
            'python', '-m', 'pytest',
            '--junitxml=test-results.xml'
        ], cwd=self.workspace, check=True)

    def build(self):
        subprocess.run([
            'python', '-m', 'pip', 'install', '-r', 'requirements.txt'
        ], cwd=self.workspace, check=True)

    def deploy(self):
        if self.deploy_dir.exists():
            shutil.rmtree(self.deploy_dir)
        shutil.copytree(self.workspace, self.deploy_dir)

    def health_check(self):
        subprocess.run([
            'curl', '--fail', 'http://localhost:8000/health'
        ], check=True)

