import os
import subprocess
import argparse
import yaml
from pathlib import Path

class DevEnvironment:
    def __init__(self, workspace_dir):
        self.workspace_dir = Path(workspace_dir)
        self.workspace_dir.mkdir(exist_ok=True)

    def clone_repo(self, repo_url):
        repo_name = repo_url.split('/')[-1].replace('.git', '')
        repo_path = self.workspace_dir / repo_name

        if not repo_path.exists():
            subprocess.run(['git', 'clone', repo_url, str(repo_path)], check=True)
        return repo_path

    def install_dependencies(self, repo_path):
        if (repo_path / 'requirements.txt').exists():
            subprocess.run(['pip', 'install', '-r', 'requirements.txt'], cwd=repo_path, check=True)

        if (repo_path / 'package.json').exists():
            subprocess.run(['npm', 'install'], cwd=repo_path, check=True)

def main():
    parser = argparse.ArgumentParser(description='Development environment manager')
    parser.add_argument('--config', type=str, required=True, help='Path to config file')
    parser.add_argument('--workspace', type=str, default='./workspace', help='Workspace directory')
    args = parser.parse_args()

    with open(args.config) as f:
        config = yaml.safe_load(f)

    dev_env = DevEnvironment(args.workspace)

    for project in config['projects']:
        repo_path = dev_env.clone_repo(project['repo'])
        dev_env.install_dependencies(repo_path)

if __name__ == '__main__':
    main()

