from typing import Dict, List, Set

class SearchEngine:
    def __init__(self):
        self.index: Dict[str, Dict[int, int]] = defaultdict(lambda: defaultdict(int))
        self.documents: Dict[int, str] = {}
        self.doc_counter = 0

    def add_document(self, content: str) -> int:
        doc_id = self.doc_counter
        self.documents[doc_id] = content

        words = re.findall(r'\w+', content.lower())
        for word in words:
            self.index[word][doc_id] += 1

        self.doc_counter += 1
        return doc_id

    def search(self, query: str) -> List[int]:
        words = query.lower().split()
        if not words:
            return []

        # Get docs containing first word
        doc_scores = defaultdict(int)
        for doc_id, count in self.index[words[0]].items():
            doc_scores[doc_id] = count

        # Intersect with other words
        for word in words[1:]:
            curr_docs = set(self.index[word].keys())
            doc_scores = {
                doc_id: score + self.index[word][doc_id]
                for doc_id, score in doc_scores.items() 
                if doc_id in curr_docs
            }

        return sorted(doc_scores.keys(), 
                     key=lambda x: doc_scores[x],
                     reverse=True)

    def get_document(self, doc_id: int) -> str:
        return self.documents.get(doc_id, '')

if __name__ == '__main__':
