import os
import shutil
import hashlib
from pathlib import Path
import logging

class ZipDiskMigrator:
    def __init__(self, source_path, destination_path):
        self.source = Path(source_path)
        self.destination = Path(destination_path)
        self.setup_logging()

    def setup_logging(self):
        logging.basicConfig(
            filename='migration.log',
            level=logging.INFO,
            format='%(asctime)s - %(message)s'
        )

    def calculate_checksum(self, file_path):
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for block in iter(lambda: f.read(4096), b''):
                sha256.update(block)
        return sha256.hexdigest()

    def copy_file(self, source_file, dest_file):
        try:
            os.makedirs(os.path.dirname(dest_file), exist_ok=True)
            shutil.copy2(source_file, dest_file)

            source_checksum = self.calculate_checksum(source_file)
            dest_checksum = self.calculate_checksum(dest_file)

            if source_checksum != dest_checksum:
                raise ValueError(f"Checksum mismatch for {source_file}")

            logging.info(f"Successfully copied: {source_file}")
            return True

        except Exception as e:
            logging.error(f"Error copying {source_file}: {str(e)}")
            return False

    def migrate(self):
        if not self.source.exists():
            raise FileNotFoundError(f"Source path {self.source} not found")

        total_files = 0
        successful_copies = 0

        for root, _, files in os.walk(self.source):
            for file in files:
                total_files += 1
                source_file = Path(root) / file
                relative_path = source_file.relative_to(self.source)
                dest_file = self.destination / relative_path

                if self.copy_file(source_file, dest_file):
                    successful_copies += 1

        logging.info(f"Migration complete. {successful_copies}/{total_files} files copied successfully")
        return successful_copies, total_files

if __name__ == "__main__":
    migrator = ZipDiskMigrator("/media/zipdisk", "/path/to/backup")
    success, total = migrator.migrate()
    print(f"Migration finished: {success}/{total} files copied")
