from datetime import datetime
import hashlib

def scan_images(source_dir):
    image_extensions = {'.jpg', '.jpeg', '.png', '.gif', '.bmp', '.tiff'}
    image_files = []

    for root, _, files in os.walk(source_dir):
        for file in files:
            if Path(file).suffix.lower() in image_extensions:
                image_files.append(os.path.join(root, file))
    return image_files

def get_image_metadata(image_path):
    with Image.open(image_path) as img:
        created_date = datetime.fromtimestamp(os.path.getctime(image_path))
        file_hash = hashlib.md5(open(image_path, 'rb').read()).hexdigest()
        return {
            'size': img.size,
            'format': img.format,
            'created': created_date,
            'hash': file_hash
        }

def organize_images(source_dir, target_dir):
    image_files = scan_images(source_dir)
    organized = {}

    for image_path in image_files:
        metadata = get_image_metadata(image_path)
        year_month = metadata['created'].strftime('%Y-%m')
        target_path = Path(target_dir) / year_month
        target_path.mkdir(parents=True, exist_ok=True)

        new_path = target_path / Path(image_path).name
        if not new_path.exists():
            shutil.copy2(image_path, new_path)
            organized[str(new_path)] = metadata

    return organized

