import os
import subprocess
import yaml
from pathlib import Path
import shutil

class Pipeline:
    def __init__(self, repo_url, branch="main"):
        self.repo_url = repo_url
        self.branch = branch
        self.workspace = Path("./workspace")

    def run(self):
        try:
            self.clean_workspace()
            self.clone_repository()
            self.install_dependencies()
            self.run_tests()
            self.build()
            self.deploy()
            return True
        except Exception as e:
            print(f"Pipeline failed: {str(e)}")
            return False

    def clean_workspace(self):
        if self.workspace.exists():
            shutil.rmtree(self.workspace)
        self.workspace.mkdir()

    def clone_repository(self):
        subprocess.run([
            "git", "clone",
            "-b", self.branch,
            self.repo_url,
            str(self.workspace)
        ], check=True)

    def install_dependencies(self):
        requirements = self.workspace / "requirements.txt"
        if requirements.exists():
            subprocess.run([
                "pip", "install", "-r", str(requirements)
            ], check=True)

    def run_tests(self):
        subprocess.run([
            "python", "-m", "pytest",
            str(self.workspace)
        ], check=True)

    def build(self):
        if (self.workspace / "setup.py").exists():
            subprocess.run([
                "python", "setup.py", "build"
            ], cwd=str(self.workspace), check=True)

    def deploy(self):
        config = self.load_deploy_config()
        if config.get("type") == "docker":
            self.docker_deploy(config)
        else:
            self.server_deploy(config)

    def load_deploy_config(self):
        config_file = self.workspace / "deploy.yml"
        if config_file.exists():
            with open(config_file) as f:
                return yaml.safe_load(f)
        return {}

    def docker_deploy(self, config):
        subprocess.run([
            "docker", "build", "-t",
            config.get("image", "app:latest"),
            str(self.workspace)
        ], check=True)

    def server_deploy(self, config):
        host = config.get("host", "localhost")
        path = config.get("path", "/var/www/app")
        subprocess.run([
            "rsync", "-av",
            str(self.workspace) + "/",
            f"{host}:{path}"
        ], check=True)

if __name__ == "__main__":
    pipeline = Pipeline("https://github.com/user/repo.git")
    pipeline.run()

