from collections import defaultdict
from pathlib import Path

class DiskAnalyzer:
    def __init__(self):
        self.duplicates = defaultdict(list)
        self.file_hashes = {}

    def calculate_hash(self, filepath):
        hasher = hashlib.sha256()
        with open(filepath, 'rb') as file:
            buf = file.read(65536)
            while len(buf) > 0:
                hasher.update(buf)
                buf = file.read(65536)
        return hasher.hexdigest()

    def find_duplicates(self, directory):
        for root, _, files in os.walk(directory):
            for filename in files:
                filepath = os.path.join(root, filename)
                if os.path.isfile(filepath):
                    file_hash = self.calculate_hash(filepath)
                    self.duplicates[file_hash].append(filepath)

    def delete_duplicates(self, keep_newest=True):
        for hash_value, file_list in self.duplicates.items():
            if len(file_list) > 1:
                if keep_newest:
                    files_by_time = sorted(file_list, key=os.path.getmtime)
                    keep_file = files_by_time[-1]
                    delete_files = files_by_time[:-1]
                else:
                    keep_file = file_list[0]
                    delete_files = file_list[1:]

                for file in delete_files:
                    os.remove(file)

                os.chmod(keep_file, 0o644)

    def print_duplicates(self):
        for hash_value, file_list in self.duplicates.items():
            if len(file_list) > 1:
                print(f"\nDuplicate files (hash: {hash_value}):")
                for file in file_list:
