import os
import hashlib
import shutil
import time
from watchdog.observers import Observer
from watchdog.events import FileSystemEventHandler

class SyncHandler(FileSystemEventHandler):
    def __init__(self, source_dir, target_dir):
        self.source_dir = source_dir
        self.target_dir = target_dir

    def on_modified(self, event):
        if event.is_directory:
            return
        relative_path = os.path.relpath(event.src_path, self.source_dir)
        target_path = os.path.join(self.target_dir, relative_path)

        if os.path.exists(event.src_path):
            os.makedirs(os.path.dirname(target_path), exist_ok=True)
            shutil.copy2(event.src_path, target_path)

    def on_created(self, event):
        if event.is_directory:
            return
        relative_path = os.path.relpath(event.src_path, self.source_dir)
        target_path = os.path.join(self.target_dir, relative_path)

        os.makedirs(os.path.dirname(target_path), exist_ok=True)
        shutil.copy2(event.src_path, target_path)

    def on_deleted(self, event):
        relative_path = os.path.relpath(event.src_path, self.source_dir)
        target_path = os.path.join(self.target_dir, relative_path)

        if os.path.exists(target_path):
            if event.is_directory:
                shutil.rmtree(target_path)
            else:
                os.remove(target_path)

def sync_folders(source_dir, target_dir):
    event_handler = SyncHandler(source_dir, target_dir)
    observer = Observer()
    observer.schedule(event_handler, source_dir, recursive=True)
    observer.start()

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        observer.stop()
    observer.join()

if __name__ == "__main__":
    source_directory = "/path/to/source"
    target_directory = "/path/to/target"
    sync_folders(source_directory, target_directory)

