import ast
import os
import coverage
from typing import List, Dict, Set

class TestAnalyzer:
    def __init__(self, src_path: str, test_path: str):
        self.src_path = src_path
        self.test_path = test_path
        self.cov = coverage.Coverage()
        self.test_template = """
import unittest
import {module}

class Test{class_name}(unittest.TestCase):
    def setUp(self):
        self.permissions = {permissions}

    def test_{method}(self):
        {test_code}

if __name__ == '__main__':
    unittest.main()
"""

    def analyze_coverage(self) -> Dict[str, float]:
        self.cov.start()
        self._run_tests()
        self.cov.stop()

        coverage_data = {}
        for filename in self.cov.get_data().measured_files():
            file_coverage = self.cov.analysis(filename)
            coverage_data[filename] = (len(file_coverage[0]) / 
                                     (len(file_coverage[1]) or 1)) * 100
        return coverage_data

    def find_untested_methods(self) -> Set[str]:
        tree = ast.parse(open(self.src_path).read())
        all_methods = {node.name for node in ast.walk(tree) 
                      if isinstance(node, ast.FunctionDef)}

        test_tree = ast.parse(open(self.test_path).read())
        tested_methods = {node.name.replace('test_', '') 
                         for node in ast.walk(test_tree)
                         if isinstance(node, ast.FunctionDef) 
                         and node.name.startswith('test_')}

        return all_methods - tested_methods

    def generate_test(self, method: str, permissions: Dict[str, str]) -> str:
        module_name = os.path.splitext(os.path.basename(self.src_path))[0]
        class_name = module_name.title()

        test_code = f"result = {module_name}.{method}()\n"
        test_code += "        self.assertIsNotNone(result)"

        return self.test_template.format(
            module=module_name,
            class_name=class_name,
            permissions=permissions,
            method=method,
            test_code=test_code
        )

    def save_test(self, test_code: str, method: str) -> None:
        test_file = f"test_{method}.py"
        with open(os.path.join(self.test_path, test_file), 'w') as f:
            f.write(test_code)
        os.chmod(os.path.join(self.test_path, test_file), 0o644)

    def _run_tests(self) -> None:
        import unittest
        loader = unittest.TestLoader()
        tests = loader.discover(self.test_path)
        runner = unittest.TextTestRunner()
        runner.run(tests)

if __name__ == '__main__':
    analyzer = TestAnalyzer('src/module.py', 'tests/')

    # Get coverage analysis
    coverage_report = analyzer.analyze_coverage()
    print("Coverage Report:")
    for file, percentage in coverage_report.items():
        print(f"{file}: {percentage:.2f}%")

    # Find untested methods
    untested = analyzer.find_untested_methods()
    print("\nUntested Methods:", untested)

    # Generate new test with custom permissions
    permissions = {
        'read': True,
        'write': False,
        'execute': True
    }

    for method in untested:
        test_code = analyzer.generate_test(method, permissions)
        analyzer.save_test(test_code, method)
