from datetime import datetime
import logging
import json
from collections import defaultdict
import threading
import queue

class LogAggregator:
    def __init__(self):
        self.logs = defaultdict(list)
        self.queue = queue.Queue()
        self.running = True
        self.processor = threading.Thread(target=self._process_logs)
        self.processor.start()

    def collect(self, source, message, level="INFO"):
        timestamp = datetime.utcnow().isoformat()
        log_entry = {
            "timestamp": timestamp,
            "source": source,
            "level": level,
            "message": message
        }
        self.queue.put(log_entry)

    def _process_logs(self):
        while self.running:
            try:
                log_entry = self.queue.get(timeout=1)
                self.logs[log_entry["source"]].append(log_entry)
                self._analyze_logs(log_entry)
            except queue.Empty:
                continue

    def _analyze_logs(self, log_entry):
        if log_entry["level"] in ["ERROR", "CRITICAL"]:
            self._alert(log_entry)
        if len(self.logs[log_entry["source"]]) > 1000:
            self._rotate_logs(log_entry["source"])

    def _alert(self, log_entry):
        logging.warning(f"Alert: {log_entry['source']} - {log_entry['message']}")

    def _rotate_logs(self, source):
        self.logs[source] = self.logs[source][-1000:]

    def get_logs(self, source=None, level=None):
        if source:
            logs = self.logs[source]
        else:
            logs = [log for source_logs in self.logs.values() for log in source_logs]

        if level:
            logs = [log for log in logs if log["level"] == level]

        return sorted(logs, key=lambda x: x["timestamp"])

    def shutdown(self):
        self.running = False
        self.processor.join()

