        self.game_path = game_path
        self.mods_path = mods_path
        self.installed_mods = {}
        self._load_installed_mods()

    def _load_installed_mods(self):
        if os.path.exists(os.path.join(self.mods_path, "installed.json")):
            with open(os.path.join(self.mods_path, "installed.json"), "r") as f:
                self.installed_mods = json.load(f)

    def download_mod(self, mod: Mod) -> bool:
        response = requests.get(mod.download_url, stream=True)
        if response.status_code != 200:
            return False

        mod_path = os.path.join(self.mods_path, f"{mod.name}.zip")
        with open(mod_path, "wb") as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        file_hash = hashlib.sha256(open(mod_path, "rb").read()).hexdigest()
        if file_hash != mod.file_hash:
            os.remove(mod_path)
            return False

        return True

    def install_mod(self, mod: Mod) -> bool:
        mod_path = os.path.join(self.mods_path, f"{mod.name}.zip")

        try:
            with zipfile.ZipFile(mod_path, 'r') as zip_ref:
                zip_ref.extractall(self.game_path)

            self.installed_mods[mod.name] = {
                "version": mod.version,
                "hash": mod.file_hash
            }

            with open(os.path.join(self.mods_path, "installed.json"), "w") as f:
                json.dump(self.installed_mods, f)

            return True
        except Exception:
            return False

    def uninstall_mod(self, mod_name: str) -> bool:
        if mod_name not in self.installed_mods:
            return False

        mod_path = os.path.join(self.mods_path, f"{mod_name}.zip")
        if os.path.exists(mod_path):
            os.remove(mod_path)

        del self.installed_mods[mod_name]
        with open(os.path.join(self.mods_path, "installed.json"), "w") as f:
            json.dump(self.installed_mods, f)

        return True

    def is_mod_installed(self, mod_name: str) -> bool:
