from datetime import datetime
from dataclasses import dataclass
from typing import List, Dict
import json

@dataclass
class Activity:
    type: str  # meal, nap, play, etc
    start_time: datetime
    end_time: datetime
    notes: str

class Child:
    def __init__(self, name: str, age: int):
        self.name = name
        self.age = age
        self.activities: List[Activity] = []

    def add_activity(self, activity_type: str, notes: str = ""):
        activity = Activity(
            type=activity_type,
            start_time=datetime.now(),
            end_time=datetime.now(),
            notes=notes
        )
        self.activities.append(activity)

    def get_daily_summary(self, date: datetime) -> Dict:
        daily_activities = [a for a in self.activities 
                          if a.start_time.date() == date.date()]
        return {
            "name": self.name,
            "date": date.strftime("%Y-%m-%d"),
            "activities": [
                {
                    "type": a.type,
                    "start": a.start_time.strftime("%H:%M"),
                    "end": a.end_time.strftime("%H:%M"),
                    "notes": a.notes
                } for a in daily_activities
            ]
        }

class DayCare:
    def __init__(self):
        self.children: Dict[str, Child] = {}

    def add_child(self, name: str, age: int):
        self.children[name] = Child(name, age)

    def log_activity(self, child_name: str, activity_type: str, notes: str = ""):
        if child_name in self.children:
            self.children[child_name].add_activity(activity_type, notes)

    def get_child_summary(self, child_name: str, date: datetime) -> Dict:
        if child_name in self.children:
            return self.children[child_name].get_daily_summary(date)
        return {}
