from pathlib import Path

class MediaLibrary:
    def __init__(self, library_path):
        self.library_path = Path(library_path)
        self.library_path.mkdir(exist_ok=True)
        self.temp_dir = Path(tempfile.gettempdir()) / "media_cache"
        self.temp_dir.mkdir(exist_ok=True)

    def add_album(self, album_path, album_name):
        archive_path = self.library_path / f"{album_name}.zip"
        with zipfile.ZipFile(archive_path, 'w', zipfile.ZIP_DEFLATED) as zf:
            for file_path in Path(album_path).glob('*'):
                zf.write(file_path, file_path.name)

    def extract_track(self, album_name, track_name):
        archive_path = self.library_path / f"{album_name}.zip"
        extract_path = self.temp_dir / album_name / track_name

        if not extract_path.exists():
            with zipfile.ZipFile(archive_path, 'r') as zf:
                zf.extract(track_name, self.temp_dir / album_name)

        return str(extract_path)

    def cleanup_cache(self):
        shutil.rmtree(self.temp_dir)
        self.temp_dir.mkdir(exist_ok=True)

    def list_albums(self):
        return [f.stem for f in self.library_path.glob('*.zip')]

    def list_tracks(self, album_name):
        archive_path = self.library_path / f"{album_name}.zip"
        with zipfile.ZipFile(archive_path, 'r') as zf:
            return zf.namelist()

