import json
import os
from operator import itemgetter
from datetime import datetime

class HighScores:
    def __init__(self, filename="highscores.json"):
        self.filename = filename
        self.scores = []
        self.load_scores()

    def load_scores(self):
        if os.path.exists(self.filename):
            with open(self.filename, 'r') as file:
                try:
                    self.scores = json.load(file)
                except json.JSONDecodeError:
                    self.scores = []

    def save_scores(self):
        with open(self.filename, 'w') as file:
            json.dump(self.scores, file)

    def add_score(self, player_name, score):
        score_entry = {
            'player': player_name,
            'score': score,
            'date': datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        }
        self.scores.append(score_entry)
        self.scores.sort(key=itemgetter('score'), reverse=True)
        self.scores = self.scores[:10]
        self.save_scores()

    def get_top_scores(self, limit=10):
        return self.scores[:limit]

class Game:
    def __init__(self):
        self.high_scores = HighScores()
        self.current_score = 0
        self.player_name = ""

    def play(self):
        self.current_score += 10

    def game_over(self):
        if self.player_name:
            self.high_scores.add_score(self.player_name, self.current_score)
            self.current_score = 0

    def display_high_scores(self):
        print("\nHigh Scores:")
        for idx, score in enumerate(self.high_scores.get_top_scores(), 1):
            print(f"{idx}. {score['player']}: {score['score']} ({score['date']})")

import os
import shutil
import tarfile
import subprocess
from pathlib import Path
import tempfile
import logging

class DependencyDeployer:
    def __init__(self, source_dir, target_dir):
        self.source_dir = Path(source_dir)
        self.target_dir = Path(target_dir)
        self.temp_dir = Path(tempfile.mkdtemp())

    def deploy(self):
        try:
            self._extract_archives()
            self._install_dependencies()
            self._cleanup()
            return True
        except Exception as e:
            logging.error(f"Deployment failed: {str(e)}")
            self._cleanup()
            return False

    def _extract_archives(self):
        for archive in self.source_dir.glob('*.tar.gz'):
            with tarfile.open(archive, 'r:gz') as tar:
                tar.extractall(path=self.temp_dir)

    def _install_dependencies(self):
        requirements = self.temp_dir / 'requirements.txt'
        if requirements.exists():
            subprocess.run([
                'pip', 'install',
                '-r', str(requirements),
                '--target', str(self.target_dir)
            ], check=True)

    def _cleanup(self):
        if self.temp_dir.exists():
            shutil.rmtree(self.temp_dir)

if __name__ == '__main__':
    deployer = DependencyDeployer('/path/to/source', '/path/to/target')
    deployer.deploy()

