import os
import re
from pathlib import Path

class FileRenamer:
    def __init__(self, directory):
        self.directory = Path(directory)
        self.files = [f for f in self.directory.iterdir() if f.is_file()]

    def rename_by_pattern(self, pattern, replacement):
        for file in self.files:
            new_name = re.sub(pattern, replacement, file.name)
            if new_name != file.name:
                try:
                    file.rename(file.parent / new_name)
                except FileExistsError:
                    base, ext = os.path.splitext(new_name)
                    file.rename(file.parent / f"{base}_copy{ext}")

    def add_prefix(self, prefix):
        for file in self.files:
            new_name = f"{prefix}{file.name}"
            file.rename(file.parent / new_name)

    def add_suffix(self, suffix):
        for file in self.files:
            base, ext = os.path.splitext(file.name)
            new_name = f"{base}{suffix}{ext}"
            file.rename(file.parent / new_name)

    def number_files(self, start=1, padding=3):
        for i, file in enumerate(sorted(self.files), start):
            base, ext = os.path.splitext(file.name)
            new_name = f"{str(i).zfill(padding)}{ext}"
            file.rename(file.parent / new_name)

