from PIL import Image
import pytesseract
import re
from datetime import datetime

class ReceiptScanner:
    def __init__(self):
        self.total_pattern = r'\$?\d+\.\d{2}'
        self.date_pattern = r'\d{2}/\d{2}/\d{4}'

    def scan_receipt(self, image_path):
        try:
            image = Image.open(image_path)
            text = pytesseract.image_to_string(image)

            receipt_data = {
                'total': self._extract_total(text),
                'date': self._extract_date(text),
                'vendor': self._extract_vendor(text),
                'items': self._extract_items(text),
                'raw_text': text
            }

            return receipt_data

        except Exception as e:
            return {'error': str(e)}

    def _extract_total(self, text):
        amounts = re.findall(self.total_pattern, text)
        if amounts:
            return max([float(amount.replace('$', '')) for amount in amounts])
        return None

    def _extract_date(self, text):
        dates = re.findall(self.date_pattern, text)
        if dates:
            return datetime.strptime(dates[0], '%m/%d/%Y').date()
        return None

    def _extract_vendor(self, text):
        lines = text.split('\n')
        if lines:
            return lines[0].strip()
        return None

    def _extract_items(self, text):
        items = []
        lines = text.split('\n')
        for line in lines:
            if re.search(self.total_pattern, line):
                item = line.split('$')[0].strip()
                if item:
                    items.append(item)
        return items

def process_receipt(image_path):
    scanner = ReceiptScanner()
    receipt_data = scanner.scan_receipt(image_path)

    if 'error' not in receipt_data:
        print(f"Vendor: {receipt_data['vendor']}")
        print(f"Date: {receipt_data['date']}")
        print(f"Total: ${receipt_data['total']:.2f}")
        print("Items:")
        for item in receipt_data['items']:
            print(f"- {item}")
    else:
        print(f"Error processing receipt: {receipt_data['error']}")

if __name__ == '__main__':
    process_receipt('receipt.jpg')
