import os
import shutil
import ast
import sys
from typing import Dict, List

def archive_folder(source_dir, archive_path):
    shutil.make_archive(archive_path, 'zip', source_dir)

def analyze_complexity(file_path: str, max_line_length: int = 50) -> Dict[str, List[str]]:
    issues = {'complex_methods': [], 'long_methods': []}

    with open(file_path) as f:
        tree = ast.parse(f.read())

    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            if len(node.body) > max_line_length:
                issues['long_methods'].append(node.name)

            complexity = sum(1 for _ in ast.walk(node) if isinstance(_, (ast.If, ast.For, ast.While, ast.ExceptHandler)))
            if complexity > 10:
                issues['complex_methods'].append(node.name)

    return issues

def scan_directory(directory: str) -> Dict[str, Dict[str, List[str]]]:
    report = {}
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                file_path = os.path.join(root, file)
                report[file_path] = analyze_complexity(file_path)
    return report

