        available_rooms = []
        for room_id, room in self.rooms.items():
            if room.available and room.capacity >= guests:
                available_rooms.append(room_id)
        return available_rooms

class Booking:
    def __init__(self):
        self.bookings = {}

    def create_booking(self, hotel: Hotel, room_id: str, guest_name: str,
                      check_in: datetime, check_out: datetime, guests: int):
        if room_id in hotel.rooms and hotel.rooms[room_id].available:
            booking_id = len(self.bookings) + 1
            self.bookings[booking_id] = {
                'hotel': hotel.name,
                'room_id': room_id,
                'guest_name': guest_name,
                'check_in': check_in,
                'check_out': check_out,
                'guests': guests
            }
            hotel.rooms[room_id].available = False
            return booking_id
        return None

    def cancel_booking(self, booking_id: int, hotel: Hotel):
        if booking_id in self.bookings:
            room_id = self.bookings[booking_id]['room_id']
            hotel.rooms[room_id].available = True
            del self.bookings[booking_id]
