        content = f"{obj_type} {len(data)}\0{data}"
        hash_value = hashlib.sha1(content.encode()).hexdigest()
        path = os.path.join(self.objects_path, hash_value)
        if not os.path.exists(path):
            with open(path, 'w') as f:
                f.write(content)
        return hash_value

    def commit(self, message):
        tree = self._create_tree()
        parent = self._get_current_commit()
        commit_data = {
            'tree': tree,
            'parent': parent,
            'message': message,
            'timestamp': datetime.now().isoformat()
        }
        commit_hash = self.hash_object(json.dumps(commit_data), 'commit')
        self._update_ref('HEAD', commit_hash)
        return commit_hash

    def _create_tree(self):
        tree = {}
        for root, _, files in os.walk(self.repo_path):
            if '.vc' in root:
                continue
            for file in files:
                path = os.path.join(root, file)
                with open(path, 'r') as f:
                    content = f.read()
                hash_value = self.hash_object(content)
                rel_path = os.path.relpath(path, self.repo_path)
                tree[rel_path] = hash_value
        return self.hash_object(json.dumps(tree), 'tree')

    def _get_current_commit(self):
        try:
            with open(os.path.join(self.refs_path, 'HEAD'), 'r') as f:
                return f.read().strip()
        except FileNotFoundError:
            return None

    def _update_ref(self, ref_name, hash_value):
        with open(os.path.join(self.refs_path, ref_name), 'w') as f:
            f.write(hash_value)

    def merge(self, other_branch):
        current = self._get_current_commit()
        other = self._get_ref(other_branch)
        base = self._find_merge_base(current, other)

        if base == other:
            return "Already up to date"
        if base == current:
            self._update_ref('HEAD', other)
            return "Fast-forward merge completed"

        current_tree = self._load_tree(current)
        other_tree = self._load_tree(other)
        base_tree = self._load_tree(base)

        merged_tree = self._merge_trees(current_tree, other_tree, base_tree)
        merged_hash = self.hash_object(json.dumps(merged_tree), 'tree')

        commit_data = {
            'tree': merged_hash,
            'parents': [current, other],
            'message': f"Merge branch '{other_branch}'",
            'timestamp': datetime.now().isoformat()
        }
        merge_commit = self.hash_object(json.dumps(commit_data), 'commit')
        self._update_ref('HEAD', merge_commit)
        return "Merge completed"

    def _load_tree(self, commit_hash):
        with open(os.path.join(self.objects_path, commit_hash), 'r') as f:
            content = f.read()
            _, _, commit_data = content.partition('\0')
            commit_obj = json.loads(commit_data)
            tree_hash = commit_obj['tree']

        with open(os.path.join(self.objects_path, tree_hash), 'r') as f:
            content = f.read()
            _, _, tree_data = content.partition('\0')
            return json.loads(tree_data)

    def _merge_trees(self, current_tree, other_tree, base_tree):
        merged = {}
        all_files = set(current_tree) | set(other_tree) | set(base_tree)

        for file in all_files:
            current_hash = current_tree.get(file)
            other_hash = other_tree.get(file)
            base_hash = base_tree.get(file)

            if current_hash == other_hash:
                merged[file] = current_hash
            elif current_hash == base_hash:
                merged[file] = other_hash
            elif other_hash == base_hash:
                merged[file] = current_hash
            else:
                # Conflict resolution needed
                merged[file] = self._resolve_conflict(file, current_hash, other_hash)

        return merged

    def _resolve_conflict(self, file, current_hash, other_hash):
        # Simple resolution strategy: take current version
        return current_hash

    def _get_ref(self, ref_name):
        try:
            with open(os.path.join(self.refs_path, ref_name), 'r') as f:
                return f.read().strip()
        except FileNotFoundError:
            return None

    def _find_merge_base(self, commit1, commit2):
        # Simple implementation: return first common ancestor
        ancestors1 = self._get_ancestors(commit1)
        ancestors2 = self._get_ancestors(commit2)
        common = ancestors1 & ancestors2
        return next(iter(common)) if common else None

    def _get_ancestors(self, commit):
        ancestors = set()
        queue = [commit]
        while queue:
            current = queue.pop(0)
            if current in ancestors:
                continue
            ancestors.add(current)
            with open(os.path.join(self.objects_path, current), 'r') as f:
                content = f.read()
                _, _, commit_data = content.partition('\0')
                commit_obj = json.loads(commit_data)
                parent = commit_obj.get('parent')
                if parent:
                    queue.append(parent)
        return ancestors

