import os
import shutil
import hashlib
import requests
from zipfile import ZipFile

class RetroModInstaller:
    def __init__(self):
        self.mod_directory = "roms/mods"
        self.console_directories = {
            "nes": "roms/nes",
            "snes": "roms/snes", 
            "genesis": "roms/genesis",
            "gba": "roms/gba"
        }

        for directory in self.console_directories.values():
            os.makedirs(directory, exist_ok=True)
        os.makedirs(self.mod_directory, exist_ok=True)

    def download_mod(self, url, console):
        response = requests.get(url, stream=True)
        mod_file = os.path.join(self.mod_directory, f"{hashlib.md5(url.encode()).hexdigest()}.zip")

        with open(mod_file, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        self.install_mod(mod_file, console)

    def install_mod(self, mod_file, console):
        target_dir = self.console_directories[console]

        with ZipFile(mod_file, 'r') as zip_ref:
            zip_ref.extractall(target_dir)

        os.remove(mod_file)

    def verify_rom(self, rom_path):
        valid_extensions = ['.nes', '.sfc', '.smc', '.md', '.gba']
        return os.path.splitext(rom_path)[1].lower() in valid_extensions

    def backup_rom(self, rom_path):
        backup_path = rom_path + '.backup'
        shutil.copy2(rom_path, backup_path)
        return backup_path

    def apply_patch(self, rom_path, patch_path):
        if not self.verify_rom(rom_path):
            raise ValueError("Invalid ROM file")

        backup = self.backup_rom(rom_path)

        # Apply IPS or BPS patch
        with open(patch_path, 'rb') as patch_file:
            patch_data = patch_file.read()

        with open(rom_path, 'rb+') as rom_file:
            rom_data = bytearray(rom_file.read())

            if patch_data[:5] == b'PATCH':
                self.apply_ips_patch(rom_data, patch_data)
            elif patch_data[:4] == b'BPS1':
                self.apply_bps_patch(rom_data, patch_data)
            else:
                raise ValueError("Unsupported patch format")

            rom_file.seek(0)
            rom_file.write(rom_data)

    def apply_ips_patch(self, rom_data, patch_data):
        offset = 5
        while offset < len(patch_data) - 3:
            address = int.from_bytes(patch_data[offset:offset+3], byteorder='big')
            length = int.from_bytes(patch_data[offset+3:offset+5], byteorder='big')

            if length == 0:
                rle_length = int.from_bytes(patch_data[offset+5:offset+7], byteorder='big')
                value = patch_data[offset+7]
                rom_data[address:address+rle_length] = [value] * rle_length
                offset += 8
            else:
                rom_data[address:address+length] = patch_data[offset+5:offset+5+length]
                offset += 5 + length

    def list_installed_mods(self, console):
        mods = []
        console_dir = self.console_directories[console]

        for root, dirs, files in os.walk(console_dir):
            for file in files:
                if file.endswith(('.patch', '.ips', '.bps')):
                    mods.append(os.path.join(root, file))

        return mods

def main():
    installer = RetroModInstaller()

    # Example usage
    try:
        # Download and install a mod
        installer.download_mod("https://example.com/super-mario-mod.zip", "nes")

        # Apply a patch to a ROM
        installer.apply_patch("roms/nes/super_mario.nes", "roms/mods/enhancement.ips")

        # List installed mods
        nes_mods = installer.list_installed_mods("nes")
        print("Installed NES mods:")
        for mod in nes_mods:
            print(f"- {mod}")

    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    main()
