class WebArchiver:
    def __init__(self, base_dir="archives"):
        self.base_dir = base_dir
        self.visited_urls = set()
        os.makedirs(base_dir, exist_ok=True)

    def archive_page(self, url, depth=1):
        if depth <= 0 or url in self.visited_urls:
            return

        try:
            response = requests.get(url, timeout=10)
            response.raise_for_status()
            self.visited_urls.add(url)

            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            url_hash = hashlib.md5(url.encode()).hexdigest()
            filename = f"{url_hash}_{timestamp}.html"

            soup = BeautifulSoup(response.text, 'html.parser')

            with open(os.path.join(self.base_dir, filename), 'w', encoding='utf-8') as f:
                f.write(response.text)

            if depth > 1:
                for link in soup.find_all('a'):
                    next_url = link.get('href')
                    if next_url:
                        next_url = urljoin(url, next_url)
                        self.archive_page(next_url, depth - 1)

        except Exception as e:
            print(f"Error archiving {url}: {str(e)}")

    def get_archived_pages(self):
        return os.listdir(self.base_dir)

if __name__ == "__main__":
