import threading
import time
import random
import copy

class DistributedKVStore:
    def __init__(self, num_replicas=3):
        self.data = defaultdict(dict)
        self.replicas = num_replicas
        self.nodes = []
        self.lock = threading.Lock()

    def add_node(self, node_id):
        with self.lock:
            self.nodes.append(node_id)
            self._rebalance()

    def remove_node(self, node_id): 
        with self.lock:
            self.nodes.remove(node_id)
            self._rebalance()

    def put(self, key, value):
        with self.lock:
            replicas = self._get_replica_nodes(key)
            for node in replicas:
                self.data[node][key] = value
            return True

    def get(self, key):
        replicas = self._get_replica_nodes(key)
        for node in replicas:
            if key in self.data[node]:
                return self.data[node][key]
        return None

    def _get_replica_nodes(self, key):
        num_nodes = len(self.nodes)
        if num_nodes == 0:
            return []

        hash_val = hash(key) % num_nodes
        replicas = []
        for i in range(self.replicas):
            node_idx = (hash_val + i) % num_nodes
            replicas.append(self.nodes[node_idx])
        return replicas

    def _rebalance(self):
        temp_data = defaultdict(dict)
        for node in self.data:
            for key, value in self.data[node].items():
                replicas = self._get_replica_nodes(key)
                for replica in replicas:
                    temp_data[replica][key] = value
        self.data = temp_data
