from git import Repo
from pathlib import Path

class BuildPipeline:
    def __init__(self, repo_url, build_dir, artifact_dir, version):
        self.repo_url = repo_url
        self.build_dir = Path(build_dir)
        self.artifact_dir = Path(artifact_dir)
        self.version = version
        self.logger = logging.getLogger(__name__)

    def checkout_code(self):
        if self.build_dir.exists():
            shutil.rmtree(self.build_dir)
        self.build_dir.mkdir(parents=True)
        Repo.clone_from(self.repo_url, self.build_dir)

    def run_build(self):
        os.chdir(self.build_dir)
        result = subprocess.run(['python', 'setup.py', 'build'], 
                              capture_output=True, text=True)
        if result.returncode != 0:
            raise Exception(f"Build failed: {result.stderr}")

    def run_tests(self):
        result = subprocess.run(['pytest'], capture_output=True, text=True)
        if result.returncode != 0:
            raise Exception(f"Tests failed: {result.stderr}")

    def publish_artifacts(self):
        if not self.artifact_dir.exists():
            self.artifact_dir.mkdir(parents=True)

        dist_dir = self.build_dir / 'dist'
        for artifact in dist_dir.glob('*'):
            shutil.copy2(artifact, self.artifact_dir)

        os.chmod(self.artifact_dir, 0o755)
        for artifact in self.artifact_dir.glob('*'):
            os.chmod(artifact, 0o644)

    def create_release(self):
        release_dir = self.artifact_dir / f'release-{self.version}'
        release_dir.mkdir()

        for artifact in self.artifact_dir.glob('*'):
            if artifact.is_file():
                shutil.copy2(artifact, release_dir)

        # Set release directory permissions
        os.chmod(release_dir, 0o755)
        for file in release_dir.glob('*'):
            os.chmod(file, 0o644)

    def run(self):
        try:
            self.logger.info("Starting build pipeline")
            self.checkout_code()
            self.run_build()
            self.run_tests()
            self.publish_artifacts()
            self.create_release()
            self.logger.info("Build pipeline completed successfully")
        except Exception as e:
            self.logger.error(f"Pipeline failed: {str(e)}")
            raise

if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)

    pipeline = BuildPipeline(
        repo_url="https://github.com/user/repo.git",
        build_dir="./build",
        artifact_dir="./artifacts", 
        version="1.0.0"
    )
