from collections import defaultdict
import time
import copy

class ReplicatedKVStore:
    def __init__(self, num_replicas=3):
        self.stores = [{}] * num_replicas
        self.locks = [Lock() for _ in range(num_replicas)]
        self.version_map = defaultdict(int)
        self.heartbeats = [time.time()] * num_replicas
        self.replica_timeout = 5.0

    def set(self, key, value):
        quorum = len(self.stores) // 2 + 1
        success_count = 0
        new_version = self.version_map[key] + 1

        for i, store in enumerate(self.stores):
            if time.time() - self.heartbeats[i] > self.replica_timeout:
                continue

            try:
                with self.locks[i]:
                    store[key] = (value, new_version)
                    self.heartbeats[i] = time.time()
                    success_count += 1
            except:
                continue

            if success_count >= quorum:
                self.version_map[key] = new_version
                return True
        return False

    def get(self, key):
        latest_value = None
        latest_version = -1
        quorum = len(self.stores) // 2 + 1
        read_count = 0

        for i, store in enumerate(self.stores):
            if time.time() - self.heartbeats[i] > self.replica_timeout:
                continue

            try:
                with self.locks[i]:
                    if key in store:
                        value, version = store[key]
                        if version > latest_version:
                            latest_value = value
                            latest_version = version
                        read_count += 1
                    self.heartbeats[i] = time.time()
            except:
                continue

        if read_count >= quorum:
            return latest_value
        return None

    def repair(self):
        for i in range(len(self.stores)):
            if time.time() - self.heartbeats[i] <= self.replica_timeout:
                continue

            try:
                with self.locks[i]:
                    self.stores[i] = copy.deepcopy(self.stores[0])
                    self.heartbeats[i] = time.time()
            except:
