from datetime import datetime

def archive_files(source_dir, archive_name, patterns=None, min_size=0, max_age=None):
    with zipfile.ZipFile(archive_name, 'w', zipfile.ZIP_DEFLATED) as archive:
        for root, _, files in os.walk(source_dir):
            for file in files:
                filepath = Path(root) / file
                if not _matches_criteria(filepath, patterns, min_size, max_age):
                    continue
                arcname = filepath.relative_to(source_dir)
                archive.write(filepath, arcname)

def _matches_criteria(filepath, patterns, min_size, max_age):
    if patterns and not any(filepath.match(pattern) for pattern in patterns):
        return False

    if min_size and filepath.stat().st_size < min_size:
        return False

    if max_age:
        file_age = datetime.now().timestamp() - filepath.stat().st_mtime
        if file_age > max_age:
            return False

    return True

