            raise ValueError("Goal not found")

        entry = {
            "date": date.today().isoformat(),
            "value": value
        }
        self.goals[goal_id].progress.append(entry)

    def get_goal_progress(self, goal_id: int) -> Dict:
        if goal_id not in self.goals:
            raise ValueError("Goal not found")

        goal = self.goals[goal_id]
        total = sum(entry["value"] for entry in goal.progress)
        percentage = (total / goal.target) * 100 if goal.target > 0 else 0

        return {
            "category": goal.category,
            "current": total,
            "target": goal.target,
            "unit": goal.unit,
            "progress_percentage": min(percentage, 100)
        }

